    function safeMessageFavoriteClone(value) {
        if (value === undefined) return undefined;
        if (value === null) return null;
        if (typeof value !== 'object') return value;
        try {
            return JSON.parse(JSON.stringify(value));
        } catch (error) {
            return value;
        }
    }

    function createDefaultMessageFavoritesState() {
        return {
            items: [],
            customGroups: [],
            preferences: {
                category: 'all',
                group: MESSAGE_FAVORITE_GROUP_ALL,
                sort: 'newest',
                date: '',
                contactId: '',
                keyword: '',
                page: 1,
                pageSize: MESSAGE_FAVORITE_PAGE_SIZE
            }
        };
    }

    function normalizeMessageFavoriteSnapshot(snapshot) {
        if (!snapshot || typeof snapshot !== 'object') return null;
        return {
            id: String(snapshot.id || `fav_snapshot_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`),
            role: String(snapshot.role || snapshot.senderType || 'assistant'),
            type: String(snapshot.type || 'text'),
            content: safeMessageFavoriteClone(snapshot.content),
            rawHtmlContent: safeMessageFavoriteClone(snapshot.rawHtmlContent),
            timestamp: Number(snapshot.timestamp) || Date.now(),
            mode: String(snapshot.mode || ''),
            quotedMessage: safeMessageFavoriteClone(snapshot.quotedMessage),
            imageId: snapshot.imageId || '',
            stickerId: snapshot.stickerId || '',
            redPacketData: safeMessageFavoriteClone(snapshot.redPacketData),
            relationshipData: safeMessageFavoriteClone(snapshot.relationshipData),
            paymentData: safeMessageFavoriteClone(snapshot.paymentData),
            listenTogetherData: safeMessageFavoriteClone(snapshot.listenTogetherData),
            musicShareData: safeMessageFavoriteClone(snapshot.musicShareData),
            transactionData: safeMessageFavoriteClone(snapshot.transactionData),
            imageGenerationMeta: safeMessageFavoriteClone(snapshot.imageGenerationMeta),
            aiDescription: safeMessageFavoriteClone(snapshot.aiDescription),
            bubbleStyleId: snapshot.bubbleStyleId || '',
            recalledMeta: safeMessageFavoriteClone(snapshot.recalledMeta)
        };
    }

    function ensureMessageFavoritesState(profile = appData && appData.globalUserProfile) {
        if (!profile || typeof profile !== 'object') {
            return createDefaultMessageFavoritesState();
        }
        if (!profile.messageFavorites || typeof profile.messageFavorites !== 'object') {
            profile.messageFavorites = createDefaultMessageFavoritesState();
        }

        const store = profile.messageFavorites;
        if (!Array.isArray(store.items)) store.items = [];
        if (!Array.isArray(store.customGroups)) store.customGroups = [];
        if (!store.preferences || typeof store.preferences !== 'object') {
            store.preferences = createDefaultMessageFavoritesState().preferences;
        }

        store.customGroups = store.customGroups
            .map((group) => {
                if (!group || typeof group !== 'object') return null;
                const name = String(group.name || '').trim();
                if (!name) return null;
                return {
                    id: String(group.id || `fav_group_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`),
                    name,
                    createdAt: Number(group.createdAt) || Date.now()
                };
            })
            .filter(Boolean);

        const validGroupIds = new Set(store.customGroups.map((group) => String(group.id)));
        store.items = store.items
            .map((item) => {
                if (!item || typeof item !== 'object') return null;
                const snapshots = (Array.isArray(item.messageSnapshots) ? item.messageSnapshots : [])
                    .map(normalizeMessageFavoriteSnapshot)
                    .filter(Boolean);
                if (snapshots.length === 0) return null;

                const normalizedCategory = MESSAGE_FAVORITE_CATEGORY_META[item.category] ? item.category : 'message';
                const startTimestamp = Number(item.messageStartTimestamp) || Number(snapshots[0]?.timestamp) || Date.now();
                const endTimestamp = Number(item.messageEndTimestamp) || Number(snapshots[snapshots.length - 1]?.timestamp) || startTimestamp;
                const customGroupIds = Array.isArray(item.customGroupIds)
                    ? [...new Set(item.customGroupIds.map((id) => String(id)).filter((id) => validGroupIds.has(id)))]
                    : [];
                const chatContext = item.chatContext && typeof item.chatContext === 'object' ? item.chatContext : {};

                return {
                    id: String(item.id || `fav_msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`),
                    category: normalizedCategory,
                    sourceKey: String(item.sourceKey || ''),
                    favoritedAt: Number(item.favoritedAt) || Date.now(),
                    note: String(item.note || ''),
                    isLoved: Boolean(item.isLoved),
                    customGroupIds,
                    messageIds: Array.isArray(item.messageIds)
                        ? item.messageIds.map((id) => String(id)).filter(Boolean)
                        : snapshots.map((snapshot) => String(snapshot.id || '')).filter(Boolean),
                    messageSnapshots: snapshots,
                    messageStartTimestamp: startTimestamp,
                    messageEndTimestamp: endTimestamp,
                    chatContext: {
                        contactId: String(chatContext.contactId || ''),
                        contactName: String(chatContext.contactName || ''),
                        isOfflineMode: Boolean(chatContext.isOfflineMode),
                        storyId: String(chatContext.storyId || ''),
                        storyName: String(chatContext.storyName || '')
                    }
                };
            })
            .filter(Boolean);

        const preferences = store.preferences;
        preferences.category = MESSAGE_FAVORITE_CATEGORY_META[preferences.category] ? preferences.category : 'all';
        preferences.group = typeof preferences.group === 'string' && preferences.group
            ? preferences.group
            : MESSAGE_FAVORITE_GROUP_ALL;
        preferences.sort = preferences.sort === 'oldest' ? 'oldest' : 'newest';
        preferences.date = String(preferences.date || '');
        preferences.contactId = String(preferences.contactId || '');
        preferences.keyword = String(preferences.keyword || '');
        preferences.page = Math.max(1, Number(preferences.page) || 1);
        preferences.pageSize = Math.max(1, Number(preferences.pageSize) || MESSAGE_FAVORITE_PAGE_SIZE);

        return store;
    }

