    /**
     * 【全新】时间格式化小助手：将秒数转换为 MM:SS 格式
     */
    function formatTime(seconds) {
        if (isNaN(seconds) || seconds < 0) {
            return "00:00";
        }
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    }
    /**
     * 【【【全新超级武器：JSON安全消毒器】】】
     * 它的唯一职责，就是把任何可能破坏JSON格式的文本，变得“人畜无害”。
     * @param {string} text - 需要消毒的原始文本
     * @returns {string} - 返回绝对安全的文本
     */
    function sanitizeForJSON(text) {
        if (typeof text !== 'string') return text;
        return text
            .replace(/\\/g, '\\\\')  // 1. 先处理反斜杠本身
            .replace(/"/g, '\\"')   // 2. 再处理双引号
            .replace(/\n/g, '\\n')  // 3. 处理换行符
            .replace(/\r/g, '\\r')  // 4. 处理回车符
            .replace(/\t/g, '\\t'); // 5. 处理制表符
    }
    /**
     * 【【【全新超级武器 V2：纯文本速记员】】】
     * 它的唯一职责，就是把一段复杂的聊天记录，翻译成AI能读懂的、纯文本的对话摘要。
     * @param {Array} history - 要翻译的聊天记录数组
     * @returns {string} - 返回一段干净的、纯文本格式的对话历史
     */
    async function formatHistoryForTextPrompt(history, contact) {
        if (!contact) return "（最近没有聊天记录）";
        history = await mergeIdicCompanionHistoryForPrompt(Array.isArray(history) ? history : [], contact);
        if (!history || history.length === 0) return "（最近没有聊天记录）";

        const textParts = await Promise.all(history.map(async msg => {
            if (!msg || !msg.role) return null;

            const roleName = msg.role === 'user' ? (contact.userProfile.name || '用户') : contact.name;
            let contentText = '';

            switch (msg.type) {
                case 'image':
                    contentText = `[发送了一张图片，描述是：${msg.content || '无'}]`;
                    break;
                case 'sticker':
                    contentText = `[发送了一个表情：${msg.content.replace('[表情]', '').trim()}]`;
                    break;
                case 'voice':
                    contentText = formatVoiceMessageContentForPrompt(msg, contact, { compact: true });
                    break;
                case 'red-packet':
                    contentText = `[发送了一张图片，描述是：${msg.content || '无'}]`;
                    break;
                case 'system':
                case 'thought':
                    return null; // 在摘要中忽略系统消息和内心独白
                default:
                    // 对于普通文本和所有其他未知的类型，我们只取 content
                    if (typeof msg.content === 'string') {
                        contentText = msg.content;
                    }
                    break;
            }

            return `${roleName}: ${contentText}`;
        }));

        return textParts.filter(Boolean).join('\n');
    }

    function roundVoiceMetric(value, digits = 2) {
        const number = Number(value);
        if (!Number.isFinite(number)) return 0;
        const factor = Math.pow(10, Math.max(0, digits));
        return Math.round(number * factor) / factor;
    }

    function sanitizeVoicePromptText(value, maxLength = 240) {
        const text = String(value || '').replace(/\s+/g, ' ').trim();
        if (!text) return '';
        return text.length > maxLength ? `${text.slice(0, maxLength)}...` : text;
    }

    function getDefaultVoiceUnderstandingSettings() {
        return {
            enabled: false,
            provider: 'aliyun',
            apiKey: '',
            baseUrl: DEFAULT_VOICE_UNDERSTANDING_BASE_URL,
            model: DEFAULT_VOICE_UNDERSTANDING_MODEL,
            prompt: DEFAULT_VOICE_UNDERSTANDING_PROMPT
        };
    }

    function normalizeVoiceUnderstandingSettings(rawSettings = {}) {
        const defaults = getDefaultVoiceUnderstandingSettings();
        const raw = rawSettings && typeof rawSettings === 'object' ? rawSettings : {};
        const baseUrl = String(raw.baseUrl || defaults.baseUrl).trim().replace(/\/+$/, '') || defaults.baseUrl;
        const model = String(raw.model || defaults.model).trim() || defaults.model;
        return {
            ...defaults,
            ...raw,
            enabled: Boolean(raw.enabled),
            provider: 'aliyun',
            apiKey: String(raw.apiKey || '').trim(),
            baseUrl,
            model,
            prompt: String(raw.prompt || defaults.prompt).trim() || defaults.prompt
        };
    }

    function formatVoiceAcousticMetaForPrompt(meta) {
        if (!meta || typeof meta !== 'object') return '';
        const parts = [];
        const push = (label, value) => {
            const text = sanitizeVoicePromptText(value);
            if (text) parts.push(`${label}: ${text}`);
        };

        push('听感摘要', meta.summary);
        push('环境声/底噪', meta.environment);
        if (meta.pace && typeof meta.pace === 'object') {
            const rateText = Number.isFinite(Number(meta.pace.unitsPerSecond))
                ? `${meta.pace.label || ''}(${roundVoiceMetric(meta.pace.unitsPerSecond, 2)}字/词每秒)`
                : meta.pace.label;
            push('语速', rateText);
        }
        if (meta.pauses && typeof meta.pauses === 'object') {
            const pauseText = [
                meta.pauses.label,
                Number.isFinite(Number(meta.pauses.count)) ? `停顿${meta.pauses.count}次` : '',
                Number.isFinite(Number(meta.pauses.longestSec)) ? `最长${roundVoiceMetric(meta.pauses.longestSec, 1)}秒` : ''
            ].filter(Boolean).join('，');
            push('停顿/呼吸感', pauseText);
        }
        if (meta.volume && typeof meta.volume === 'object') {
            push('音量', meta.volume.label);
        }
        push('语气/语调', meta.prosody);
        push('情绪倾向', meta.emotion);
        push('表达方式', meta.delivery);
        push('AI 听感增强', meta.aiUnderstanding || meta.enhancedSummary);
        return parts.join('；');
    }

    function formatVoiceMessageContentForPrompt(msg, contact, options = {}) {
        const safeMsg = msg && typeof msg === 'object' ? msg : {};
        const content = String(safeMsg.content || '').trim();
        const transcript = content || '（没有识别到清晰文字）';
        const isUser = safeMsg.role === 'user' || safeMsg.senderType === 'user';
        const speakerName = options.speakerName
            || (isUser ? (contact?.userProfile?.name || '我') : (contact?.name || '你'));
        const baseLead = isUser
            ? `${speakerName}发来一条语音`
            : `${speakerName}发出一条语音`;
        const voiceMetaText = formatVoiceAcousticMetaForPrompt(
            safeMsg.voiceMeta || safeMsg.acousticMeta || safeMsg.voiceAnalysis
        );

        if (!voiceMetaText) {
            return `[${baseLead}，转写内容：${transcript}]`;
        }

        const suffix = options.compact
            ? ''
            : '。请把这些声音细节当成这条语音真实携带的信息来理解，不要当作普通旁白';
        return `[${baseLead}，转写内容：${transcript}。声音细节：${voiceMetaText}${suffix}]`;
    }
    /**
     * 【【【全新超级武器：带重试功能的API请求官】】】
     * @param {string} url - 要请求的API地址
     * @param {object} options - fetch函数的额外选项 (例如 headers)
     * @param {number} retries - 最大重试次数
     * @param {number} delay - 每次重试前的等待时间 (毫秒)
     * @returns {Promise<any>} - 返回解析后的JSON数据
     */
    async function fetchWithRetry(url, options = {}, retries = 10, delay = 1000) {
        let lastError = null;
        for (let i = 0; i < retries; i++) {
            try {
                const response = await fetch(url, options);
                if (!response.ok) {
                // 【【【终极修复：安装“二楼业务安检门”！】】】
                    throw new Error(`服务器响应失败: ${response.status}`);
                }

                // 关键升级：安检员立刻拆开“包裹”（解析JSON）
                const data = await response.json();

                // 只有通过了网络和业务两道安检门，才算是真正的成功！
// 检查权限的主函数
                if (data.code !== 200) {
                    // 如果code不是200，说明是业务逻辑上的错误（例如“系统运行错误”）。
                    // 我们主动抛出一个错误，并把API返回的错误信息作为原因。
                    // 这样，外面的catch就能捕捉到它，并触发重试！
                    throw new Error(data.message || `API返回了业务错误，状态码: ${data.code}`);
                }

                // 如果这不是最后一次尝试，就等待一小会儿再继续
                return data;

            } catch (error) {
                lastError = error; // 记下这次的错误原因
                console.warn(`API请求尝试 ${i + 1}/${retries} 失败: ${error.message}. 将在 ${delay / 1000}秒后重试...`);

        // 如果循环结束了还没成功，说明所有尝试都失败了，抛出最后一次记录的错误
                if (i < retries - 1) {
                    await sleep(delay);
                }
            }
        }
    // ▼▼▼ 【【【全新：歌词处理引擎核心】】】 ▼▼▼
        throw lastError;
    }

    /**
     * 【【【终极修复：Suno API 专属的、带重试功能的请求官 V1.0】】】
     * 这个版本移除了对 data.code === 200 的检查，因为它不适用于 Suno API。
     */
    async function fetchSunoWithRetry(url, options = {}, retries = 10, delay = 1000) {
        let lastError = null;
        for (let i = 0; i < retries; i++) {
            try {
                const response = await fetch(url, options);
                if (!response.ok) {
                    // 网络或服务器层面的错误（比如 500 Internal Server Error）
                    throw new Error(`服务器响应失败: ${response.status}`);
                }

                // 直接解析JSON，不再检查 code 字段
                const data = await response.json();
                return data;

            } catch (error) {
                lastError = error;
                console.warn(`[Suno请求官] 尝试 ${i + 1}/${retries} 失败: ${error.message}. 将在 ${delay / 1000}秒后重试...`);

                if (i < retries - 1) {
                    await sleep(delay);
                }
            }
        }
        throw lastError;
    }

    const DEFAULT_ALBUM_ART_URL = `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300">' +
        '<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">' +
        '<stop offset="0%" stop-color="#eff4fb"/><stop offset="100%" stop-color="#c8d7ee"/>' +
        '</linearGradient></defs>' +
        '<rect width="300" height="300" rx="36" fill="url(#bg)"/>' +
        '<circle cx="150" cy="150" r="98" fill="#18202d"/>' +
        '<circle cx="150" cy="150" r="52" fill="#f8fbff"/>' +
        '<path d="M176 86v85a31 31 0 1 1-18-27.9V111l58-10v66.2a31 31 0 1 1-18-27.9V86z" fill="#76a7ff"/>' +
        '</svg>'
    )}`;

    function buildAlbumCoverSrc(coverUrl, size = '100y100') {
        const source = typeof coverUrl === 'string' && coverUrl.trim()
            ? coverUrl.trim()
            : DEFAULT_ALBUM_ART_URL;

        if (!source || source === 'null' || source === 'undefined') {
            return DEFAULT_ALBUM_ART_URL;
        }
        if (source.startsWith('data:') || source.startsWith('blob:')) {
            return source;
        }
        if (!/^https?:\/\//i.test(source)) {
            return source;
        }

        try {
            const parsed = new URL(source);
            if (/music\.126\.net$/i.test(parsed.hostname)) {
                parsed.searchParams.set('param', size);
                return parsed.toString();
            }
        } catch (_) {
            return source;
        }

        return source;
    }

    function bindAlbumCoverFallback(imageElement) {
        if (!imageElement) return;
        imageElement.addEventListener('error', () => {
            if (imageElement.dataset.fallbackApplied === '1') return;
            imageElement.dataset.fallbackApplied = '1';
            imageElement.src = DEFAULT_ALBUM_ART_URL;
        });
    }

    const DEFAULT_MUSIC_API_BASE_URLS = [];
    const DEFAULT_MUSIC_API_BASE_URL = DEFAULT_MUSIC_API_BASE_URLS[0];
    let musicQrLoginState = {
        key: '',
        pollTimer: null
    };

    function ensureMusicBackendSettings() {
        if (!appData.appSettings) appData.appSettings = {};
        if (typeof appData.appSettings.musicApiBaseUrl !== 'string') appData.appSettings.musicApiBaseUrl = '';
        if (typeof appData.appSettings.musicLoginCookie !== 'string') appData.appSettings.musicLoginCookie = '';
        if (typeof appData.appSettings.musicSessionToken !== 'string') appData.appSettings.musicSessionToken = '';
        if (appData.appSettings.musicSessionProfile === undefined) appData.appSettings.musicSessionProfile = null;
        if (isRemovedNetlifyMusicApiBaseUrl(appData.appSettings.musicApiBaseUrl)) {
            appData.appSettings.musicApiBaseUrl = '';
        }
        return appData.appSettings;
    }

    function getMusicApiBaseUrl() {
        const settings = ensureMusicBackendSettings();
        return (settings.musicApiBaseUrl || DEFAULT_MUSIC_API_BASE_URL || '').trim().replace(/\/+$/, '');
    }

    function getMusicSessionToken() {
        const settings = ensureMusicBackendSettings();
        const cookie = (settings.musicLoginCookie || '').trim();
        if (cookie) return cookie;
        const legacyToken = (settings.musicSessionToken || '').trim();
        return /(?:^|;\s*)MUSIC_U=/.test(legacyToken) ? legacyToken : '';
    }

    function setMusicSession(sessionCookie = '', sessionProfile = null) {
        const settings = ensureMusicBackendSettings();
        const cookie = (sessionCookie || '').trim();
        settings.musicLoginCookie = cookie;
        settings.musicSessionToken = cookie ? 'direct-netease-cookie' : '';
        settings.musicSessionProfile = sessionProfile || null;
        saveAppData();
    }

    function setMusicApiBaseUrl(baseUrl = '') {
        const settings = ensureMusicBackendSettings();
        settings.musicApiBaseUrl = (baseUrl || '').trim().replace(/\/+$/, '');
        saveAppData();
    }

    function buildMusicApiUrl(path, query = {}) {
        const baseUrl = getMusicApiBaseUrl();
        if (!baseUrl) {
            throw new Error('请先填写网易云 API Endpoint');
        }

        const url = new URL(path, `${baseUrl}/`);
        Object.entries(query || {}).forEach(([key, value]) => {
            if (value === undefined || value === null || value === '') return;
            url.searchParams.set(key, String(value));
        });
        return url.toString();
    }

    function normalizeMusicApiError(error) {
        if (!error) {
            return new Error('音乐服务暂时不可用，请稍后再试');
        }

        if (error.status === 401) {
            const authError = new Error('网易云登录已失效，请重新登录后再试');
            authError.status = error.status;
            authError.payload = error.payload;
            return authError;
        }

        const message = String(error.message || '').trim();
        const isNetworkError = (
            error.name === 'TypeError' ||
            /Failed to fetch/i.test(message) ||
            /NetworkError/i.test(message) ||
            /Load failed/i.test(message) ||
            /ERR_FAILED/i.test(message)
        );

        if (isNetworkError) {
            const networkError = new Error('当前网络无法连接音乐服务，请开启代理后重试');
            networkError.status = error.status;
            networkError.payload = error.payload;
            return networkError;
        }

        return error;
    }

    async function fetchMusicApi(path, options = {}) {
        const {
            method = 'GET',
            query = null,
            body = null,
            headers = {},
            requireSession = false,
            retryCount = 2
        } = options;

        const token = getMusicSessionToken();
        if (requireSession && !token) {
            throw new Error('请先扫码登录网易云账号');
        }

        const requestHeaders = { ...headers };
        if (token) {
            requestHeaders.Authorization = `Bearer ${token}`;
        }
        if (body !== null && !requestHeaders['Content-Type']) {
            requestHeaders['Content-Type'] = 'application/json';
        }

        const requestInit = {
            method,
            headers: requestHeaders
        };
        if (body !== null) {
            requestInit.body = typeof body === 'string' ? body : JSON.stringify(body);
        }

        let lastError = null;
        for (let attempt = 0; attempt < retryCount; attempt += 1) {
            try {
                const response = await fetch(buildMusicApiUrl(path, query || {}), requestInit);
                const text = await response.text();
                let payload = {};

                try {
                    payload = text ? JSON.parse(text) : {};
                } catch (parseError) {
                    payload = { ok: false, error: text || `请求失败: ${response.status}` };
                }

                if (!response.ok || payload.ok === false) {
                    const baseMessage = payload.error || payload.message || `请求失败: ${response.status}`;
                    const detailMessage = payload && payload.details && typeof payload.details === 'object'
                        ? (payload.details.message || payload.details.error || '')
                        : '';
                    const detailStatus = payload && payload.details && typeof payload.details === 'object'
                        ? payload.details.status
                        : null;
                    let finalMessage = baseMessage;

                    if (detailMessage && !String(baseMessage).includes(String(detailMessage))) {
                        finalMessage = `${baseMessage}: ${detailMessage}`;
                    } else if (!detailMessage && detailStatus) {
                        finalMessage = `${baseMessage} (上游状态 ${detailStatus})`;
                    }

                    const error = new Error(finalMessage);
                    error.status = response.status;
                    error.payload = payload;
                    throw error;
                }

                return payload.data !== undefined ? payload.data : payload;
            } catch (error) {
                lastError = normalizeMusicApiError(error);
                if (attempt < retryCount - 1) {
                    await sleep(500);
                }
            }
        }

        throw lastError || new Error('音乐服务请求失败');
    }

    function normalizeMusicApiBaseUrl(baseUrl = '') {
        const rawValue = String(baseUrl || '').trim();
        if (!rawValue) return '';
        if (/^\/(?!\/)/.test(rawValue) && typeof window !== 'undefined' && window.location && window.location.origin) {
            return new URL(rawValue, `${window.location.origin}/`).toString().replace(/\/+$/, '');
        }
        return rawValue.replace(/\/+$/, '');
    }

    function isRemovedNetlifyMusicApiBaseUrl(baseUrl = '') {
        const normalized = normalizeMusicApiBaseUrl(baseUrl);
        if (!normalized) return false;
        if (/\/\.netlify\/functions\/music-api\/?$/i.test(normalized)) return true;
        try {
            const parsed = new URL(normalized);
            return /\/\.netlify\/functions\/music-api\/?$/i.test(parsed.pathname || '');
        } catch (_) {
            return false;
        }
    }

    function getDefaultMusicApiBaseUrls() {
        return [...new Set((DEFAULT_MUSIC_API_BASE_URLS || [])
            .map((item) => normalizeMusicApiBaseUrl(item))
            .filter(Boolean))];
    }

    function isDefaultMusicApiBaseUrl(baseUrl = '') {
        const normalized = normalizeMusicApiBaseUrl(baseUrl);
        if (!normalized) return false;
        return getDefaultMusicApiBaseUrls().includes(normalized);
    }

    function getMusicApiBaseUrl() {
        const settings = ensureMusicBackendSettings();
        return normalizeMusicApiBaseUrl(settings.musicApiBaseUrl || '');
    }

    function getMusicApiBaseUrlCandidates() {
        const settings = ensureMusicBackendSettings();
        const savedBaseUrl = isRemovedNetlifyMusicApiBaseUrl(settings.musicApiBaseUrl)
            ? ''
            : normalizeMusicApiBaseUrl(settings.musicApiBaseUrl || '');
        const defaultBaseUrls = getDefaultMusicApiBaseUrls();
        const candidates = [];

        const pushCandidate = (baseUrl, isCustom = false) => {
            if (!baseUrl || candidates.some((candidate) => candidate.baseUrl === baseUrl)) return;
            candidates.push({
                baseUrl,
                isDefault: isDefaultMusicApiBaseUrl(baseUrl),
                isCustom
            });
        };

        if (savedBaseUrl) {
            pushCandidate(savedBaseUrl, !isDefaultMusicApiBaseUrl(savedBaseUrl));
        }

        defaultBaseUrls.forEach((baseUrl) => pushCandidate(baseUrl, false));

        return candidates;
    }

    function setMusicApiBaseUrl(baseUrl = '') {
        const settings = ensureMusicBackendSettings();
        settings.musicApiBaseUrl = normalizeMusicApiBaseUrl(baseUrl);
        saveAppData();
    }

    function buildMusicApiUrlWithBase(baseUrl, path, query = {}) {
        const normalizedBaseUrl = normalizeMusicApiBaseUrl(baseUrl);
        if (!normalizedBaseUrl) {
            throw new Error('音乐服务暂未配置完成');
        }

        const normalizedPath = String(path || '').startsWith('/') ? String(path || '') : `/${String(path || '')}`;
        const url = new URL(normalizedPath, `${normalizedBaseUrl}/`);
        Object.entries(query || {}).forEach(([key, value]) => {
            if (value === undefined || value === null || value === '') return;
            url.searchParams.set(key, String(value));
        });
        return url.toString();
    }

    function buildMusicApiUrl(path, query = {}) {
        return buildMusicApiUrlWithBase(getMusicApiBaseUrl(), path, query);
    }

    function getMusicLoginCookie() {
        return getMusicSessionToken();
    }

    function buildMusicApiQuery(query = {}, options = {}) {
        const { includeCookie = true, addTimestamp = true } = options;
        const finalQuery = { ...(query || {}) };
        if (includeCookie) {
            const cookie = getMusicLoginCookie();
            if (cookie && finalQuery.cookie === undefined) {
                finalQuery.cookie = cookie;
            }
        }
        if (addTimestamp && finalQuery.timestamp === undefined) {
            finalQuery.timestamp = Date.now();
        }
        return finalQuery;
    }

    function extractMusicApiErrorDetailText(payload) {
        if (!payload || typeof payload !== 'object') return '';

        const details = payload.details;
        if (!details) return '';
        if (typeof details === 'string') return details.trim();
        if (typeof details !== 'object') return '';

        return [
            details.message,
            details.error,
            details.code,
            details.status
        ].filter(value => value !== undefined && value !== null && String(value).trim() !== '').join(' ');
    }

    function isMusicApiNetworkError(error) {
        const message = String(error && error.message || '').trim();
        return Boolean(
            error && (
                error.name === 'TypeError' ||
                /Failed to fetch/i.test(message) ||
                /NetworkError/i.test(message) ||
                /Load failed/i.test(message) ||
                /ERR_FAILED/i.test(message) ||
                /fetch failed/i.test(message) ||
                /timed out/i.test(message)
            )
        );
    }

    function isMusicApiBackendConfigErrorMessage(message = '') {
        const text = String(message || '').trim();
        if (!text) return false;
        return (
            /Missing env var/i.test(text) ||
            /D1 binding/i.test(text) ||
            /missing_backend_config/i.test(text)
        );
    }

    function isLikelyWrongMusicBackendResponse(error) {
        if (!error) return false;

        const payload = error.payload && typeof error.payload === 'object' ? error.payload : {};
        const message = [
            error.message,
            error.responseText,
            payload.code,
            payload.error,
            payload.message,
            extractMusicApiErrorDetailText(payload)
        ].map(value => String(value || '').trim()).filter(Boolean).join(' | ');

        if (!message) return false;
        if (/Application not found/i.test(message)) return true;
        if (/Unknown route/i.test(message)) return true;
        if (isMusicApiBackendConfigErrorMessage(message)) return true;
        if (/\bnot[_ -]?found\b/i.test(String(payload.code || ''))) return true;
        if (/<!doctype html|<html[\s>]/i.test(message)) return true;
        if ((error.status === 404 || error.status === 405) && /\/music\//i.test(String(error.musicApiPath || ''))) return true;
        return false;
    }

    function syncMusicApiBaseUrlInputValue(baseUrl = '') {
        const input = document.getElementById('music-api-base-url-input');
        if (input) {
            input.value = normalizeMusicApiBaseUrl(baseUrl);
        }
    }

    function buildMusicApiResponseError(response, payload, responseText, baseUrl, path) {
        const baseMessage = payload.error || payload.message || `请求失败: ${response.status}`;
        const detailMessage = extractMusicApiErrorDetailText(payload);
        const detailStatus = payload && payload.details && typeof payload.details === 'object'
            ? payload.details.status
            : null;
        let finalMessage = baseMessage;
        if (/<!doctype html|<html[\s>]/i.test(String(responseText || '')) || /<!doctype html|<html[\s>]/i.test(String(baseMessage || ''))) {
            finalMessage = `音乐后端地址无效或路径不存在 (${response.status})`;
        }

        if (detailMessage && !String(baseMessage).includes(String(detailMessage))) {
            finalMessage = `${baseMessage}: ${detailMessage}`;
        } else if (!detailMessage && detailStatus) {
            finalMessage = `${baseMessage} (上游状态: ${detailStatus})`;
        }

        const error = new Error(finalMessage);
        error.status = response.status;
        error.payload = payload;
        error.responseText = responseText;
        error.musicApiBaseUrl = baseUrl;
        error.musicApiPath = path;
        return error;
    }

    function normalizeMusicApiError(error) {
        if (!error) {
            return new Error('音乐服务暂时不可用，请稍后再试');
        }

        if (error.status === 401) {
            const authError = new Error('网易云登录已失效，请重新登录后再试');
            authError.status = error.status;
            authError.payload = error.payload;
            return authError;
        }

        if (isMusicApiNetworkError(error)) {
            const apiBase = error.musicApiBaseUrl ? `\n当前地址：${error.musicApiBaseUrl}` : '';
            const networkError = new Error(`当前网络无法连接音乐服务，请检查网络/VPN或音乐后端地址后重试${apiBase}`);
            networkError.status = error.status;
            networkError.payload = error.payload;
            networkError.musicApiBaseUrl = error.musicApiBaseUrl;
            networkError.musicApiPath = error.musicApiPath;
            return networkError;
        }

        const message = String(error.message || '').trim();
        if (
            /Application not found/i.test(message) ||
            /Unknown route/i.test(message) ||
            /音乐后端地址无效|路径不存在/i.test(message) ||
            /<!doctype html|<html[\s>]/i.test(message) ||
            isMusicApiBackendConfigErrorMessage(message)
        ) {
            const backendError = new Error('音乐后端暂时不可用，请检查音乐后端地址');
            backendError.status = error.status;
            backendError.payload = error.payload;
            return backendError;
        }

        return error;
    }

async function requestMusicApi(baseUrl, path, query, requestInit) {
        let response;
        try {
            response = await fetch(buildMusicApiUrlWithBase(baseUrl, path, query || {}), requestInit);
        } catch (error) {
            error.musicApiBaseUrl = baseUrl;
            error.musicApiPath = path;
            throw error;
        }
        const responseText = await response.text();
        let payload = {};

        try {
            payload = responseText ? JSON.parse(responseText) : {};
        } catch (parseError) {
            payload = { ok: false, error: responseText || `请求失败: ${response.status}` };
        }

        if (!response.ok || payload.ok === false) {
            throw buildMusicApiResponseError(response, payload, responseText, baseUrl, path);
        }

        return payload.data !== undefined ? payload.data : payload;
    }

    async function fetchMusicApi(path, options = {}) {
        const {
            method = 'GET',
            query = null,
            body = null,
            headers = {},
            requireSession = false,
            retryCount = 2,
            includeCookie = true,
            addTimestamp = true
        } = options;

        const cookie = getMusicLoginCookie();
        if (requireSession && !cookie) {
            throw new Error('请先扫码登录网易云账号');
        }

        const requestHeaders = { ...headers };
        if (body !== null && !requestHeaders['Content-Type']) {
            requestHeaders['Content-Type'] = 'application/json';
        }

        const requestInit = {
            method,
            headers: requestHeaders
        };
        if (body !== null) {
            requestInit.body = typeof body === 'string' ? body : JSON.stringify(body);
        }

        const baseUrl = getMusicApiBaseUrl();
        if (!baseUrl) {
            throw new Error('请先填写网易云 API Endpoint');
        }

        const finalQuery = buildMusicApiQuery(query || {}, {
            includeCookie: includeCookie && Boolean(cookie),
            addTimestamp
        });
        let lastError = null;

        for (let attempt = 0; attempt < retryCount; attempt += 1) {
            try {
                return await requestMusicApi(baseUrl, path, finalQuery, requestInit);
            } catch (error) {
                lastError = normalizeMusicApiError(error);
                if (attempt < retryCount - 1) {
                    await sleep(500);
                }
            }
        }

        throw lastError || new Error('音乐服务请求失败');
    }

    function normalizeNeteaseArtistList(artists) {
        return (Array.isArray(artists) ? artists : [])
            .map(item => item && item.name)
            .filter(Boolean)
            .join(' / ');
    }

    function normalizeWorkerSong(song) {
        if (!song || !song.id) return null;

        const rawArtists = Array.isArray(song.singerList)
            ? song.singerList.map(item => item && item.name).filter(Boolean).join(' / ')
            : '';
        const neteaseArtists = normalizeNeteaseArtistList(song.ar || song.artists);
        const album = song.al || song.album || {};

        return {
            ...song,
            id: String(song.id),
            song: song.song || song.name || '未知歌曲',
            singer: song.singer || rawArtists || neteaseArtists || '未知歌手',
            cover: song.cover || album.picUrl || album.blurPicUrl || DEFAULT_ALBUM_ART_URL,
            duration: Number(song.duration || song.time || song.dt || 0) || 0,
            url: song.url || ''
        };
    }

    function escapeHtml(text) {
        return String(text == null ? '' : text).replace(/[&<>"']/g, (char) => ({
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;'
        }[char]));
    }

    function hideSearchCitationMarkers(text) {
        if (typeof text !== 'string' || !text) return text;
        return text
            .replace(/[ \t]*\[(?:\s*\d+\s*)(?:,\s*\d+\s*)*\](?=[ \t]*(?:$|[\r\n]|[，。！？；：,.!?;)）]))/g, '')
            .replace(/[ \t]+([，。！？；：,.!?;)）])/g, '$1')
            .replace(/\n{3,}/g, '\n\n')
            .trim();
    }

