    async function refreshMusicBackendSessionStatus(options = {}) {
        const { silent = false, forceRefresh = false } = options;

        if (!getMusicApiBaseUrl()) {
            renderMusicBackendSessionStatus(null, '请先填写网易云 API Endpoint');
            if (!silent) showToast('请先填写网易云 API Endpoint', 'info');
            return null;
        }

        if (!getMusicLoginCookie()) {
            renderMusicBackendSessionStatus(null, '还没有扫码登录网易云');
            if (!silent) showToast('还没有登录网易云', 'info');
            return null;
        }

        try {
            const statusPayload = await fetchMusicApi('/login/status', {
                method: 'POST',
                query: forceRefresh ? { refresh: 1 } : null,
                body: { cookie: getMusicLoginCookie() },
                requireSession: true,
                includeCookie: false,
                retryCount: 1
            });
            const profile = normalizeMusicProfile(statusPayload);
            if (!profile) throw new Error('当前登录态没有拿到账号资料，请重新扫码登录');
            setMusicSession(getMusicLoginCookie(), profile);
            renderMusicBackendSessionStatus(profile);
            if (!silent) showToast(`当前网易云账号：${profile.nickname || '已连接'}`, 'success');
            return profile;
        } catch (error) {
            renderMusicBackendSessionStatus(null, error.message);
            if (!silent) showToast(error.message, 'error');
            return null;
        }
    }

    async function importMusicBackendCookie(cookieText) {
        const musicU = (cookieText || '').trim();
        if (!musicU) {
            throw new Error('没有可用的网易云登录态，请先扫码登录');
        }

        setMusicSession(musicU, null);
        return refreshMusicBackendSessionStatus({ forceRefresh: true });
    }

    async function startMusicQrLogin() {
        const endpointInput = document.getElementById('music-api-endpoint-modal-input');
        const endpointValue = endpointInput ? endpointInput.value.trim() : getMusicApiBaseUrl();
        const normalizedEndpoint = normalizeMusicApiBaseUrl(endpointValue);
        if (!normalizedEndpoint) {
            renderMusicBackendSessionStatus(null, '请先填写网易云 API Endpoint');
            showToast('请先填写网易云 API Endpoint', 'info');
            return;
        }

        setMusicApiBaseUrl(normalizedEndpoint);
        syncMusicApiEndpointInputs(normalizedEndpoint);
        stopMusicQrLoginPolling();
        setMusicQrLoginImage('');
        setMusicQrLoginMessage('正在生成二维码...');

        try {
            const keyPayload = await fetchMusicApi('/login/qr/key', {
                includeCookie: false,
                retryCount: 1
            });
            const key = keyPayload && keyPayload.data && keyPayload.data.unikey
                ? keyPayload.data.unikey
                : keyPayload.unikey;
            if (!key) throw new Error('二维码 key 获取失败，请检查 API Endpoint 是否可用');

            const qrPayload = await fetchMusicApi('/login/qr/create', {
                query: { key, qrimg: true },
                includeCookie: false,
                retryCount: 1
            });
            const qrImage = qrPayload && qrPayload.data && (qrPayload.data.qrimg || qrPayload.data.qrurl)
                ? (qrPayload.data.qrimg || qrPayload.data.qrurl)
                : (qrPayload.qrimg || qrPayload.qrurl || '');
            if (!qrImage) throw new Error('二维码生成失败，请稍后再试');

            musicQrLoginState.key = key;
            setMusicQrLoginImage(qrImage);
            setMusicQrLoginMessage('请用网易云音乐 App 扫码，并在手机上确认登录。');
            musicQrLoginState.pollTimer = setInterval(() => {
                checkMusicQrLoginStatus().catch((error) => {
                    stopMusicQrLoginPolling();
                    setMusicQrLoginMessage(error.message);
                    renderMusicBackendSessionStatus(null, error.message);
                });
            }, 3000);
            await checkMusicQrLoginStatus();
        } catch (error) {
            stopMusicQrLoginPolling();
            setMusicQrLoginMessage(error.message);
            renderMusicBackendSessionStatus(null, error.message);
            showToast(error.message, 'error');
        }
    }

    async function checkMusicQrLoginStatus() {
        const key = musicQrLoginState.key;
        if (!key) return null;

        const statusPayload = await fetchMusicApi('/login/qr/check', {
            query: { key },
            includeCookie: false,
            retryCount: 1
        });
        const statusCode = Number(statusPayload && statusPayload.code);

        if (statusCode === 800) {
            stopMusicQrLoginPolling();
            setMusicQrLoginMessage('二维码已过期，请重新生成。');
            return statusPayload;
        }
        if (statusCode === 801) {
            setMusicQrLoginMessage('等待扫码...');
            return statusPayload;
        }
        if (statusCode === 802) {
            setMusicQrLoginMessage('已扫码，等待你在手机上确认。');
            return statusPayload;
        }
        if (statusCode === 803) {
            const cookie = statusPayload.cookie || (statusPayload.data && statusPayload.data.cookie) || '';
            if (!cookie) throw new Error('登录成功但没有返回 Cookie，请检查 API 部署版本');

            stopMusicQrLoginPolling();
            setMusicSession(cookie, null);
            setMusicQrLoginMessage('登录成功，正在同步账号资料...');
            renderMusicBackendSessionStatus(null, '登录成功，正在同步账号资料...');
            const profile = await refreshMusicBackendSessionStatus({ silent: true, forceRefresh: true });
            renderMusicBackendSettingsSummary();
            renderSettingsHubSummaries();
            showToast(`已连接网易云账号：${profile && profile.nickname ? profile.nickname : '登录成功'}`, 'success');
            setMusicQrLoginMessage('登录成功');
            return statusPayload;
        }

        setMusicQrLoginMessage(statusPayload && statusPayload.message ? statusPayload.message : '等待扫码确认...');
        return statusPayload;
    }

    async function clearMusicBackendSession() {
        const token = getMusicLoginCookie();
        if (token && getMusicApiBaseUrl()) {
            try {
                await fetchMusicApi('/logout', {
                    requireSession: true,
                    retryCount: 1
                });
            } catch (error) {
                console.warn('清除音乐会话时后端返回错误，将继续清理本地状态', error);
            }
        }

        setMusicSession('', null);
        stopMusicQrLoginPolling();
        setMusicQrLoginImage('');
        setMusicQrLoginMessage('已退出登录。');
        renderMusicBackendSessionStatus(null, '音乐会话已清除');
    }
