    /**
         * 【歌词大脑 #1 v1.1】根据歌曲ID获取并解析歌词 (已修复代理请求)
         */
    async function fetchAndParseLyrics(songId) {
        const lyricsList = document.getElementById('lyrics-list');
        lyricsList.innerHTML = '<li class="lyric-line active">歌词加载中...</li>';
        currentLyrics = [];

        try {
            const data = await fetchLyricsFromMusicBackend(songId);
            const lyricText = data.lrc || data.yrc || data.tlyric || '';
            if (!lyricText) throw new Error('没有找到歌词');

            currentLyrics = parseLrc(lyricText);
            lyricsList.innerHTML = '';

            if (currentLyrics.length === 0) {
                const plainLines = lyricText
                    .split('\n')
                    .map(line => line.replace(/\[[^\]]+\]/g, '').trim())
                    .filter(Boolean);

                if (plainLines.length === 0) {
            lyricsList.innerHTML = '';
                    return;
                }

                lyricsList.innerHTML = plainLines.map(line => `<li class="lyric-line">${line}</li>`).join('');
                return;
            }

            currentLyrics.forEach(line => {
                const li = document.createElement('li');
                li.className = 'lyric-line';
                li.textContent = line.text;
                li.dataset.time = line.time;
                lyricsList.appendChild(li);
            });
        } catch (error) {
            console.error(`获取歌词最终失败:`, error);
            lyricsList.innerHTML = `<li class="lyric-line active">${error.message}</li>`;
        }
    }

    /**
     * 【歌词大脑 #2】解析LRC格式的歌词文本
     */
    function parseLrc(lrcText) {
        const lines = lrcText.split('\n');
        const result = [];
        const timeRegex = /\[(\d{2}):(\d{2})\.(\d{2,3})\]/;

        for (const line of lines) {
            const match = line.match(timeRegex);
            if (match) {
                const minutes = parseInt(match[1], 10);
                const seconds = parseInt(match[2], 10);
                const milliseconds = parseInt(match[3], 10);
                const time = minutes * 60 + seconds + milliseconds / 1000;
                const text = line.replace(timeRegex, '').trim();
                if (text) {
                    result.push({ time, text });
                }
            }
        }
        return result;
    }

    /**
     * 【歌词大脑 #3 v2.0】根据当前播放时间，更新歌词高亮和滚动 (已植入“智能避让”系统)
     */
    function updateLyrics() {
        if (!audioPlayer || audioPlayer.paused || currentLyrics.length === 0) {
            return;
        }

        const currentTime = audioPlayer.currentTime;
        const lyricsContainer = document.querySelector('.lyrics-container'); // 【核心修正】我们现在直接操作父容器
        const lyricsList = document.getElementById('lyrics-list');

        let currentIndex = currentLyrics.findIndex(line => line.time > currentTime) - 1;
        if (currentIndex < 0) {
            if (currentTime > currentLyrics[currentLyrics.length - 1].time) {
                currentIndex = currentLyrics.length - 1;
            } else {
                currentIndex = 0;
            }
        }

        const activeLine = lyricsList.querySelector('.active');
        if (activeLine) {
            activeLine.classList.remove('active');
        }

        const newLine = lyricsList.children[currentIndex];
        if (newLine && !newLine.classList.contains('active')) {
            newLine.classList.add('active');

            // 在尝试滚动前，先检查用户是否挂上了“请勿打扰”的牌子
                // 计算目标滚动位置，让高亮行尽量保持在容器的中央
            if (!isUserScrolling) {
                const containerHeight = lyricsContainer.clientHeight;
                const lineTop = newLine.offsetTop; // 获取当前歌词相对于列表顶部的距离
                const listScrollTop = lyricsContainer.scrollTop; // 获取列表当前的滚动位置

                // 平滑滚动效果
                const targetScrollTop = lineTop - (containerHeight / 2) + (newLine.offsetHeight / 2);

                // 成功时的回调
                lyricsContainer.scrollTo({
                    top: targetScrollTop,
                    behavior: 'smooth'
                });
            }
        }
    }

