    /**
     * 【装修工 #1 v3.0】渲染AI的听歌历史 (职责修正版)
     */
    async function renderAiListeningHistory() {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        const container = document.getElementById('ai-profile-history-content');

        // 【核心修正】我们不再在这里检查和生成数据，只负责渲染！
        if (!contact || !container) return;
        const history = Array.isArray(contact.musicProfile.listeningHistory) ? contact.musicProfile.listeningHistory : [];
        if (!history || history.length === 0) {
            container.innerHTML = isAiMusicHistoryPending(contact)
                ? '<p class="placeholder-text">有新的听歌历史待刷新，点击上方“主页”标签即可生成。</p>'
                : '<p class="placeholder-text">TA最近好像什么都没听...</p>';
            return;
        }

        container.innerHTML = '';
        history.forEach(item => {
            const historyItem = document.createElement('div');
            historyItem.className = 'ai-history-item';
            historyItem.dataset.songId = item.song.id;

            const songItemHTML = `
                <div class="music-result-item">
                    <img src="${buildAlbumCoverSrc(item.song.cover)}" class="album-cover">
                    <div class="song-details">
                        <span class="song-title">${item.song.song}</span>
                        <span class="song-artist">${item.song.singer}</span>
                    </div>
                    <span class="play-count">播放了 ${item.playCount} 次</span>
                    <div class="song-actions">
                         <button class="song-action-btn play" title="播放">
                            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"></path></svg>
                         </button>
                    </div>
                </div>
            `;

            const contextHTML = `
                <div class="ai-history-details">
                    <div class="ai-history-context">
                        <p><strong>TA为什么听:</strong> ${item.reason}</p>
                        <p><strong>TA的内心活动:</strong> *${item.thoughts}*</p>
                    </div>
                </div>
            `;

            historyItem.innerHTML = songItemHTML + contextHTML;
            bindAlbumCoverFallback(historyItem.querySelector('.album-cover'));
            container.appendChild(historyItem);
        });
    }

