    /**
     * 【辅助函数】根据关键词搜索并只返回第一条歌曲数据
     */
    async function searchAndGetFirstSong(query) {
        if (!query) return null;
        try {
            return (await searchSongsFromMusicBackend(query, 1))[0] || null;
        } catch (error) {
            console.error(`搜索歌曲 "${query}" 失败:`, error);
            return null;
        }
    }
