        const modeSelect = document.getElementById('song-creation-mode');
        const autoLyricsPanel = document.getElementById('auto-lyrics-panel');
        const customLyricsPanel = document.getElementById('custom-lyrics-panel');

        const updatePanels = () => {
            const selectedMode = modeSelect.value;
            autoLyricsPanel.classList.toggle('hidden', selectedMode !== 'auto_lyrics');
            customLyricsPanel.classList.toggle('hidden', selectedMode !== 'custom');
        };

        modeSelect.removeEventListener('change', updatePanels); // 先移除旧监听器，防止重复绑定
