    /**
         * 【音乐API助理 #1】提交Suno音乐创作任务
         * @param {object} payload - 发送给API的JSON数据包
         * @returns {Promise<string>} - 返回任务ID (task_id)
         */
    async function createSunoTask(payload) {
        const SUNO_API_KEY = appData.appSettings.sunoApiKey;
        if (!SUNO_API_KEY) {
            throw new Error("请先在设置页面填写音乐生成API密钥！");
        }

        // 【核心改造】在这里，我们告诉Suno，歌曲做好了请送到这个地址
        const webhookPayload = {
            ...payload,
            webhook_url: 'https://noisy-horse-52.reikirk0229.deno.net/webhook'
        };

        const originalApiUrl = 'https://api.sunoapi.com/api/v1/suno/create';
        const proxyUrl = originalApiUrl.replace('https://api.sunoapi.com', 'https://noisy-horse-52.reikirk0229.deno.net');

        const response = await fetch(proxyUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${SUNO_API_KEY}`
            },
            // 我们现在发送的是包含了webhook地址的新数据包
            body: JSON.stringify(webhookPayload)
        });

        if (!response.ok) {
            const errorData = await response.json();
            throw new Error(`Suno API 错误: ${errorData.error || response.statusText}`);
        }

        const data = await response.json();

        // 【【【终极修复：安装 Task ID 出生证明检查站！】】】
        console.log('[Suno Create] >> 收到来自创建API的完整响应:', data);

        // 检查站：在返回之前，严格验证 task_id 是否存在且是一个有效的字符串。
        if (data && data.task_id && typeof data.task_id === 'string') {
            // 验证通过，是合法的新生儿，返回ID。
            return data.task_id;
        } else {
            // 验证失败，这不是一个合法的任务！立刻抛出错误，阻止后续的无效等待。
            throw new Error("Suno API未能返回有效的任务ID，创建失败。");
        }
    }

    /**
     * 【音乐API助理 #2】轮询Suno任务状态，直到歌曲生成
     * @param {string} taskId - 任务ID
     * @returns {Promise<Array>} - 返回包含一或两首歌曲数据的数组
     */
    /**
     * 【全新Webhook版】轮询我们自己的代理，等待歌曲生成结果
     * @param {string} taskId - 任务ID
     * @returns {Promise<Array>} - 返回包含一或两首歌曲数据的数组
     */
    async function pollOurOwnServerForResult(taskId) {
        const maxAttempts = 20; // 最多轮询20次（大约5分钟）
        const delay = 15000; // 每15秒问一次

        for (let i = 0; i < maxAttempts; i++) {
            await sleep(delay);
            try {
                // 我们现在访问的是Deno代理上的“取餐窗口”
                const response = await fetch(`https://noisy-horse-52.reikirk0229.deno.net/get-result?id=${taskId}`);

                if (!response.ok) {
                    console.warn(`[Webhook Poll] 查询结果失败 (尝试 ${i + 1}/${maxAttempts})`);
                    continue;
                }

                const result = await response.json();

                // 如果储物柜里有结果了 (不再是 'pending')
                if (result.status !== 'pending') {
                    // 检查Suno送来的结果是不是失败了
                    if (result.event === 'song.failed') {
                        throw new Error(result.message || 'Suno 歌曲生成失败。');
                    }
                    // 检查歌曲数据是否存在
                    if (result.data && result.data.length > 0) {
                        return result.data; // 成功！返回歌曲数据
                    }
                }
                // 如果还是 'pending'，循环会继续，15秒后再次查询
                console.log(`[Webhook Poll] 任务 ${taskId} 仍在处理中...`);

            } catch (error) {
                console.error(`[Webhook Poll] 查询结果时捕获到错误:`, error);
                // 【核心修复】将错误再次抛出，这样就能立刻终止 for 循环，
                // 并将失败信息传递给调用这个函数的地方。
                throw error;
            }
        }

        // 如果循环了20次还没结果，就判定为超时失败
        throw new Error("等待歌曲生成结果超时。");
    }
    /**
     * 【音乐API助理 #3】提交创建虚拟歌手（Persona）的任务
     * @param {object} payload - 包含name, description, continue_clip_id 的数据包
     * @returns {Promise<string>} - 返回创建成功后的 persona_id
     */
    async function createSunoPersona(payload) {
        const SUNO_API_KEY = appData.appSettings.sunoApiKey;
        if (!SUNO_API_KEY) {
            throw new Error("请先在设置页面填写音乐生成API密钥！");
        }
        const originalApiUrl = 'https://api.sunoapi.com/api/v1/suno/persona';
        // 【全新】同样，使用 Deno 中转站地址
        const proxyUrl = originalApiUrl.replace('https://api.sunoapi.com', 'https://noisy-horse-52.reikirk0229.deno.net');

        const response = await fetch(proxyUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${SUNO_API_KEY}`
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const errorData = await response.json();
            // 【【【终极修复：更智能的错误信息提取】】】
            // 尝试从多层结构中提取最具体的错误细节
            const details = errorData.details?.details?.detail || errorData.details?.error || errorData.error || response.statusText;
            throw new Error(`创建虚拟歌手失败: ${details}`);
        }

        const data = await response.json();
        if (data.code !== 200 || !data.persona_id) {
            throw new Error(`API返回错误: ${data.message || '未能获取persona_id'}`);
        }

        return data.persona_id;
    }

