    /**
     * 核心功能：获取并格式化天气数据，生成给AI看的“天气简报”
     */
    async function fetchAndFormatWeather(lat, lon) {
        try {
            console.log("天气系统：正在获取实时天气 (from Open-Meteo)...");
            const url = getOpenMeteoUrl(OPEN_METEO_FORECAST_URL, {
                latitude: String(lat),
                longitude: String(lon),
                current: 'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,weather_code,pressure_msl,surface_pressure,wind_speed_10m',
                daily: 'weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,uv_index_max,wind_speed_10m_max',
                timezone: 'auto',
                forecast_days: '7',
                temperature_unit: 'celsius',
                wind_speed_unit: 'ms',
                precipitation_unit: 'mm'
            });
            const weatherData = await fetchWeatherJson(url, 'Open-Meteo 天气同步错误');
            const current = weatherData.current || {};
            const currentMeta = getOpenMeteoWeatherMeta(current.weather_code, Number(current.is_day) !== 0);
            const forecastDays = buildForecastDaysFromOpenMeteo(weatherData);

            simpleWeatherData = {
                temp: Math.round(Number(current.temperature_2m || 0)),
                iconCode: currentMeta.iconCode
            };
            updateWeatherDisplay();

            let report = "## 用户的实时天气与环境报告\n";
            report += `### 当前实况: \n- **天气**: ${currentMeta.description}\n- **体感温度**: ${Number(current.apparent_temperature || current.temperature_2m || 0).toFixed(1)}°C (实际${Number(current.temperature_2m || 0).toFixed(1)}°C)\n- **风力**: ${getWindLevelText(current.wind_speed_10m)}\n`;
            report += "### 未来天气预报:\n";
            forecastDays.slice(0, 6).forEach(day => {
                report += `- **${day.dateLabel}**: ${day.description}，气温 ${day.tempMin}°C 到 ${day.tempMax}°C。\n`;
            });

            formattedWeatherData = report;
            console.log("天气系统：天气简报生成完毕！", formattedWeatherData);
            showToast('天气信息已同步！', 'success');

        } catch (error) {
            console.error("天气系统：获取天气数据时发生错误:", error);
            showToast(`天气同步失败: ${error.message}`, 'error');
            formattedWeatherData = "（天气信息获取失败，请检查网络或天气服务状态）";
        }
    }
