    function getSubscribedUserStickerGroups() {
        return Array.isArray(appData?.globalUserProfile?.selectedStickerGroups)
            ? appData.globalUserProfile.selectedStickerGroups
            : [];
    }

    function getAvailableUserStickers() {
        const groups = getSubscribedUserStickerGroups();
        const seenStickerIds = new Set();
        const stickers = [];

        groups.forEach((groupName) => {
            const groupStickers = Array.isArray(appData?.globalAiStickers?.[groupName])
                ? appData.globalAiStickers[groupName]
                : [];

            groupStickers.forEach((sticker) => {
                const stickerId = String(sticker?.id || '').trim();
                if (!stickerId || seenStickerIds.has(stickerId)) return;
                seenStickerIds.add(stickerId);

                const desc = String(sticker?.desc || '').trim() || '未命名表情';
                const aiId = String(sticker?.aiId || '').trim();
                const searchText = [desc, groupName, aiId].filter(Boolean).join(' ').toLowerCase();

                stickers.push({
                    ...sticker,
                    id: stickerId,
                    desc,
                    groupName,
                    searchText
                });
            });
        });

        return stickers;
    }

    async function getStickerPreviewUrl(stickerId) {
        const cacheKey = String(stickerId || '').trim();
        if (!cacheKey) return '';
        if (stickerPreviewUrlCache.has(cacheKey)) {
            return stickerPreviewUrlCache.get(cacheKey) || '';
        }

        const blob = await db.getImage(cacheKey);
        const previewUrl = blob ? URL.createObjectURL(blob) : '';
        stickerPreviewUrlCache.set(cacheKey, previewUrl);
        return previewUrl;
    }

    function showFullStickerDescription(stickerDesc) {
        const fullText = String(stickerDesc || '').trim();
        if (!fullText) return;

        if (typeof showCustomAlert === 'function') {
            showCustomAlert('表情描述', fullText);
            return;
        }

        if (typeof showToast === 'function') {
            showToast(fullText, 'info', 2600);
        }
    }

    function bindStickerItemPressActions(target, stickerDesc, onTap) {
        if (!target || typeof onTap !== 'function') return;

        let pressTimer = null;
        let suppressClickOnce = false;
        let startX = 0;
        let startY = 0;

        const clearPressTimer = () => {
            if (!pressTimer) return;
            clearTimeout(pressTimer);
            pressTimer = null;
        };

        const getPoint = (event) => {
            if (event?.touches?.[0]) return event.touches[0];
            if (event?.changedTouches?.[0]) return event.changedTouches[0];
            return event;
        };

        const beginPress = (event) => {
            if (event.type === 'mousedown' && event.button !== 0) return;

            const point = getPoint(event);
            startX = Number(point?.clientX) || 0;
            startY = Number(point?.clientY) || 0;
            suppressClickOnce = false;
            clearPressTimer();

            pressTimer = setTimeout(() => {
                pressTimer = null;
                suppressClickOnce = true;
                showFullStickerDescription(stickerDesc);
            }, 420);
        };

        const cancelPressIfMoved = (event) => {
            if (!pressTimer) return;
            const point = getPoint(event);
            const currentX = Number(point?.clientX) || 0;
            const currentY = Number(point?.clientY) || 0;
            if (Math.abs(currentX - startX) > 10 || Math.abs(currentY - startY) > 10) {
                clearPressTimer();
            }
        };

        const endPress = () => {
            clearPressTimer();
        };

        target.addEventListener('touchstart', beginPress, { passive: true });
        target.addEventListener('touchmove', cancelPressIfMoved, { passive: true });
        target.addEventListener('touchend', endPress, { passive: true });
        target.addEventListener('touchcancel', endPress, { passive: true });
        target.addEventListener('mousedown', beginPress);
        target.addEventListener('mousemove', cancelPressIfMoved);
        target.addEventListener('mouseup', endPress);
        target.addEventListener('mouseleave', endPress);
        target.addEventListener('contextmenu', (event) => {
            event.preventDefault();
        });
        target.addEventListener('click', async (event) => {
            event.preventDefault();
            event.stopPropagation();

            if (suppressClickOnce) {
                suppressClickOnce = false;
                return;
            }

            await onTap();
        });
    }

    function ensureSlashStickerSuggestionPanel() {
        ensureStickerAssistStyles();

        if (slashStickerSuggestionPanel && slashStickerSuggestionPanel.isConnected) {
            return slashStickerSuggestionPanel;
        }

        const inputRow = chatInput ? chatInput.closest('.input-row') : null;
        const panel = document.createElement('div');
        panel.id = 'slash-sticker-suggestion-panel';
        panel.className = 'slash-sticker-suggestion-panel hidden';

        if (inputRow && inputRow.parentNode) {
            inputRow.insertAdjacentElement('afterend', panel);
        } else if (userStickerPanel && userStickerPanel.parentNode) {
            userStickerPanel.parentNode.insertBefore(panel, userStickerPanel);
        }

        slashStickerSuggestionPanel = panel;
        return slashStickerSuggestionPanel;
    }

    function hideSlashStickerSuggestionPanel() {
        if (!slashStickerSuggestionPanel) return;
        slashStickerSuggestionPanel.classList.add('hidden');
        slashStickerSuggestionPanel.innerHTML = '';
    }

    function getSlashStickerQuery(value) {
        const normalizedText = String(value || '').trim();
        if (!normalizedText.startsWith('/')) return null;
        if (normalizedText.includes('\n')) return null;
        const rawQuery = normalizedText.slice(1).trim();
        if (!rawQuery) return '';
        return rawQuery.split(/\s+/)[0] || '';
    }

    function getMatchedSlashStickerResults(query) {
        const normalizedQuery = String(query || '').trim().toLowerCase();
        const availableStickers = getAvailableUserStickers();

        return availableStickers
            .map((sticker, index) => {
                if (!normalizedQuery) {
                    return { sticker, score: 1, index };
                }

                const desc = String(sticker.desc || '').toLowerCase();
                const searchText = String(sticker.searchText || '').toLowerCase();
                let score = 0;

                if (desc === normalizedQuery) score = 320;
                else if (desc.startsWith(normalizedQuery)) score = 240;
                else if (desc.includes(normalizedQuery)) score = 180;
                else if (searchText.includes(normalizedQuery)) score = 120;

                return { sticker, score, index };
            })
            .filter(item => item.score > 0)
            .sort((a, b) => {
                if (b.score !== a.score) return b.score - a.score;
                return a.index - b.index;
            });
    }

    async function renderSlashStickerSuggestions(query) {
        const panel = ensureSlashStickerSuggestionPanel();
        if (!panel) return;

        const matches = getMatchedSlashStickerResults(query);
        const limitedMatches = matches.slice(0, query ? 8 : 12);
        if (limitedMatches.length === 0) {
            hideSlashStickerSuggestionPanel();
            return;
        }

        const renderToken = ++slashStickerSuggestionRenderToken;
        panel.innerHTML = '';
        panel.classList.remove('hidden');

        limitedMatches.forEach(({ sticker }) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'slash-sticker-suggestion-item';
            button.title = sticker.desc;

            const img = document.createElement('img');
            img.alt = sticker.desc;

            const desc = document.createElement('div');
            desc.className = 'slash-sticker-suggestion-desc';
            desc.textContent = sticker.desc;

            button.appendChild(img);
            button.appendChild(desc);

            button.addEventListener('mousedown', (event) => {
                event.preventDefault();
                event.stopPropagation();
            });

            button.addEventListener('click', async (event) => {
                event.preventDefault();
                event.stopPropagation();
                if (chatInput) chatInput.value = '';
                hideSlashStickerSuggestionPanel();
                await sendStickerMessage(sticker);
            });

            panel.appendChild(button);

            getStickerPreviewUrl(sticker.id).then((previewUrl) => {
                if (renderToken !== slashStickerSuggestionRenderToken) return;
                if (previewUrl) img.src = previewUrl;
            }).catch(() => { });
        });
    }

    function refreshSlashStickerSuggestionsFromInput() {
        if (!chatInput) return;

        const query = getSlashStickerQuery(chatInput.value);
        if (query === null) {
            hideSlashStickerSuggestionPanel();
            return;
        }

        renderSlashStickerSuggestions(query).catch((error) => {
            console.error('[IDIC][StickerSlash] render failed', error);
            hideSlashStickerSuggestionPanel();
        });
    }

    function renderUserStickerPanel() {
        ensureStickerAssistStyles();
        userStickerPanel.innerHTML = ''; // 清空面板

        const subscribedGroups = getSubscribedUserStickerGroups();

        if (subscribedGroups.length === 0) {
            userStickerPanel.innerHTML = '<p class="placeholder-text" style="padding: 20px;">你还没有选择任何表情包分组，请到 设置 -> 我的表情包 中选择。</p>';
            return;
        }

        // 创建标签页容器和内容容器
        const tabsContainer = document.createElement('div');
        tabsContainer.className = 'sticker-panel-tabs';
        const contentContainer = document.createElement('div');
        contentContainer.className = 'sticker-panel-content';

        userStickerPanel.appendChild(tabsContainer);
        userStickerPanel.appendChild(contentContainer);

        // 遍历用户订阅的每个分组，创建对应的标签页和内容区
        subscribedGroups.forEach((groupName, index) => {
            const groupStickers = appData.globalAiStickers[groupName] || [];

            // 1. 创建标签按钮
            const tabButton = document.createElement('button');
            tabButton.className = 'sticker-tab-btn';
            tabButton.textContent = groupName;
            tabButton.dataset.targetTab = `tab-content-${index}`;
            tabsContainer.appendChild(tabButton);

            // 2. 创建标签对应的内容面板
            const tabContent = document.createElement('div');
            tabContent.className = 'sticker-grid sticker-tab-content';
            tabContent.id = `tab-content-${index}`;
            contentContainer.appendChild(tabContent);

            // 3. 填充表情包到内容面板
            groupStickers.forEach(sticker => {
                const stickerItem = document.createElement('div');
                stickerItem.className = 'sticker-item sticker-item-with-desc';
                const img = document.createElement('img');
                const stickerDescText = String(sticker?.desc || '').trim() || '未命名表情';
                img.alt = stickerDescText;
                img.title = stickerDescText;
                const desc = document.createElement('div');
                desc.className = 'sticker-item-desc';
                desc.textContent = stickerDescText;
                stickerItem.appendChild(img);
                stickerItem.appendChild(desc);

                // 异步从数据库加载图片
                getStickerPreviewUrl(sticker.id).then(previewUrl => {
                    if (previewUrl) img.src = previewUrl;
                });

                // 轻点发送，长按查看完整描述
                bindStickerItemPressActions(stickerItem, stickerDescText, async () => {
                    await sendStickerMessage(sticker);
                });

                tabContent.appendChild(stickerItem);
            });

            // 默认激活第一个标签页
            if (index === 0) {
                tabButton.classList.add('active');
                tabContent.classList.add('active');
            }
        });

        // 为标签页按钮添加点击切换逻辑
        tabsContainer.addEventListener('click', (e) => {
            if (e.target.classList.contains('sticker-tab-btn')) {
                // 移除所有按钮和内容的激活状态
                tabsContainer.querySelectorAll('.sticker-tab-btn').forEach(btn => btn.classList.remove('active'));
                contentContainer.querySelectorAll('.sticker-tab-content').forEach(content => content.classList.remove('active'));

                // 激活被点击的按钮和其对应的内容
                e.target.classList.add('active');
                document.getElementById(e.target.dataset.targetTab).classList.add('active');
            }
        });
    }
    async function sendStickerMessage(sticker) {
        userStickerPanel.classList.remove('is-open');
        hideSlashStickerSuggestionPanel();
        const stickerDesc = String(sticker?.desc || '').trim() || '未命名表情';
        await dispatchAndDisplayUserMessage({ content: `[表情] ${stickerDesc}`, type: 'sticker', stickerId: sticker.id });
    }

    // ================================================================
    // 【【【全新：次元币(钱包)系统核心逻辑】】】
    // ================================================================

    /**
     * 1. 核心：增加/消耗货币
     * @param {number} amount - 变动金额 (正数为加，负数为减)
     * @param {string} reason - 变动原因 (如: "与 xxx 聊天")
     */
    function updateCurrency(amount, reason, options = {}) {
        if (!appData.wallet) return;

        const now = Date.now();

        // 【智能合并逻辑】
        // 如果上一笔交易和这笔交易 原因相同 且 时间间隔小于 2分钟
        // 就不新增条目，而是直接合并到上一笔，让账单更清爽
        const lastTx = appData.wallet.transactions[0]; // 取最新的一笔
        if (lastTx && lastTx.reason === reason && (now - lastTx.timestamp < 2 * 60 * 1000)) {
            lastTx.amount += amount; // 合并金额
            lastTx.timestamp = now;  // 更新时间
        } else {
            // 否则，新增一笔记录
            appData.wallet.transactions.unshift({
                id: `tx-${now}-${Math.random()}`,
                amount: amount,
                reason: reason,
                timestamp: now
            });
        }

        // 限制账单记录数，只保留最近100条
        if (appData.wallet.transactions.length > 100) {
            appData.wallet.transactions.length = 100;
        }

        // 更新总余额
        appData.wallet.balance += amount;
        if (!options.skipSave) {
            saveAppData();
        }

        // 如果钱包页面正打开着，就刷新它
        const walletView = document.getElementById('wallet-view');
        if (walletView && !walletView.classList.contains('hidden')) {
            renderWalletView();
        }
    }

    /**
     * 2. 渲染钱包页面
     */
    function renderWalletView() {
        const balanceEl = document.getElementById('wallet-balance-display');
        const listEl = document.getElementById('wallet-transaction-list');
        const convertBox = document.getElementById('history-convert-box');
        const convertPreviewText = document.getElementById('convert-preview-text');

        // 渲染余额
        balanceEl.textContent = appData.wallet.balance;

        // 渲染兑换入口 (如果还没兑换过)
        if (!appData.wallet.hasConverted) {
            // 【核心修复】直接读取冻结的缓存数字
            const frozenCount = appData.wallet.legacyCache || 0;
            convertPreviewText.textContent = `当前累计对话约 ${frozenCount} 条，可兑换 ${frozenCount} 夸特`;
            convertBox.classList.remove('hidden');
        } else {
            convertBox.classList.add('hidden');
        }

        // 渲染账单列表
        listEl.innerHTML = '';
        if (appData.wallet.transactions.length === 0) {
            listEl.innerHTML = '<p class="placeholder-text" style="padding:20px;">暂无收支记录，快去聊天赚钱吧~</p>';
        } else {
            appData.wallet.transactions.forEach(tx => {
                const item = document.createElement('div');
                item.className = 'wallet-item';

                const isIncome = tx.amount > 0;
                const sign = isIncome ? '+' : '';
                const date = new Date(tx.timestamp);
                const timeStr = `${date.getMonth() + 1}-${date.getDate()} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;

                item.innerHTML = `
                    <div class="wallet-item-left">
                        <span class="wallet-item-reason">${tx.reason}</span>
                        <span class="wallet-item-time">${timeStr}</span>
                    </div>
                    <div class="wallet-item-amount ${isIncome ? 'income' : 'expense'}">${sign}${tx.amount}</div>
                `;
                listEl.appendChild(item);
            });
        }
    }

    /**
     * 3. 执行老用户一键兑换
     */
    function executeHistoryConversion() {
        showCustomConfirm(
            '确认兑换',
            '确定要将所有历史对话条数转换为夸特吗？\n此福利每个账号只能领取一次！',
            () => {
                // 【核心修复】直接读取冻结的缓存数字
                const totalMessages = appData.wallet.legacyCache || 0;

                if (totalMessages > 0) {
                    updateCurrency(totalMessages, "老用户历史数据回馈");
                    appData.wallet.hasConverted = true; // 标记为已领取
                    saveAppData();
                    renderWalletView(); // 刷新界面
                    showToast(`成功兑换 ${totalMessages} 夸特！`, 'success');
                } else {
                    showToast('没有可兑换的历史记录', 'info');
                }
            }
        );
    }
    // --- 3. 核心功能 ---
    // --- 【全新】全局Toast提示助手 ---
    let toastTimer;
    /**
     * 【全新 V2.0】多条并存 Toast 系统 (保留原版样式)
     */
    function showToast(message, type = 'info', duration = 3000) {
        // 1. 寻找或创建容器
        let container = document.getElementById('toast-container');
        if (!container) {
            container = document.createElement('div');
            container.id = 'toast-container';
            document.body.appendChild(container);
        }

        // 2. 创建新的 Toast 条目
        const toast = document.createElement('div');
        toast.className = `global-toast-item ${type}`; // 使用新定义的类名
        toast.textContent = message;

        // 3. 添加到容器
        container.appendChild(toast);

        // 4. 触发进场动画 (加一点延迟确保 transition 生效)
        requestAnimationFrame(() => {
            toast.classList.add('show');
        });

        // 5. 自动销毁逻辑
        if (duration > 0) {
            setTimeout(() => {
                toast.classList.remove('show'); // 退场动画
                // 等动画播完再从 DOM 移除
                setTimeout(() => {
                    if (toast.parentNode) toast.parentNode.removeChild(toast);
                }, 400);
            }, duration);
        }

        return toast;
    }

    function dismissToast(toast) {
        if (!toast || !toast.parentNode) return;
        toast.classList.remove('show');
        setTimeout(() => {
            if (toast.parentNode) toast.parentNode.removeChild(toast);
        }, 400);
    }

    const sleep = ms => new Promise(res => setTimeout(res, ms));

    async function runInBatches(items, worker, options = {}) {
        const source = Array.isArray(items) ? items : [];
        const concurrency = Math.max(1, Math.floor(Number(options.concurrency) || 1));
        const delayMs = Math.max(0, Math.floor(Number(options.delayMs) || 0));
        const results = [];
        for (let index = 0; index < source.length; index += concurrency) {
            const batch = source.slice(index, index + concurrency);
            const settled = await Promise.all(batch.map((item, batchIndex) => Promise.resolve()
                .then(() => worker(item, index + batchIndex))
                .catch(error => {
                    console.warn('[IDIC] 批量任务失败:', error && error.message ? error.message : error);
                    return null;
                })));
            results.push(...settled);
            if (delayMs > 0 && index + concurrency < source.length) {
                await sleep(delayMs);
            }
        }
        return results;
    }

    function formatMessageTimestamp(ts) {
        const date = new Date(ts);
        const now = new Date();
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const yesterday = new Date(today.getTime() - 86400000);
        let hours = date.getHours();
        const minutes = date.getMinutes().toString().padStart(2, '0');
        let timePeriod = '';
        if (hours < 12) timePeriod = '上午';
        else if (hours < 18) timePeriod = '下午';
        else timePeriod = '晚上';
        if (hours > 12) hours -= 12;
        if (hours === 0) hours = 12;
        const timeStr = `${timePeriod} ${hours}:${minutes}`;
        if (date >= today) {
            return timeStr;
        } else if (date >= yesterday) {
            return `昨天 ${timeStr}`;
        } else {
            return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${minutes}`;
        }
    }
    /**
     * 【【【全新辅助函数：将时间戳格式化为 YYYY-MM-DD】】】
     */
    function formatTimestampToDateString(timestamp) {
        if (!timestamp) return '';
        const date = new Date(timestamp);
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0'); // 月份从0开始，所以+1
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

