    function buildStoredImagePreviewOptions(role, text, options = {}) {
        const cleanText = String(options.aiDescription || text || '').trim();
        const metaParts = [];
        const generationMeta = options.imageGenerationMeta && typeof options.imageGenerationMeta === 'object'
            ? options.imageGenerationMeta
            : null;

        if (options.isDigested) {
            metaParts.push('记忆图像');
        }

        if (generationMeta) {
            const providerLabel = window.IDICImageGenerationBridge && typeof window.IDICImageGenerationBridge.getProviderLabel === 'function'
                ? window.IDICImageGenerationBridge.getProviderLabel(generationMeta.provider)
                : String(generationMeta.provider || '').trim();
            const modelName = String(generationMeta.model || '').trim();
            if (providerLabel) {
                metaParts.push(modelName ? `${providerLabel} / ${modelName}` : providerLabel);
            }
            if ((Number(generationMeta.referenceImageCount) || 0) > 0) {
                metaParts.push(`参考图 ${Number(generationMeta.referenceImageCount)}`);
            }
            if (generationMeta.usedDirectReferenceImages && (Number(generationMeta.directReferenceImageCount) || 0) > 0) {
                metaParts.push(`直传参考图 ${Number(generationMeta.directReferenceImageCount)}`);
            }
            if (generationMeta.providerRequestMode) {
                metaParts.push(`链路 ${String(generationMeta.providerRequestMode)}`);
            }
            if (generationMeta.promptExtractorSource || generationMeta.promptExtractorModel) {
                metaParts.push(
                    generationMeta.promptExtractorModel
                        ? `提炼器 ${generationMeta.promptExtractorSource || 'AI'} / ${generationMeta.promptExtractorModel}`
                        : `提炼器 ${generationMeta.promptExtractorSource || 'AI'}`
                );
            }
        }

        if (cleanText && cleanText !== '图片') {
            metaParts.push(cleanText);
        }

        return {
            title: role === 'assistant' ? 'AI 图片预览' : '图片预览',
            meta: metaParts.join(' · '),
            fileName: cleanText || (role === 'assistant' ? 'ai-image' : 'chat-image'),
            shouldWatermark: options.isAiGenerated === true || role === 'assistant'
        };
    }

