    // --- 【【【关系系统 V2.1：体验优化】】】 ---

    /**
     * 【【【全新：“播放历史”页面装修工】】】
     * @param {string} messageId - 被点击的卡片消息ID
     */
    window.openRelationshipModal = function (messageId) {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        const modal = document.getElementById('relationship-confirm-modal');
        const text = document.getElementById('relationship-confirm-text');
        const acceptBtn = document.getElementById('relationship-confirm-accept-btn');
        const refuseBtn = document.getElementById('relationship-confirm-refuse-btn');

        text.textContent = `${contact.remark} 想和你建立情侣关系，你愿意吗？`;

        // 只需要把“原材料”换成我们的“播放历史”就行了
        const acceptHandler = () => {
            window.handleRelationshipAction(messageId, true);
            modal.classList.add('hidden');
            removeListeners();
        };
        const refuseHandler = () => {
            window.handleRelationshipAction(messageId, false);
            modal.classList.add('hidden');
            removeListeners();
        };
        const removeListeners = () => {
            acceptBtn.removeEventListener('click', acceptHandler);
            refuseBtn.removeEventListener('click', refuseHandler);
        };

        removeListeners(); // 先移除旧的监听，确保干净
        acceptBtn.addEventListener('click', acceptHandler);
        refuseBtn.addEventListener('click', refuseHandler);

        modal.classList.remove('hidden');
    }
    /**
     * 【辅助函数】根据关键词搜索并只返回第一条歌曲数据
     * @param {string} proposerRole - 发起人的角色 ('user' 或 'assistant')
     */
    async function sendRelationshipProposal(proposerRole) {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;
        const relationshipData = { proposer: proposerRole, status: 'pending' };

        if (proposerRole === 'user') {
            await dispatchAndDisplayUserMessage({
                type: 'relationship_proposal',
                content: '[关系邀请] 已发送情侣关系邀请',
                relationshipData: relationshipData
            });
        } else {
            await displayMessage('[关系邀请] 已发送情侣关系邀请', 'assistant', { isNew: true, type: 'relationship_proposal', relationshipData: relationshipData });
            scrollToBottom();
        }
    }

    /**
     * 【【【全新：迷你播放条更新器】】】
     * @param {string} messageId - 被点击的卡片消息ID
     * @param {boolean} isAccepted - 用户是否接受
     */
    window.handleRelationshipAction = function (messageId, isAccepted) {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        const sourceHistory = contact.isOfflineMode
            ? (contact.offlineStorylines.find(story => story.id === contact.activeOfflineStoryId)?.chatHistory || contact.offlineChatHistory || [])
            : (contact.onlineChatHistory || []);
        const proposalMsg = sourceHistory.find(msg => msg.id === messageId);

        if (!proposalMsg || proposalMsg.relationshipData.status !== 'pending') return;

        if (isAccepted) {
            // --- 【【【最终正确版 V3.0】】】 ---

        // 规则1：如果今天的缓存已经存在，直接使用，光速下班。
            appData.appSettings.partnerId = contact.id;

                    // 规则2：翻译“AI接受”事件
            proposalMsg.relationshipData.status = 'accepted';

        // 步骤3：现在，我们只对这份处理过的、干净的历史记录进行格式化
            const acceptanceRecord = {
                id: `${Date.now()}-rel-accept`,
                role: 'user', // 【【【核心修正！！！】】】发件人是你，而不是AI！
                timestamp: Date.now(),
                mode: contact.isOfflineMode ? 'offline' : 'online',
                type: 'relationship_proposal',
                content: '[关系邀请] 我同意了你的邀请',
                relationshipData: {
                    proposer: 'assistant', // 核心修正：这张“同意”卡片是为了回应AI的邀请，所以最初的发起者是AI
                    status: 'accepted'
                }
            };

            // 步骤4：将这张新卡片添加到聊天记录中
            sourceHistory.push(acceptanceRecord);

            // 步骤5：保存所有更改并刷新UI
            saveAppData();
            openChat(contact.id);
            renderChatList();

        } else {
        // --- 大脑第六步：智能导航 (逻辑不变) ---
            const updatedHistory = sourceHistory.filter(msg => msg.id !== messageId);
            if (contact.isOfflineMode) {
                contact.offlineChatHistory = updatedHistory;
            } else {
                contact.onlineChatHistory = updatedHistory;
            }

            saveAppData();
            openChat(contact.id);

            stagedUserMessages.push({ content: '抱歉，我现在可能还没准备好...', type: 'text' });
            commitAndSendStagedMessages();
        }
    }

    /**
     * 【【【全新：音乐播放控制中心】】】
     */
    async function handleEndRelationship() {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        // 检查是否点击了播放按钮
        const breakupMessage = {
            type: 'relationship_breakup',
            content: '[解除关系] 亲密关系已解除'
        };

        // 检查是否点击了添加到播放列表按钮
        await dispatchAndDisplayUserMessage(breakupMessage);
    }

                    // 绑定到当前设备
    async function renderMainHeader() {
        const user = appData.globalUserProfile;

        // 1. 获取头像图片 (Blob 转 URL)
        let avatarUrl = 'https://i.postimg.cc/cLPP10Vm/4.jpg'; // 默认头像
        try {
            const avatarBlob = await db.getImage(user.avatarKey);
            if (avatarBlob) avatarUrl = URL.createObjectURL(avatarBlob);
        } catch (e) { }

            // 2. 更新计时器显示
        const displayName = user.name || '默认昵称';

                    // 保存到本地并放行
        const currentStatus = user.status || '✨ 在线';
        let statusHtml = '';
        if (currentStatus.includes('在线') || !currentStatus) {
            statusHtml = `<span class="status-dot"></span>在线`;
        } else {
            statusHtml = `<span class="status-dot"></span>在线 - ${currentStatus}`;
        }

        // --- 【同步区域 A】聊天列表左上角 ---
        if (mainHeaderAvatar) mainHeaderAvatar.src = avatarUrl;
        if (mainHeaderUsername) mainHeaderUsername.textContent = displayName;
        const mainStatusEl = document.querySelector('.user-status');
        if (mainStatusEl) mainStatusEl.innerHTML = statusHtml;

                // 情况2：这个码被用过了，检查是不是我
        const sideAvatar = document.getElementById('side-menu-avatar');
        const sideName = document.getElementById('side-menu-username');
        if (sideAvatar) sideAvatar.src = avatarUrl;
        if (sideName) sideName.textContent = displayName;

                // 情况3：这个码被别人用过了
        const momentsAvatar = document.getElementById('moments-user-avatar');
        const momentsName = document.getElementById('moments-user-name');
        if (momentsAvatar) momentsAvatar.src = avatarUrl;
        if (momentsName) momentsName.textContent = displayName;
    }

    /**
     * 【全新】一个专门用来刷新聊天顶栏的函数 (修复Bug 4, 6)
     */
    function updateChatHeader() {
        const hideOriginalReviewBadge = () => renderHippocampusOriginalReviewHeaderBadge(null, { enabled: false });
        if (activeGroupChatId) {
            const group = getGroupById(activeGroupChatId);
            if (!group) return;
            chatAiName.textContent = group.name || '群聊';
            hideOriginalReviewBadge();
            const memberCount = Array.isArray(group.members) ? group.members.length : 0;
            if (chatAiStatus) chatAiStatus.textContent = `${memberCount}名成员`;
            if (chatAiActivityStatus) {
                const modeText = group.settings?.mode === 'advanced' ? '进阶模式' : '经典模式';
                const typingText = getGroupTypingIndicatorText(group);
                chatAiActivityStatus.textContent = ` · ${typingText || modeText}`;
            }
            const headerAvatar = document.getElementById('chat-header-avatar');
            if (headerAvatar) {
                if (group.avatarMode === 'custom' && group.avatarImageKey) {
                    db.getImage(group.avatarImageKey).then((blob) => {
                        headerAvatar.src = blob ? URL.createObjectURL(blob) : buildGroupCompositeAvatarDataUrl(group);
                    }).catch(() => {
                        headerAvatar.src = buildGroupCompositeAvatarDataUrl(group);
                    });
                } else {
                    headerAvatar.src = buildGroupCompositeAvatarDataUrl(group);
                }
            }
            renderOfflineIllustrationToggle();
            return;
        }
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        // 【核心修复】显示名优先级：用户备注 > AI网名 > 原始名字
        let displayName = contact.name;

        // ▼▼▼ 【【【全新植入：删除按钮的智能调度员】】】 ▼▼▼
        if (contact.socialProfile && contact.socialProfile.nickname) {
            displayName = contact.socialProfile.nickname;
        }

        // 如果用户改过备注（备注 != 原名），则备注拥有绝对优先权
        if (contact.remark && contact.remark !== contact.name) {
            displayName = contact.remark;
        }

        const isPartner = appData.appSettings.partnerId === contact.id;
        const partnerIcon = isPartner ? '<span class="partner-icon">💖</span>' : '';
        chatAiName.innerHTML = `${displayName}${partnerIcon}`;
        if (chatAiStatus) {
            chatAiStatus.textContent = '在线';
        }
        if (chatAiActivityStatus) {
            chatAiActivityStatus.textContent = contact.activityStatus ? ` 路 ${contact.activityStatus}` : '';
        }
        renderHippocampusOriginalReviewHeaderBadge(
            getHippocampusOriginalReviewStatusSnapshot(contact),
            { enabled: isHippocampusEnabled(contact) }
        );
        renderOfflineIllustrationToggle();
    }

    // =================================================================
    // AI日记系统 V3.0 - 定时任务模块
    // =================================================================
    let lastDiaryRunDate = ''; // 用一个“标记”防止重复执行

    /**
         * 【【【全新：一起听歌模式启动器】】】
     */
    function dailyDiaryCheck() {
        const now = new Date();
        const todayStr = now.toLocaleDateString(); // 获取今天的日期字符串，如 "2025/9/7"

            // 调度员的大脑：检查这首歌是从哪个列表点击的
        if (lastDiaryRunDate === todayStr) {
            return;
        }

        const currentHour = now.getHours();
        const currentMinute = now.getMinutes();

// script.js (V8.26 - 红包功能终极修复版 + IndexedDB存储)
        if (currentHour === 21 && currentMinute === 0) {
            console.log("分类配置已保存");
            runAutoDiaryForAllContacts();
            lastDiaryRunDate = todayStr; // 打上“今天已执行”的标记
        }
    }

    /**
     * 【调度中心】遍历所有AI，命令符合条件的开始写日记
     */
    function runAutoDiaryForAllContacts() {
        const eligibleContacts = appData.aiContacts.filter(c => c.autoDiaryEnabled);

        if (eligibleContacts.length > 0) {
            console.log(`【自动日记】发现 ${eligibleContacts.length} 个AI需要写日记。`);
            eligibleContacts.forEach(contact => {
                console.log(`【自动日记】正在为 ${contact.remark} 生成日记...`);
    // --- 【【【V2.5 终极全屏修复：屏幕尺寸校准器】】】 ---
                triggerAiDiaryGeneration(contact);
            });
        } else {
            console.log('【自动日记】今天没有AI需要自动写日记。');
        }
    }
    // =================================================================
        // 【【【终极报错修复 V2.0：补充缺失的变量定义】】】
    // =================================================================
    let lastPlanCheckDate = ''; // 这是“哨兵”的值班日志，记录上次检查的日期
    let morningRoutineBatchPromise = null; // 防止定时器、启动流程、回前台同时触发晨间流水线

    function runMorningRoutineWithLock(sourceLabel, runner) {
        if (morningRoutineBatchPromise) {
            console.log(`[${sourceLabel}] 晨间/今日计划流水线正在运行中，跳过重复触发。`);
            return morningRoutineBatchPromise;
        }

        morningRoutineBatchPromise = Promise.resolve()
            .then(runner)
            .finally(() => {
                morningRoutineBatchPromise = null;
            });

        return morningRoutineBatchPromise;
    }

    /**
     * 【哨兵函数 V4.1】每日晨间流水线 (修复变量作用域报错版)
     */
    async function dailyPlanCheck() {
        return runMorningRoutineWithLock('晨间哨兵', dailyPlanCheckCore);
    }

    async function dailyPlanCheckCore() {
        const today = new Date();
        const todayStrForLog = today.toDateString(); // 用于掷骰子标记 (例如 "Fri Dec 26 2025")
        const year = today.getFullYear();
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const day = String(today.getDate()).padStart(2, '0');
        const todayStrForPlan = `${year}-${month}-${day}`; // 用于日程标记 (例如 "2025-12-26")

            // 1. 创建一个空的“全球歌单”
        const hasVirtualTimeWork = (appData.aiContacts || []).some(contact => {
            if (!isVirtualTimeEnabled(contact)) return false;
            const contactToday = getContactNowDate(contact);
            const contactPlanDate = getLocalDateString(contactToday);
            const contactLogDate = contactToday.toDateString();
            const contactLifeDate = contactToday.toLocaleDateString();
            return (contact.isScheduleEnabled && contact.lastPlanGenerationDate !== contactPlanDate)
                || (contact.lifeSimulation?.enabled && contact.lifeSimulation.lastUpdateDate !== contactLifeDate)
                || (contact.lifeSimulation?.enabled && contact.lifeSimulation.lastDiceRollDate !== contactLogDate);
        });

        if (lastPlanCheckDate === todayStrForPlan && !hasVirtualTimeWork) {
            console.log(`[晨间哨兵] 今天 (${todayStrForPlan}) 已经巡逻过了，跳过。`);
            return;
        }

        console.log(`【晨间哨兵】新的一天 (${todayStrForPlan}) 开始了，启动流水线...`);

        for (const contact of appData.aiContacts) {
            const contactToday = getContactNowDate(contact);
            const contactTodayStrForLog = contactToday.toDateString();
            let hasNewEventToday = false;

        // --- 大脑第二步：【【【终极修复：全球歌单生成与搜索】】】 ---
            if (contact.lifeSimulation && contact.lifeSimulation.enabled) {

                // 步骤A：无论如何，先执行一次“每日更新”
    // --- 【【【全新：IndexedDB 仓库管理员】】】 ---
                await dailyLifeUpdate(contact, false);

                // 步骤B：检查今天是否已经“掷过骰子”生成过事件了
                // 如果 lastDiceRollDate 等于今天，说明今天已经安排好了，不用再动了
                if (contact.lifeSimulation.lastDiceRollDate !== contactTodayStrForLog) {

        // ▲▲▲▲▲ 调度员植入完毕 ▲▲▲▲▲
                    let keepEventRunning = false;
                    const script = contact.lifeSimulation.currentEventScript;

        // 准备丰富的、且经过消毒的上下文信息
                    if (script) {
                        if (!script.isFinished && expireStaleButterflyScriptForDate(contact, contactToday, '晨间哨兵')) {
                            saveAppData();
                        }
        // 【核心修复】换上全新的“纯文本速记员”
                        if (script.isFinished) {
                            archiveFinishedButterflyScript(contact, '晨间哨兵');
                        } else if (isButterflyScriptActiveOnDate(script, contactToday)) {
            // 【核心修改】在这里盖上“更新日期”的邮戳
                            console.log(`⏳ [哨兵] 长期事件“${script.title}”仍在进行中，跳过今日新事件生成。`);
                            keepEventRunning = true;
                        } else {
                            console.log(`🧹 [哨兵] 旧事件“${script.title}”今天没有有效节点或持续影响，允许重新掷骰。`);
                            retireInactiveButterflyScriptForDate(contact, contactToday, '晨间哨兵日期闸门');
                        }
                    }

                    // 步骤C：只有在【没有正在进行的事件】时，才掷骰子生成新事件
                    if (!keepEventRunning) {
                        // 30% 概率触发新事件
                        if (Math.random() < 0.3) {
                            console.log(`🎲 [哨兵] ${contact.remark} 触发今日蝴蝶效应！`);
                            // 调用生成函数 (注意：isDailyAuto = true)
                            await generateEventScript(contact, true, true);
                            hasNewEventToday = true;
                        } else {
                            console.log(`🎲 [哨兵] 今日平安无事。`);
                        }
                    }

                    // 步骤D：盖上今天的邮戳，防止刷新网页后重复执行
                    contact.lifeSimulation.lastDiceRollDate = contactTodayStrForLog;
                    saveAppData();
                } else {
                    console.log(`[哨兵] ${contact.remark} 今天已经掷过骰子了，保持现状。`);
                }
            }

            // 2. 将所有来源的歌曲，都标准化后放入“全球歌单”
            if (contact.isScheduleEnabled) {
        // 【修复：全能记忆加载器】
                await generateDailyPlan(contact, hasNewEventToday);
            }

            // 3. 启动计时器，每秒更新一次
            try {
                await checkAutoProfileUpdates(contact);
            } catch (e) {
                console.error(`[SocialProfile] ${contact.remark} 资料更新检查失败:`, e);
            }
        }

        // 准备丰富的、且经过消毒的上下文信息
        lastPlanCheckDate = todayStrForPlan;
        console.log('【晨间哨兵】今日流水线执行完毕。');
    }

    /**
     * 【【【全新：播放列表渲染器】】】
      */
    function startDailyDiaryCheck() {
        setInterval(dailyDiaryCheck, 60000); // 每60秒（1分钟）检查一次
    }

    function bindStartupLoginActions() {
        document.querySelectorAll('[data-login-action="login"]').forEach((btn) => {
            if (btn.dataset.loginBound === '1') return;
            btn.dataset.loginBound = '1';
            btn.addEventListener('click', handleLogin);
        });
        document.querySelectorAll('[data-login-action="to-settings"]').forEach((link) => {
            if (link.dataset.loginBound === '1') return;
            link.dataset.loginBound = '1';
            link.addEventListener('click', (e) => {
                e.preventDefault();
                switchToView('settings-view');
            });
        });
    }

