            const partner = appData.aiContacts.find(c => c.id === currentPartnerId);
            const partnerName = partner ? (partner.remark || partner.name || '未知') : '未知';
            showCustomAlert('提示', `你当前的情侣是 ${partnerName}。\n请先与对方解除关系，才能开始新的恋情。`);
