    /**
     * 【全新辅助函数】用于显示红包详情模态框
     */
    function populateSearchFilters() {
        const charSelect = document.getElementById('char-filter-select');
        if (!charSelect) return;

        charSelect.innerHTML = '<option value="all">所有角色</option>'; // 重置并添加默认选项

        appData.aiContacts.forEach(contact => {
            const option = document.createElement('option');
            const displayName = String(contact.remark || contact.name || contact.id || '').trim();
            if (!displayName) return;
            option.value = displayName.toLowerCase(); // 用小写备注作为值
            option.textContent = displayName;
            charSelect.appendChild(option);
        });
    }

    window.saveAppData = saveAppData; function saveAppData() {
        // 根据发送者角色，决定头像和名字
        db.saveObject('appData', appData).catch(error => {
            console.error("保存数据到 IndexedDB 失败:", error);
        // 填充模态框上半部分（这部分总会显示）
            try {
                localStorage.setItem('myAiChatApp_V8_Data', JSON.stringify(appData));
            } catch (e) {
                console.error("保存数据到 localStorage 也失败了，数据可能已丢失:", e);
        // 为按钮绑定【一次性】事件，防止重复触发
                showCustomAlert('【严重错误】', '数据保存失败，存储空间可能已满！请尝试导出数据并清理浏览器缓存。');
            }
        });
    }

    /**
     * 通过角色 ID 查找角色对象。
     * 仅供海马体前情提要 bridge 使用，避免把完整 appData 暴露到全局。
     */
    function hasMeaningfulIdicCompanionSupabaseConfig() {
        const companionSettings = ensureIdicCompanionSettings();
        const directConfig = companionSettings.supabase && typeof companionSettings.supabase === 'object'
            ? companionSettings.supabase
            : {};
        return Boolean(
            String(directConfig.url || directConfig.apiUrl || directConfig.baseUrl || '').trim()
            && String(directConfig.publishableKey || directConfig.key || directConfig.anonKey || directConfig.apiKey || '').trim()
        );
    }

    const saveAppDataCore = saveAppData;
    saveAppData = function () {
        const result = saveAppDataCore.apply(this, arguments);
        const companionSettings = ensureIdicCompanionSettings();
        if (toHippocampusBoolean(companionSettings.autoSyncRoles) && hasMeaningfulIdicCompanionSupabaseConfig()) {
            scheduleIdicCompanionRoleSync();
        }
        const proactiveSettings = ensureProactiveMessageSettings();
        if (toHippocampusBoolean(proactiveSettings.enabled) && hasMeaningfulProactiveMessageSupabaseConfig()) {
            scheduleProactiveMessageSync();
        }
        return result;
    };

    function findAiContactByCharId(charId) {
        const safeCharId = String(charId || '').trim();
        if (!safeCharId) return null;

        const contacts = Array.isArray(appData.aiContacts) ? appData.aiContacts : [];
        return contacts.find((item) => String(item?.id || '').trim() === safeCharId) || null;
    }

    /**
     * 【全新】打开关系确认弹窗的控制器
     */
    function toHippocampusContactSummary(contact) {
        if (!contact || typeof contact !== 'object') return null;

        const contactId = String(contact.id || '').trim();
        if (!contactId) return null;

        return {
            id: contactId,
            name: String(contact.name || '').trim() || contactId,
            remark: String(contact.remark || contact.name || '').trim() || contactId,
            hippocampusEnabled: toHippocampusBoolean(contact.hippocampusEnabled)
        };
    }

    /**
     * 【全新】创建并发送一个关系邀请卡片
     */
    function getCurrentHippocampusContactSummary() {
        return toHippocampusContactSummary(getCurrentHippocampusContact());
    }

    /**
     * 【全新】处理用户点击卡片按钮的动作
     */
    function listHippocampusEnabledContactSummaries() {
        const contacts = Array.isArray(appData.aiContacts) ? appData.aiContacts : [];
        return contacts
            .filter((contact) => toHippocampusBoolean(contact && contact.hippocampusEnabled))
            .map((contact) => toHippocampusContactSummary(contact))
            .filter(Boolean);
    }

    /**
     * 【全新】处理解除关系的流程
     */
    function getHippocampusRecentRecap(charId) {
        const contact = findAiContactByCharId(charId);
        if (!contact) return null;

        const recapText = String(contact.recentRecap || '').trim();
        return recapText || null;
    }

    /**
     * 【定时闹钟】每分钟检查一次时间，判断是否需要写日记
     */
    function saveHippocampusRecentRecap(charId, recapText) {
        const contact = findAiContactByCharId(charId);
        if (!contact) return false;

        contact.recentRecap = String(recapText || '').trim();
        saveAppData();
        return true;
    }

    async function getHippocampusContinuityAdminSnapshot(charId) {
        const safeCharId = toHippocampusTrimmedString(charId);
        const contact = safeCharId ? findAiContactByCharId(safeCharId) : getCurrentHippocampusContact();
        const targetCharId = toHippocampusTrimmedString(contact && contact.id) || safeCharId;
        const continuity = window.HippocampusContinuity;
        if (!continuity || typeof continuity.readSnapshot !== 'function') {
            return {
                ok: false,
                error: 'continuity_unavailable',
                snapshot: null,
                promptText: '',
                userId: ''
            };
        }
        if (!targetCharId) {
            return {
                ok: false,
                error: 'missing_char_id',
                snapshot: null,
                promptText: '',
                userId: ''
            };
        }
        const userId = await resolveHippocampusUserId(true);
        if (!userId) {
            return {
                ok: false,
                error: 'missing_user_id',
                snapshot: null,
                promptText: '',
                userId: ''
            };
        }
        const snapshot = continuity.readSnapshot(userId, targetCharId);
        const promptText = typeof continuity.buildPromptBlock === 'function'
            ? continuity.buildPromptBlock(snapshot, { userId, charId: targetCharId })
            : '';
        return {
            ok: true,
            userId,
            charId: targetCharId,
            charName: toHippocampusTrimmedString(contact && (contact.name || contact.remark)) || targetCharId,
            snapshot,
            promptText
        };
    }

    async function saveHippocampusContinuityAdminSnapshot(charId, patch = {}) {
        const safeCharId = toHippocampusTrimmedString(charId);
        const contact = safeCharId ? findAiContactByCharId(safeCharId) : getCurrentHippocampusContact();
        const targetCharId = toHippocampusTrimmedString(contact && contact.id) || safeCharId;
        const continuity = window.HippocampusContinuity;
        if (!continuity || typeof continuity.readSnapshot !== 'function' || typeof continuity.writeSnapshot !== 'function') {
            return { ok: false, error: 'continuity_unavailable' };
        }
        if (!targetCharId) {
            return { ok: false, error: 'missing_char_id' };
        }
        const userId = await resolveHippocampusUserId(true);
        if (!userId) {
            return { ok: false, error: 'missing_user_id' };
        }
        const sourcePatch = patch && typeof patch === 'object' ? patch : {};
        const previous = continuity.readSnapshot(userId, targetCharId);
        const summaryText = toHippocampusTrimmedString(sourcePatch.summaryText);
        let ongoingThreads = previous && Array.isArray(previous.ongoingThreads) ? previous.ongoingThreads : [];
        if (Array.isArray(sourcePatch.ongoingThreads)) {
            ongoingThreads = sourcePatch.ongoingThreads;
        }
        const snapshot = continuity.writeSnapshot(Object.assign({}, previous, {
            userId,
            charId: targetCharId,
            updatedAt: new Date().toISOString(),
            source: 'manual_admin_edit',
            rollingWindow: Object.assign({}, previous && previous.rollingWindow || {}, {
                summaryText
            }),
            ongoingThreads,
            metadata: Object.assign({}, previous && previous.metadata || {}, {
                manualEditedAt: new Date().toISOString(),
                lastError: '',
                lastErrorAt: ''
            })
        }));
        const promptText = typeof continuity.buildPromptBlock === 'function'
            ? continuity.buildPromptBlock(snapshot, { userId, charId: targetCharId })
            : '';
        return {
            ok: true,
            userId,
            charId: targetCharId,
            snapshot,
            promptText
        };
    }

    async function retryHippocampusContinuityAdminSnapshot(charId) {
        const safeCharId = toHippocampusTrimmedString(charId);
        const contact = safeCharId ? findAiContactByCharId(safeCharId) : getCurrentHippocampusContact();
        if (!contact) {
            return { ok: false, error: 'missing_contact' };
        }
        return await updateHippocampusContinuityForContact(contact, {
            force: true,
            source: 'manual_admin_retry',
            suppressToast: true
        });
    }

    /**
     * 读取指定角色当前保存的 YAML 记忆文本，供旧记忆迁移工具使用。
     */
    function getHippocampusMigrationSource(charId) {
        const contact = findAiContactByCharId(charId);
        if (!contact) return null;

        const userProfile = contact.userProfile && typeof contact.userProfile === 'object'
            ? contact.userProfile
            : (appData && appData.globalUserProfile && typeof appData.globalUserProfile === 'object'
                ? appData.globalUserProfile
                : {});

        return {
            id: String(contact.id || '').trim(),
            name: String(contact.name || '').trim(),
            remark: String(contact.remark || contact.name || '').trim(),
            yamlContent: String(contact.memory || ''),
            sourceType: 'legacy_contact_memory',
            sourceLabel: '角色已有 YAML 记忆',
            persona: String(contact.persona || '').trim(),
            genderIdentity: String(contact.genderIdentity || '').trim(),
            userName: String(userProfile.name || '').trim(),
            userPersona: String(userProfile.persona || '').trim(),
            userGenderIdentity: String(userProfile.genderIdentity || '').trim()
        };
    }

    /**
     * 【【【全新：API预设渲染器】】】
         * 所有角色同时开始生成，不再排队！
     */
    function getHippocampusMigrationApiConfig() {
        const config = getHippocampusDehydrateApiConfig();
        if (!config || typeof config !== 'object') {
            return {};
        }

        return {
            apiUrl: String(config.apiUrl || config.url || config.baseUrl || '').trim(),
            apiKey: String(config.apiKey || config.key || '').trim(),
            model: String(config.model || config.modelName || '').trim(),
            temperature: config.temperature,
            headers: config.headers && typeof config.headers === 'object'
                ? Object.assign({}, config.headers)
                : {},
            requestBody: config.requestBody && typeof config.requestBody === 'object'
                ? Object.assign({}, config.requestBody)
                : {}
        };
    }

    async function countHippocampusRowsForUser(supabase, userId, charId = '') {
        const safeUserId = String(userId || '').trim();
        const safeCharId = String(charId || '').trim();
        const empty = {
            userId: safeUserId,
            charId: safeCharId,
            memories: null,
            unresolved: null,
            events: null,
            statuses: null,
            profiles: null,
            mustRemember: null,
            redlines: null,
            relationshipArcs: null,
            error: ''
        };
        if (!supabase || !safeUserId) return empty;
        const result = Object.assign({}, empty);
        const errors = [];
        const countTable = async (tableName, extraFilter = null) => {
            try {
                let query = supabase
                    .from(tableName)
                    .select('id', { count: 'exact', head: true })
                    .eq('user_id', safeUserId);
                if (safeCharId) query = query.eq('char_id', safeCharId);
                if (typeof extraFilter === 'function') query = extraFilter(query);
                const response = await query;
                if (response.error) throw response.error;
                return Number(response.count) || 0;
            } catch (error) {
                errors.push(`${tableName}: ${error && error.message ? error.message : String(error || 'unknown_error')}`);
                return null;
            }
        };

        result.memories = await countTable('hippocampus_memories');
        result.unresolved = await countTable('hippocampus_memories', (query) => query.eq('resolved', false));
        result.events = await countTable('hippocampus_memory_events');
        result.statuses = await countTable('hippocampus_user_status');
        result.profiles = await countTable('hippocampus_user_profile');
        result.mustRemember = await countTable('hippocampus_user_must_remember');
        result.redlines = await countTable('hippocampus_user_redlines');
        result.relationshipArcs = await countTable('hippocampus_relationship_arcs');
        if (errors.length > 0) {
            result.error = errors.join(' | ');
        }
        return result;
    }

    function quoteSqlStringForHippocampusRecovery(value) {
        return String(value || '').replace(/'/g, "''");
    }

    function buildHippocampusRecoverySqlLegacyCopyTemplate(options = {}) {
        const oldUserId = quoteSqlStringForHippocampusRecovery(options.oldUserId || 'OLD_USER_ID');
        const newUserId = quoteSqlStringForHippocampusRecovery(options.newUserId || 'NEW_USER_ID');
        const charId = quoteSqlStringForHippocampusRecovery(options.charId || 'CHAR_ID');
        return `-- IDIC 海马体记忆合并恢复 SQL
-- 用法：先把 OLD_USER_ID / NEW_USER_ID / CHAR_ID 换成真实值，在 Supabase SQL Editor 里执行。
-- 这份脚本不删除旧记忆，只把旧身份下该角色的记忆复制到当前身份；今天新增的几条会保留。

begin;

insert into public.hippocampus_memories (
    user_id, char_id, room_id, content, valence, arousal, importance,
    activation_count, resolved, created_at, last_active_at, context_scope,
    resolved_at, last_injected_at, dedupe_key, source_type, source_ref,
    metadata, updated_at, memory_layer, is_flashbulb, event_id, event_title,
    event_summary, event_status, event_depth, event_date, event_fragment_count,
    event_is_unresolved, event_salience_score, event_depth_score, continuation_key,
    event_anchor_memory_id, event_detail_memory_ids, embedding
)
select
    '${newUserId}' as user_id,
    char_id, room_id, content, valence, arousal, importance,
    activation_count, resolved, created_at, last_active_at, context_scope,
    resolved_at, last_injected_at,
    coalesce(dedupe_key, 'recovered:' || id::text) as dedupe_key,
    source_type, source_ref,
    coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('recovered_from_user_id', '${oldUserId}', 'recovered_from_memory_id', id::text),
    updated_at, memory_layer, is_flashbulb, event_id, event_title,
    event_summary, event_status, event_depth, event_date, event_fragment_count,
    event_is_unresolved, event_salience_score, event_depth_score, continuation_key,
    event_anchor_memory_id, event_detail_memory_ids, embedding
from public.hippocampus_memories
where user_id = '${oldUserId}'
  and char_id = '${charId}'
on conflict do nothing;

insert into public.hippocampus_memory_events (
    id, user_id, char_id, room_id, context_scope, title, summary, status,
    depth, is_unresolved, continuation_key, event_date, fragment_count,
    salience_score, depth_score, anchor_memory_id, memory_ids, detail_memory_ids,
    start_at, end_at, last_related_at, manual_edited, manual_note, metadata,
    created_at, updated_at, event_is_flashbulb, event_flashbulb_memory_ids
)
select
    id, '${newUserId}' as user_id, char_id, room_id, context_scope, title, summary, status,
    depth, is_unresolved, continuation_key, event_date, fragment_count,
    salience_score, depth_score, anchor_memory_id, memory_ids, detail_memory_ids,
    start_at, end_at, last_related_at, manual_edited, manual_note,
    coalesce(metadata, '{}'::jsonb) || jsonb_build_object('recovered_from_user_id', '${oldUserId}'),
    created_at, updated_at, event_is_flashbulb, event_flashbulb_memory_ids
from public.hippocampus_memory_events
where user_id = '${oldUserId}'
  and char_id = '${charId}'
on conflict (user_id, char_id, id) do nothing;

commit;`;
    }

    function buildHippocampusRecoverySql(options = {}) {
        const oldUserId = quoteSqlStringForHippocampusRecovery(options.oldUserId || 'OLD_USER_ID');
        const newUserId = quoteSqlStringForHippocampusRecovery(options.newUserId || 'NEW_USER_ID');
        const charId = quoteSqlStringForHippocampusRecovery(options.charId || 'CHAR_ID');
        return `-- IDIC hippocampus full recovery SQL
-- Replace OLD_USER_ID / NEW_USER_ID / CHAR_ID first, then run in Supabase SQL Editor.
-- This backs up and rebinds memories, events, notebook rows, and relationship arcs for one role.
-- Run once for each old user_id that belongs to this char_id.

begin;

create table if not exists public.hippocampus_memories_recovery_backup as
select *
from public.hippocampus_memories
where false;

create table if not exists public.hippocampus_memory_events_recovery_backup as
select *
from public.hippocampus_memory_events
where false;

create table if not exists public.hippocampus_user_status_recovery_backup as
select *
from public.hippocampus_user_status
where false;

create table if not exists public.hippocampus_user_profile_recovery_backup as
select *
from public.hippocampus_user_profile
where false;

create table if not exists public.hippocampus_user_must_remember_recovery_backup as
select *
from public.hippocampus_user_must_remember
where false;

create table if not exists public.hippocampus_user_redlines_recovery_backup as
select *
from public.hippocampus_user_redlines
where false;

create table if not exists public.hippocampus_relationship_arcs_recovery_backup as
select *
from public.hippocampus_relationship_arcs
where false;

insert into public.hippocampus_memories_recovery_backup
select *
from public.hippocampus_memories
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_memory_events_recovery_backup
select *
from public.hippocampus_memory_events
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_user_status_recovery_backup
select *
from public.hippocampus_user_status
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_user_profile_recovery_backup
select *
from public.hippocampus_user_profile
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_user_must_remember_recovery_backup
select *
from public.hippocampus_user_must_remember
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_user_redlines_recovery_backup
select *
from public.hippocampus_user_redlines
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

insert into public.hippocampus_relationship_arcs_recovery_backup
select *
from public.hippocampus_relationship_arcs
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}';

update public.hippocampus_memories
set
    user_id = '${newUserId}',
    dedupe_key = case
        when dedupe_key is not null
         and exists (
             select 1
             from public.hippocampus_memories existing
             where existing.user_id = '${newUserId}'
               and existing.char_id = public.hippocampus_memories.char_id
               and existing.context_scope = public.hippocampus_memories.context_scope
               and coalesce(existing.room_id, '') = coalesce(public.hippocampus_memories.room_id, '')
               and existing.dedupe_key = public.hippocampus_memories.dedupe_key
         )
        then 'recovered:' || id::text
        else dedupe_key
    end,
    metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where user_id = '${oldUserId}'
  and char_id = '${charId}';

update public.hippocampus_memory_events e
set
    user_id = '${newUserId}',
    metadata = coalesce(e.metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where e.user_id = '${oldUserId}'
  and e.char_id = '${charId}'
  and not exists (
      select 1
      from public.hippocampus_memory_events existing
      where existing.user_id = '${newUserId}'
        and existing.char_id = e.char_id
        and existing.id = e.id
  );

update public.hippocampus_user_status
set
    user_id = '${newUserId}',
    metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where user_id = '${oldUserId}'
  and char_id = '${charId}';

update public.hippocampus_user_profile
set
    user_id = '${newUserId}',
    metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where user_id = '${oldUserId}'
  and char_id = '${charId}';

update public.hippocampus_user_must_remember
set
    user_id = '${newUserId}',
    metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where user_id = '${oldUserId}'
  and char_id = '${charId}';

update public.hippocampus_user_redlines
set
    user_id = '${newUserId}',
    metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
where user_id = '${oldUserId}'
  and char_id = '${charId}';

update public.hippocampus_relationship_arcs
set is_current = false
where user_id in ('${oldUserId}', '${newUserId}')
  and char_id = '${charId}'
  and is_current = true;

with old_arc_rows as (
    select
        id,
        row_number() over (order by version_number asc, generated_at asc, created_at asc, id asc) as rn
    from public.hippocampus_relationship_arcs
    where user_id = '${oldUserId}'
      and char_id = '${charId}'
),
new_arc_base as (
    select coalesce(max(version_number), 0) as max_version
    from public.hippocampus_relationship_arcs
    where user_id = '${newUserId}'
      and char_id = '${charId}'
)
update public.hippocampus_relationship_arcs arc
set
    user_id = '${newUserId}',
    version_number = new_arc_base.max_version + old_arc_rows.rn,
    metadata = coalesce(arc.metadata, '{}'::jsonb)
        || jsonb_build_object(
            'recovered_from_user_id', '${oldUserId}',
            'recovered_rebound_at', now()
        ),
    updated_at = now()
from old_arc_rows, new_arc_base
where arc.id = old_arc_rows.id;

with latest_arc as (
    select id
    from public.hippocampus_relationship_arcs
    where user_id = '${newUserId}'
      and char_id = '${charId}'
    order by generated_at desc, version_number desc, updated_at desc, id desc
    limit 1
)
update public.hippocampus_relationship_arcs arc
set is_current = (arc.id = (select id from latest_arc))
where arc.user_id = '${newUserId}'
  and arc.char_id = '${charId}';

commit;`;
    }

    function buildHippocampusFindOldUserSql() {
        return `with source_rows as (
  select user_id, char_id, 'memories' as source_table, created_at from public.hippocampus_memories
  union all
  select user_id, char_id, 'events' as source_table, created_at from public.hippocampus_memory_events
  union all
  select user_id, char_id, 'status' as source_table, created_at from public.hippocampus_user_status
  union all
  select user_id, char_id, 'profile' as source_table, created_at from public.hippocampus_user_profile
  union all
  select user_id, char_id, 'must_remember' as source_table, created_at from public.hippocampus_user_must_remember
  union all
  select user_id, char_id, 'redlines' as source_table, created_at from public.hippocampus_user_redlines
  union all
  select user_id, char_id, 'relationship_arcs' as source_table, created_at from public.hippocampus_relationship_arcs
)
select
  user_id,
  char_id,
  count(*) filter (where source_table = 'memories') as memory_count,
  count(*) filter (where source_table = 'events') as event_count,
  count(*) filter (where source_table = 'status') as status_count,
  count(*) filter (where source_table = 'profile') as profile_count,
  count(*) filter (where source_table = 'must_remember') as must_remember_count,
  count(*) filter (where source_table = 'redlines') as redline_count,
  count(*) filter (where source_table = 'relationship_arcs') as relationship_arc_count,
  min(created_at) as first_row_at,
  max(created_at) as last_row_at
from source_rows
group by user_id, char_id
order by memory_count desc, event_count desc, last_row_at desc;`;
    }

    async function getHippocampusRecoveryStatus(charId = '') {
        const config = getHippocampusSupabaseConfig();
        const signature = getHippocampusSupabaseSignature(config);
        const supabase = getHippocampusSupabaseClient();
        const currentUserId = await readHippocampusCurrentAuthUserId({ cache: true, allowMismatch: true });
        const activeContact = String(charId || '').trim()
            ? findAiContactByCharId(charId)
            : getCurrentHippocampusContact();
        const safeCharId = String(charId || activeContact && activeContact.id || '').trim();
        const rememberedUserIds = listRememberedHippocampusUserIds();
        const visibleCounts = [];
        if (currentUserId) {
            visibleCounts.push(await countHippocampusRowsForUser(supabase, currentUserId, safeCharId));
        }
        const status = {
            ok: Boolean(config.url && config.publishableKey && supabase && currentUserId),
            projectRef: getHippocampusProjectRef(config.url),
            configReady: Boolean(config.url && config.publishableKey),
            currentUserId,
            rememberedUserIds,
            currentCharId: safeCharId,
            currentContact: activeContact ? toHippocampusContactSummary(activeContact) : null,
            visibleCounts,
            enabledContacts: listHippocampusEnabledContactSummaries(),
            supabaseSignatureKnown: Boolean(signature),
            findOldUserSql: buildHippocampusFindOldUserSql(),
            recoverySqlTemplate: buildHippocampusRecoverySql({
                oldUserId: rememberedUserIds.find((item) => item && item !== currentUserId) || 'OLD_USER_ID',
                newUserId: currentUserId || 'NEW_USER_ID',
                charId: safeCharId || 'CHAR_ID'
            })
        };
        console.log('[IDIC 海马体恢复状态]', status);
        return status;
    }

