        const rawSettings = appData.appSettings.imageGeneration || {};
        if (window.IDICImageGenerationBridge && typeof window.IDICImageGenerationBridge.normalizeImageGenerationSettings === 'function') {
            appData.appSettings.imageGeneration = window.IDICImageGenerationBridge.normalizeImageGenerationSettings(rawSettings);
        } else {
            appData.appSettings.imageGeneration = Object.assign({}, getDefaultImageGenerationSettings(), rawSettings);
        }

