    function stripOpenAiCompatibleEndpointSuffix(url) {
        return String(url || '').trim().replace(/\/+$/, '')
            .replace(/\/images\/generations$/i, '')
            .replace(/\/image\/generations$/i, '')
            .replace(/\/chat\/completions$/i, '')
            .replace(/\/chat$/i, '')
            .replace(/\/completions$/i, '')
            .replace(/\/embeddings$/i, '')
            .replace(/\/responses$/i, '')
            .replace(/\/models$/i, '');
    }

    function normalizeOpenAiCompatibleApiBaseUrl(url) {
        const value = stripOpenAiCompatibleEndpointSuffix(url);
        if (!value) return '';

        try {
            const parsed = new URL(value);
            const path = parsed.pathname.replace(/\/+$/, '');
            if (!path || path === '/') {
                parsed.pathname = '/v1';
                parsed.search = '';
                parsed.hash = '';
                return parsed.toString().replace(/\/+$/, '');
            }
        } catch (error) { }

        return value;
    }

    function buildOpenAiCompatibleApiUrl(url, endpointPath) {
        const baseUrl = normalizeOpenAiCompatibleApiBaseUrl(url);
        if (!baseUrl) return '';
        const safePath = String(endpointPath || '').replace(/^\/+/, '');
        return `${baseUrl}/${safePath}`;
    }

    function normalizeChatApiUrl(url) {
        return buildOpenAiCompatibleApiUrl(url, '/chat/completions');
    }

    function getGroupApiProfiles() {
        const settings = appData.appSettings || {};
        const temperature = Number(settings.temperature);
        return {
            main: {
                url: normalizeChatApiUrl(settings.apiUrl),
                key: String(settings.apiKey || ''),
                model: String(settings.apiModel || ''),
                temperature: Number.isFinite(temperature) ? temperature : 0.8
            },
            sub1: {
                url: normalizeChatApiUrl(settings.secondaryApi1?.url || settings.apiUrl),
                key: String(settings.secondaryApi1?.key || settings.apiKey || ''),
                model: String(settings.secondaryApi1?.model || settings.apiModel || ''),
                temperature: Number.isFinite(temperature) ? temperature : 0.8
            },
            sub2: {
                url: normalizeChatApiUrl(settings.secondaryApi2?.url || settings.apiUrl),
                key: String(settings.secondaryApi2?.key || settings.apiKey || ''),
                model: String(settings.secondaryApi2?.model || settings.apiModel || ''),
                temperature: Number.isFinite(temperature) ? temperature : 0.8
            }
        };
    }

    function sanitizeLooseJsonString(input) {
        const text = String(input || '').trim();
        if (!text) return '';
        return text
            .replace(/^\uFEFF/, '')
            .replace(/([{,]\s*)([A-Za-z_][A-Za-z0-9_-]*)(\s*:)/g, '$1"$2"$3')
            .replace(/,\s*([}\]])/g, '$1');
    }

    function extractBalancedJsonBlocks(text, openingChar, closingChar, maxCount = 24) {
        const source = String(text || '');
        const results = [];
        let start = -1;
        let depth = 0;
        let inString = false;
        let escaped = false;

        for (let index = 0; index < source.length; index += 1) {
            const char = source[index];
            if (inString) {
                if (escaped) {
                    escaped = false;
                    continue;
                }
                if (char === '\\') {
                    escaped = true;
                    continue;
                }
                if (char === '"') {
                    inString = false;
                }
                continue;
            }

            if (char === '"') {
                inString = true;
                continue;
            }

            if (char === openingChar) {
                if (depth === 0) {
                    start = index;
                }
                depth += 1;
                continue;
            }

            if (char === closingChar && depth > 0) {
                depth -= 1;
                if (depth === 0 && start !== -1) {
                    results.push(source.slice(start, index + 1));
                    start = -1;
                    if (results.length >= maxCount) {
                        break;
                    }
                }
            }
        }

        return results;
    }

    function parseJsonLike(raw) {
        if (raw === null || raw === undefined) return null;
        if (typeof raw === 'object') return raw;
        const text = String(raw).trim();
        if (!text) return null;
        const tryParse = (input) => {
            const candidate = String(input || '').trim();
            if (!candidate) return null;
            try {
                return JSON.parse(candidate);
            } catch (_) {
                const sanitized = sanitizeLooseJsonString(candidate);
                if (!sanitized || sanitized === candidate) return null;
                try {
                    return JSON.parse(sanitized);
                } catch (_) {
                    return null;
                }
            }
        };
        const direct = tryParse(text);
        if (direct !== null) return direct;
        const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
        if (fenced && fenced[1]) {
            const parsed = tryParse(fenced[1].trim());
            if (parsed !== null) return parsed;
        }
        const objMatch = text.match(/\{[\s\S]*\}/);
        if (objMatch) {
            const parsed = tryParse(objMatch[0]);
            if (parsed !== null) return parsed;
        }
        const arrMatch = text.match(/\[[\s\S]*\]/);
        if (arrMatch) {
            const parsed = tryParse(arrMatch[0]);
            if (parsed !== null) return parsed;
        }
        const balancedObjects = extractBalancedJsonBlocks(text, '{', '}');
        for (const candidate of balancedObjects) {
            const parsed = tryParse(candidate);
            if (parsed !== null) return parsed;
        }
        const balancedArrays = extractBalancedJsonBlocks(text, '[', ']');
        for (const candidate of balancedArrays) {
            const parsed = tryParse(candidate);
            if (parsed !== null) return parsed;
        }
        return null;
    }

    function normalizeDailyPlanTime(value) {
        const text = String(value || '').trim();
        if (!text) return '';
        const match = text.match(/(\d{1,2})\s*[:：]\s*(\d{1,2})/);
        if (!match) return '';
        const hour = Math.max(0, Math.min(23, Number(match[1])));
        const minute = Math.max(0, Math.min(59, Number(match[2])));
        if (!Number.isFinite(hour) || !Number.isFinite(minute)) return '';
        return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
    }

    function parseDailyPlanTimeRange(value) {
        const source = String(value || '');
        const matches = Array.from(source.matchAll(/(\d{1,2})\s*[:：]\s*(\d{1,2})/g));
        if (matches.length < 2) {
            return { startTime: '', endTime: '' };
        }
        return {
            startTime: normalizeDailyPlanTime(`${matches[0][1]}:${matches[0][2]}`),
            endTime: normalizeDailyPlanTime(`${matches[1][1]}:${matches[1][2]}`)
        };
    }

    function parseDailyPlanBoolean(value, fallbackValue) {
        if (typeof value === 'boolean') return value;
        const text = String(value || '').trim().toLowerCase();
        if (!text) return fallbackValue;
        if (['true', '1', 'yes', 'y', '是', '可', '可以', '随机', '灵活'].includes(text)) return true;
        if (['false', '0', 'no', 'n', '否', '不', '不可以', '固定'].includes(text)) return false;
        return fallbackValue;
    }

    function normalizeDailyPlanItems(items) {
        const source = Array.isArray(items) ? items : [];
        return source.map((item) => {
            const safeItem = item && typeof item === 'object' ? item : {};
            const range = parseDailyPlanTimeRange(
                safeItem.timeRange
                || safeItem.time_range
                || safeItem.time
                || safeItem.period
            );
            const startTime = normalizeDailyPlanTime(
                safeItem.startTime
                || safeItem.start_time
                || safeItem.start
                || range.startTime
            );
            const endTime = normalizeDailyPlanTime(
                safeItem.endTime
                || safeItem.end_time
                || safeItem.end
                || range.endTime
            );
            const location = String(
                safeItem.location
                || safeItem.place
                || safeItem.where
                || ''
            ).trim();
            const activity = String(
                safeItem.activity
                || safeItem.event
                || safeItem.content
                || safeItem.task
                || safeItem.plan
                || ''
            ).trim();
            if (!startTime || !endTime || !activity) {
                return null;
            }
            return {
                startTime,
                endTime,
                location,
                activity,
                isRandom: parseDailyPlanBoolean(
                    safeItem.isRandom !== undefined ? safeItem.isRandom : safeItem.is_random,
                    false
                ),
                isFlexible: parseDailyPlanBoolean(
                    safeItem.isFlexible !== undefined ? safeItem.isFlexible : safeItem.is_flexible,
                    true
                )
            };
        }).filter(Boolean);
    }

    function parseDailyPlanLabelBlocks(rawText) {
        const text = String(rawText || '')
            .replace(/```(?:json)?/gi, '')
            .replace(/```/g, '')
            .replace(/\r/g, '')
            .trim();
        if (!text) return [];

        const lines = text.split('\n').map((line) => line.trim()).filter(Boolean);
        const blocks = [];
        let current = null;

        const pushCurrent = () => {
            if (!current) return;
            blocks.push(current);
            current = null;
        };

        const ensureCurrent = () => {
            if (!current) current = {};
            return current;
        };

        const stripLabel = (line, pattern) => line.replace(pattern, '').trim();

        lines.forEach((line) => {
            if (/^(?:[-*]\s*)?(?:\[\s*event\s*\]|event|事件|行程|活动)\s*[:：]?/i.test(line)) {
                pushCurrent();
                current = {};
                const inlineActivity = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*event\s*\]|event|事件|行程|活动)\s*[:：]?\s*/i);
                if (inlineActivity) {
                    current.activity = inlineActivity;
                }
                return;
            }

            if (/^\d{1,2}\s*[:：]\s*\d{1,2}\s*(?:-|–|—|~|至|到)\s*\d{1,2}\s*[:：]\s*\d{1,2}/.test(line)) {
                const target = ensureCurrent();
                target.timeRange = line;
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*time\s*\]|time|时间|时段|时间段)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.timeRange = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*time\s*\]|time|时间|时段|时间段)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*start(?:\s*time)?\s*\]|start(?:\s*time)?|开始时间|开始)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.startTime = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*start(?:\s*time)?\s*\]|start(?:\s*time)?|开始时间|开始)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*end(?:\s*time)?\s*\]|end(?:\s*time)?|结束时间|结束)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.endTime = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*end(?:\s*time)?\s*\]|end(?:\s*time)?|结束时间|结束)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*location\s*\]|location|地点|位置)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.location = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*location\s*\]|location|地点|位置)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*activity\s*\]|activity|安排|内容)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.activity = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*activity\s*\]|activity|安排|内容)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*is[_\s-]*random\s*\]|is[_\s-]*random|随机)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.isRandom = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*is[_\s-]*random\s*\]|is[_\s-]*random|随机)\s*[:：]?\s*/i);
                return;
            }

            if (/^(?:[-*]\s*)?(?:\[\s*is[_\s-]*flexible\s*\]|is[_\s-]*flexible|灵活|可调整)\s*[:：]?/i.test(line)) {
                const target = ensureCurrent();
                target.isFlexible = stripLabel(line, /^(?:[-*]\s*)?(?:\[\s*is[_\s-]*flexible\s*\]|is[_\s-]*flexible|灵活|可调整)\s*[:：]?\s*/i);
                return;
            }

            if (current && !current.activity) {
                current.activity = line.replace(/^[*-]\s*/, '').trim();
            }
        });

        pushCurrent();
        return normalizeDailyPlanItems(blocks);
    }

    function parseDailyPlanAiResponse(rawText) {
        const parsed = parseJsonLike(rawText);
        if (Array.isArray(parsed)) {
            const normalized = normalizeDailyPlanItems(parsed);
            if (normalized.length > 0) return normalized;
        } else if (parsed && typeof parsed === 'object') {
            const nestedKeys = ['plan', 'dailyPlan', 'daily_plan', 'schedule', 'items', 'events', 'data'];
            for (const key of nestedKeys) {
                if (Array.isArray(parsed[key])) {
                    const normalized = normalizeDailyPlanItems(parsed[key]);
                    if (normalized.length > 0) return normalized;
                }
            }
        }

        const fallback = parseDailyPlanLabelBlocks(rawText);
        return fallback.length > 0 ? fallback : null;
    }

    async function callChatApiWithProfile(profile, prompt, options = {}) {
        const body = {
            model: String(options.modelOverride || profile.model || ''),
            messages: [{ role: 'user', content: String(prompt || '') }],
            temperature: Number.isFinite(Number(options.temperature)) ? Number(options.temperature) : Number(profile.temperature || 0.8)
        };
        const response = await fetch(profile.url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${profile.key || ''}`
            },
            body: JSON.stringify(body)
        });
        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`API请求失败(${response.status}): ${errorText}`);
        }
        const data = await response.json();
        const raw = data?.choices?.[0]?.message?.content ?? '';
        return {
            raw,
            parsed: parseJsonLike(raw)
        };
    }

    async function callMainApiPrompt(prompt, options = {}) {
        const profiles = getGroupApiProfiles();
        return callChatApiWithProfile(profiles.main, prompt, options);
    }

    function resolveGroupMemberDisplayName(group, memberType, memberId) {
        if (memberType === 'user') {
            const userNick = group?.settings?.myProfileInGroup?.nickname;
            if (userNick) return String(userNick);
            return String(appData?.globalUserProfile?.name || '你');
        }
        const contact = getContactById(memberId);
        const member = getGroupMemberRecord(group, 'char', memberId);
        if (member && member.groupNickname) return String(member.groupNickname);
        return getCharDisplayName(contact);
    }

    function getGroupContextLimit(group) {
        const mode = group?.settings?.mode === 'advanced' ? 'advanced' : 'classic';
        if (mode === 'advanced') {
            return Math.max(10, Number(group?.settings?.contextLimitAdvanced) || 100);
        }
        return Math.max(5, Number(group?.settings?.contextLimitClassic) || 30);
    }

    function getGroupContextMessages(group) {
        if (!group || !Array.isArray(group.chatHistory)) return [];
        const start = Math.max(0, Number(group.contextResetIndex) || 0);
        const limit = getGroupContextLimit(group);
        return group.chatHistory.slice(start).slice(-limit);
    }

    function toLegacyMessageTypeForRender(type) {
        if (type === 'red_packet') return 'red-packet';
        return type;
    }

    function resolveGroupBubbleStyleId(group, message) {
        const bubble = group?.settings?.bubbleStyle;
        if (!bubble || typeof bubble !== 'object') return '';
        const perMember = bubble.perMemberStyleId && typeof bubble.perMemberStyleId === 'object'
            ? bubble.perMemberStyleId
            : {};
        const key = message?.senderType === 'user' ? 'user' : String(message?.senderId || '');
        return String(perMember[key] || bubble.globalStyleId || '').trim();
    }

    function getGroupDisplayRole(message) {
        if (message.senderType === 'user') return 'user';
        if (message.senderType === 'system') return 'system';
        return 'assistant';
    }

    async function resolveGroupMessageAvatarUrl(group, message) {
        try {
            if (message?.senderDisplay?.isAnonymous) return null;
            if (message.senderType === 'user') {
                const key = group?.settings?.myProfileInGroup?.avatarKey || `${message.senderId}_user_avatar`;
                const blob = await db.getImage(key);
                if (blob) return URL.createObjectURL(blob);
                return 'https://i.postimg.cc/cLPP10Vm/4.jpg';
            }
            if (message.senderType === 'char') {
                const blob = await db.getImage(`${message.senderId}_avatar`);
                if (blob) return URL.createObjectURL(blob);
                return 'https://i.postimg.cc/kXq06mNq/ai-default.png';
            }
        } catch (_) { }
        return null;
    }

    async function appendGroupMessageToDom(group, message, options = {}) {
        if (isAdvancedDebugGroupMessage(message) || isHiddenGroupSystemMessage(message)) return;
        const role = getGroupDisplayRole(message);
        const isGroupAnonymous = Boolean(message?.senderDisplay?.isAnonymous);
        const senderTitle = !isGroupAnonymous && group?.settings?.groupTitleEnabled
            ? (message?.senderDisplay?.title || getGroupMemberRecord(group, message.senderType, message.senderId)?.title || '')
            : '';
        const senderLabel = role === 'assistant'
            ? (isGroupAnonymous
                ? String(message?.senderDisplay?.anonymousAlias || randomAnonymousAlias())
                : `${resolveGroupMemberDisplayName(group, message.senderType, message.senderId)}${senderTitle ? ` 路 ${senderTitle}` : ''}`)
            : '';
        const avatarOverride = await resolveGroupMessageAvatarUrl(group, message);
        const bubbleStyleId = resolveGroupBubbleStyleId(group, message);
        const passThrough = {};
        ['imageId', 'redPacketData', 'stickerId', 'stickerUrl', 'musicShareData', 'listenTogetherData', 'relationshipData', 'paymentData', 'quoteData', 'voicePayload'].forEach((key) => {
            if (message[key] !== undefined) {
                passThrough[key] = message[key];
            }
        });
        if (message.payload && typeof message.payload === 'object') {
            Object.assign(passThrough, message.payload);
        }
        const element = await createMessageElement(message.content, role, {
            isNew: false,
            isStaged: Boolean(options.isStaged),
            type: toLegacyMessageTypeForRender(message.type || 'text'),
            id: message.id,
            timestamp: message.timestamp,
            avatarOverride,
            senderLabel,
            payload: message.payload,
            redPacketData: message.payload,
            bubbleStyleId,
            groupMessage: true,
            ...passThrough
        });
        messageContainer.appendChild(element);
        if (options.scroll !== false) {
            scrollToBottom();
        }
    }

    async function appendGroupMessagesSequentiallyToDom(group, messages, intervalMs = 220) {
        if (!group || !Array.isArray(messages) || !messages.length) return;
        if (String(activeGroupChatId || '') !== String(group.id || '')) return;
        const gap = Math.max(60, Number(intervalMs) || 220);
        for (let i = 0; i < messages.length; i += 1) {
            await appendGroupMessageToDom(group, messages[i], { scroll: true });
            if (i < messages.length - 1) {
                await new Promise((resolve) => setTimeout(resolve, gap));
            }
        }
    }

    function resetGroupStagedQueue() {
        stagedGroupUserMessages = [];
        groupMemberManagerMode = 'view';
        clearGroupTypingIndicator(activeGroupChatId || '');
    }

    async function renderGroupChatHistory(group) {
        if (!group) return;
        hideGroupTypingBubble(group.id);
        messageContainer.innerHTML = '<div id="load-more-btn" class="load-more-btn hidden"></div>';
        lastRenderedTimestamp = 0;
        const rawHistory = Array.isArray(group.chatHistory) ? group.chatHistory : [];
        const history = rawHistory.filter((msg) => !isAdvancedDebugGroupMessage(msg) && !isHiddenGroupSystemMessage(msg));
        const cleanedHistory = rawHistory.filter((msg) => !isAdvancedDebugGroupMessage(msg));
        if (cleanedHistory.length !== rawHistory.length) {
            group.chatHistory = cleanedHistory;
            group.updatedAt = Date.now();
            saveAppData();
        }
        for (let i = 0; i < history.length; i += 1) {
            await appendGroupMessageToDom(group, history[i], { scroll: false });
        }
        if (stagedGroupUserMessages.length > 0) {
            for (let i = 0; i < stagedGroupUserMessages.length; i += 1) {
                await appendGroupMessageToDom(group, stagedGroupUserMessages[i], { isStaged: true, scroll: false });
            }
        }
        scrollToBottom();
    }

    async function applyGroupVisualSettings(group) {
        if (!messageContainer) return;
        const groupKey = String(group?.settings?.dailyBackgroundImageKey || '').trim();
        const globalKey = String(appData?.globalUserProfile?.backgroundKey || '').trim();
        const tryKeys = [];
        if (groupKey) tryKeys.push(groupKey);
        if (globalKey && globalKey !== groupKey) tryKeys.push(globalKey);
        for (const key of tryKeys) {
            try {
                const blob = await db.getImage(key);
                if (!blob) continue;
                messageContainer.style.backgroundImage = `url(${URL.createObjectURL(blob)})`;
                messageContainer.style.backgroundSize = 'cover';
                messageContainer.style.backgroundPosition = 'center';
                return;
            } catch (_) { }
        }
        messageContainer.style.backgroundImage = '';
    }

    function clearSingleChatDynamicVisualStateForGroup() {
        const styleTag = document.getElementById('dynamic-chat-style');
        if (styleTag) {
            styleTag.textContent = '';
        }
        document.body.classList.remove('chat-compact-mode');
        document.body.classList.remove('chat-bubble-time-mode');
    }

    function getGroupBubbleStyleLabel(styleId) {
        const value = String(styleId || '').trim();
        if (!value) return '系统默认气泡';
        if (value === 'soft') return 'soft（柔和）';
        if (value === 'candy') return 'candy（糖果）';
        if (value === 'mono') return 'mono（简洁）';
        if (value.startsWith('preset:')) {
        return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
        }
        return value;
    }

    function renderGroupBubbleMappingPreview(group) {
        if (!groupPersonalizationBubblePreview) return;
        const bubble = group?.settings?.bubbleStyle || {};
        const rows = [];
        rows.push(`全局：${getGroupBubbleStyleLabel(bubble.globalStyleId)}`);
        const mapping = bubble.perMemberStyleId && typeof bubble.perMemberStyleId === 'object'
            ? bubble.perMemberStyleId
            : {};
        Object.keys(mapping).forEach((key) => {
            const style = String(mapping[key] || '').trim();
            if (!style) return;
            const memberLabel = key === 'user'
                ? `用户（${appData?.globalUserProfile?.name || '你'}）`
                : resolveGroupMemberDisplayName(group, 'char', key);
            rows.push(`${memberLabel}：${getGroupBubbleStyleLabel(style)}`);
        });
        groupPersonalizationBubblePreview.textContent = rows.length ? rows.join('\n') : '当前：系统默认气泡';
    }

    function populateGroupBubbleMemberSelect(group, selectedMemberKey = 'user') {
        if (!groupPersonalizationBubbleMemberSelect) return;
        const targetKey = String(selectedMemberKey || 'user');
        groupPersonalizationBubbleMemberSelect.innerHTML = '';
        const userOpt = document.createElement('option');
        userOpt.value = 'user';
        userOpt.textContent = `用户（${appData?.globalUserProfile?.name || '你'}）`;
        groupPersonalizationBubbleMemberSelect.appendChild(userOpt);
        (group?.members || [])
            .filter((m) => m.memberType === 'char')
            .forEach((member) => {
                const opt = document.createElement('option');
                opt.value = String(member.memberId);
                opt.textContent = resolveGroupMemberDisplayName(group, 'char', member.memberId);
                groupPersonalizationBubbleMemberSelect.appendChild(opt);
            });
        if (Array.from(groupPersonalizationBubbleMemberSelect.options).some((opt) => opt.value === targetKey)) {
            groupPersonalizationBubbleMemberSelect.value = targetKey;
        } else {
            groupPersonalizationBubbleMemberSelect.value = 'user';
        }
    }

    function getGroupBubbleStyleIdForSelection(group) {
        const bubble = group?.settings?.bubbleStyle || { globalStyleId: null, perMemberStyleId: {} };
        const scope = groupPersonalizationBubbleScope === 'single' ? 'single' : 'global';
        if (scope === 'single') {
            const key = String(groupPersonalizationBubbleMemberSelect?.value || groupPersonalizationBubbleMemberKey || 'user');
            const mapping = bubble.perMemberStyleId && typeof bubble.perMemberStyleId === 'object'
                ? bubble.perMemberStyleId
                : {};
            return String(mapping[key] || bubble.globalStyleId || '').trim();
        }
        return String(bubble.globalStyleId || '').trim();
    }

    function resolveCssPresetDeclarations(styleId, role) {
        const raw = String(styleId || '').trim();
        if (!raw.startsWith('preset:')) return null;
        const presetName = raw.slice('preset:'.length).trim();
        if (!presetName) return null;
        const warehouse = Array.isArray(appData?.themeSettings?.bubbleCssWarehouse)
            ? appData.themeSettings.bubbleCssWarehouse
            : [];
        const preset = warehouse.find((item) => String(item?.name || '').trim() === presetName);
        const css = String(preset?.css || '');
        if (!css) return null;
        const selectorKeyword = role === 'user' ? 'user-row' : 'assistant-row';
        const blockRegex = /([^{}]+)\{([^{}]+)\}/g;
        let matchedBody = '';
        let match = null;
        while ((match = blockRegex.exec(css)) !== null) {
            const selectors = String(match[1] || '');
            if (!selectors.includes(selectorKeyword)) continue;
            matchedBody = String(match[2] || '').trim();
            if (matchedBody) break;
        }
        if (!matchedBody) return null;
        const styleMap = {};
        matchedBody.split(';').forEach((row) => {
            const idx = row.indexOf(':');
            if (idx <= 0) return;
            const key = row.slice(0, idx).trim().toLowerCase();
            const value = row.slice(idx + 1).trim();
            if (!key || !value) return;
            styleMap[key] = value.replace(/\s*!important\s*$/i, '');
        });
        return styleMap;
    }

    function applyResolvedPresetStyleToBubble(bubble, styleMap) {
        if (!bubble || !styleMap) return false;
        let applied = false;
        const background = styleMap.background || styleMap['background-color'];
        if (background) {
            bubble.style.background = background;
            applied = true;
        }
        if (styleMap.color) {
            bubble.style.color = styleMap.color;
            applied = true;
        }
        if (styleMap.border) {
            bubble.style.border = styleMap.border;
            applied = true;
        }
        return applied;
    }

    function getMessageRowRoleForBubbleStyle(messageRow) {
        if (!messageRow) return '';
        if (messageRow.classList.contains('user-row')) return 'user';
        if (messageRow.classList.contains('assistant-row')) return 'assistant';
        return '';
    }

    function applyNamedBubbleStyle(messageRow, styleId) {
        if (!messageRow) return;
        const bubble = messageRow.querySelector('.message');
        if (!bubble) return;
        const normalizedRaw = String(styleId || '').trim();
        const rowRole = getMessageRowRoleForBubbleStyle(messageRow);
        const presetStyleMap = resolveCssPresetDeclarations(normalizedRaw, rowRole);
        if (presetStyleMap && applyResolvedPresetStyleToBubble(bubble, presetStyleMap)) {
            return;
        }
        const normalized = normalizedRaw.toLowerCase();
        if (!normalized || normalized === 'default') {
            bubble.style.background = '';
            bubble.style.color = '';
            bubble.style.border = '';
            return;
        }
        if (normalized === 'soft') {
            bubble.style.background = '#f3f7ff';
            bubble.style.color = '#1e2b45';
            bubble.style.border = '1px solid #dbe7ff';
            return;
        }
        if (normalized === 'candy') {
            bubble.style.background = '#ffeef5';
            bubble.style.color = '#4d1730';
            bubble.style.border = '1px solid #ffd3e6';
            return;
        }
        if (normalized === 'mono') {
            bubble.style.background = '#f5f5f5';
            bubble.style.color = '#222';
            bubble.style.border = '1px solid #d8d8d8';
            return;
        }
        if (normalized.startsWith('#')) {
            bubble.style.background = normalized;
            bubble.style.color = '#111';
            bubble.style.border = 'none';
            return;
        }
        if (normalized.startsWith('preset:')) {
            return;
        }
        bubble.style.background = '';
        bubble.style.color = '';
        bubble.style.border = '';
    }

    function updateGroupPersonalizationBubbleUi(group) {
        if (!group) return;
        const isSingle = groupPersonalizationBubbleScope === 'single';
        if (groupPersonalizationBubbleMemberWrap) {
            groupPersonalizationBubbleMemberWrap.classList.toggle('hidden', !isSingle);
        }
        if (isSingle && groupPersonalizationBubbleMemberSelect) {
            groupPersonalizationBubbleMemberKey = String(groupPersonalizationBubbleMemberSelect.value || groupPersonalizationBubbleMemberKey || 'user');
        }
        const selectedStyle = getGroupBubbleStyleIdForSelection(group);
        renderGroupBubbleMappingPreview(group);
        if (!groupPersonalizationBubblePreview) return;
        const scopeText = isSingle
            ? '当前对象：' + resolveGroupMemberDisplayName(group, groupPersonalizationBubbleMemberKey === 'user' ? 'user' : 'char', groupPersonalizationBubbleMemberKey === 'user' ? 'user' : groupPersonalizationBubbleMemberKey)
            : '当前对象：全群默认';
        groupPersonalizationBubblePreview.textContent = scopeText + '\n当前样式：' + getGroupBubbleStyleLabel(selectedStyle) + '\n\n' + groupPersonalizationBubblePreview.textContent;
    }

    function loadGroupPersonalizationBubbleState(group) {
        if (!group) return;
        if (!group.settings.bubbleStyle || typeof group.settings.bubbleStyle !== 'object') {
            group.settings.bubbleStyle = { globalStyleId: null, perMemberStyleId: {} };
        }
        groupPersonalizationBubbleScope = String(groupPersonalizationBubbleScope || 'global');
        groupPersonalizationBubbleMemberKey = String(groupPersonalizationBubbleMemberKey || 'user');
        populateGroupBubbleMemberSelect(group, groupPersonalizationBubbleMemberKey);
        if (groupPersonalizationBubbleScopeSelect) {
            groupPersonalizationBubbleScopeSelect.value = groupPersonalizationBubbleScope;
        }
        updateGroupPersonalizationBubbleUi(group);
    }

    function clearGroupBubbleStyleForCurrentSelection(group) {
        if (!group) return;
        if (!group.settings.bubbleStyle || typeof group.settings.bubbleStyle !== 'object') {
            group.settings.bubbleStyle = { globalStyleId: null, perMemberStyleId: {} };
        }
        const bubble = group.settings.bubbleStyle;
        if (groupPersonalizationBubbleScope === 'single') {
            const memberKey = String(groupPersonalizationBubbleMemberSelect?.value || 'user');
            groupPersonalizationBubbleMemberKey = memberKey;
            if (!bubble.perMemberStyleId || typeof bubble.perMemberStyleId !== 'object') {
                bubble.perMemberStyleId = {};
            }
            delete bubble.perMemberStyleId[memberKey];
        } else {
            bubble.globalStyleId = null;
        }
        renderGroupBubbleMappingPreview(group);
    }

    async function updateThreadComposerMode() {
        const isGroup = Boolean(activeGroupChatId);
        if (cameraBtn) cameraBtn.style.display = isGroup ? 'none' : '';
        if (aiHelperButton) aiHelperButton.style.display = isGroup ? 'none' : '';
        const relationshipFn = document.getElementById('fn-relationship');
        const weatherFn = document.getElementById('fn-ai-weather');
        if (relationshipFn) relationshipFn.style.display = isGroup ? 'none' : '';
        if (weatherFn) weatherFn.style.display = isGroup ? 'none' : '';
        const videoFnLabel = document.querySelector('#fn-video-call .function-label');
        if (videoFnLabel) videoFnLabel.textContent = isGroup ? '群视频' : '视频通话';
        const listenFnLabel = document.querySelector('#fn-listen-together .function-label');
        if (listenFnLabel) listenFnLabel.textContent = isGroup ? '一起听歌' : '音乐';
        if (!isGroup) {
            const voteBtn = document.getElementById('group-vote-btn');
            const freeTalkBtn = document.getElementById('group-free-talk-btn');
            const memorySyncBtn = document.getElementById('group-memory-sync-btn');
            if (voteBtn) voteBtn.remove();
            if (freeTalkBtn) freeTalkBtn.remove();
            if (memorySyncBtn) memorySyncBtn.remove();
            return;
        }
        const toolbar = document.querySelector('.chat-functions-toolbar');
        if (!toolbar) return;
        if (!document.getElementById('group-vote-btn')) {
            const voteBtn = document.createElement('button');
            voteBtn.id = 'group-vote-btn';
            voteBtn.className = 'tool-button';
            voteBtn.title = '发起群投票';
            voteBtn.textContent = '投票';
            toolbar.insertBefore(voteBtn, moreFunctionsButton);
            voteBtn.addEventListener('click', () => {
                openGroupPollCreator();
            });
        }
        if (!document.getElementById('group-free-talk-btn')) {
            const freeTalkBtn = document.createElement('button');
            freeTalkBtn.id = 'group-free-talk-btn';
            freeTalkBtn.className = 'tool-button';
            freeTalkBtn.title = '自由发言';
            freeTalkBtn.textContent = '自由';
            toolbar.insertBefore(freeTalkBtn, moreFunctionsButton);
            freeTalkBtn.addEventListener('click', () => {
                runGroupFreeTalk();
            });
        }
        if (!document.getElementById('group-memory-sync-btn')) {
            const memorySyncBtn = document.createElement('button');
            memorySyncBtn.id = 'group-memory-sync-btn';
            memorySyncBtn.className = 'tool-button';
            memorySyncBtn.title = '群记忆同步';
            memorySyncBtn.textContent = '同步';
            toolbar.insertBefore(memorySyncBtn, moreFunctionsButton);
            memorySyncBtn.addEventListener('click', () => {
                runGroupMemorySync();
            });
        }
    }

    async function openGroupChat(groupId) {
        const group = getGroupById(groupId);
        if (!group) return;
        resetBubbleEditorContext();
        activeGroupChatId = group.id;
        activeChatContactId = null;
        resetChatState();
        resetGroupStagedQueue();
        bindCoreChatEventFallbacks();
        clearSingleChatDynamicVisualStateForGroup();
        await updateThreadComposerMode();
        await applyGroupVisualSettings(group);
        updateChatHeader();
        bindCoreChatEventFallbacks();
        switchToView('chat-window-view');
        await renderGroupChatHistory(group);
    }
