    function getSettingsField(id) {
        return document.getElementById(id);
    }

    function setSettingsFieldValue(id, value) {
        const field = getSettingsField(id);
        if (field) field.value = value == null ? '' : value;
    }

    function setSettingsFieldChecked(id, checked) {
        const field = getSettingsField(id);
        if (field) field.checked = Boolean(checked);
    }

    function getSettingsFieldValue(id) {
        const field = getSettingsField(id);
        return field ? field.value : '';
    }

    function getSettingsFieldChecked(id) {
        const field = getSettingsField(id);
        return field ? Boolean(field.checked) : false;
    }

    function getSettingsFieldNumber(id, fallback) {
        const numericValue = Number(getSettingsFieldValue(id));
        return Number.isFinite(numericValue) ? numericValue : fallback;
    }

    function getDefaultMinimaxTtsSettings() {
        return {
            apiKey: '',
            voiceId: 'female-tianmei',
            model: 'speech-2.8-hd',
            voiceLibrary: []
        };
    }

    function normalizeMinimaxVoiceLibraryItem(source) {
        const input = source && typeof source === 'object' ? source : {};
        return {
            id: String(input.id || input.voiceId || input.voice || '').trim(),
            remark: String(input.remark || input.note || '').trim()
        };
    }

    function normalizeMinimaxVoiceLibrary(source) {
        if (!Array.isArray(source)) return [];
        const seen = new Set();
        return source
            .map(normalizeMinimaxVoiceLibraryItem)
            .filter((item) => {
                if (!item.id || seen.has(item.id)) return false;
                seen.add(item.id);
                return true;
            });
    }

    function normalizeMinimaxTtsSettings(source) {
        const defaults = getDefaultMinimaxTtsSettings();
        const input = source && typeof source === 'object' ? source : {};
        const rawModel = String(input.model || defaults.model).trim() || defaults.model;
        const normalizedModel = /^(speech-2\.8-hd|speech-2\.8-turbo)$/i.test(rawModel)
            ? rawModel.toLowerCase()
            : defaults.model;
        return {
            apiKey: String(input.apiKey || input.key || '').trim(),
            voiceId: String(input.voiceId || input.voice || '').trim(),
            model: normalizedModel,
            voiceLibrary: normalizeMinimaxVoiceLibrary(input.voiceLibrary)
        };
    }

    function ensureMinimaxTtsSettings() {
        if (!appData.appSettings) appData.appSettings = {};
        appData.appSettings.minimaxTts = normalizeMinimaxTtsSettings(appData.appSettings.minimaxTts);
        return appData.appSettings.minimaxTts;
    }

    function createMinimaxVoiceLibraryItem(item = {}) {
        const normalized = normalizeMinimaxVoiceLibraryItem(item);
        const card = document.createElement('div');
        card.className = 'card voice-library-item';
        card.innerHTML = `
            <div class="form-group">
                <label>音色 ID</label>
                <input type="text" class="minimax-voice-library-id" placeholder="例如：female-tianmei" value="${escapeHtml(normalized.id)}">
            </div>
            <div class="form-group">
                <label>备注</label>
                <input type="text" class="minimax-voice-library-remark" placeholder="例如：温柔女声" value="${escapeHtml(normalized.remark)}">
            </div>
            <div class="worldbook-action-row">
                <button type="button" class="danger-button minimax-voice-library-delete">删除</button>
            </div>
        `;
        const deleteButton = card.querySelector('.minimax-voice-library-delete');
        if (deleteButton) {
            deleteButton.addEventListener('click', () => {
                card.remove();
                if (minimaxVoiceLibraryList && !minimaxVoiceLibraryList.querySelector('.voice-library-item')) {
                    minimaxVoiceLibraryList.innerHTML = '<p class="placeholder-text">还没有添加音色，角色会先使用全局默认音色。</p>';
                }
            });
        }
        return card;
    }

    function collectMinimaxVoiceLibraryFromUi() {
        if (!minimaxVoiceLibraryList) return [];
        return Array.from(minimaxVoiceLibraryList.querySelectorAll('.voice-library-item'))
            .map((card) => normalizeMinimaxVoiceLibraryItem({
                id: card.querySelector('.minimax-voice-library-id')?.value,
                remark: card.querySelector('.minimax-voice-library-remark')?.value
            }))
            .filter((item) => item.id);
    }

    function renderMinimaxVoiceLibrary(settingsOverride = null) {
        if (!minimaxVoiceLibraryList) return;
        const settings = normalizeMinimaxTtsSettings(settingsOverride || ensureMinimaxTtsSettings());
        minimaxVoiceLibraryList.innerHTML = '';
        if (!settings.voiceLibrary.length) {
            minimaxVoiceLibraryList.innerHTML = '<p class="placeholder-text">还没有添加音色，角色会先使用全局默认音色。</p>';
            return;
        }
        settings.voiceLibrary.forEach((item) => {
            minimaxVoiceLibraryList.appendChild(createMinimaxVoiceLibraryItem(item));
        });
    }

    function renderAiEditorTtsVoiceOptions(selectedVoiceId = '') {
        if (!aiEditorTtsVoiceSelect) return;
        const settings = ensureMinimaxTtsSettings();
        const library = normalizeMinimaxVoiceLibrary(settings.voiceLibrary);
        const selectedId = String(selectedVoiceId || '').trim();
        let optionsHtml = '<option value="">跟随全局默认</option>';
        library.forEach((item) => {
            const label = item.remark ? `${escapeHtml(item.remark)} (${escapeHtml(item.id)})` : escapeHtml(item.id);
            optionsHtml += `<option value="${escapeHtml(item.id)}">${label}</option>`;
        });
        if (selectedId && !library.some((item) => item.id === selectedId)) {
            optionsHtml += `<option value="${escapeHtml(selectedId)}">已失效音色 (${escapeHtml(selectedId)})</option>`;
        }
        aiEditorTtsVoiceSelect.innerHTML = optionsHtml;
        aiEditorTtsVoiceSelect.value = selectedId;
        if (aiEditorTtsVoiceSelect.value !== selectedId) {
            aiEditorTtsVoiceSelect.value = '';
        }
    }

    function resolveContactTtsVoiceId(contact, settingsOverride = null) {
        const settings = normalizeMinimaxTtsSettings(settingsOverride || ensureMinimaxTtsSettings());
        const library = settings.voiceLibrary || [];
        const roleVoiceId = String(contact && contact.ttsVoiceId || '').trim();
        if (roleVoiceId && library.some((item) => item.id === roleVoiceId)) {
            return {
                voiceId: roleVoiceId,
                source: 'contact'
            };
        }
        return {
            voiceId: String(settings.voiceId || '').trim(),
            source: 'global'
        };
    }

    function writeMinimaxTtsSettingsToUI(settingsOverride = null) {
        const settings = normalizeMinimaxTtsSettings(settingsOverride || ensureMinimaxTtsSettings());
        if (voiceCallTtsProviderSelect) {
            voiceCallTtsProviderSelect.value = appData?.appSettings?.voiceCallTtsProvider || '';
        }
        if (minimaxTtsApiKeyInput) minimaxTtsApiKeyInput.value = settings.apiKey || '';
        if (minimaxTtsVoiceInput) minimaxTtsVoiceInput.value = settings.voiceId || '';
        renderMinimaxVoiceLibrary(settings);
    }

    function readMinimaxTtsSettingsFromUI() {
        const current = normalizeMinimaxTtsSettings(ensureMinimaxTtsSettings());
        return normalizeMinimaxTtsSettings({
            apiKey: minimaxTtsApiKeyInput ? minimaxTtsApiKeyInput.value : current.apiKey,
            voiceId: minimaxTtsVoiceInput ? minimaxTtsVoiceInput.value : current.voiceId,
            model: current.model,
            voiceLibrary: collectMinimaxVoiceLibraryFromUi()
        });
    }

    function isMinimaxTtsConfigured(settingsOverride = null) {
        const settings = normalizeMinimaxTtsSettings(settingsOverride || ensureMinimaxTtsSettings());
        return Boolean(settings.apiKey && settings.voiceId);
    }

    let activeTtsAudio = null;
    let activeTtsObjectUrl = '';
    let activeTtsRequestController = null;
    let lastTtsAudioDebugInfo = null;
    let lastTtsResponseFieldInfo = null;
    let ttsPlaybackGeneration = 0;
    let activeTtsPlaybackGeneration = 0;

    function createTtsPlaybackStaleError(generation, phase) {
        const error = new Error(`TTS 播放任务已失效(generation=${generation}, phase=${phase})`);
        error.name = 'TtsPlaybackStaleError';
        return error;
    }

    function isTtsPlaybackStaleError(error) {
        return Boolean(error && error.name === 'TtsPlaybackStaleError');
    }

    function getDebugTextPreview(text, maxLength = 60) {
        return String(text || '').replace(/\s+/g, ' ').trim().slice(0, maxLength);
    }

    function getDebugClassListValue(element) {
        return element && element.classList ? Array.from(element.classList).join(' ') : '';
    }

    function debugLogJson(label, payload) {
        try {
            console.log(`${label} ${JSON.stringify(payload || {})}`);
        } catch (error) {
            console.log(label, payload);
        }
    }

    function invalidateActiveTtsPlayback(reason = 'unknown') {
        activeTtsPlaybackGeneration = ++ttsPlaybackGeneration;
        console.log('[VoiceCallTTS] 失效当前播放代次', {
            reason,
            activeGeneration: activeTtsPlaybackGeneration
        });
        return activeTtsPlaybackGeneration;
    }

    function createActiveTtsPlaybackSession(source = '') {
        const generation = invalidateActiveTtsPlayback(source ? `${source}:replace` : 'play:replace');
        console.log('[VoiceCallTTS] 创建播放代次', {
            source,
            generation
        });
        return generation;
    }

    function ensureTtsPlaybackSessionActive(generation, phase) {
        if (generation !== activeTtsPlaybackGeneration) {
            console.log('[VoiceCallTTS] 丢弃过期播放任务', {
                generation,
                activeGeneration: activeTtsPlaybackGeneration,
                phase
            });
            throw createTtsPlaybackStaleError(generation, phase);
        }
    }

    function ensureActiveTtsAudio() {
        if (!activeTtsAudio) {
            activeTtsAudio = new Audio();
            activeTtsAudio.preload = 'auto';
        }
        activeTtsAudio.volume = 1;
        activeTtsAudio.muted = false;
        return activeTtsAudio;
    }

    function revokeActiveTtsObjectUrl() {
        if (!activeTtsObjectUrl) return;
        URL.revokeObjectURL(activeTtsObjectUrl);
        activeTtsObjectUrl = '';
    }

    function stopActiveTtsPlayback() {
        if (activeTtsRequestController) {
            activeTtsRequestController.abort();
            activeTtsRequestController = null;
        }
        if (window.speechSynthesis && typeof window.speechSynthesis.cancel === 'function') {
            window.speechSynthesis.cancel();
        }
        if (activeTtsAudio) {
            activeTtsAudio.pause();
            activeTtsAudio.removeAttribute('src');
            activeTtsAudio.load();
        }
        revokeActiveTtsObjectUrl();
    }

    const MINIMAX_TTS_AFFECT_TAG_LIST = [
        'laughs',
        'chuckle',
        'coughs',
        'clear-throat',
        'groans',
        'breath',
        'pant',
        'inhale',
        'exhale',
        'gasps',
        'sniffs',
        'sighs',
        'snorts',
        'burps',
        'lip-smacking',
        'humming',
        'hissing',
        'emm',
        'sneezes'
    ];
    const MINIMAX_TTS_AFFECT_TAGS = new Set(MINIMAX_TTS_AFFECT_TAG_LIST);
    const MINIMAX_TTS_AFFECT_TAG_PATTERN = new RegExp(`[（(]\\s*(?:${MINIMAX_TTS_AFFECT_TAG_LIST.map((tag) => tag.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')).join('|')})\\s*[)）]`, 'gi');
    const VOICE_CALL_PAUSE_TAG_PATTERN = /<#\d{1,2}(?:\.\d{1,2})?#>/g;

    function isSupportedMinimaxTtsAffectTag(content) {
        return MINIMAX_TTS_AFFECT_TAGS.has(String(content || '').trim().toLowerCase());
    }

    function shouldPreserveVoiceCallSpeechParenthetical(content) {
        return isSupportedMinimaxTtsAffectTag(content);
    }

    function hideSupportedVoiceCallAffectTags(text) {
        return String(text || '')
            .replace(MINIMAX_TTS_AFFECT_TAG_PATTERN, ' ')
            .replace(/[ \t]{2,}/g, ' ')
            .replace(/\s+([，。！？!?；;,.])/g, '$1')
            .replace(/\n[ \t]+/g, '\n')
            .trim();
    }

    function hideVoiceMessageSilentMarkers(text, options = {}) {
        const hideAffectTags = options.hideAffectTags !== false;
        let output = String(text || '');
        output = output.replace(/\[[^[\]\n]{1,120}\]/g, ' ');
        if (hideAffectTags) {
            output = output.replace(MINIMAX_TTS_AFFECT_TAG_PATTERN, ' ');
        }
        return output
            .replace(/[ \t]{2,}/g, ' ')
            .replace(/\s+([，。！？!?；;,.])/g, '$1')
            .replace(/\n[ \t]+/g, '\n')
            .trim();
    }

    function normalizeVoiceCallAffectTags(text) {
        return String(text || '').replace(/[（(]\s*([A-Za-z-]+)\s*[)）]/g, (match, inner) => {
            const normalized = String(inner || '').trim().toLowerCase();
            if (!isSupportedMinimaxTtsAffectTag(normalized)) return match;
            return `(${normalized})`;
        });
    }

    function normalizeVoiceCallPauseTags(text) {
        return String(text || '').replace(/[<＜]\s*#\s*(\d{1,2}(?:\.\d{1,2})?)\s*#\s*[>＞]/g, (match, seconds) => {
            const numeric = Number(seconds);
            if (!Number.isFinite(numeric) || numeric < 0.01 || numeric > 99.99) return match;
            return `<#${numeric.toFixed(2).replace(/\.00$/, '').replace(/(\.\d)0$/, '$1')}#>`;
        });
    }

    function normalizeVoiceCallSpeechSynthesisText(text) {
        return normalizeVoiceCallPauseTags(normalizeVoiceCallAffectTags(text));
    }

    function stripVoicePerformanceDescriptions(text, options = {}) {
        const preserveSpeechControls = Boolean(options.preserveSpeechControls);
        return String(text || '')
            .replace(/\[[^[\]\n]{1,120}\]|#[^#\n]{1,80}#|[*＊][^*＊\n]+[*＊]|（[^（）()\n]{1,80}[）)]|\([^()\n]{1,80}\)/g, (token) => {
                if (VOICE_CALL_PAUSE_TAG_PATTERN.test(token)) {
                    VOICE_CALL_PAUSE_TAG_PATTERN.lastIndex = 0;
                    return token;
                }
                VOICE_CALL_PAUSE_TAG_PATTERN.lastIndex = 0;
                if (!preserveSpeechControls) return '';
                if (token.startsWith('(') && token.endsWith(')')) {
                    const inner = token.slice(1, -1).trim();
                    if (shouldPreserveVoiceCallSpeechParenthetical(inner)) {
                        return token;
                    }
                }
                return '';
            })
            .replace(/\s{2,}/g, ' ')
            .trim();
    }

    function clampVoiceSegmentNumber(value, min, max, fallback) {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return fallback;
        return Math.min(max, Math.max(min, numeric));
    }

    function normalizeVoiceSegmentSpeed(value, emotion = 'neutral') {
        const normalizedEmotion = ALLOWED_VOICE_SEGMENT_EMOTIONS.has(String(emotion || '').trim().toLowerCase())
            ? String(emotion || '').trim().toLowerCase()
            : 'neutral';
        const emotionSpeed = VOICE_SEGMENT_EMOTION_SPEED_MAP[normalizedEmotion] || 1;
        const requestedSpeed = Number(value);
        const baseSpeed = Number.isFinite(requestedSpeed) ? requestedSpeed : 1;
        return clampVoiceSegmentNumber(baseSpeed * emotionSpeed, 0.9, 1.0, emotionSpeed);
    }

    function getVoiceSegmentDurationSeconds(text) {
        return Math.max(1, Math.round(String(text || '').trim().length / 4));
    }

    function buildVoiceWaveBarsHTML() {
        return Array.from({ length: 15 }, () => `<div class="wave-bar" style="height: ${Math.random() * 80 + 20}%;"></div>`).join('');
    }

    function buildVoiceSegmentBubbleHTML(segmentText, segmentIndex = 0) {
        const cleanText = hideVoiceMessageSilentMarkers(segmentText);
        const duration = getVoiceSegmentDurationSeconds(cleanText);
        const bubbleWidth = Math.min(220, 100 + duration * 10);
        const safeText = escapeHtml(cleanText).replace(/\n/g, '<br>');
        return `
            <div class="voice-segment-item" data-segment-index="${segmentIndex}">
                <div class="message message-voice voice-segment-bubble" style="width: ${bubbleWidth}px;">
                    <div class="play-icon-container"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"></path></svg></div>
                    <div class="sound-wave">${buildVoiceWaveBarsHTML()}</div>
                    <span class="voice-duration">${duration}"</span>
                </div>
                <div class="voice-text-content">${safeText}</div>
            </div>
        `;
    }

    function buildVoiceMessageContentHTML(text, voicePayload) {
        const normalizedPayload = normalizeVoiceSegmentsPayload(voicePayload);
        if (normalizedPayload && normalizedPayload.segments.length) {
            return `<div class="voice-segment-list">${normalizedPayload.segments.map((segment, index) => buildVoiceSegmentBubbleHTML(segment.text, index)).join('')}</div>`;
        }
        return buildVoiceSegmentBubbleHTML(text, 0, 1);
    }

    function normalizeVoiceSegmentsPayload(payload) {
        if (!payload || typeof payload !== 'object' || !Array.isArray(payload.segments)) return null;
        const segments = payload.segments
            .slice(0, 4)
            .map((segment) => {
                const text = String(segment && segment.text || '').trim();
                if (!text) return null;
                const emotion = String(segment && segment.emotion || 'neutral').trim().toLowerCase();
                return {
                    text,
                    emotion: ALLOWED_VOICE_SEGMENT_EMOTIONS.has(emotion) ? emotion : 'neutral',
                    speed: normalizeVoiceSegmentSpeed(segment && segment.speed, emotion),
                    pitch: FIXED_VOICE_SEGMENT_PITCH
                };
            })
            .filter(Boolean);
        if (!segments.length) return null;
        return { segments };
    }

    function parseVoiceDirectiveBody(rawBody) {
        const body = String(rawBody || '').trim();
        if (!body) return { text: '', payload: null };
        if (!body.startsWith('{')) return { text: body, payload: null };
        try {
            const parsed = JSON.parse(body);
            const payload = normalizeVoiceSegmentsPayload(parsed);
            if (!payload) return { text: body, payload: null };
            return {
                text: payload.segments.map((segment) => segment.text).join(''),
                payload
            };
        } catch (error) {
            return { text: body, payload: null };
        }
    }

    function sanitizeTextForSpeech(text, options = {}) {
        const source = String(options.source || '').trim();
        const prepared = source === 'voice_call'
            ? normalizeVoiceCallSpeechSynthesisText(text)
            : String(text || '');
        const compact = String(prepared || '')
            .replace(/```[\s\S]*?```/g, ' ')
            .replace(/`([^`]+)`/g, '$1')
            .replace(/\s+/g, ' ')
            .trim();
        if (!compact) return '';
        if (source === 'voice_call') {
            return stripVoicePerformanceDescriptions(compact, { preserveSpeechControls: true }) || compact;
        }
        if (source === 'voice_message') {
            return stripVoicePerformanceDescriptions(compact, { preserveSpeechControls: true }) || compact;
        }
        return compact
            .replace(/[#>*_~\-]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function createAudioDataUrlFromBase64(base64Text, mimeType = 'audio/mpeg') {
        const pureBase64 = String(base64Text || '').trim().replace(/^data:[^;]+;base64,/i, '');
        if (!pureBase64) return '';
        return `data:${mimeType};base64,${pureBase64}`;
    }

    function decodeBase64ToBytes(base64Text) {
        const pureBase64 = String(base64Text || '').trim().replace(/^data:[^;]+;base64,/i, '');
        if (!pureBase64) return null;
        const normalizedBase64 = pureBase64.replace(/-/g, '+').replace(/_/g, '/');
        const paddedBase64 = normalizedBase64 + '='.repeat((4 - normalizedBase64.length % 4) % 4);
        const binary = atob(paddedBase64);
        const len = binary.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i += 1) {
            bytes[i] = binary.charCodeAt(i);
        }
        return bytes;
    }

    function decodeHexToBytes(hexText) {
        const pureHex = String(hexText || '').trim().replace(/\s+/g, '');
        if (!pureHex || pureHex.length % 2 !== 0 || !/^[0-9a-f]+$/i.test(pureHex)) return null;
        const bytes = new Uint8Array(pureHex.length / 2);
        for (let i = 0; i < pureHex.length; i += 2) {
            bytes[i / 2] = parseInt(pureHex.slice(i, i + 2), 16);
        }
        return bytes;
    }

    function looksLikeHexAudio(text) {
        const value = String(text || '').trim().replace(/\s+/g, '');
        if (!value || value.length < 128 || value.length % 2 !== 0) return false;
        return /^[0-9a-f]+$/i.test(value);
    }

    function decodeAudioTextToBytes(audioText) {
        if (looksLikeHexAudio(audioText)) {
            return {
                bytes: decodeHexToBytes(audioText),
                encoding: 'hex'
            };
        }
        return {
            bytes: decodeBase64ToBytes(audioText),
            encoding: 'base64'
        };
    }

    function decodeBase64ToText(base64Text) {
        const bytes = decodeBase64ToBytes(base64Text);
        if (!bytes || !bytes.length) return '';
        try {
            return new TextDecoder('utf-8').decode(bytes);
        } catch (error) {
            let output = '';
            const limit = Math.min(bytes.length, 256);
            for (let i = 0; i < limit; i += 1) {
                output += String.fromCharCode(bytes[i]);
            }
            return output;
        }
    }

    function base64ToBlob(base64Text, mimeType = 'audio/mpeg') {
        const bytes = decodeAudioTextToBytes(base64Text).bytes;
        if (!bytes || !bytes.length) return null;
        return new Blob([bytes], { type: mimeType });
    }

    function inferAudioMimeTypeFromBytes(bytes, fallback = 'audio/mpeg') {
        if (!bytes || bytes.length < 4) return fallback;
        const b0 = bytes[0];
        const b1 = bytes[1];
        const b2 = bytes[2];
        const b3 = bytes[3];

        if (b0 === 0x52 && b1 === 0x49 && b2 === 0x46 && b3 === 0x46) return 'audio/wav';
        if (b0 === 0x49 && b1 === 0x44 && b2 === 0x33) return 'audio/mpeg';
        if (b0 === 0xff && (b1 & 0xe0) === 0xe0) return 'audio/mpeg';
        if (b0 === 0x4f && b1 === 0x67 && b2 === 0x67 && b3 === 0x53) return 'audio/ogg';
        if (b0 === 0x66 && b1 === 0x4c && b2 === 0x61 && b3 === 0x43) return 'audio/flac';
        if (b0 === 0x23 && b1 === 0x21 && b2 === 0x41 && b3 === 0x4d) return 'audio/amr';
        return fallback;
    }

    function isStandardAudioHeader(bytes, expectedMimeType = '') {
        const normalizedMimeType = String(expectedMimeType || '').trim().toLowerCase();
        const detectedMimeType = inferAudioMimeTypeFromBytes(bytes, '').toLowerCase();
        if (!detectedMimeType) return false;
        if (!normalizedMimeType) return true;
        if (normalizedMimeType === 'audio/wav') return detectedMimeType === 'audio/wav';
        if (normalizedMimeType === 'audio/mpeg' || normalizedMimeType === 'audio/mp3') return detectedMimeType === 'audio/mpeg';
        return detectedMimeType === normalizedMimeType;
    }

    function buildTtsAudioDebugInfo(bytes, fallbackMimeType = 'audio/mpeg') {
        if (!bytes || !bytes.length) {
            return {
                byteLength: 0,
                inferredMimeType: fallbackMimeType,
                headerHex: '',
                headerAscii: ''
            };
        }
        const previewBytes = Array.from(bytes.slice(0, 16));
        return {
            byteLength: bytes.length,
            inferredMimeType: inferAudioMimeTypeFromBytes(bytes, fallbackMimeType),
            headerHex: previewBytes.map((item) => item.toString(16).padStart(2, '0')).join(' '),
            headerAscii: previewBytes.map((item) => {
                if (item >= 32 && item <= 126) return String.fromCharCode(item);
                return '.';
            }).join('')
        };
    }

    function encodePcmBytesToWav(bytes, sampleRate = 32000, channels = 1, bitsPerSample = 16) {
        if (!bytes || !bytes.length) return null;
        const pcmBytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
        const output = new ArrayBuffer(44 + pcmBytes.length);
        const view = new DataView(output);
        const blockAlign = channels * bitsPerSample / 8;
        const byteRate = sampleRate * blockAlign;

        view.setUint32(0, 0x52494646, false);
        view.setUint32(4, 36 + pcmBytes.length, true);
        view.setUint32(8, 0x57415645, false);
        view.setUint32(12, 0x666d7420, false);
        view.setUint32(16, 16, true);
        view.setUint16(20, 1, true);
        view.setUint16(22, channels, true);
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, byteRate, true);
        view.setUint16(32, blockAlign, true);
        view.setUint16(34, bitsPerSample, true);
        view.setUint32(36, 0x64617461, false);
        view.setUint32(40, pcmBytes.length, true);

        new Uint8Array(output, 44).set(pcmBytes);
        return new Blob([output], { type: 'audio/wav' });
    }

    function inferAudioMimeTypeFromBase64(base64Text, fallback = 'audio/mpeg') {
        const bytes = decodeAudioTextToBytes(base64Text).bytes;
        if (!bytes || !bytes.length) return fallback;
        try {
            return inferAudioMimeTypeFromBytes(bytes, fallback);
        } catch (error) {
            return fallback;
        }
    }

    function parseMimeTypeFromDataUrl(value, fallback = 'audio/mpeg') {
        const matched = String(value || '').match(/^data:([^;]+);base64,/i);
        return matched && matched[1] ? matched[1].trim() : fallback;
    }

    function buildAudioBlobFromBase64(base64Text, mimeType = 'audio/mpeg') {
        const bytes = decodeAudioTextToBytes(base64Text).bytes;
        if (!bytes || !bytes.length) {
            lastTtsAudioDebugInfo = buildTtsAudioDebugInfo(null, mimeType);
            return null;
        }
        let resolvedMimeType = inferAudioMimeTypeFromBytes(bytes, mimeType);
        lastTtsAudioDebugInfo = buildTtsAudioDebugInfo(bytes, resolvedMimeType);
        if (!isStandardAudioHeader(bytes, mimeType)) {
            lastTtsAudioDebugInfo = Object.assign({}, lastTtsAudioDebugInfo, {
                inferredMimeType: 'unknown-raw-audio',
                wrappedAsWav: false,
                unsupportedRawAudio: true,
                expectedMimeType: mimeType
            });
            return null;
        }
        if (mimeType === 'audio/mp3') {
            resolvedMimeType = 'audio/mpeg';
        } else if (mimeType === 'audio/wav') {
            resolvedMimeType = 'audio/wav';
        }
        return new Blob([bytes], { type: resolvedMimeType });
    }

    function blobToDataUrl(blob) {
        if (!blob) return Promise.resolve('');
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(new Error('Blob 转 dataURL 失败'));
            reader.readAsDataURL(blob);
        });
    }

    async function buildPlayableAudioSources(audioPayload) {
        if (!audioPayload || !audioPayload.kind) return [];
        if (audioPayload.kind === 'url') {
            return [{ src: String(audioPayload.value || '').trim(), revoke: false, label: 'url' }];
        }

        if (audioPayload.kind !== 'blob' || !audioPayload.value) {
            return [];
        }

        const blob = audioPayload.value;
        const originalType = String(blob.type || '').trim() || 'audio/mpeg';
        const candidateTypes = Array.from(new Set([
            originalType,
            originalType === 'audio/mpeg' ? 'audio/mp3' : '',
            originalType === 'audio/mp3' ? 'audio/mpeg' : '',
            'application/octet-stream'
        ].filter(Boolean)));

        const sources = [];
        const buffer = await blob.arrayBuffer();
        candidateTypes.forEach((type) => {
            const candidateBlob = type === originalType ? blob : new Blob([buffer], { type });
            sources.push({
                src: URL.createObjectURL(candidateBlob),
                revoke: true,
                label: `blob:${type}`
            });
        });

        try {
            const dataUrl = await blobToDataUrl(blob);
            if (dataUrl) {
                sources.push({ src: dataUrl, revoke: false, label: `dataurl:${originalType}` });
            }
        } catch (error) {
            console.warn('TTS dataURL 回退源生成失败:', error && error.message ? error.message : error);
        }

        return sources;
    }

    function summarizeTtsPayload(payload) {
        if (!payload || typeof payload !== 'object') return '(empty payload)';
        const keys = Object.keys(payload);
        return `keys=${keys.slice(0, 12).join(',')}`;
    }

    function summarizeUnknownTtsResponse(rawText, payload, contentType = '') {
        const raw = String(rawText || '').trim();
        const preview = raw.replace(/\s+/g, ' ').slice(0, 320);
        const summary = {
            contentType: String(contentType || '').trim(),
            rawPreview: preview,
            payloadKeys: payload && typeof payload === 'object' ? Object.keys(payload).slice(0, 20) : [],
            dataKeys: payload && payload.data && typeof payload.data === 'object' ? Object.keys(payload.data).slice(0, 20) : []
        };
        if (payload && typeof payload === 'object') {
            if (payload.data && typeof payload.data === 'object') {
                const nested = payload.data;
                ['audio', 'audio_data', 'audio_base64', 'audio_file', 'file', 'result', 'output'].forEach((key) => {
                    if (!Object.prototype.hasOwnProperty.call(nested, key)) return;
                    const value = nested[key];
                    summary[`data_${key}_type`] = Array.isArray(value) ? 'array' : typeof value;
                    if (typeof value === 'string') {
                        summary[`data_${key}_preview`] = value.slice(0, 120);
                    } else if (value && typeof value === 'object') {
                        summary[`data_${key}_keys`] = Object.keys(value).slice(0, 20);
                    }
                });
            }
        }
        return summary;
    }

    function summarizeAudioPayload(payload) {
        if (!payload || typeof payload !== 'object') return '(empty audio payload)';
        const blobType = payload.value && payload.value.type ? payload.value.type : '';
        const blobSize = payload.value && typeof payload.value.size === 'number' ? payload.value.size : 0;
        return {
            kind: payload.kind || '',
            blobType,
            blobSize,
            attemptLabel: payload.attemptLabel || '',
            responseField: lastTtsResponseFieldInfo,
            audioDebug: lastTtsAudioDebugInfo
        };
    }

    function rememberTtsResponseFieldInfo(fieldPath, rawValue, extra = {}) {
        const valueType = Array.isArray(rawValue) ? 'array' : typeof rawValue;
        const preview = typeof rawValue === 'string'
            ? rawValue.slice(0, 120)
            : (rawValue && typeof rawValue === 'object' ? JSON.stringify(Object.keys(rawValue).slice(0, 20)) : '');
        lastTtsResponseFieldInfo = Object.assign({
            fieldPath,
            valueType,
            preview
        }, extra || {});
    }

    function resolveAudioPayloadFromBase64String(base64Text, mimeType = 'audio/mpeg') {
        const decodedAudio = decodeAudioTextToBytes(base64Text);
        const nestedText = decodedAudio.encoding === 'base64' ? decodeBase64ToText(base64Text).trim() : '';
        if (nestedText && (nestedText.startsWith('{') || nestedText.startsWith('['))) {
            try {
                const nestedPayload = JSON.parse(nestedText);
                const nestedAudioPayload = extractAudioPayloadFromJson(nestedPayload);
                if (nestedAudioPayload) {
                    return nestedAudioPayload;
                }
            } catch (error) {
                // ignore and continue to binary path
            }
        }
        return { kind: 'blob', value: buildAudioBlobFromBase64(base64Text, mimeType) };
    }

    function looksLikeBase64Audio(text) {
        const value = String(text || '').trim();
        if (!value || value.length < 128) return false;
        if (looksLikeHexAudio(value)) return true;
        return /^[A-Za-z0-9+/=\s]+$/.test(value);
    }

    function detectEncodedAudioKind(text) {
        return looksLikeHexAudio(text) ? 'hex' : 'base64';
    }

    function extractErrorMessageFromPayload(payload, fallback = '') {
        if (!payload || typeof payload !== 'object') return fallback;
        const baseResp = payload.base_resp && typeof payload.base_resp === 'object'
            ? payload.base_resp
            : (payload.baseResp && typeof payload.baseResp === 'object' ? payload.baseResp : null);
        if (baseResp) {
            const statusCode = Number(baseResp.status_code ?? baseResp.statusCode ?? 0);
            const statusMessage = String(baseResp.status_msg ?? baseResp.statusMsg ?? '').trim();
            if (statusCode && statusCode !== 0) {
                return statusMessage ? `${statusMessage} (code=${statusCode})` : `接口错误 (code=${statusCode})`;
            }
        }
        const candidates = [
            payload.message,
            payload.msg,
            payload.error,
            payload.err_msg,
            payload.base_resp && payload.base_resp.status_msg,
            payload.baseResp && payload.baseResp.statusMsg,
            payload.detail
        ];
        for (const item of candidates) {
            const text = typeof item === 'string' ? item.trim() : '';
            if (text) return text;
        }
        return fallback;
    }

    function extractAudioPayloadFromJson(payload, expectedMimeType = 'audio/mpeg') {
        if (!payload || typeof payload !== 'object') return null;
        const data = payload.data && typeof payload.data === 'object' ? payload.data : {};
        const urlCandidates = [
            ['payload.audio_url', payload.audio_url],
            ['payload.audioUrl', payload.audioUrl],
            ['data.audio_url', data.audio_url],
            ['data.audioUrl', data.audioUrl],
            ['payload.url', payload.url],
            ['data.url', data.url],
            ['payload.audio_file_url', payload.audio_file_url],
            ['data.audio_file_url', data.audio_file_url]
        ];
        for (const [fieldPath, fieldValue] of urlCandidates) {
            if (typeof fieldValue === 'string' && /^https?:\/\//i.test(fieldValue.trim())) {
                rememberTtsResponseFieldInfo(fieldPath, fieldValue, { normalizedKind: 'url' });
                return { kind: 'url', value: fieldValue.trim() };
            }
        }

        const mimeType = payload.mime_type || data.mime_type || payload.audio_mime_type || data.audio_mime_type || expectedMimeType || 'audio/mpeg';
        const directAudioCandidates = [
            ['payload.audio', payload.audio],
            ['data.audio', data.audio],
            ['payload.audio_data', payload.audio_data],
            ['data.audio_data', data.audio_data],
            ['payload.audioContent', payload.audioContent],
            ['data.audioContent', data.audioContent],
            ['payload.audio_content', payload.audio_content],
            ['data.audio_content', data.audio_content]
        ];
        for (const [fieldPath, directAudioValue] of directAudioCandidates) {
            if (typeof directAudioValue !== 'string') continue;
            const normalizedAudioValue = directAudioValue.trim();
            if (/^https?:\/\//i.test(normalizedAudioValue)) {
                rememberTtsResponseFieldInfo(fieldPath, normalizedAudioValue, { normalizedKind: 'url', mimeType });
                return { kind: 'url', value: normalizedAudioValue };
            }
            if (/^data:audio\//i.test(normalizedAudioValue)) {
                rememberTtsResponseFieldInfo(fieldPath, normalizedAudioValue, { normalizedKind: 'dataurl', mimeType });
                return {
                    kind: 'blob',
                    value: buildAudioBlobFromBase64(normalizedAudioValue, parseMimeTypeFromDataUrl(normalizedAudioValue, mimeType))
                };
            }
            if (looksLikeBase64Audio(normalizedAudioValue)) {
                rememberTtsResponseFieldInfo(fieldPath, normalizedAudioValue, { normalizedKind: detectEncodedAudioKind(normalizedAudioValue), mimeType });
                return resolveAudioPayloadFromBase64String(normalizedAudioValue, mimeType);
            }
        }

        const base64Candidates = [
            ['payload.audio_base64', payload.audio_base64],
            ['payload.audioBase64', payload.audioBase64],
            ['data.audio_base64', data.audio_base64],
            ['data.audioBase64', data.audioBase64],
            ['payload.base64', payload.base64],
            ['data.base64', data.base64]
        ];
        for (const [fieldPath, base64Text] of base64Candidates) {
            if (typeof base64Text === 'string' && base64Text.trim()) {
                rememberTtsResponseFieldInfo(fieldPath, base64Text, { normalizedKind: detectEncodedAudioKind(base64Text), mimeType });
                return resolveAudioPayloadFromBase64String(base64Text, mimeType);
            }
        }

        return null;
    }

    async function parseMinimaxTtsResponse(response, expectedMimeType = 'audio/mpeg') {
        const contentType = String(response.headers.get('content-type') || '').toLowerCase();
        if (response.ok && /(audio|octet-stream)/i.test(contentType)) {
            return { kind: 'blob', value: await response.blob() };
        }

        if (response.ok && contentType && !/(json|text|javascript|xml)/i.test(contentType)) {
            return { kind: 'blob', value: await response.blob() };
        }

        const rawText = await response.text();
        let payload = null;
        try {
            payload = rawText ? JSON.parse(rawText) : null;
        } catch (error) {
            payload = null;
        }

        const baseResp = payload && payload.base_resp && typeof payload.base_resp === 'object'
            ? payload.base_resp
            : (payload && payload.baseResp && typeof payload.baseResp === 'object' ? payload.baseResp : null);
        if (baseResp) {
            const statusCode = Number(baseResp.status_code ?? baseResp.statusCode ?? 0);
            if (statusCode && statusCode !== 0) {
                throw new Error(extractErrorMessageFromPayload(payload, rawText || `HTTP ${response.status}`));
            }
        }

        if (!payload && /^data:/i.test(String(rawText || '').trim())) {
            const dataUrl = String(rawText || '').trim();
            return {
                kind: 'blob',
                value: buildAudioBlobFromBase64(dataUrl, parseMimeTypeFromDataUrl(dataUrl))
            };
        }

        if (!payload && /^data:/mi.test(String(rawText || ''))) {
            const dataLines = String(rawText || '')
                .split(/\r?\n/)
                .map((line) => line.replace(/^data:\s*/i, '').trim())
                .filter(Boolean);
            for (const line of dataLines) {
                if (/^data:audio\//i.test(line)) {
                    return {
                        kind: 'blob',
                        value: buildAudioBlobFromBase64(line, parseMimeTypeFromDataUrl(line))
                    };
                }
                try {
                    const parsedLine = JSON.parse(line);
                    const audioPayload = extractAudioPayloadFromJson(parsedLine, expectedMimeType);
                    if (audioPayload) return audioPayload;
                } catch (error) {
                    if (looksLikeBase64Audio(line)) {
                        return resolveAudioPayloadFromBase64String(line, expectedMimeType);
                    }
                }
            }
        }

        if (!response.ok) {
            throw new Error(extractErrorMessageFromPayload(payload, rawText || `HTTP ${response.status}`));
        }

        const audioPayload = extractAudioPayloadFromJson(payload, expectedMimeType);
        if (audioPayload) return audioPayload;
        if (looksLikeBase64Audio(rawText)) {
            return resolveAudioPayloadFromBase64String(rawText, expectedMimeType);
        }
        if (/^data:audio\//i.test(String(rawText || '').trim())) {
            const dataUrl = String(rawText).trim();
            return {
                kind: 'blob',
                value: buildAudioBlobFromBase64(dataUrl, parseMimeTypeFromDataUrl(dataUrl, expectedMimeType))
            };
        }
        throw new Error('Minimax TTS 未返回可识别的音频数据');
    }

    async function requestMinimaxTtsAudio(text, options = {}) {
        const safeText = sanitizeTextForSpeech(text, options);
        const settings = normalizeMinimaxTtsSettings(options.settings || ensureMinimaxTtsSettings());
        const resolvedVoice = resolveContactTtsVoiceId(options.contact, settings);
        const effectiveModel = /^(speech-2\.8-hd|speech-2\.8-turbo)$/i.test(String(settings.model || ''))
            ? String(settings.model).toLowerCase()
            : 'speech-2.8-hd';
        const voiceSpeed = clampVoiceSegmentNumber(options.speed, 0.5, 2.0, 1);
        const voicePitch = FIXED_VOICE_SEGMENT_PITCH;
        if (!safeText) throw new Error('没有可播报的文本');
        if (!settings.apiKey) throw new Error('请先完善 Minimax TTS 配置');
        debugLogJson('[VoiceCallTTS] Minimax 请求', {
            generation: options.generation || 0,
            messageId: String(options.messageId || ''),
            source: options.source || '',
            model: effectiveModel,
            voiceId: resolvedVoice.voiceId || '',
            voiceSource: resolvedVoice.source,
            speed: voiceSpeed,
            pitch: voicePitch,
            textLength: safeText.length,
            textPreview: getDebugTextPreview(safeText, 120)
        });

        const attempts = [
            {
                label: 't2a_v2 strict wav',
                url: 'https://api.minimaxi.com/v1/t2a_v2',
                body: {
                    model: effectiveModel,
                    text: safeText,
                    stream: false,
                    voice_setting: {
                        voice_id: resolvedVoice.voiceId || 'female-tianmei',
                        speed: voiceSpeed,
                        vol: 1,
                        pitch: voicePitch
                    },
                    audio_setting: {
                        sample_rate: 16000,
                        bitrate: 128000,
                        format: 'wav',
                        channel: 1
                    },
                    subtitle_enable: false
                }
            }
        ];

        let lastError = null;
        for (const attempt of attempts) {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 45000);
            activeTtsRequestController = controller;
            try {
                const response = await fetch(attempt.url, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${settings.apiKey}`
                    },
                    body: JSON.stringify(attempt.body),
                    signal: controller.signal
                });
                const expectedMimeType = attempt.body && attempt.body.audio_setting && attempt.body.audio_setting.format === 'wav'
                    ? 'audio/wav'
                    : 'audio/mpeg';
                const parsedPayload = await parseMinimaxTtsResponse(response, expectedMimeType);
                if (parsedPayload && typeof parsedPayload === 'object') {
                    parsedPayload.attemptLabel = attempt.label;
                }
                if (parsedPayload && parsedPayload.kind === 'blob' && !parsedPayload.value) {
                    lastError = new Error(`空音频结果: ${attempt.label}`);
                    continue;
                }
                if (
                    parsedPayload
                    && parsedPayload.kind === 'blob'
                    && parsedPayload.value
                    && String(parsedPayload.value.type || '').toLowerCase() === 'audio/wav'
                    && (!lastTtsAudioDebugInfo || lastTtsAudioDebugInfo.inferredMimeType !== 'audio/wav')
                ) {
                    lastError = new Error(`非标准 WAV 结果: ${attempt.label}`);
                    continue;
                }
                return parsedPayload;
            } catch (error) {
                lastError = error;
            } finally {
                clearTimeout(timeoutId);
                if (activeTtsRequestController === controller) {
                    activeTtsRequestController = null;
                }
            }
        }

        throw lastError || new Error('Minimax TTS 请求失败');
    }

    async function playResolvedTtsAudio(audioPayload, generation) {
        ensureTtsPlaybackSessionActive(generation, 'before-resolve-audio');
        const audio = ensureActiveTtsAudio();
        debugLogJson('[VoiceCallTTS] 准备播放音频', {
            generation,
            messageId: String(audioPayload && audioPayload.messageId ? audioPayload.messageId : ''),
            source: String(audioPayload && audioPayload.source ? audioPayload.source : ''),
            textPreview: String(audioPayload && audioPayload.textPreview ? audioPayload.textPreview : ''),
            kind: audioPayload && audioPayload.kind ? audioPayload.kind : 'unknown',
            currentVolume: audio.volume,
            muted: audio.muted,
            debug: lastTtsAudioDebugInfo
        });
        revokeActiveTtsObjectUrl();
        const sources = await buildPlayableAudioSources(audioPayload);
        ensureTtsPlaybackSessionActive(generation, 'after-build-audio-sources');
        if (!sources.length) {
            throw new Error('音频地址为空');
        }

        let lastError = null;
        for (const source of sources) {
            try {
                await new Promise((resolve, reject) => {
                    let settled = false;
                    const cleanup = () => {
                        audio.removeEventListener('ended', handleEnded);
                        audio.removeEventListener('error', handleError);
                        audio.removeEventListener('canplay', handleCanPlay);
                        audio.removeEventListener('loadedmetadata', handleCanPlay);
                    };
                    const finalizeReject = (error) => {
                        if (settled) return;
                        settled = true;
                        cleanup();
                        reject(error);
                    };
                    const finalizeResolve = () => {
                        if (settled) return;
                        settled = true;
                        cleanup();
                        resolve();
                    };
                    const handleEnded = () => {
                        finalizeResolve();
                    };
                    const handleError = () => {
                        const mediaError = audio.error;
                        const mediaCode = mediaError && mediaError.code ? mediaError.code : 'unknown';
                        finalizeReject(new Error(`音频播放失败(code=${mediaCode}, srcLabel=${source.label}, srcType=${audioPayload.kind}, blobType=${audioPayload.value && audioPayload.value.type ? audioPayload.value.type : 'n/a'})`));
                    };
                    const handleCanPlay = () => {
                        try {
                            ensureTtsPlaybackSessionActive(generation, 'before-audio-play');
                        } catch (error) {
                            finalizeReject(error);
                            return;
                        }
                        const playPromise = audio.play();
                        if (playPromise && typeof playPromise.catch === 'function') {
                            playPromise.catch((error) => {
                                finalizeReject(new Error(`音频播放失败(${error && error.message ? error.message : error}, srcLabel=${source.label})`));
                            });
                        }
                    };

                    cleanup();
                    try {
                        ensureTtsPlaybackSessionActive(generation, 'before-audio-src');
                    } catch (error) {
                        finalizeReject(error);
                        return;
                    }
                    audio.addEventListener('ended', handleEnded);
                    audio.addEventListener('error', handleError);
                    audio.addEventListener('canplay', handleCanPlay, { once: true });
                    audio.addEventListener('loadedmetadata', handleCanPlay, { once: true });
                    audio.preload = 'auto';
                    audio.playsInline = true;
                    audio.src = source.src;
                    audio.load();
                });

                if (source.revoke) {
                    URL.revokeObjectURL(source.src);
                }
                revokeActiveTtsObjectUrl();
                return;
            } catch (error) {
                lastError = error;
                if (source.revoke) {
                    URL.revokeObjectURL(source.src);
                }
                audio.pause();
                audio.removeAttribute('src');
                audio.load();
                if (isTtsPlaybackStaleError(error)) {
                    throw error;
                }
            }
        }

        revokeActiveTtsObjectUrl();
        throw lastError || new Error('音频播放失败');
    }

    async function playBrowserSpeech(text, options = {}) {
        ensureTtsPlaybackSessionActive(options.generation, 'before-browser-speech');
        const safeText = sanitizeTextForSpeech(text, options);
        const speechRate = clampVoiceSegmentNumber(options.speed, 0.5, 2.0, 1);
        const speechPitch = FIXED_VOICE_SEGMENT_PITCH;
        if (!safeText) return;
        if (!window.speechSynthesis || typeof window.SpeechSynthesisUtterance !== 'function') {
            throw new Error('当前环境不支持默认 TTS');
        }
        console.warn('[VoiceCallTTS] 正在使用浏览器默认 TTS 回退', {
            generation: options.generation,
            source: options.source || '',
            textLength: safeText.length,
            textPreview: safeText.slice(0, 120)
        });
        window.speechSynthesis.cancel();
        return new Promise((resolve, reject) => {
            const utterance = new SpeechSynthesisUtterance(safeText);
            utterance.lang = 'zh-CN';
            utterance.rate = speechRate;
            utterance.pitch = speechPitch;
            utterance.onend = () => resolve();
            utterance.onerror = () => reject(new Error('默认 TTS 播放失败'));
            try {
                ensureTtsPlaybackSessionActive(options.generation, 'before-browser-speak');
            } catch (error) {
                reject(error);
                return;
            }
            window.speechSynthesis.speak(utterance);
        });
    }

    async function playVoiceMessageSegments(payload, options = {}) {
        const normalizedPayload = normalizeVoiceSegmentsPayload(payload);
        if (!normalizedPayload) return false;
        const generation = options.generation;
        const provider = String(options.provider || '').trim().toLowerCase();
        for (let index = 0; index < normalizedPayload.segments.length; index += 1) {
            ensureTtsPlaybackSessionActive(generation, `voice-message-segment-${index}`);
            const segment = normalizedPayload.segments[index];
            if (!segment || !String(segment.text || '').trim()) continue;
            if (provider === 'minimax') {
                const audioPayload = await requestMinimaxTtsAudio(segment.text, {
                    ...options,
                    speed: segment.speed,
                    pitch: segment.pitch
                });
                if (audioPayload && typeof audioPayload === 'object') {
                    audioPayload.messageId = String(options.messageId || '');
                    audioPayload.source = options.source || 'voice_message';
                    audioPayload.textPreview = getDebugTextPreview(segment.text);
                }
                ensureTtsPlaybackSessionActive(generation, `voice-message-segment-${index}-after-request`);
                await playResolvedTtsAudio(audioPayload, generation);
                continue;
            }
            await playBrowserSpeech(segment.text, {
                ...options,
                speed: segment.speed,
                pitch: segment.pitch
            });
        }
        return true;
    }

    window.IDICVoiceCallTTS = {
        async play(options = {}) {
            const text = String(options.text || '').trim();
            const provider = String(options.provider || appData?.appSettings?.voiceCallTtsProvider || '').trim().toLowerCase();
            const source = String(options.source || 'voice_call').trim();
            const messageId = String(options.messageId || '').trim();
            const voicePayload = normalizeVoiceSegmentsPayload(options.voicePayload);
            if (!text) return;

            const generation = createActiveTtsPlaybackSession(source);
            debugLogJson('[VoiceCallTTS] play入口', {
                messageId,
                source,
                provider,
                generation,
                textLength: text.length,
                textPreview: getDebugTextPreview(text)
            });
            stopActiveTtsPlayback();

            if (source === 'voice_message' && voicePayload && voicePayload.segments.length) {
                try {
                    const handled = await playVoiceMessageSegments(voicePayload, {
                        ...options,
                        provider,
                        source,
                        messageId,
                        generation
                    });
                    if (handled) return;
                } catch (error) {
                    if (isTtsPlaybackStaleError(error)) throw error;
                    console.warn('分段语音消息 TTS 失败，准备回退整段播放:', error && error.message ? error.message : error);
                }
            }

            if (provider === 'minimax') {
                try {
                    const audioPayload = await requestMinimaxTtsAudio(text, {
                        generation,
                        messageId,
                        source,
                        settings: options.settings || ensureMinimaxTtsSettings(),
                        contact: options.contact || null
                    });
                    if (audioPayload && typeof audioPayload === 'object') {
                        audioPayload.messageId = messageId;
                        audioPayload.source = source;
                        audioPayload.textPreview = getDebugTextPreview(text);
                    }
                    ensureTtsPlaybackSessionActive(generation, 'after-minimax-request');
                    await playResolvedTtsAudio(audioPayload, generation);
                    return;
                } catch (error) {
                    if (error && (error.name === 'AbortError' || isTtsPlaybackStaleError(error) || /aborted without reason/i.test(String(error.message || '')))) {
                        return;
                    }
                    console.warn('Minimax TTS 失败，准备回退默认 TTS:', error && error.message ? error.message : error);
                }
            }

            try {
                ensureTtsPlaybackSessionActive(generation, 'before-browser-fallback');
                await playBrowserSpeech(text, { source, generation });
            } catch (error) {
                if (isTtsPlaybackStaleError(error)) {
                    return;
                }
                if (/当前环境不支持默认 TTS/.test(String(error && error.message || ''))) {
                    if (source === 'voice_call') {
                        await new Promise((resolve) => setTimeout(resolve, Math.min(Math.max(text.length * 90, 700), 2400)));
                        return;
                    }
                    return;
                }
                throw error;
            }
        },
        stop() {
            invalidateActiveTtsPlayback('manual-stop');
            stopActiveTtsPlayback();
        }
    };

    function renderMusicBackendSettingsSummary() {
        const summaryEl = document.getElementById('music-backend-settings-summary');
        if (!summaryEl) return;
        const profile = appData.appSettings && appData.appSettings.musicSessionProfile;
        const token = getMusicLoginCookie();
        if (profile && profile.nickname) {
            summaryEl.textContent = `已登录：${profile.nickname}`;
            return;
        }
        summaryEl.textContent = token ? '已登录，等待刷新资料' : '未扫码登录';
    }

    function mountImageGenerationProviderPanels() {
        if (!imageGenerationProviderConfigSlot) return;
        document.querySelectorAll('.image-provider-panel').forEach((panel) => {
            if (panel.parentElement !== imageGenerationProviderConfigSlot) {
                imageGenerationProviderConfigSlot.appendChild(panel);
            }
        });
    }

    function syncImageGenerationCurrentModelInputForProvider(providerOverride = '') {
        const provider = String(providerOverride || getSettingsFieldValue('image-gen-provider-select') || 'openai').trim() || 'openai';
        const modelInput = document.getElementById('image-gen-model-input');
        const pollinationsModelInput = document.getElementById('image-gen-pollinations-model-input');
        if (!modelInput) return;

        if (provider === 'pollinations') {
            const pollinationsModel = String(pollinationsModelInput && pollinationsModelInput.value || '').trim();
            if (pollinationsModel) {
                modelInput.value = pollinationsModel;
            }
            return;
        }

        if (imageGenerationGlobalModelDraft) {
            modelInput.value = imageGenerationGlobalModelDraft;
        }
    }

    function syncActiveImageGenerationProviderModelDraft() {
        const provider = String(getSettingsFieldValue('image-gen-provider-select') || 'openai').trim() || 'openai';
        const modelInput = document.getElementById('image-gen-model-input');
        const pollinationsModelInput = document.getElementById('image-gen-pollinations-model-input');
        const modelValue = String(modelInput && modelInput.value || '').trim();

        if (provider === 'pollinations') {
            if (pollinationsModelInput) {
                pollinationsModelInput.value = modelValue;
            }
            return;
        }

        imageGenerationGlobalModelDraft = modelValue;
    }

    function updateImageGenerationProviderPanels() {
        const provider = String(getSettingsFieldValue('image-gen-provider-select') || 'openai').trim();
        mountImageGenerationProviderPanels();
        syncImageGenerationCurrentModelInputForProvider(provider);
        document.querySelectorAll('.image-provider-panel').forEach((panel) => {
            panel.classList.toggle('hidden', panel.id !== `image-gen-panel-${provider}`);
        });
    }

    function renderImageGenerationReferenceCapability(settingsOverride = null) {
        const badgeEl = document.getElementById('image-gen-reference-capability-badge');
        const textEl = document.getElementById('image-gen-reference-capability-text');
        if (!badgeEl || !textEl) return;

        const bridge = window.IDICImageGenerationBridge;
        if (!bridge || typeof bridge.getReferenceCapability !== 'function') {
            badgeEl.textContent = '文本锚点';
            textEl.textContent = '当前版本尚未加载参考图能力说明，系统会默认回退到文本锚点。';
            return;
        }

        const settings = settingsOverride || readImageGenerationSettingsFromUI();
        const capability = bridge.getReferenceCapability(
            settings,
            settings && settings.provider,
            settings && settings.model
        ) || {};

        badgeEl.textContent = String(capability.shortLabel || '文本锚点').trim() || '文本锚点';
        textEl.textContent = String(
            capability.message
            || '当前模型若不支持参考图直传，会自动回退为文本锚点与参考包。'
        ).trim();
    }

    function writeImageGenerationSettingsToUI(imageSettings) {
        const settings = imageSettings || ensureImageGenerationSettings();
        const common = settings.common || {};
        const offlineIllustration = settings.offlineIllustration || {};
        const providers = settings.providers || {};
        const openai = providers.openai || {};
        const google = providers.google || {};
        const novelai = providers.novelai || {};
        const pollinations = providers.pollinations || {};
        const customProvider = providers.customOpenAiLike || {};

        setSettingsFieldChecked('image-gen-enabled-toggle', settings.enabled);
        setSettingsFieldValue('image-gen-provider-select', settings.provider || 'openai');
        imageGenerationGlobalModelDraft = String(settings.model || '').trim();
        setSettingsFieldValue(
            'image-gen-model-input',
            settings.provider === 'pollinations'
                ? (pollinations.model || settings.model || '')
                : (settings.model || '')
        );
        setSettingsFieldChecked('image-gen-fallback-toggle', settings.fallbackToTextDescription !== false);
        setSettingsFieldChecked('image-gen-auto-health-toggle', settings.autoHealthCheck !== false);
        setSettingsFieldValue('image-gen-health-status-text', '');

        const statusEl = document.getElementById('image-gen-health-status-text');
        if (statusEl) {
            statusEl.textContent = String(settings.lastHealthCheckMessage || '未检查');
        }

        setSettingsFieldValue('image-gen-count-input', common.imageCount || 1);
        setSettingsFieldValue('image-gen-width-input', common.width || 1024);
        setSettingsFieldValue('image-gen-height-input', common.height || 1024);
        setSettingsFieldValue('image-gen-aspect-ratio-select', common.aspectRatio || '1:1');
        setSettingsFieldValue('image-gen-quality-select', common.quality || 'medium');
        setSettingsFieldValue('image-gen-seed-input', common.seed || '');
        setSettingsFieldValue('image-gen-prompt-prefix-input', common.promptPrefix || '');
        setSettingsFieldValue('image-gen-style-preset-select', common.promptStylePreset || 'balanced');
        setSettingsFieldChecked('image-gen-allow-reference-toggle', common.allowReference !== false);
        setSettingsFieldValue('image-gen-watermark-text-input', common.exportWatermarkText || '图片由AI生成');

        setSettingsFieldChecked('image-gen-offline-default-toggle', Boolean(offlineIllustration.enabledByDefault));
        setSettingsFieldChecked('image-gen-offline-per-turn-toggle', offlineIllustration.generatePerAssistantTurn !== false);
        setSettingsFieldValue('image-gen-offline-output-position-select', offlineIllustration.outputPosition || 'after_reply');
        setSettingsFieldValue('image-gen-offline-max-images-input', offlineIllustration.maxImagesPerTurn || 1);

        setSettingsFieldValue('image-gen-openai-api-key-input', openai.apiKey || '');
        setSettingsFieldValue('image-gen-openai-base-url-input', openai.baseUrl || '');
        setSettingsFieldValue('image-gen-openai-image-path-input', openai.imagePath || '');
        setSettingsFieldValue('image-gen-openai-api-mode-select', openai.apiMode || 'auto');

        setSettingsFieldValue('image-gen-google-api-key-input', google.apiKey || '');
        setSettingsFieldValue('image-gen-google-base-url-input', google.baseUrl || '');
        setSettingsFieldValue('image-gen-google-safety-select', google.safetyLevel || 'block_few');

        setSettingsFieldValue('image-gen-novelai-api-key-input', novelai.apiKey || '');
        setSettingsFieldValue('image-gen-novelai-sampler-input', novelai.sampler || 'k_euler_ancestral');
        setSettingsFieldValue('image-gen-novelai-steps-input', novelai.steps || 28);
        setSettingsFieldValue('image-gen-novelai-scale-input', novelai.scale || 6.5);
        setSettingsFieldValue('image-gen-novelai-strength-input', novelai.strength || 0.7);
        setSettingsFieldValue('image-gen-novelai-noise-input', novelai.noise || 0.2);
        setSettingsFieldValue('image-gen-novelai-cfg-rescale-input', novelai.cfgRescale ?? 0.18);
        setSettingsFieldValue('image-gen-novelai-noise-schedule-input', novelai.noiseSchedule || 'karras');
        setSettingsFieldChecked('image-gen-novelai-sm-toggle', Boolean(novelai.sm));
        setSettingsFieldChecked('image-gen-novelai-sm-dyn-toggle', Boolean(novelai.smDyn));
        setSettingsFieldValue('image-gen-novelai-artist-prompt-input', novelai.artistPrompt || '');
        setSettingsFieldValue('image-gen-novelai-positive-prompt-input', novelai.positivePrompt || '');
        setSettingsFieldValue('image-gen-novelai-negative-prompt-input', novelai.negativePrompt || '');

        setSettingsFieldValue('image-gen-pollinations-base-url-input', pollinations.baseUrl || 'https://image.pollinations.ai/prompt');
        setSettingsFieldValue('image-gen-pollinations-model-input', pollinations.model || 'flux');
        setSettingsFieldValue('image-gen-pollinations-negative-prompt-input', pollinations.negativePrompt || '');
        setSettingsFieldChecked('image-gen-pollinations-private-toggle', Boolean(pollinations.privateMode));
        setSettingsFieldChecked('image-gen-pollinations-enhance-toggle', pollinations.enhancePrompt !== false);

        setSettingsFieldValue('image-gen-custom-api-key-input', customProvider.apiKey || '');
        setSettingsFieldValue('image-gen-custom-base-url-input', customProvider.baseUrl || '');
        setSettingsFieldValue('image-gen-custom-api-mode-select', customProvider.apiMode || 'auto');
        setSettingsFieldValue('image-gen-custom-image-path-input', customProvider.imagePath || '/images/generations');
        setSettingsFieldValue('image-gen-custom-chat-path-input', customProvider.chatPath || '/chat/completions');
        setSettingsFieldValue('image-gen-custom-extra-headers-input', customProvider.extraHeaders || '');

        updateImageGenerationProviderPanels();
        renderImageGenerationReferenceCapability(settings);
    }

    function readImageGenerationSettingsFromUI() {
        const current = ensureImageGenerationSettings();
        const next = getDefaultImageGenerationSettings();

        next.enabled = getSettingsFieldChecked('image-gen-enabled-toggle');
        next.provider = String(getSettingsFieldValue('image-gen-provider-select') || 'openai').trim() || 'openai';
        next.model = String(getSettingsFieldValue('image-gen-model-input') || '').trim();
        next.fallbackToTextDescription = getSettingsFieldChecked('image-gen-fallback-toggle');
        next.autoHealthCheck = getSettingsFieldChecked('image-gen-auto-health-toggle');
        next.lastHealthCheckAt = current.lastHealthCheckAt || 0;
        next.lastHealthCheckStatus = current.lastHealthCheckStatus || 'unknown';
        next.lastHealthCheckMessage = current.lastHealthCheckMessage || '未检查';

        next.common.imageCount = Math.max(1, Math.min(4, getSettingsFieldNumber('image-gen-count-input', 1)));
        next.common.width = Math.max(256, getSettingsFieldNumber('image-gen-width-input', 1024));
        next.common.height = Math.max(256, getSettingsFieldNumber('image-gen-height-input', 1024));
        next.common.aspectRatio = String(getSettingsFieldValue('image-gen-aspect-ratio-select') || '1:1').trim() || '1:1';
        next.common.quality = String(getSettingsFieldValue('image-gen-quality-select') || 'medium').trim() || 'medium';
        next.common.seed = String(getSettingsFieldValue('image-gen-seed-input') || '').trim();
        next.common.promptPrefix = String(getSettingsFieldValue('image-gen-prompt-prefix-input') || '').trim();
        next.common.promptStylePreset = String(getSettingsFieldValue('image-gen-style-preset-select') || 'balanced').trim() || 'balanced';
        next.common.allowReference = getSettingsFieldChecked('image-gen-allow-reference-toggle');
        next.common.exportWatermarkText = String(getSettingsFieldValue('image-gen-watermark-text-input') || '图片由AI生成').trim() || '图片由AI生成';

        next.offlineIllustration.enabledByDefault = getSettingsFieldChecked('image-gen-offline-default-toggle');
        next.offlineIllustration.generatePerAssistantTurn = getSettingsFieldChecked('image-gen-offline-per-turn-toggle');
        next.offlineIllustration.outputPosition = String(getSettingsFieldValue('image-gen-offline-output-position-select') || 'after_reply').trim() || 'after_reply';
        next.offlineIllustration.maxImagesPerTurn = Math.max(1, Math.min(3, getSettingsFieldNumber('image-gen-offline-max-images-input', 1)));

        next.providers.openai.apiKey = String(getSettingsFieldValue('image-gen-openai-api-key-input') || '').trim();
        next.providers.openai.baseUrl = String(getSettingsFieldValue('image-gen-openai-base-url-input') || '').trim();
        next.providers.openai.imagePath = String(getSettingsFieldValue('image-gen-openai-image-path-input') || '').trim();
        next.providers.openai.apiMode = String(getSettingsFieldValue('image-gen-openai-api-mode-select') || 'auto').trim() || 'auto';

        next.providers.google.apiKey = String(getSettingsFieldValue('image-gen-google-api-key-input') || '').trim();
        next.providers.google.baseUrl = String(getSettingsFieldValue('image-gen-google-base-url-input') || '').trim();
        next.providers.google.safetyLevel = String(getSettingsFieldValue('image-gen-google-safety-select') || 'block_few').trim() || 'block_few';

        next.providers.novelai.apiKey = String(getSettingsFieldValue('image-gen-novelai-api-key-input') || '').trim();
        next.providers.novelai.sampler = String(getSettingsFieldValue('image-gen-novelai-sampler-input') || 'k_euler_ancestral').trim() || 'k_euler_ancestral';
        next.providers.novelai.steps = Math.max(1, getSettingsFieldNumber('image-gen-novelai-steps-input', 28));
        next.providers.novelai.scale = Math.max(1, getSettingsFieldNumber('image-gen-novelai-scale-input', 6.5));
        next.providers.novelai.strength = Math.max(0, Math.min(1, getSettingsFieldNumber('image-gen-novelai-strength-input', 0.7)));
        next.providers.novelai.noise = Math.max(0, Math.min(1, getSettingsFieldNumber('image-gen-novelai-noise-input', 0.2)));
        next.providers.novelai.cfgRescale = Math.max(0, Math.min(1, getSettingsFieldNumber('image-gen-novelai-cfg-rescale-input', 0.18)));
        next.providers.novelai.noiseSchedule = String(getSettingsFieldValue('image-gen-novelai-noise-schedule-input') || 'karras').trim() || 'karras';
        next.providers.novelai.sm = getSettingsFieldChecked('image-gen-novelai-sm-toggle');
        next.providers.novelai.smDyn = getSettingsFieldChecked('image-gen-novelai-sm-dyn-toggle');
        next.providers.novelai.smeaConfigured = true;
        next.providers.novelai.artistPrompt = String(getSettingsFieldValue('image-gen-novelai-artist-prompt-input') || '').trim();
        next.providers.novelai.positivePrompt = String(getSettingsFieldValue('image-gen-novelai-positive-prompt-input') || '').trim();
        next.providers.novelai.negativePrompt = String(getSettingsFieldValue('image-gen-novelai-negative-prompt-input') || '').trim();

        next.providers.pollinations.baseUrl = String(getSettingsFieldValue('image-gen-pollinations-base-url-input') || '').trim() || 'https://image.pollinations.ai/prompt';
        next.providers.pollinations.model = String(getSettingsFieldValue('image-gen-pollinations-model-input') || 'flux').trim() || 'flux';
        next.providers.pollinations.negativePrompt = String(getSettingsFieldValue('image-gen-pollinations-negative-prompt-input') || '').trim();
        next.providers.pollinations.privateMode = getSettingsFieldChecked('image-gen-pollinations-private-toggle');
        next.providers.pollinations.enhancePrompt = getSettingsFieldChecked('image-gen-pollinations-enhance-toggle');

        if (next.provider === 'pollinations' && next.model) {
            next.providers.pollinations.model = next.model;
        } else {
            imageGenerationGlobalModelDraft = next.model;
        }

        next.providers.customOpenAiLike.apiKey = String(getSettingsFieldValue('image-gen-custom-api-key-input') || '').trim();
        next.providers.customOpenAiLike.baseUrl = String(getSettingsFieldValue('image-gen-custom-base-url-input') || '').trim();
        next.providers.customOpenAiLike.apiMode = String(getSettingsFieldValue('image-gen-custom-api-mode-select') || 'auto').trim() || 'auto';
        next.providers.customOpenAiLike.imagePath = String(getSettingsFieldValue('image-gen-custom-image-path-input') || '').trim() || '/images/generations';
        next.providers.customOpenAiLike.chatPath = String(getSettingsFieldValue('image-gen-custom-chat-path-input') || '').trim() || '/chat/completions';
        next.providers.customOpenAiLike.extraHeaders = String(getSettingsFieldValue('image-gen-custom-extra-headers-input') || '').trim();

        if (window.IDICImageGenerationBridge && typeof window.IDICImageGenerationBridge.normalizeImageGenerationSettings === 'function') {
            return window.IDICImageGenerationBridge.normalizeImageGenerationSettings(next);
        }
        return next;
    }

    function renderSettingsHubSummaries() {
        const settings = appData.appSettings || {};
        const hippocampusSettings = ensureHippocampusSettings();
        const imageSettings = ensureImageGenerationSettings();

        const apiSummaryEl = document.getElementById('api-settings-summary');
        if (apiSummaryEl) {
            const mainModel = String(settings.apiModel || '').trim();
            apiSummaryEl.textContent = mainModel ? `${mainModel}` : '未配置';
        }

        const hippocampusSummaryEl = document.getElementById('hippocampus-settings-summary');
        if (hippocampusSummaryEl) {
            const supabaseReady = Boolean(hippocampusSettings.supabase && hippocampusSettings.supabase.url && hippocampusSettings.supabase.publishableKey);
            const dehydrateReady = Boolean(hippocampusSettings.dehydrateApi && hippocampusSettings.dehydrateApi.apiUrl && hippocampusSettings.dehydrateApi.apiKey);
            hippocampusSummaryEl.textContent = supabaseReady || dehydrateReady ? '已配置核心能力' : '未配置';
        }

        const musicSummaryEl = document.getElementById('music-settings-summary');
        if (musicSummaryEl) {
            const hasSunoKey = Boolean(String(settings.sunoApiKey || '').trim());
            const hasMusicLogin = Boolean(getMusicLoginCookie());
            if (hasSunoKey && hasMusicLogin) musicSummaryEl.textContent = 'Suno + 网易云已配置';
            else if (hasSunoKey) musicSummaryEl.textContent = 'Suno 已配置';
            else if (hasMusicLogin) musicSummaryEl.textContent = '网易云已登录';
            else musicSummaryEl.textContent = 'Suno / 网易云未配置';
        }

        const sttSummaryEl = document.getElementById('stt-settings-summary');
        if (sttSummaryEl) {
            const tencentAsr = settings.tencentAsr || {};
            const voiceUnderstanding = normalizeVoiceUnderstandingSettings(settings.voiceUnderstanding);
            const asrText = (tencentAsr.secretId && tencentAsr.secretKey) ? '腾讯云已配置' : '未配置';
            const enhanceText = (voiceUnderstanding.enabled && voiceUnderstanding.apiKey) ? '增强已开' : '本地分析';
            const functionText = settings.voiceFunctionBaseUrl ? '函数域名已配' : '函数域名未配';
            sttSummaryEl.textContent = `${asrText} · ${enhanceText} · ${functionText}`;
        }

        const imageSummaryEl = document.getElementById('image-generation-settings-summary');
        if (imageSummaryEl) {
            if (window.IDICImageGenerationBridge && typeof window.IDICImageGenerationBridge.buildImageGenerationSummary === 'function') {
                imageSummaryEl.textContent = window.IDICImageGenerationBridge.buildImageGenerationSummary(imageSettings);
            } else {
                imageSummaryEl.textContent = imageSettings.enabled ? '已启用' : '未启用';
            }
        }

        const ttsSummaryEl = document.getElementById('tts-settings-summary');
        if (ttsSummaryEl) {
            const provider = String(settings.voiceCallTtsProvider || '').trim().toLowerCase();
            const minimaxTts = normalizeMinimaxTtsSettings(settings.minimaxTts);
            if (provider === 'minimax' && minimaxTts.apiKey && minimaxTts.voiceId) {
                ttsSummaryEl.textContent = `Minimax · ${minimaxTts.voiceId}`;
            } else if (provider === 'minimax') {
                ttsSummaryEl.textContent = 'Minimax 待补全';
            } else {
                ttsSummaryEl.textContent = '默认 TTS';
            }
        }

        renderPhoneLauncherSettingsSummary();

        const globalOfflineSummaryEl = document.getElementById('global-offline-settings-summary');
        if (globalOfflineSummaryEl) {
            const defaultPreset = getDefaultOfflinePreset();
            const globalWorldBook = ensureGlobalWorldBookStore();
            const parts = [];
            parts.push(defaultPreset ? `默认预设：${defaultPreset.name}` : '未设默认预设');
            parts.push(globalWorldBook.entries.length ? `全局世界书 ${globalWorldBook.entries.length} 条` : '全局世界书为空');
            globalOfflineSummaryEl.textContent = parts.join(' · ');
        }
    }

    function renderGlobalOfflinePresetSettings() {
        const select = document.getElementById('global-offline-preset-select');
        if (!select) return;
        const presets = ensureSillyTavernPresetLibrary();
        const selectedId = toHippocampusTrimmedString(appData.appSettings.defaultOfflinePresetId);
        select.innerHTML = '<option value="">不设默认预设</option>' + presets.map((preset) => {
            const selected = selectedId === String(preset.id || '') ? 'selected' : '';
            return `<option value="${escapeHtml(preset.id)}" ${selected}>${escapeHtml(preset.name)}</option>`;
        }).join('');
    }

    function getSillyTavernRegexSourceLabel(sourceType) {
        const safeType = toHippocampusTrimmedString(sourceType).toLowerCase();
        if (safeType === 'character') return '角色自带';
        if (safeType === 'global') return '全局';
        return '预设自带';
    }

    function createGlobalOfflinePromptEntryElement(entry = {}, index = 0) {
        const safeEntry = {
            id: toHippocampusTrimmedString(entry.id) || createSillyTavernPromptEntryId(),
            name: toHippocampusTrimmedString(entry.name || entry.title) || `预设条目 ${index + 1}`,
            content: normalizeSillyTavernPresetContent(entry.content || entry.prompt || entry.text || ''),
            enabled: entry.enabled !== false && entry.disabled !== true,
            role: getSillyTavernPromptRole(entry.role),
            injectionPosition: entry.injectionPosition ?? entry.injection_position ?? '',
            injectionDepth: entry.injectionDepth ?? entry.injection_depth ?? '',
            injectionOrder: entry.injectionOrder ?? entry.injection_order ?? '',
            marker: toHippocampusTrimmedString(entry.marker),
            forbidOverrides: entry.forbidOverrides === true || entry.forbid_overrides === true,
            systemPrompt: entry.systemPrompt === true || entry.system_prompt === true,
            injectionTrigger: toHippocampusTrimmedString(entry.injectionTrigger || entry.injection_trigger),
            order: Number.isFinite(Number(entry.order)) ? Number(entry.order) : index
        };
        const wrapper = document.createElement('div');
        wrapper.className = 'global-offline-prompt-entry';
        wrapper.dataset.entryId = safeEntry.id;
        wrapper.dataset.promptMeta = JSON.stringify({
            injectionPosition: safeEntry.injectionPosition,
            injectionDepth: safeEntry.injectionDepth,
            injectionOrder: safeEntry.injectionOrder,
            marker: safeEntry.marker,
            forbidOverrides: safeEntry.forbidOverrides,
            systemPrompt: safeEntry.systemPrompt,
            injectionTrigger: safeEntry.injectionTrigger
        });
        wrapper.innerHTML = `
            <div class="global-offline-entry-toolbar">
                <label class="worldbook-inline-toggle">
                    <input type="checkbox" class="global-offline-prompt-enabled" ${safeEntry.enabled ? 'checked' : ''}>
                    启用
                </label>
                <input type="text" class="global-offline-prompt-name" placeholder="条目名" value="${escapeHtml(safeEntry.name)}">
                <select class="global-offline-prompt-role" title="这条内容以什么身份发给 AI">
                    <option value="system">系统规则</option>
                    <option value="user">用户补充</option>
                    <option value="assistant">AI 示例</option>
                </select>
                <button type="button" class="global-offline-entry-move-up" title="上移">上移</button>
                <button type="button" class="global-offline-entry-move-down" title="下移">下移</button>
                <button type="button" class="worldbook-delete-btn global-offline-entry-delete" title="删除">-</button>
            </div>
            <textarea class="global-offline-prompt-content" rows="5" placeholder="这条预设内容...">${escapeHtml(safeEntry.content)}</textarea>
        `;
        const roleSelect = wrapper.querySelector('.global-offline-prompt-role');
        if (roleSelect) roleSelect.value = safeEntry.role;
        const moveUp = wrapper.querySelector('.global-offline-entry-move-up');
        const moveDown = wrapper.querySelector('.global-offline-entry-move-down');
        const deleteBtn = wrapper.querySelector('.global-offline-entry-delete');
        if (moveUp) {
            moveUp.addEventListener('click', () => {
                const previous = wrapper.previousElementSibling;
                if (previous && previous.classList.contains('global-offline-prompt-entry')) {
                    wrapper.parentElement.insertBefore(wrapper, previous);
                }
            });
        }
        if (moveDown) {
            moveDown.addEventListener('click', () => {
                const next = wrapper.nextElementSibling;
                if (next && next.classList.contains('global-offline-prompt-entry')) {
                    wrapper.parentElement.insertBefore(next, wrapper);
                }
            });
        }
        if (deleteBtn) deleteBtn.addEventListener('click', () => wrapper.remove());
        return wrapper;
    }

    function renderGlobalOfflinePromptEntryEditor(preset = null) {
        const container = document.getElementById('global-offline-prompt-entry-editor');
        const rawEditor = document.getElementById('global-offline-preset-editor');
        if (!container) return;
        const selectedPreset = preset || getSillyTavernPresetById(document.getElementById('global-offline-preset-select')?.value);
        container.dataset.rendered = '1';
        container.innerHTML = '';
        if (rawEditor) rawEditor.value = selectedPreset && selectedPreset.content ? selectedPreset.content : '';
        let entries = selectedPreset ? getOrderedSillyTavernPromptEntries(selectedPreset) : [];
        if (!entries.length && selectedPreset && selectedPreset.content) {
            entries = [{
                id: createSillyTavernPromptEntryId(),
                name: '整份预设',
                role: 'system',
                enabled: true,
                content: selectedPreset.content
            }];
        }
        if (!entries.length) {
            container.innerHTML = '<p class="placeholder-text">还没有载入预设。可以先导入酒馆预设，或点“添加预设条目”自己写。</p>';
            return;
        }
        entries.forEach((entry, index) => {
            container.appendChild(createGlobalOfflinePromptEntryElement(entry, index));
        });
    }

    function collectGlobalOfflinePromptEntryEditorData() {
        const container = document.getElementById('global-offline-prompt-entry-editor');
        const rawEditor = document.getElementById('global-offline-preset-editor');
        const entries = [];
        if (container) {
            container.querySelectorAll('.global-offline-prompt-entry').forEach((entryDiv, index) => {
                const content = normalizeSillyTavernPresetContent(entryDiv.querySelector('.global-offline-prompt-content')?.value || '');
                const rawName = toHippocampusTrimmedString(entryDiv.querySelector('.global-offline-prompt-name')?.value);
                if (!content && !rawName) return;
                const name = rawName || `预设条目 ${index + 1}`;
                const meta = parseJsonMaybe(entryDiv.dataset.promptMeta) || {};
                entries.push(Object.assign({}, meta, {
                    id: entryDiv.dataset.entryId || createSillyTavernPromptEntryId(),
                    name,
                    content,
                    enabled: Boolean(entryDiv.querySelector('.global-offline-prompt-enabled')?.checked),
                    role: getSillyTavernPromptRole(entryDiv.querySelector('.global-offline-prompt-role')?.value),
                    order: index
                }));
            });
        }
        const promptOrder = entries.map(entry => entry.id);
        const rawContent = normalizeSillyTavernPresetContent(rawEditor ? rawEditor.value : '');
        const content = entries.length
            ? buildSillyTavernPresetContent({ promptEntries: entries, promptOrder })
            : rawContent;
        return {
            promptEntries: entries,
            promptOrder,
            content
        };
    }

    function createGlobalOfflineRegexElement(script = {}, sourceType = 'preset', index = 0) {
        const safeScript = normalizeSillyTavernRegexScript(script, index, sourceType);
        const safeSourceType = toHippocampusTrimmedString(safeScript.sourceType || sourceType) || sourceType;
        const placement = normalizeSillyTavernPlacement(safeScript.placement);
        const wrapper = document.createElement('div');
        wrapper.className = 'global-offline-regex-rule';
        wrapper.dataset.regexId = safeScript.id;
        wrapper.dataset.sourceType = safeSourceType;
        wrapper.dataset.regexMeta = JSON.stringify({
            trimStrings: safeScript.trimStrings || [],
            substituteRegex: safeScript.substituteRegex || 0,
            minDepth: safeScript.minDepth,
            maxDepth: safeScript.maxDepth,
            markdownOnly: safeScript.markdownOnly === true,
            runOnEdit: safeScript.runOnEdit !== false
        });
        wrapper.innerHTML = `
            <div class="global-offline-regex-toolbar">
                <span class="global-offline-regex-source">${escapeHtml(getSillyTavernRegexSourceLabel(safeSourceType))}</span>
                <label class="worldbook-inline-toggle">
                    <input type="checkbox" class="global-offline-regex-enabled" ${safeScript.enabled !== false && safeScript.disabled !== true ? 'checked' : ''}>
                    启用
                </label>
                <input type="text" class="global-offline-regex-name" placeholder="规则名" value="${escapeHtml(safeScript.scriptName || `正则 ${index + 1}`)}">
                <button type="button" class="worldbook-delete-btn global-offline-regex-delete" title="删除">-</button>
            </div>
            <div class="global-offline-regex-options">
                <label><input type="checkbox" class="global-offline-regex-place-user" ${placement.includes(1) ? 'checked' : ''}> 处理用户消息</label>
                <label><input type="checkbox" class="global-offline-regex-place-assistant" ${placement.includes(2) ? 'checked' : ''}> 处理 AI 回复</label>
                <label><input type="checkbox" class="global-offline-regex-prompt-only" ${safeScript.promptOnly ? 'checked' : ''}> 只改发给 AI 的内容</label>
            </div>
            <label class="global-offline-regex-label">匹配内容</label>
            <textarea class="global-offline-regex-find" rows="3" placeholder="正则匹配表达式">${escapeHtml(safeScript.findRegex || '')}</textarea>
            <label class="global-offline-regex-label">替换成</label>
            <textarea class="global-offline-regex-replace" rows="3" placeholder="可以留空，也可以使用 $1、$2 这类捕获组">${escapeHtml(safeScript.replaceString || '')}</textarea>
        `;
        const deleteBtn = wrapper.querySelector('.global-offline-regex-delete');
        if (deleteBtn) deleteBtn.addEventListener('click', () => wrapper.remove());
        return wrapper;
    }

    function renderGlobalOfflineRegexEditor(preset = null) {
        const container = document.getElementById('global-offline-regex-editor');
        if (!container) return;
        const selectedPreset = preset || getSillyTavernPresetById(document.getElementById('global-offline-preset-select')?.value);
        const globalScripts = ensureGlobalRegexScriptsStore();
        const presetScripts = normalizeSillyTavernRegexScripts(selectedPreset && selectedPreset.regexScripts, 'preset');
        container.dataset.rendered = '1';
        container.innerHTML = '';
        const appendSection = (title, scripts, sourceType) => {
            const header = document.createElement('div');
            header.className = 'global-offline-regex-section-title';
            header.textContent = title;
            container.appendChild(header);
            scripts.forEach((script, index) => {
                container.appendChild(createGlobalOfflineRegexElement(script, sourceType, index));
            });
        };
        if (globalScripts.length) appendSection('全局正则', globalScripts, 'global');
        if (presetScripts.length) appendSection('当前预设自带正则', presetScripts, 'preset');
        if (!globalScripts.length && !presetScripts.length) {
            container.innerHTML = '<p class="placeholder-text">还没有正则规则。导入带正则的酒馆预设，或点“添加全局正则”。</p>';
        }
    }

    function collectGlobalOfflineRegexEditorData() {
        const result = { global: [], preset: [] };
        const container = document.getElementById('global-offline-regex-editor');
        if (!container || container.dataset.rendered !== '1') return result;
        container.querySelectorAll('.global-offline-regex-rule').forEach((ruleDiv, index) => {
            const sourceType = ruleDiv.dataset.sourceType === 'global' ? 'global' : 'preset';
            const rawName = toHippocampusTrimmedString(ruleDiv.querySelector('.global-offline-regex-name')?.value);
            const findRegex = toHippocampusTrimmedString(ruleDiv.querySelector('.global-offline-regex-find')?.value);
            const replaceString = String(ruleDiv.querySelector('.global-offline-regex-replace')?.value || '');
            if (!findRegex && !replaceString && !rawName) return;
            const name = rawName || `正则 ${index + 1}`;
            const placement = [];
            if (ruleDiv.querySelector('.global-offline-regex-place-user')?.checked) placement.push(1);
            if (ruleDiv.querySelector('.global-offline-regex-place-assistant')?.checked) placement.push(2);
            const meta = parseJsonMaybe(ruleDiv.dataset.regexMeta) || {};
            result[sourceType].push(normalizeSillyTavernRegexScript(Object.assign({}, meta, {
                id: ruleDiv.dataset.regexId || createSillyTavernRegexId(),
                scriptName: name,
                enabled: Boolean(ruleDiv.querySelector('.global-offline-regex-enabled')?.checked),
                disabled: !Boolean(ruleDiv.querySelector('.global-offline-regex-enabled')?.checked),
                findRegex,
                replaceString,
                placement: placement.length ? placement : [2],
                promptOnly: Boolean(ruleDiv.querySelector('.global-offline-regex-prompt-only')?.checked),
                sourceType
            }), index, sourceType));
        });
        return result;
    }

    function addGlobalOfflinePromptEntry() {
        const container = document.getElementById('global-offline-prompt-entry-editor');
        if (!container) return;
        if (container.querySelector('.placeholder-text')) container.innerHTML = '';
        container.dataset.rendered = '1';
        container.appendChild(createGlobalOfflinePromptEntryElement({
            id: createSillyTavernPromptEntryId(),
            name: '',
            role: 'system',
            enabled: true,
            content: ''
        }, container.querySelectorAll('.global-offline-prompt-entry').length));
    }

    function addGlobalOfflineRegexScript() {
        const container = document.getElementById('global-offline-regex-editor');
        if (!container) return;
        if (container.querySelector('.placeholder-text')) container.innerHTML = '';
        container.dataset.rendered = '1';
        if (!container.querySelector('.global-offline-regex-section-title')) {
            const header = document.createElement('div');
            header.className = 'global-offline-regex-section-title';
            header.textContent = '全局正则';
            container.appendChild(header);
        }
        container.appendChild(createGlobalOfflineRegexElement({
            id: createSillyTavernRegexId(),
            scriptName: '',
            enabled: true,
            findRegex: '',
            replaceString: '',
            placement: [2],
            sourceType: 'global'
        }, 'global', container.querySelectorAll('.global-offline-regex-rule').length));
    }

    function renderGlobalWorldBookPresetSelect() {
        const select = document.getElementById('global-worldbook-preset-select');
        if (!select) return;
        const presets = ensureGlobalWorldBookPresetLibrary();
        select.innerHTML = '<option value="">选择已保存的全局世界书...</option>' + presets.map((preset) => (
            `<option value="${escapeHtml(preset.id)}">${escapeHtml(preset.name)}</option>`
        )).join('');
    }

    function createGlobalWorldBookEntryElement(entry = {}) {
        const safeEntry = normalizeWorldBookEntry(entry);
        const wrapper = document.createElement('div');
        wrapper.className = 'worldbook-entry global-worldbook-entry';
        wrapper.dataset.entryId = safeEntry.id;
        wrapper.dataset.worldbookMeta = JSON.stringify({
            insertionDepth: safeEntry.insertionDepth,
            scanDepth: safeEntry.scanDepth,
            position: safeEntry.position,
            insertionPosition: safeEntry.insertionPosition,
            selective: safeEntry.selective,
            probability: safeEntry.probability,
            useProbability: safeEntry.useProbability,
            caseSensitive: safeEntry.caseSensitive,
            matchWholeWords: safeEntry.matchWholeWords,
            recursive: safeEntry.recursive,
            source: safeEntry.source
        });
        wrapper.innerHTML = `
            <div class="worldbook-entry-toolbar">
                <label class="worldbook-inline-toggle">
                    <input type="checkbox" class="global-worldbook-entry-enabled" ${safeEntry.enabled !== false ? 'checked' : ''}>
                    启用
                </label>
                <select class="global-worldbook-entry-mode">
                    <option value="always">一直挂载</option>
                    <option value="keyword">关键词触发</option>
                </select>
                <input type="text" class="global-worldbook-entry-keywords" placeholder="触发关键词，用逗号分隔" value="${escapeHtml(safeEntry.keywords || '')}">
                <input type="number" class="global-worldbook-entry-depth" min="0" placeholder="深度" value="${escapeHtml(Number.isFinite(Number(safeEntry.depth)) ? String(safeEntry.depth) : '4')}">
                <button type="button" class="worldbook-delete-btn global-worldbook-entry-delete">-</button>
            </div>
            <div class="worldbook-header">
                <input type="text" class="worldbook-key global-worldbook-entry-key" placeholder="条目名" value="${escapeHtml(safeEntry.key || '')}">
            </div>
            <textarea class="worldbook-value global-worldbook-entry-value" placeholder="内容...">${escapeHtml(safeEntry.value || '')}</textarea>
        `;
        const mode = wrapper.querySelector('.global-worldbook-entry-mode');
        if (mode) mode.value = safeEntry.triggerMode === 'keyword' ? 'keyword' : 'always';
        const deleteBtn = wrapper.querySelector('.global-worldbook-entry-delete');
        if (deleteBtn) deleteBtn.addEventListener('click', () => wrapper.remove());
        return wrapper;
    }

    function renderGlobalWorldBookEditor() {
        const store = ensureGlobalWorldBookStore();
        setSettingsFieldChecked('global-worldbook-enabled-toggle', store.enabled !== false);
        setSettingsFieldValue('global-worldbook-default-depth', String(store.defaultDepth || 4));
        renderGlobalWorldBookPresetSelect();
        const container = document.getElementById('global-worldbook-editor');
        if (!container) return;
        container.dataset.rendered = '1';
        container.innerHTML = '';
        if (!store.entries.length) {
            container.innerHTML = '<p class="placeholder-text">还没有全局世界书条目。可以导入 JSON，也可以点“添加条目”。</p>';
            return;
        }
        store.entries.forEach(entry => {
            container.appendChild(createGlobalWorldBookEntryElement(entry));
        });
    }

    function collectGlobalWorldBookEditorData() {
        const defaultDepth = Math.max(0, Math.floor(Number(getSettingsFieldValue('global-worldbook-default-depth') || 4) || 4));
        const entries = [];
        document.querySelectorAll('#global-worldbook-editor .global-worldbook-entry').forEach((entryDiv, index) => {
            const key = entryDiv.querySelector('.global-worldbook-entry-key')?.value.trim() || '';
            const value = entryDiv.querySelector('.global-worldbook-entry-value')?.value.trim() || '';
            if (!key && !value) return;
            const preservedMeta = parseJsonMaybe(entryDiv.dataset.worldbookMeta) || {};
            entries.push(Object.assign({}, preservedMeta, {
                id: entryDiv.dataset.entryId || createWorldBookId('gwbe'),
                key,
                value,
                enabled: Boolean(entryDiv.querySelector('.global-worldbook-entry-enabled')?.checked),
                triggerMode: normalizeWorldBookTriggerMode(entryDiv.querySelector('.global-worldbook-entry-mode')?.value, 'always'),
                keywords: entryDiv.querySelector('.global-worldbook-entry-keywords')?.value.trim() || '',
                groupId: DEFAULT_WORLD_BOOK_GROUP_ID,
                sortOrder: index,
                depth: Math.max(0, Math.floor(Number(entryDiv.querySelector('.global-worldbook-entry-depth')?.value) || defaultDepth))
            }));
        });
        return normalizeGlobalWorldBookSource({
            enabled: getSettingsFieldChecked('global-worldbook-enabled-toggle'),
            defaultDepth,
            groups: [getDefaultWorldBookGroup()],
            entries
        });
    }

