    function readGlobalOfflineWorldBookSettingsFromUI() {
        if (!appData.appSettings) appData.appSettings = {};
        const presetSelect = document.getElementById('global-offline-preset-select');
        if (presetSelect) appData.appSettings.defaultOfflinePresetId = presetSelect.value || '';
        const selectedPreset = getSillyTavernPresetById(presetSelect ? presetSelect.value : '');
        const promptEditor = document.getElementById('global-offline-prompt-entry-editor');
        if (selectedPreset && promptEditor && promptEditor.dataset.rendered === '1') {
            const promptData = collectGlobalOfflinePromptEntryEditorData();
            if (promptData.content) {
                selectedPreset.content = promptData.content;
                selectedPreset.promptEntries = promptData.promptEntries;
                selectedPreset.promptOrder = promptData.promptOrder;
                selectedPreset.updatedAt = new Date().toISOString();
            }
        }
        const worldBookEditor = document.getElementById('global-worldbook-editor');
        if (worldBookEditor && worldBookEditor.dataset.rendered === '1') {
            appData.globalWorldBook = collectGlobalWorldBookEditorData();
        }
        const regexEditor = document.getElementById('global-offline-regex-editor');
        if (regexEditor && regexEditor.dataset.rendered === '1') {
            const regexData = collectGlobalOfflineRegexEditorData();
            appData.globalRegexScripts = normalizeSillyTavernRegexScripts(regexData.global, 'global');
            if (selectedPreset) {
                selectedPreset.regexScripts = normalizeSillyTavernRegexScripts(regexData.preset, 'preset');
                selectedPreset.updatedAt = new Date().toISOString();
            }
        }
        ensureGlobalWorldBookStore();
        ensureGlobalWorldBookPresetLibrary();
        ensureGlobalRegexScriptsStore();
    }

    function importJsonTextFile(accept, onParsed) {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = accept || '.json,application/json,text/plain,*/*';
        input.onchange = (event) => {
            const file = event.target.files && event.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (readerEvent) => {
                try {
                    const rawText = String(readerEvent.target && readerEvent.target.result || '');
                    const parsed = parseJsonMaybe(rawText);
                    if (!parsed) throw new Error('这个文件不是可识别的 JSON。');
                    onParsed(parsed, file);
                } catch (error) {
                    showCustomAlert('导入失败', error && error.message ? error.message : String(error));
                }
            };
            reader.readAsText(file);
        };
        input.click();
    }

    function importGlobalOfflinePresetFile() {
        importJsonTextFile('.json,application/json,text/plain,*/*', (parsed, file) => {
            const fallbackName = String(file && file.name || '酒馆预设').replace(/\.[^.]+$/, '');
            const preset = normalizeSillyTavernPresetPayload(parsed, fallbackName);
            if (!preset || !preset.content) throw new Error('没有读到可用的预设内容。');
            ensureSillyTavernPresetLibrary().push(preset);
            appData.appSettings.defaultOfflinePresetId = preset.id;
            saveAppData();
            renderGlobalOfflinePresetSettings();
            renderGlobalOfflinePromptEntryEditor(preset);
            renderGlobalOfflineRegexEditor(preset);
            renderSettingsHubSummaries();
            showToast(`已导入预设：${preset.name}`, 'success');
        });
    }

    function importGlobalOfflineRegexFile() {
        importJsonTextFile('.json,application/json,text/plain,*/*', (parsed, file) => {
            const scripts = extractSillyTavernRegexScripts(parsed, 'global').length
                ? extractSillyTavernRegexScripts(parsed, 'global')
                : normalizeSillyTavernRegexScripts(parsed, 'global');
            if (!scripts.length) throw new Error('没有读到可用的正则规则。');
            const current = collectGlobalOfflineRegexEditorData();
            appData.globalRegexScripts = normalizeSillyTavernRegexScripts([
                ...current.global,
                ...scripts.map(script => Object.assign({}, script, { sourceType: 'global' }))
            ], 'global');
            saveAppData();
            renderGlobalOfflineRegexEditor(getSillyTavernPresetById(document.getElementById('global-offline-preset-select')?.value));
            renderSettingsHubSummaries();
            showToast(`已导入 ${scripts.length} 条全局正则`, 'success');
        });
    }

    function loadGlobalOfflinePresetIntoEditor() {
        const select = document.getElementById('global-offline-preset-select');
        const editor = document.getElementById('global-offline-preset-editor');
        if (!select) return;
        const preset = getSillyTavernPresetById(select.value);
        if (!preset) {
            showToast('先选择一个预设', 'info');
            return;
        }
        if (editor) editor.value = preset.content || '';
        renderGlobalOfflinePromptEntryEditor(preset);
        renderGlobalOfflineRegexEditor(preset);
        showToast('已载入编辑器，可以逐条修改', 'success');
    }

    function saveGlobalOfflinePresetFromEditor() {
        const select = document.getElementById('global-offline-preset-select');
        if (!select) return;
        const promptData = collectGlobalOfflinePromptEntryEditorData();
        const regexData = collectGlobalOfflineRegexEditorData();
        if (!promptData.content) {
            showToast('预设内容是空的，不能保存', 'info');
            return;
        }
        const existing = getSillyTavernPresetById(select.value);
        showCustomPrompt(
            existing ? '覆盖当前预设' : '保存新预设',
            '给这个预设起个名字：',
            existing ? existing.name : '我的线下预设',
            (nameInput) => {
                const name = toHippocampusTrimmedString(nameInput) || (existing ? existing.name : '我的线下预设');
                const library = ensureSillyTavernPresetLibrary();
                let target = existing;
                if (target) {
                    target.name = name;
                    target.content = promptData.content;
                    target.promptEntries = promptData.promptEntries;
                    target.promptOrder = promptData.promptOrder;
                    target.regexScripts = normalizeSillyTavernRegexScripts(regexData.preset, 'preset');
                    target.updatedAt = new Date().toISOString();
                } else {
                    target = {
                        id: createSillyTavernPresetId(),
                        name,
                        content: promptData.content,
                        promptEntries: promptData.promptEntries,
                        promptOrder: promptData.promptOrder,
                        regexScripts: normalizeSillyTavernRegexScripts(regexData.preset, 'preset'),
                        source: 'manual',
                        importedAt: new Date().toISOString(),
                        updatedAt: new Date().toISOString()
                    };
                    library.push(target);
                }
                appData.globalRegexScripts = normalizeSillyTavernRegexScripts(regexData.global, 'global');
                appData.appSettings.defaultOfflinePresetId = target.id;
                saveAppData();
                renderGlobalOfflinePresetSettings();
                const nextSelect = document.getElementById('global-offline-preset-select');
                if (nextSelect) nextSelect.value = target.id;
                renderGlobalOfflinePromptEntryEditor(target);
                renderGlobalOfflineRegexEditor(target);
                renderSettingsHubSummaries();
                showToast('预设已保存', 'success');
            },
            true
        );
    }

    function deleteGlobalOfflinePreset() {
        const select = document.getElementById('global-offline-preset-select');
        if (!select) return;
        const preset = getSillyTavernPresetById(select.value);
        if (!preset) {
            showToast('先选择一个预设', 'info');
            return;
        }
        showCustomConfirm('删除预设', `确定删除预设「${preset.name}」吗？`, () => {
            appData.sillyTavernPresets = ensureSillyTavernPresetLibrary().filter(item => String(item.id) !== String(preset.id));
            if (String(appData.appSettings.defaultOfflinePresetId || '') === String(preset.id)) {
                appData.appSettings.defaultOfflinePresetId = '';
            }
            saveAppData();
            renderGlobalOfflinePresetSettings();
            renderGlobalOfflinePromptEntryEditor();
            renderGlobalOfflineRegexEditor();
            renderSettingsHubSummaries();
            showToast('预设已删除', 'success');
        }, null, '删除', '取消', true);
    }

