    function renderOfflineIllustrationToggle() {
        if (!offlineIllustrationToggleButton || !offlineIllustrationToggleLabel) return;

        if (activeGroupChatId) {
            offlineIllustrationToggleButton.classList.add('hidden');
            return;
        }

        const contact = appData.aiContacts.find((item) => item.id === activeChatContactId);
        if (!contact) {
            offlineIllustrationToggleButton.classList.add('hidden');
            return;
        }

        ensureContactImageGenerationProfile(contact);
        const isOfflineMode = Boolean(contact.isOfflineMode);
        if (!isOfflineMode) {
            offlineIllustrationToggleButton.classList.add('hidden');
            return;
        }

        offlineIllustrationToggleButton.classList.remove('hidden');
        const enabled = Boolean(contact.imageGenerationProfile.offlineIllustrationModeEnabled);
        offlineIllustrationToggleButton.classList.toggle('is-enabled', enabled);
        offlineIllustrationToggleLabel.textContent = enabled ? '插图开' : '插图关';
    }

    function normalizeContactReferencePackLines(value) {
        return String(value || '')
            .split(/\r?\n/)
            .map((line) => line.trim())
            .filter(Boolean)
            .slice(0, 8);
    }

    function formatContactReferencePackLines(referencePacks) {
        if (!Array.isArray(referencePacks)) return '';

        return referencePacks
            .map((pack) => {
                if (!pack) return '';
                if (typeof pack === 'string') {
                    return String(pack).trim();
                }

                if (typeof pack === 'object') {
                    return [
                        pack.name || pack.title || pack.label || '',
                        pack.description || pack.note || pack.summary || pack.text || ''
                    ].filter(Boolean).join(': ').trim();
                }

                return '';
            })
            .filter(Boolean)
            .join('\n');
    }

    function clearContactReferenceImagePreviewUrls() {
        contactReferenceImagePreviewUrls.forEach((url) => {
            try { URL.revokeObjectURL(url); } catch (error) { }
        });
        contactReferenceImagePreviewUrls = [];
    }

    function buildContactReferenceImageStorageKey(contactId) {
        return `refimg-${String(contactId || 'contact').trim()}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    }

    function buildContactReferenceImageEntryId() {
        return `ref-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    }

    function getActiveContactReferenceImageEntry(referenceId) {
        const contact = appData.aiContacts.find((item) => item.id === activeChatContactId);
        if (!contact) return { contact: null, profile: null, entry: null };

        const profile = ensureContactImageGenerationProfile(contact);
        const safeReferenceId = String(referenceId || '').trim();
        const entry = (profile.referenceImages || []).find((item) => String(item && item.id || '').trim() === safeReferenceId) || null;
        return { contact, profile, entry };
    }

    function extractChatMessageText(content) {
        if (typeof content === 'string') return content.trim();
        if (Array.isArray(content)) {
            return content
                .map((item) => {
                    if (!item) return '';
                    if (typeof item === 'string') return item;
                    if (item.type === 'text') return String(item.text || '').trim();
                    return '';
                })
                .filter(Boolean)
                .join('\n')
                .trim();
        }
        if (content && typeof content === 'object') {
            if (typeof content.text === 'string') return content.text.trim();
            if (typeof content.content === 'string') return content.content.trim();
        }
        return '';
    }

    function updateContactReferenceUploadHint(count) {
        if (!csImageReferenceUploadHint) return;
        const safeCount = Math.max(0, Number(count) || 0);
        csImageReferenceUploadHint.textContent = safeCount >= 8
            ? '已达到 8 张上限，请先删除旧参考图'
            : `点击上传角色/场景参考图${safeCount ? `（已上传 ${safeCount} 张）` : ''}`;
    }

    function renderContactReferenceImageList(contact) {
        if (!csImageReferenceList) return;

        clearContactReferenceImagePreviewUrls();

        const profile = contact && typeof contact === 'object'
            ? ensureContactImageGenerationProfile(contact)
            : getDefaultContactImageGenerationProfile();
        const entries = Array.isArray(profile.referenceImages) ? profile.referenceImages : [];

        updateContactReferenceUploadHint(entries.length);

        if (!entries.length) {
            csImageReferenceList.innerHTML = '<div class="settings-help-text">还没有上传参考图。你可以放角色固定形象、常驻场景、房间、公司工位等。</div>';
            return;
        }

        csImageReferenceList.innerHTML = entries.map((entry, index) => {
            const safeId = escapeHtml(entry.id);
            const title = escapeHtml(entry.name || `参考图 ${index + 1}`);
            const note = escapeHtml(entry.note || '');
            const autoHint = escapeHtml(entry.autoHint || '');
            const hintText = autoHint || '还没有自动提炼锚点，可以点击“提炼锚点”。';

            return `
                <div data-reference-entry="${safeId}" style="border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 10px; background: rgba(255,255,255,0.72);">
                    <div style="display: flex; gap: 10px; align-items: flex-start;">
                        <div data-ref-action="preview" data-ref-id="${safeId}" style="width: 84px; height: 84px; border-radius: 10px; overflow: hidden; background: rgba(0,0,0,0.05); display: flex; align-items: center; justify-content: center; cursor: pointer; flex-shrink: 0;">
                            <img data-ref-preview-id="${safeId}" alt="${title}" style="width: 100%; height: 100%; object-fit: cover; display: none;">
                            <span data-ref-empty-id="${safeId}" style="font-size: 12px; color: #777; text-align: center; padding: 8px;">参考图</span>
                        </div>
                        <div style="flex: 1; min-width: 0;">
                            <input type="text" data-ref-field="name" data-ref-id="${safeId}" value="${title}" placeholder="参考图标题" style="width: 100%; box-sizing: border-box; margin-bottom: 8px;">
                            <textarea data-ref-field="note" data-ref-id="${safeId}" rows="2" placeholder="补充说明这张图为什么重要，比如“这是角色最稳定的脸和发型”" style="width: 100%; box-sizing: border-box; resize: vertical;">${note}</textarea>
                            <div style="margin-top: 8px; padding: 8px 10px; border-radius: 10px; background: rgba(80,151,205,0.08); color: #35556f; font-size: 12px; line-height: 1.6;">
                                <strong>自动提炼锚点：</strong>
                                <div data-ref-hint-id="${safeId}" style="margin-top: 4px; white-space: pre-line;">${hintText}</div>
                            </div>
                            <div style="display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px;">
                                <button type="button" data-ref-action="preview" data-ref-id="${safeId}">预览</button>
                                <button type="button" data-ref-action="analyze" data-ref-id="${safeId}">${entry.autoHint ? '重新提炼' : '提炼锚点'}</button>
                                <button type="button" data-ref-action="delete" data-ref-id="${safeId}">删除</button>
                            </div>
                        </div>
                    </div>
                </div>
            `;
        }).join('');

        entries.forEach(async (entry) => {
            try {
                const blob = await db.getImage(entry.imageId);
                if (!blob) return;
                const imageUrl = URL.createObjectURL(blob);
                contactReferenceImagePreviewUrls.push(imageUrl);

                const imgEl = csImageReferenceList.querySelector(`[data-ref-preview-id="${entry.id}"]`);
                const emptyEl = csImageReferenceList.querySelector(`[data-ref-empty-id="${entry.id}"]`);
                if (imgEl) {
                    imgEl.src = imageUrl;
                    imgEl.style.display = 'block';
                }
                if (emptyEl) {
                    emptyEl.style.display = 'none';
                }
            } catch (error) {
                console.warn('[IDIC] 参考图缩略图加载失败', error);
            }
        });
    }

    function renderContactImageGenerationSettings(contact) {
        if (
            !csImageProviderOverrideSelect
            || !csImageStylePresetSelect
            || !csImageAnchorAppearanceInput
            || !csImageAnchorClothingInput
            || !csImageAnchorVibeInput
            || !csImageAnchorForbiddenInput
            || !csImageReferencePacksInput
        ) {
            return;
        }

        const profile = contact && typeof contact === 'object'
            ? ensureContactImageGenerationProfile(contact)
            : getDefaultContactImageGenerationProfile();
        const anchors = profile.identityAnchors || {};
        const naiPreset = profile.naiPreset || {};

        csImageProviderOverrideSelect.value = String(profile.defaultProviderOverride || '').trim();
        csImageStylePresetSelect.value = String(profile.defaultPromptStyle || '').trim();
        csImageAnchorAppearanceInput.value = String(anchors.appearance || '').trim();
        csImageAnchorClothingInput.value = String(anchors.clothing || '').trim();
        csImageAnchorVibeInput.value = String(anchors.vibe || '').trim();
        csImageAnchorForbiddenInput.value = String(anchors.forbiddenDrift || '').trim();
        if (csImageNaiArtistPromptInput) csImageNaiArtistPromptInput.value = String(naiPreset.artistPrompt || '').trim();
        if (csImageNaiPositivePromptInput) csImageNaiPositivePromptInput.value = String(naiPreset.positivePrompt || '').trim();
        if (csImageNaiNegativePromptInput) csImageNaiNegativePromptInput.value = String(naiPreset.negativePrompt || '').trim();
        csImageReferencePacksInput.value = formatContactReferencePackLines(profile.referencePacks);
        renderContactReferenceImageList(contact);
    }

    function persistActiveContactImageGenerationSettings() {
        const contact = appData.aiContacts.find((item) => item.id === activeChatContactId);
        if (!contact) return;

        const profile = ensureContactImageGenerationProfile(contact);
        profile.defaultProviderOverride = String(csImageProviderOverrideSelect && csImageProviderOverrideSelect.value || '').trim();
        profile.defaultPromptStyle = String(csImageStylePresetSelect && csImageStylePresetSelect.value || '').trim();
        profile.identityAnchors = Object.assign({}, profile.identityAnchors, {
            appearance: String(csImageAnchorAppearanceInput && csImageAnchorAppearanceInput.value || '').trim(),
            clothing: String(csImageAnchorClothingInput && csImageAnchorClothingInput.value || '').trim(),
            vibe: String(csImageAnchorVibeInput && csImageAnchorVibeInput.value || '').trim(),
            forbiddenDrift: String(csImageAnchorForbiddenInput && csImageAnchorForbiddenInput.value || '').trim()
        });
        profile.naiPreset = Object.assign({}, profile.naiPreset, {
            artistPrompt: String(csImageNaiArtistPromptInput && csImageNaiArtistPromptInput.value || '').trim(),
            positivePrompt: String(csImageNaiPositivePromptInput && csImageNaiPositivePromptInput.value || '').trim(),
            negativePrompt: String(csImageNaiNegativePromptInput && csImageNaiNegativePromptInput.value || '').trim()
        });
        profile.referencePacks = normalizeContactReferencePackLines(
            csImageReferencePacksInput && csImageReferencePacksInput.value
        );

        saveAppData();
    }

    async function analyzeContactReferenceImage(referenceId, options = {}) {
        const { contact, entry } = getActiveContactReferenceImageEntry(referenceId);
        if (!contact || !entry) {
            throw new Error('参考图不存在');
        }

        const endpointUrl = normalizeChatApiUrl(appData && appData.appSettings && appData.appSettings.apiUrl);
        const apiKey = String(appData && appData.appSettings && appData.appSettings.apiKey || '').trim();
        const model = String(appData && appData.appSettings && appData.appSettings.apiModel || '').trim();
        if (!endpointUrl || !apiKey || !model) {
            throw new Error('当前聊天模型未配置，无法自动提炼参考图锚点');
        }

        const originalBlob = await db.getImage(entry.imageId);
        if (!originalBlob) {
            throw new Error('参考图文件不存在');
        }

        const compressedBlob = await compressImageBlob(originalBlob, 0.85, 1024);
        const imageDataUrl = await blobToDataURL(compressedBlob);
        const displayName = getCharDisplayName(contact);
        const userNote = String(entry.note || '').trim();
        const userTitle = String(entry.name || '').trim();
        const prompt = [
            '你是 IDIC 的“角色生图参考图锚点提炼器”。目标是为角色后续生图提炼稳定、可复用的视觉锚点。',
            `当前角色：${displayName || contact.remark || contact.name || '未命名角色'}`,
            userTitle ? `参考图标题：${userTitle}` : '',
            userNote ? `用户补充说明：${userNote}` : '',
            '请根据这张参考图，输出一段简洁中文描述，控制在 80 到 180 字。',
            '必须优先提炼稳定元素：发型发色、脸部或体型特征、常见穿搭或配饰、整体气质、场景稳定元素（如果明显）。',
            '不要写摄影参数，不要写构图评价，不要写“可能、大概、像是”这类不确定措辞，不要扩写剧情。'
        ].filter(Boolean).join('\n');

        const response = await fetch(endpointUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify({
                model,
                messages: [{
                    role: 'user',
                    content: [
                        { type: 'text', text: prompt },
                        { type: 'image_url', image_url: { url: imageDataUrl } }
                    ]
                }],
                temperature: 0.2
            })
        });

        if (!response.ok) {
            let errorText = `HTTP ${response.status}`;
            try {
                const errorData = await response.json();
                errorText = String(
                    errorData && errorData.error && errorData.error.message
                    || errorData && errorData.error
                    || errorData && errorData.message
                    || errorText
                ).trim() || errorText;
            } catch (error) {
                try {
                    errorText = String(await response.text() || errorText).trim() || errorText;
                } catch (innerError) { }
            }
            throw new Error(errorText);
        }

        const data = await response.json();
        const choice = Array.isArray(data && data.choices) ? data.choices[0] : null;
        const summary = extractChatMessageText(choice && choice.message && choice.message.content);
        if (!summary) {
            throw new Error('模型没有返回可用的锚点描述');
        }

        const latest = getActiveContactReferenceImageEntry(referenceId);
        if (!latest.contact || !latest.entry) {
            return summary;
        }

        latest.entry.autoHint = summary.trim();
        saveAppData();
        if (!options.skipRender) {
            renderContactReferenceImageList(latest.contact);
        }
        return latest.entry.autoHint;
    }

    async function addContactReferenceImage(file) {
        const contact = appData.aiContacts.find((item) => item.id === activeChatContactId);
        if (!contact) {
            showToast('请先打开一个角色设置页', 'error');
            return;
        }

        const profile = ensureContactImageGenerationProfile(contact);
        if ((profile.referenceImages || []).length >= 8) {
            showToast('参考图最多保存 8 张，请先删除旧图片', 'info');
            return;
        }

        const safeFile = file instanceof File || file instanceof Blob ? file : null;
        if (!safeFile) {
            showToast('未选择参考图文件', 'error');
            return;
        }

        const imageId = buildContactReferenceImageStorageKey(contact.id);
        const entry = {
            id: buildContactReferenceImageEntryId(),
            imageId,
            name: safeFile.name ? String(safeFile.name).replace(/\.[^.]+$/, '').trim() : `参考图 ${(profile.referenceImages || []).length + 1}`,
            note: '',
            autoHint: '',
            createdAt: Date.now()
        };

        try {
            const storedBlob = await compressImageBlob(safeFile, 0.92, 1280);
            await db.saveImage(imageId, storedBlob);
            profile.referenceImages.push(entry);
            saveAppData();
            renderContactReferenceImageList(contact);
            showToast('参考图已保存，正在尝试自动提炼锚点...', 'info');

            try {
                await analyzeContactReferenceImage(entry.id);
                showToast('参考图锚点提炼完成', 'success');
            } catch (analysisError) {
                console.warn('[IDIC] 参考图自动提炼失败', analysisError);
                showToast(`参考图已保存，自动提炼失败：${analysisError.message}`, 'info', 5000);
            }
        } catch (error) {
        console.error('验证网络错误', error);
            showToast(error.message, 'error');
        } finally {
            if (csImageReferenceUploadInput) {
                csImageReferenceUploadInput.value = '';
            }
        }
    }

    function updateContactReferenceImageField(referenceId, field, value) {
        const { contact, entry } = getActiveContactReferenceImageEntry(referenceId);
        if (!contact || !entry) return;

        if (field === 'name') {
            entry.name = String(value || '').trim();
        } else if (field === 'note') {
            entry.note = String(value || '').trim();
        } else {
            return;
        }

        saveAppData();
        renderContactReferenceImageList(contact);
    }

    async function removeContactReferenceImage(referenceId) {
        const { contact, profile, entry } = getActiveContactReferenceImageEntry(referenceId);
        if (!contact || !profile || !entry) return;

        profile.referenceImages = (profile.referenceImages || []).filter((item) => String(item && item.id || '').trim() !== String(referenceId || '').trim());
        saveAppData();
        renderContactReferenceImageList(contact);

        try {
            await db.deleteImage(entry.imageId);
        } catch (error) {
                console.warn('[ForumMemory] Failed to create Supabase client.', error);
        }
    }

