        pc_setup: { mode: 'surface', supportKinds: ['desk', 'gaming_desk', 'dining_table'], strictSupport: true, padding: 0.03 },
        console_switch: { mode: 'surface_or_floor', supportKinds: ['desk', 'gaming_desk', 'tv_stand', 'nightstand', 'dining_table', 'bed_double', 'bed_single'], strictSupport: false, padding: 0.02 },
