    let petImportedHomeLibrariesPromise = null;
    let petImportedHomeMonitorSession = null;
    let petImportedHomeMonitorLoadToken = 0;

    function cloneImportedPetHomeValue(value) {
        return value == null ? value : JSON.parse(JSON.stringify(value));
    }

    function clampImportedPetHomeNumber(value, min, max) {
        return Math.min(max, Math.max(min, value));
    }

    function hashImportedPetHomeText(text) {
        const sourceText = String(text || '');
        let hash = 0;
        for (let index = 0; index < sourceText.length; index++) {
            hash = ((hash << 5) - hash) + sourceText.charCodeAt(index);
            hash |= 0;
        }
        return Math.abs(hash).toString(36);
    }

    function hasImportedPetHomeLayout(petSystem) {
        return !!(petSystem && petSystem.importedHomeLayout && Array.isArray(petSystem.importedHomeLayout.rooms) && petSystem.importedHomeLayout.rooms.length > 0);
    }

    function getImportedPetHomeCameraConfigs(layout) {
        if (!layout || !Array.isArray(layout.rooms)) {
            return [{ key: PET_IMPORTED_HOME_OVERVIEW_KEY, label: '全景' }];
        }
        return [
            { key: PET_IMPORTED_HOME_OVERVIEW_KEY, label: '全景' },
            ...layout.rooms.map((room, index) => ({
                key: String(room && room.key || `room_${index + 1}`),
                label: String(room && room.label || `房间${index + 1}`)
            }))
        ];
    }

    function getImportedPetHomeRoomBounds(room) {
        const width = Number(room && room.width || 4);
        const depth = Number(room && room.depth || 4);
        const centerX = Number(room && room.x || 0);
        const centerZ = Number(room && room.z || 0);
        return {
            minX: centerX - width / 2,
            maxX: centerX + width / 2,
            minZ: centerZ - depth / 2,
            maxZ: centerZ + depth / 2
        };
    }

    function isPointInsideImportedPetHomeRoom(room, x, z, inset = 0) {
        const bounds = getImportedPetHomeRoomBounds(room);
        return x >= bounds.minX + inset
            && x <= bounds.maxX - inset
            && z >= bounds.minZ + inset
            && z <= bounds.maxZ - inset;
    }

    function getDistanceToImportedPetHomeRoom(room, x, z) {
        const bounds = getImportedPetHomeRoomBounds(room);
        const dx = x < bounds.minX ? bounds.minX - x : (x > bounds.maxX ? x - bounds.maxX : 0);
        const dz = z < bounds.minZ ? bounds.minZ - z : (z > bounds.maxZ ? z - bounds.maxZ : 0);
        return Math.hypot(dx, dz);
    }

    function resolveImportedPetHomeRoom(layout, x, z, preferredRoomKey = '') {
        if (!layout || !Array.isArray(layout.rooms) || !layout.rooms.length) return null;
        const preferredRoom = preferredRoomKey
            ? layout.rooms.find(room => String(room && room.key || '') === String(preferredRoomKey || ''))
            : null;
        const containingRoom = layout.rooms.find(room => isPointInsideImportedPetHomeRoom(room, x, z)) || null;
        if (preferredRoom && containingRoom && preferredRoom.key === containingRoom.key) return preferredRoom;
        if (containingRoom) return containingRoom;
        if (preferredRoom) return preferredRoom;
        let nearestRoom = null;
        layout.rooms.forEach(room => {
            const distance = getDistanceToImportedPetHomeRoom(room, x, z);
            if (!nearestRoom || distance < nearestRoom.distance) {
                nearestRoom = { room, distance };
            }
        });
        return nearestRoom ? nearestRoom.room : null;
    }

    function normalizeImportedPetHomeRoom(rawRoom = {}, index = 0) {
        return {
            ...cloneImportedPetHomeValue(rawRoom),
            key: String(rawRoom && rawRoom.key || `room_${index + 1}`),
            label: String(rawRoom && rawRoom.label || `房间${index + 1}`),
            x: Number(rawRoom && rawRoom.x || 0),
            z: Number(rawRoom && rawRoom.z || 0),
            width: Math.max(1, Number(rawRoom && rawRoom.width || 4)),
            depth: Math.max(1, Number(rawRoom && rawRoom.depth || 4)),
            height: Math.max(0.6, Number(rawRoom && rawRoom.height || 2.8))
        };
    }

    function normalizeImportedPetHomeFurniture(rawItem = {}, index = 0) {
        if (!rawItem || typeof rawItem !== 'object') return null;
        const type = String(rawItem.type || '').trim();
        if (!type) return null;
        const nextItem = cloneImportedPetHomeValue(rawItem) || {};
        nextItem.id = rawItem.id != null ? rawItem.id : `pet-home-furniture-${index + 1}`;
        nextItem.type = type;
        nextItem.x = Number(rawItem.x || 0);
        nextItem.z = Number(rawItem.z || 0);
        nextItem.rotationY = Number(rawItem.rotationY || 0);
        nextItem.scale = Math.max(0.1, Number(rawItem.scale || 1));
        nextItem.manualPlacement = !!rawItem.manualPlacement;
        nextItem.manualY = Number(rawItem.manualY || 0);
        nextItem.rotationX = Number(rawItem.rotationX || 0);
        nextItem.rotationZ = Number(rawItem.rotationZ || 0);
        nextItem.room = rawItem.room ? String(rawItem.room) : '';
        return nextItem;
    }

    function normalizeImportedPetHomeLayout(rawLayout, rawText = '') {
        const sourceLayout = rawLayout && typeof rawLayout === 'object' && rawLayout.layout && Array.isArray(rawLayout.layout.rooms)
            ? rawLayout.layout
            : rawLayout;
        if (!sourceLayout || typeof sourceLayout !== 'object') {
            throw new Error('房屋 JSON 无法解析');
        }

        const rooms = Array.isArray(sourceLayout.rooms)
            ? sourceLayout.rooms.map((room, index) => normalizeImportedPetHomeRoom(room, index))
            : [];
        if (!rooms.length) {
            throw new Error('房屋 JSON 里没有 rooms');
        }

        const layout = {
            signature: `pet-home-${hashImportedPetHomeText(rawText || JSON.stringify(sourceLayout))}`,
            rooms,
            furniture: Array.isArray(sourceLayout.furniture)
                ? sourceLayout.furniture.map((item, index) => normalizeImportedPetHomeFurniture(item, index)).filter(Boolean)
                : [],
            posePresets: Array.isArray(sourceLayout.posePresets) ? cloneImportedPetHomeValue(sourceLayout.posePresets) : [],
            scenePresets: Array.isArray(sourceLayout.scenePresets) ? cloneImportedPetHomeValue(sourceLayout.scenePresets) : []
        };

        layout.furniture.forEach(item => {
            const room = resolveImportedPetHomeRoom(layout, Number(item.x || 0), Number(item.z || 0), item.room || '');
            if (room && room.key) {
                item.room = room.key;
            }
        });

        return layout;
    }

    function loadImportedPetHomeScript(src, testFn) {
        if (typeof testFn === 'function' && testFn()) {
            return Promise.resolve();
        }
        const absoluteSrc = new URL(src, window.location.href).href;
        const existingScript = Array.from(document.scripts || []).find(script => script.src === absoluteSrc);
        if (existingScript) {
            return new Promise((resolve, reject) => {
                const checkReady = () => {
                    if (typeof testFn !== 'function' || testFn()) {
                        resolve();
                        return true;
                    }
                    return false;
                };
                if (checkReady()) return;
                existingScript.addEventListener('load', () => checkReady() && resolve(), { once: true });
                existingScript.addEventListener('error', () => reject(new Error(`脚本加载失败：${src}`)), { once: true });
            });
        }
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = absoluteSrc;
            script.async = true;
            script.onload = () => {
                if (typeof testFn === 'function' && !testFn()) {
                    reject(new Error(`脚本已加载但能力缺失：${src}`));
                    return;
                }
                resolve();
            };
            script.onerror = () => reject(new Error(`脚本加载失败：${src}`));
            document.head.appendChild(script);
        });
    }

    async function loadImportedPetHomeModule(src) {
        return import(/* webpackIgnore: true */ src);
    }

    async function ensureImportedPetHomeThreeRuntime() {
        if (window.THREE) {
            return;
        }

        const moduleSources = [
            'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js',
            'https://unpkg.com/three@0.160.0/build/three.module.js'
        ];

        let lastError = null;
        for (const source of moduleSources) {
            try {
                const importedThree = await loadImportedPetHomeModule(source);
                if (importedThree) {
                    window.THREE = importedThree;
                    return;
                }
            } catch (error) {
                lastError = error;
            }
        }

        const legacySources = [
            'https://cdn.jsdelivr.net/npm/three@0.159.0/build/three.min.js',
            'https://unpkg.com/three@0.159.0/build/three.min.js'
        ];

        for (const source of legacySources) {
            try {
                await loadImportedPetHomeScript(source, () => !!window.THREE);
                if (window.THREE) {
                    return;
                }
            } catch (error) {
                lastError = error;
            }
        }

        throw lastError || new Error('Imported pet home 3D runtime failed to load.');
    }

    function ensureImportedPetHomeLibraries() {
        const threeReady = () => !!window.THREE;
        const modelsReady = () => !!(window.Home3DModels && typeof window.Home3DModels.buildFloorPlan === 'function');
        const furnitureReady = () => !!(window.Home3DModels && typeof window.Home3DModels.createFurniture === 'function');

        if (threeReady() && modelsReady() && furnitureReady()) {
            return Promise.resolve(window.Home3DModels);
        }
        if (petImportedHomeLibrariesPromise) {
            return petImportedHomeLibrariesPromise;
        }

        petImportedHomeLibrariesPromise = (async () => {
            await ensureImportedPetHomeThreeRuntime();
            await loadImportedPetHomeScript('home3d_models.js?v=20260501a', modelsReady);
            await loadImportedPetHomeScript('home3d_furniture.js?v=20260501a', furnitureReady);
            return window.Home3DModels;
        })().catch(error => {
            petImportedHomeLibrariesPromise = null;
            throw error;
        });

        return petImportedHomeLibrariesPromise;
    }

    function getPetStableRoll(seedText) {
        const input = String(seedText || '');
        let hash = 2166136261;
        for (let i = 0; i < input.length; i++) {
            hash ^= input.charCodeAt(i);
            hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
        }
        return (Math.abs(hash) % 1000) / 1000;
    }

    function getPetStableChoice(seedText, choices, fallbackValue = null) {
        if (!Array.isArray(choices) || choices.length === 0) return fallbackValue;
        const index = Math.min(choices.length - 1, Math.floor(getPetStableRoll(seedText) * choices.length));
        return choices[index];
    }

    function buildAutoPetName(species, index = 0) {
        const normalizedSpecies = String(species || '').trim().toLowerCase();
        const namePools = {
            cat: ['年糕', '团团', '小橘', '奶油', '豆包', '咪呜'],
            dog: ['可乐', '年年', '多多', '布丁', '球球', '阿福'],
            rabbit: ['糯米', '雪团', '团子', '跳跳'],
            bird: ['啾啾', '云朵', '小羽', '铃铛'],
            hamster: ['瓜子', '栗子', '软糖', '棉球'],
            other: ['小家伙', '团子', '豆豆', '软软']
        };
        const pool = namePools[normalizedSpecies] || namePools.other;
        return pool[index % pool.length];
    }

    function normalizePetSpeciesInput(speciesText) {
        const rawText = String(speciesText || '').trim().toLowerCase();
        if (!rawText) return 'cat';
        if (/dog|犬|狗/.test(rawText)) return 'dog';
        if (/cat|猫/.test(rawText)) return 'cat';
        if (/rabbit|兔/.test(rawText)) return 'rabbit';
        if (/bird|鹦鹉|文鸟|鸟/.test(rawText)) return 'bird';
        if (/hamster|仓鼠|金丝熊/.test(rawText)) return 'hamster';
        return 'other';
    }

    function normalizePetSex(rawSex) {
        const sexText = String(rawSex || '').trim().toLowerCase();
        if (!sexText) return 'unknown';
        if (/公|弟|boy|male|雄/.test(sexText)) return 'male';
        if (/母|妹|girl|female|雌/.test(sexText)) return 'female';
        return 'unknown';
    }

    function getPetSexLabel(sex) {
        if (sex === 'male') return '公';
        if (sex === 'female') return '母';
        return '未知';
    }

    function normalizePetAgeText(rawAge, fallbackAge = '1岁') {
        const ageText = String(rawAge || '').trim();
        if (!ageText) return fallbackAge;
        if (/^\d+$/.test(ageText)) return `${ageText}岁`;
        return ageText;
    }

    function normalizePetHabitList(rawHabits) {
        if (Array.isArray(rawHabits)) {
            return rawHabits.map(item => String(item || '').trim()).filter(Boolean).slice(0, 4);
        }
        return String(rawHabits || '')
            .replace(/[、，；|]/g, ',')
            .split(',')
            .map(item => item.trim())
            .filter(Boolean)
            .slice(0, 4);
    }

    function getPetContextHistory(contact, limit = 24) {
        if (!contact) return [];
        const sourceHistory = contact.isOfflineMode
            ? (contact.offlineStorylines.find(story => story.id === contact.activeOfflineStoryId)?.chatHistory || [])
            : (contact.onlineChatHistory || []);
        return sourceHistory
            .filter(msg => msg && typeof msg.content === 'string' && (msg.role === 'user' || msg.role === 'assistant'))
            .slice(-limit)
            .map(msg => `${msg.role === 'user' ? 'user' : 'char'}:${msg.content}`);
    }

    function buildPetReferenceText(contact, extraText = '') {
        const worldBookText = formatWorldBookForPrompt(contact, { contextText: extraText, emptyText: '' });
        return [
            contact && contact.persona ? contact.persona : '',
            contact && contact.remark ? contact.remark : '',
            worldBookText,
            getPetContextHistory(contact).join('\n'),
            String(extraText || '').trim()
        ].filter(Boolean).join('\n');
    }

    function getPetToneFromContext(contact, referenceText = '') {
        const mergedText = `${contact && contact.persona ? contact.persona : ''}\n${referenceText}`;
        if (/安静|慢热|克制|冷静|理性|沉稳|寡言/.test(mergedText)) return 'calm';
        if (/活泼|热情|外向|元气|闹腾|爱玩|直球/.test(mergedText)) return 'bright';
        return 'balanced';
    }

    function inferPetBreedFromContext(contact, species, referenceText = '') {
        const options = PET_BREED_OPTIONS[species] || PET_BREED_OPTIONS.other;
        if (!Array.isArray(options) || options.length === 0) return '';
        const matchedBreed = options.find(option => referenceText.includes(option));
        if (matchedBreed) return matchedBreed;
        return getPetStableChoice(`${contact && contact.id ? contact.id : 'pet'}-${species}-breed-${referenceText}`, options, options[0]);
    }

    function inferPetSexFromContext(species, seedBase, referenceText = '') {
        if (/公猫|公狗|公兔|公鸟|公仓鼠|男孩/.test(referenceText)) return 'male';
        if (/母猫|母狗|母兔|母鸟|母仓鼠|女孩/.test(referenceText)) return 'female';
        return getPetStableRoll(`${seedBase}-sex-${species}`) < 0.5 ? 'female' : 'male';
    }

    function inferPetAgeFromContext(species, seedBase, referenceText = '') {
        if (/奶猫|幼猫|幼犬|幼兔|幼鸟|幼崽|宝宝|幼宠/.test(referenceText)) {
            return getPetStableChoice(`${seedBase}-baby-age`, ['3个月', '4个月', '5个月'], '4个月');
        }
        const options = PET_AGE_OPTIONS[species] || PET_AGE_OPTIONS.other;
        return getPetStableChoice(`${seedBase}-age-${species}`, options, options[0]);
    }

    function inferPetPersonalityFromContext(contact, species, seedBase, referenceText = '') {
        const tone = getPetToneFromContext(contact, referenceText);
        const options = (PET_PERSONALITY_OPTIONS[species] && PET_PERSONALITY_OPTIONS[species][tone])
            || PET_PERSONALITY_OPTIONS.other.balanced;
        return getPetStableChoice(`${seedBase}-personality-${tone}`, options, options[0]);
    }

    function inferPetHabitsFromContext(contact, species, seedBase, referenceText = '') {
        const options = PET_HABIT_OPTIONS[species] || PET_HABIT_OPTIONS.other;
        const picked = getPetStableChoice(`${seedBase}-habits-${referenceText}`, options, options[0]);
        return Array.isArray(picked) ? picked.slice(0, 3) : normalizePetHabitList(picked);
    }

    function buildPetArchiveSummary(pet) {
        const speciesLabel = getPetSpeciesMeta(pet.species).label;
        const habitsText = normalizePetHabitList(pet.habits).join('、') || '习惯还在慢慢摸索';
        return `${pet.name}，${speciesLabel}${pet.breed ? ` / ${pet.breed}` : ''}，${getPetSexLabel(pet.sex)}，${pet.age || '年龄未知'}。性格：${pet.personality || '温和稳定'}。习惯：${habitsText}。`;
    }

    function createDefaultPetMonitorCache() {
        return {
            generatedAt: 0,
            reason: '',
            charState: null,
            roomsByKey: {},
            raw: ''
        };
    }

    function createDefaultPetSystem() {
        return {
            pets: [],
            eventLog: [],
            selectedPetId: null,
            selectedRoom: 'living_room',
            monitorCache: createDefaultPetMonitorCache(),
            isMonitorRefreshing: false,
            lastMonitorError: '',
            pendingAdoptionPrompt: null,
            adoptionIntent: {
                level: 0,
                source: '',
                note: '',
                updatedAt: 0,
                lastRejectedAt: 0,
                cooldownUntil: 0,
                rejectionNote: '',
                rejectionFirmness: ''
            },
            importedHomeLayout: null,
            importedHomeSelectedCamera: PET_IMPORTED_HOME_OVERVIEW_KEY,
            importedHomeWallMode: 'half',
            lastPetEventDate: '',
            lastRandomAcquisitionAt: 0,
            lastFollowUpEventAt: 0,
            lastAutoCareAt: 0,
            lastSupplyIncidentAt: 0
        };
    }

    function createPetEventEntry(kind, title, description, extra = {}) {
        return {
            id: `pet-event-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            kind: kind || 'daily',
            title: title || '宠物动态',
            description: description || '',
            timestamp: Date.now(),
            ...extra
        };
    }

    function normalizePetObject(rawPet = {}, contact = null) {
        const referenceText = buildPetReferenceText(contact, [
            rawPet.seedNote,
            rawPet.source,
            rawPet.note,
            rawPet.notes,
            rawPet.breed,
            rawPet.personality,
            rawPet.name,
            Array.isArray(rawPet.habits) ? rawPet.habits.join(',') : rawPet.habits
        ].filter(Boolean).join('\n'));
        const manualFieldMap = rawPet.manualFieldMap && typeof rawPet.manualFieldMap === 'object'
            ? { ...rawPet.manualFieldMap }
            : {};
        const species = rawPet.species
            ? normalizePetSpeciesInput(rawPet.species)
            : inferPetSpeciesFromText(referenceText, 'other');
        const meta = getPetSpeciesMeta(species);
        const sex = rawPet.sex || rawPet.gender
            ? normalizePetSex(rawPet.sex || rawPet.gender)
            : 'unknown';
        const age = rawPet.age || rawPet.ageText
            ? normalizePetAgeText(rawPet.age || rawPet.ageText, '')
            : '';
        const habits = normalizePetHabitList(rawPet.habits);
        return {
            id: rawPet.id || `pet-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            name: String(rawPet.name || buildAutoPetName(species)).trim() || buildAutoPetName(species),
            species,
            breed: String(rawPet.breed || '').trim(),
            sex,
            age,
            personality: String(rawPet.personality || '').trim(),
            habits,
            source: String(rawPet.source || '').trim(),
            acquiredAt: rawPet.acquiredAt || Date.now(),
            satiety: clampPetNumber(rawPet.satiety ?? rawPet.fullness ?? 72, 0, 100),
            hydration: clampPetNumber(rawPet.hydration ?? rawPet.thirst ?? 78, 0, 100),
            fun: clampPetNumber(rawPet.fun ?? rawPet.entertainment ?? 66, 0, 100),
            health: clampPetNumber(rawPet.health ?? 88, 0, 100),
            foodBowl: clampPetNumber(rawPet.foodBowl ?? 62, 0, 100),
            waterBowl: clampPetNumber(rawPet.waterBowl ?? 68, 0, 100),
            homeRoom: rawPet.homeRoom || meta.defaultRoom,
            notes: String(rawPet.notes || rawPet.note || '').trim(),
            isManual: !!rawPet.isManual,
            manualFieldMap,
            seedNote: String(rawPet.seedNote || '').trim(),
            aiProfileGeneratedAt: Number(rawPet.aiProfileGeneratedAt) || 0,
            lastUpdatedAt: Number(rawPet.lastUpdatedAt) || Date.now()
        };
    }

    function ensurePetSystem(contact) {
        if (!contact || typeof contact !== 'object') return createDefaultPetSystem();
        if (!contact.petSystem || typeof contact.petSystem !== 'object') {
            contact.petSystem = createDefaultPetSystem();
        }

        const petSystem = contact.petSystem;
        if (!Array.isArray(petSystem.pets)) petSystem.pets = [];
        if (!Array.isArray(petSystem.eventLog)) petSystem.eventLog = [];
        if (petSystem.pendingAdoptionPrompt && typeof petSystem.pendingAdoptionPrompt !== 'object') {
            petSystem.pendingAdoptionPrompt = null;
        }
        if (!petSystem.adoptionIntent || typeof petSystem.adoptionIntent !== 'object') {
            petSystem.adoptionIntent = { level: 0, source: '', note: '', updatedAt: 0, lastRejectedAt: 0, cooldownUntil: 0, rejectionNote: '', rejectionFirmness: '' };
        } else {
            petSystem.adoptionIntent.level = clampPetNumber(petSystem.adoptionIntent.level || 0, 0, 100);
            petSystem.adoptionIntent.source = String(petSystem.adoptionIntent.source || '').trim();
            petSystem.adoptionIntent.note = String(petSystem.adoptionIntent.note || '').trim();
            petSystem.adoptionIntent.updatedAt = Number(petSystem.adoptionIntent.updatedAt || 0);
            petSystem.adoptionIntent.lastRejectedAt = Number(petSystem.adoptionIntent.lastRejectedAt || 0);
            petSystem.adoptionIntent.cooldownUntil = Number(petSystem.adoptionIntent.cooldownUntil || 0);
            petSystem.adoptionIntent.rejectionNote = String(petSystem.adoptionIntent.rejectionNote || '').trim();
            petSystem.adoptionIntent.rejectionFirmness = String(petSystem.adoptionIntent.rejectionFirmness || '').trim();
        }
        if (!petSystem.monitorCache || typeof petSystem.monitorCache !== 'object') {
            petSystem.monitorCache = createDefaultPetMonitorCache();
        }
        if (!petSystem.monitorCache.roomsByKey || typeof petSystem.monitorCache.roomsByKey !== 'object') {
            petSystem.monitorCache.roomsByKey = {};
        }
        petSystem.monitorCache.generatedAt = Number(petSystem.monitorCache.generatedAt) || 0;
        petSystem.monitorCache.reason = String(petSystem.monitorCache.reason || '').trim();
        petSystem.monitorCache.raw = String(petSystem.monitorCache.raw || '');
        if (petSystem.monitorCache.charState && typeof petSystem.monitorCache.charState !== 'object') {
            petSystem.monitorCache.charState = null;
        }
        if (typeof petSystem.isMonitorRefreshing !== 'boolean') petSystem.isMonitorRefreshing = false;
        if (typeof petSystem.lastMonitorError !== 'string') petSystem.lastMonitorError = '';
        if (petSystem.importedHomeLayout && typeof petSystem.importedHomeLayout !== 'object') {
            petSystem.importedHomeLayout = null;
        }
        if (typeof petSystem.importedHomeSelectedCamera !== 'string' || !petSystem.importedHomeSelectedCamera.trim()) {
            petSystem.importedHomeSelectedCamera = PET_IMPORTED_HOME_OVERVIEW_KEY;
        }
        if (petSystem.importedHomeWallMode !== 'full' && petSystem.importedHomeWallMode !== 'half') {
            petSystem.importedHomeWallMode = 'half';
        }

        petSystem.selectedRoom = PET_ROOM_CONFIGS.some(room => room.key === petSystem.selectedRoom)
            ? petSystem.selectedRoom
            : 'living_room';
        petSystem.pets = petSystem.pets.map(pet => normalizePetObject(pet, contact));
        petSystem.eventLog = petSystem.eventLog
            .filter(entry => entry && typeof entry === 'object')
            .sort((a, b) => Number(b.timestamp || 0) - Number(a.timestamp || 0))
            .slice(0, 60);

        if (!petSystem.selectedPetId || !petSystem.pets.some(pet => pet.id === petSystem.selectedPetId)) {
            petSystem.selectedPetId = petSystem.pets[0] ? petSystem.pets[0].id : null;
        }

        return petSystem;
    }

    function pushPetEvent(contact, entry) {
        const petSystem = ensurePetSystem(contact);
        const normalizedEntry = entry && typeof entry === 'object'
            ? createPetEventEntry(entry.kind, entry.title, entry.description, entry)
            : createPetEventEntry('daily', '宠物动态', '');
        petSystem.eventLog.unshift(normalizedEntry);
        if (petSystem.eventLog.length > 60) petSystem.eventLog.length = 60;
        petSystem.lastPetEventDate = new Date(normalizedEntry.timestamp).toLocaleDateString();
        return normalizedEntry;
    }

    function inferPetSpeciesFromText(text, fallbackSpecies = 'cat') {
        const sourceText = String(text || '');
        if (/小狗|狗狗|养狗|狗\b/.test(sourceText)) return 'dog';
        if (/小猫|猫猫|养猫|猫\b/.test(sourceText)) return 'cat';
        if (/兔/.test(sourceText)) return 'rabbit';
        if (/仓鼠/.test(sourceText)) return 'hamster';
        if (/鹦鹉|小鸟|鸟\b/.test(sourceText)) return 'bird';
        return fallbackSpecies;
    }

    function detectPetSuggestionSignals(text) {
        const sourceText = String(text || '').trim();
        if (!sourceText) {
            return { score: 0, wantsPet: false, wantsAnother: false, species: '', mentionsCare: false, notes: '' };
        }

        if (/不养|别养|先别|不要养宠物/.test(sourceText)) {
            return { score: 0, wantsPet: false, wantsAnother: false, species: '', mentionsCare: false, notes: sourceText };
        }

        let score = 0;
        const wantsPet = /宠物|养猫|养狗|养只|领养|抱养|宠物店|捡到.*宠物|捡猫|捡狗|养一只|养个|领一只|抱一只/.test(sourceText);
        const wantsAnother = /再养|第二只|多养一只|再来一只|还想养|再养一只|再添一只/.test(sourceText);
        const mentionsCare = /喂|添粮|加粮|换水|喂食|喂水|猫砂|遛狗/.test(sourceText);

        if (wantsPet) score += 28;
        if (/建议|要不要|不如|可以|应该/.test(sourceText) && /养|宠物/.test(sourceText)) score += 14;
        if (/求你|想看|好想|真的想/.test(sourceText) && /宠物|猫|狗|兔|鸟|仓鼠/.test(sourceText)) score += 16;
        if (wantsAnother) score += 24;
        if (mentionsCare) score += 8;

        return {
            score,
            wantsPet,
            wantsAnother,
            species: inferPetSpeciesFromText(sourceText),
            mentionsCare,
            notes: sourceText
        };
    }

    function appendRecentRowsForPetDiscussion(target, source, count) {
        if (!Array.isArray(target) || !Array.isArray(source) || source.length === 0) return;
        const safeCount = Math.max(1, Math.floor(Number(count) || 8));
        const startIndex = Math.max(0, source.length - safeCount);
        for (let i = startIndex; i < source.length; i++) {
            target.push(source[i]);
        }
    }

    function getRecentPetDiscussionText(contact, limit = 8) {
        const rows = [];
        const maxCount = Math.max(1, Math.floor(Number(limit) || 8));
        const scanCount = Math.max(maxCount * 4, 16);
        appendRecentRowsForPetDiscussion(rows, contact?.onlineChatHistory, scanCount);
        appendRecentRowsForPetDiscussion(rows, contact?.unsentMessages, scanCount);
        if (contact?.isOfflineMode) {
            const story = (contact.offlineStorylines || []).find(item => item.id === contact.activeOfflineStoryId);
            appendRecentRowsForPetDiscussion(rows, story?.chatHistory, scanCount);
        }
        return rows
            .filter(message => message && (message.role === 'assistant' || message.role === 'user'))
            .sort((a, b) => Number(a.timestamp || a.createdAt || 0) - Number(b.timestamp || b.createdAt || 0))
            .slice(-maxCount)
            .map(message => {
                const content = typeof flattenPromptMessageContent === 'function'
                    ? flattenPromptMessageContent(message.content || '')
                    : String(message.content || '');
                return `${message.role || ''}: ${content}`;
            })
            .join('\n');
    }

    function detectPetAdoptionRejection(text, contact = null) {
        const sourceText = String(text || '').trim();
        if (!sourceText) return { rejected: false, firmness: '', cooldownHours: 0, note: '' };

        const recentPetText = getRecentPetDiscussionText(contact, 8);
        const petContextText = `${sourceText}\n${recentPetText}`;
        const hasPetContext = /宠物|养宠|养猫|养狗|领养|收养|抱养|买猫|买狗|猫|狗|兔|仓鼠|鸟|德牧|边牧|金毛|拉布拉多|萨摩耶|捷克狼|遛狗|铲屎/.test(petContextText);
        if (!hasPetContext) return { rejected: false, firmness: '', cooldownHours: 0, note: '' };

        const hardReject = /不养|别养|不要养|不想养|不能养|养不了|不可能养|绝对不|坚决不|别提|别再提|不要再提|打住|免谈|拒绝|做梦|没门|不喜欢(?:猫|狗|宠物)|对(?:猫|狗|宠物).*过敏/.test(sourceText);
        const softReject = /再说吧|以后再说|晚点再说|下次再说|看看再说|看情况|先别|先等等|先缓缓|暂时不|现在不|目前不|没条件|没时间|没精力|没钱|房东不让|家里不让|太麻烦|太累|负担|责任太大|照顾不过来|住处不合适|空间不够/.test(sourceText);
        const contextualHardReject = /^(不|不要|不行|不可以|别|算了|别想了|别做梦|停|打住)[。！!？?\s]*$/.test(sourceText)
            || /^(我拒绝|拒绝|不可能|没门|做梦)$/.test(sourceText);
        const contextualSoftReject = /^(再说吧|以后再说|先等等|先缓缓|看情况|晚点说|暂时算了)[。！!？?\s]*$/.test(sourceText);

        if (hardReject || contextualHardReject) {
            return { rejected: true, firmness: 'hard', cooldownHours: 24 * 7, note: sourceText };
        }
        if (softReject || contextualSoftReject) {
            return { rejected: true, firmness: 'soft', cooldownHours: 24 * 3, note: sourceText };
        }
        return { rejected: false, firmness: '', cooldownHours: 0, note: '' };
    }

    function isPetAdoptionIntentCoolingDown(petSystem, nowMs = Date.now()) {
        const intent = petSystem?.adoptionIntent;
        return Number(intent?.cooldownUntil || 0) > nowMs;
    }

    function applyPetAdoptionRejection(contact, rejection, options = {}) {
        const petSystem = ensurePetSystem(contact);
        const intent = petSystem.adoptionIntent;
        const nowMs = Date.now();
        const previousLevel = clampPetNumber(intent.level || 0, 0, 100);
        const firmness = rejection?.firmness === 'hard' ? 'hard' : 'soft';
        const nextLevel = firmness === 'hard'
            ? Math.min(Math.max(previousLevel - 55, 0), 18)
            : Math.min(Math.max(previousLevel - 28, 0), 45);
        intent.level = clampPetNumber(nextLevel, 0, 100);
        intent.source = options.source || (firmness === 'hard' ? 'user_rejected_pet' : 'user_delayed_pet');
        intent.note = String(rejection?.note || options.note || '').trim();
        intent.updatedAt = nowMs;
        intent.lastRejectedAt = nowMs;
        intent.cooldownUntil = nowMs + Math.max(6, Number(rejection?.cooldownHours || options.cooldownHours || (firmness === 'hard' ? 168 : 72))) * 60 * 60 * 1000;
        intent.rejectionNote = intent.note;
        intent.rejectionFirmness = firmness;
        petSystem.pendingAdoptionPrompt = null;
        return {
            rejected: true,
            previousLevel,
            nextLevel: intent.level,
            firmness
        };
    }

    function shouldRunPetAdoptionSemanticCheck(contact, text, preliminarySignal = {}) {
        const sourceText = String(text || '').trim();
        if (!sourceText) return false;
        if (preliminarySignal.appliedRejection && preliminarySignal.firmness) return false;
        if (preliminarySignal.rejected || preliminarySignal.wantsPet || preliminarySignal.wantsAnother) return true;
        const petSystem = ensurePetSystem(contact);
        const recentText = getRecentPetDiscussionText(contact, 8);
        const hasRecentPetContext = Boolean(petSystem.pendingAdoptionPrompt)
            || clampPetNumber(petSystem.adoptionIntent.level || 0, 0, 100) >= 20
            || /宠物|养宠|养猫|养狗|领养|收养|抱养|猫|狗|兔|仓鼠|鸟|德牧|边牧|金毛|拉布拉多|萨摩耶|捷克狼/.test(recentText);
        if (!hasRecentPetContext) return false;
        if (sourceText.length <= 18) return /不|别|算了|再说|以后|等等|缓缓|行|可以|好|同意|愿意|不要|不行|没门|做梦/.test(sourceText);
        return /没条件|没时间|没精力|没钱|顾不过来|负担|责任|麻烦|空间|房东|过敏|养明白|上强度|别闹|别提|认真|决定|同意|愿意|可以养|那就养|先别|暂时|以后/.test(sourceText);
    }

    async function refinePetAdoptionIntentWithSemanticCheck(contact, text, preliminarySignal = {}) {
        if (!shouldRunPetAdoptionSemanticCheck(contact, text, preliminarySignal)) return preliminarySignal;
        const petSystem = ensurePetSystem(contact);
        const recentText = getRecentPetDiscussionText(contact, 10).slice(-3000);
        const pending = petSystem.pendingAdoptionPrompt;
        const prompt = `
# 任务：判断用户对“角色养宠/领养宠物”这条线的真实态度
你是聊天应用里的状态判定器。请结合最近对话，不要只看关键词。

## 最近对话
${recentText || '（无）'}

## 当前待确认的养宠提议
${pending ? JSON.stringify(pending, null, 2) : '（无）'}

## 用户最新消息
${String(text || '').trim()}

## 判定目标
判断用户最新消息对“角色继续推进养宠/领养宠物”这件事的态度：
- reject_hard：明确拒绝、不想养、不许再提、强烈否定、讽刺性拒绝。
- delay_soft：暂缓/以后再说/现实条件不允许/精力钱空间责任不足，但不是永久拒绝。
- accept_commit：认真同意推进，不是玩笑，不只是随口聊宠物。
- interested_discuss：还在讨论、权衡、幻想、询问，不代表同意立刻推进。
- neutral：与养宠态度无关，或无法判断。

只输出 JSON：
{
  "stance": "reject_hard|delay_soft|accept_commit|interested_discuss|neutral",
  "confidence": 0到1,
  "reason": "一句话说明",
  "cooldownHours": 数字
}
`;
        try {
            const { parsed } = await callMainApiPrompt(prompt, { temperature: 0.1 });
            const result = parsed && typeof parsed === 'object' ? parsed : {};
            const stance = String(result.stance || '').trim();
            const confidence = Number(result.confidence);
            if (!Number.isFinite(confidence) || confidence < 0.58) return preliminarySignal;

            if (stance === 'reject_hard' || stance === 'delay_soft') {
                const rejection = {
                    rejected: true,
                    firmness: stance === 'reject_hard' ? 'hard' : 'soft',
                    cooldownHours: Math.max(12, Number(result.cooldownHours) || (stance === 'reject_hard' ? 24 * 7 : 24 * 3)),
                    note: `${String(text || '').trim()}${result.reason ? `｜语义判断：${result.reason}` : ''}`
                };
                const applied = applyPetAdoptionRejection(contact, rejection, {
                    source: stance === 'reject_hard' ? 'semantic_user_rejected_pet' : 'semantic_user_delayed_pet'
                });
                return { ...preliminarySignal, ...rejection, semanticStance: stance, semanticConfidence: confidence, appliedRejection: applied };
            }

            if (stance === 'accept_commit') {
                petSystem.adoptionIntent.level = clampPetNumber(Math.max(Number(petSystem.adoptionIntent.level) || 0, 72), 0, 100);
                petSystem.adoptionIntent.source = 'semantic_user_pet_consent';
                petSystem.adoptionIntent.note = String(text || '').trim();
                petSystem.adoptionIntent.updatedAt = Date.now();
                petSystem.adoptionIntent.cooldownUntil = 0;
                petSystem.adoptionIntent.rejectionNote = '';
                petSystem.adoptionIntent.rejectionFirmness = '';
                return { ...preliminarySignal, wantsPet: true, semanticStance: stance, semanticConfidence: confidence };
            }

            return { ...preliminarySignal, semanticStance: stance, semanticConfidence: confidence };
        } catch (error) {
            console.warn('[宠物意愿] 语义判断失败，回退本地规则:', error && error.message ? error.message : error);
            return preliminarySignal;
        }
    }

    async function runPetAdoptionSemanticCheckForSentBatch(contact, messages = []) {
        const rows = Array.isArray(messages) ? messages : [];
        if (!contact || rows.length === 0) return null;
        const candidates = rows
            .map(message => ({
                message,
                text: typeof flattenPromptMessageContent === 'function'
                    ? flattenPromptMessageContent(message?.content || '')
                    : String(message?.content || '')
            }))
            .filter(item => item.text.trim());
        if (!candidates.length) return null;

        const target = [...candidates].reverse().find(item => {
            const signal = detectPetSuggestionSignals(item.text);
            return shouldRunPetAdoptionSemanticCheck(contact, item.text, signal);
        });
        if (!target) return null;

        const signal = detectPetSuggestionSignals(target.text);
        const refined = await refinePetAdoptionIntentWithSemanticCheck(contact, target.text, signal);
        if (refined && (refined.semanticStance || refined.appliedRejection)) {
            const followUpPrompt = armPetAdoptionPrompt(contact, target.text, refined);
            if (refined.rejected && !followUpPrompt) {
                const petSystem = ensurePetSystem(contact);
                petSystem.pendingAdoptionPrompt = null;
            }
            saveAppData();
        }
        return refined;
    }

    function updatePetAdoptionIntentFromMessage(contact, text) {
        const petSystem = ensurePetSystem(contact);
        const rejection = detectPetAdoptionRejection(text, contact);
        if (rejection.rejected) {
            const applied = applyPetAdoptionRejection(contact, rejection, { source: rejection.firmness === 'hard' ? 'user_rejected_pet' : 'user_delayed_pet' });
            return { ...detectPetSuggestionSignals(text), ...rejection, appliedRejection: applied };
        }

        const signal = detectPetSuggestionSignals(text);
        if (!signal.wantsPet && !signal.wantsAnother && !signal.mentionsCare) return signal;

        const previousLevel = Number(petSystem.adoptionIntent.level) || 0;
        const decayHours = petSystem.adoptionIntent.updatedAt
            ? (Date.now() - petSystem.adoptionIntent.updatedAt) / (1000 * 60 * 60)
            : 0;
        const decayedLevel = Math.max(0, previousLevel - Math.max(0, decayHours - 24) * 2.5);
        const delta = signal.wantsPet ? signal.score : Math.min(signal.score, 10);
        petSystem.adoptionIntent.level = clampPetNumber(decayedLevel + delta, 0, 100);
        petSystem.adoptionIntent.source = signal.wantsAnother ? 'user_push_more_pets' : 'user_chat';
        petSystem.adoptionIntent.note = signal.notes;
        petSystem.adoptionIntent.updatedAt = Date.now();
        petSystem.adoptionIntent.cooldownUntil = 0;
        petSystem.adoptionIntent.rejectionNote = '';
        petSystem.adoptionIntent.rejectionFirmness = '';
        return signal;
    }

    function shouldArmPetAdoptionPrompt(text, signal = detectPetSuggestionSignals(text)) {
        const sourceText = String(text || '').trim();
        if (!sourceText || !signal) return false;
        if (signal.rejected) return false;
        if (/宠物视频|宠物博主|宠物表情包|猫咖|狗咖|别人家的宠物|别人家养|云吸猫|云养宠/.test(sourceText)) return false;

        const hasPetObject = /宠物|猫|狗|兔|仓鼠|鸟|养一只|养个|再养一只|多养一只/.test(sourceText);
        const hasAdoptionVerb = /养|领养|抱养|收养|买|带回家|接回家|再养|添一只|多养一只/.test(sourceText);
        const hasProposalTone = /要不要|愿不愿意|想不想|同不同意|可不可以|能不能|行不行|好不好|要不|不如|建议|拜托|求你|我们|给你/.test(sourceText);
        return hasPetObject && hasAdoptionVerb && (hasProposalTone || signal.wantsAnother);
    }

    function armPetAdoptionPrompt(contact, text, signal = detectPetSuggestionSignals(text)) {
        const petSystem = ensurePetSystem(contact);
        if (!shouldArmPetAdoptionPrompt(text, signal)) {
            petSystem.pendingAdoptionPrompt = null;
            return null;
        }

        petSystem.pendingAdoptionPrompt = {
            sourceText: String(text || '').trim(),
            species: signal.species || inferPetSpeciesFromText(text),
            wantsAnother: !!signal.wantsAnother,
            createdAt: Date.now()
        };
        return petSystem.pendingAdoptionPrompt;
    }

    function consumePetAdoptionPrompt(contact) {
        const petSystem = ensurePetSystem(contact);
        const pendingPrompt = petSystem.pendingAdoptionPrompt && typeof petSystem.pendingAdoptionPrompt === 'object'
            ? { ...petSystem.pendingAdoptionPrompt }
            : null;
        petSystem.pendingAdoptionPrompt = null;
        return pendingPrompt;
    }

    function detectSeriousPetConsentFromReplies(replies, pendingPrompt = null) {
        const textReplies = Array.isArray(replies)
            ? replies
                .filter(msg => typeof msg === 'string')
                .map(msg => msg.replace(/^\[[A-Z_]+:?.*?\]$/g, '').trim())
                .filter(Boolean)
            : [];

        if (textReplies.length === 0) {
            return { approved: false, rejected: false, text: '' };
        }

        const mergedText = textReplies.join('\n');
        if (/不养|先别养|还是别养|算了|太麻烦|没兴趣|不想养|养不了/.test(mergedText)) {
            return { approved: false, rejected: true, text: mergedText };
        }
        if (/再说吧|以后再说|晚点再说|看看再说|看情况|也不是不行|随便|到时候再说|先缓缓|先等等/.test(mergedText)) {
            return { approved: false, rejected: true, text: mergedText };
        }

        const hasPetContext = !!pendingPrompt || /宠物|猫|狗|兔|仓鼠|鸟/.test(mergedText);
        const hasAdoptionAction = /养一只|养个|养吧|领养|抱养|收养|买一只|带回家|接回家|再养|再添一只|多养一只/.test(mergedText);
        const hasPositiveCommitment = /愿意|同意|答应|决定|就养|那就养|好，那就养|行，那就养|可以养/.test(mergedText);
        if (!hasPetContext || (!hasAdoptionAction && !(pendingPrompt && hasPositiveCommitment))) {
            return { approved: false, rejected: false, text: mergedText };
        }

        let score = 0;
        if (hasPositiveCommitment) score += 3;
        if (/认真|想过了|决定了|就这么定了|我们去领养|我们去买|去领养|去买|抱一只|带一只回家/.test(mergedText)) score += 2;
        if (pendingPrompt && pendingPrompt.wantsAnother && /再养|再添|第二只|多养一只/.test(mergedText)) score += 1;
        if (/也不是不行|看看|再说|以后再说|随便|先等等|先缓缓/.test(mergedText)) score -= 4;

        return {
            approved: score >= 3,
            rejected: false,
            text: mergedText
        };
    }

    function getCurrentDailyPlanItem(contact, atDate = new Date()) {
        const plan = getDailyPlanItemsForRuntimeContext(contact, atDate);
        if (!contact || plan.length === 0) return null;
        const currentMinutes = atDate.getHours() * 60 + atDate.getMinutes();

        for (const item of plan) {
            if (!item) continue;
            const start = parsePetClockToMinutes(item.startTime);
            const end = parsePetClockToMinutes(item.endTime);
            if (start < 0 || end < 0) continue;

            if (end >= start) {
                if (currentMinutes >= start && currentMinutes < end) return item;
            } else {
                if (currentMinutes >= start || currentMinutes < end) return item;
            }
        }

        return null;
    }

    function isHomeLocation(locationText) {
        const text = String(locationText || '').trim();
        if (!text) return true;
        if (PET_OUTSIDE_LOCATION_REGEX.test(text)) return false;
        return PET_HOME_LOCATION_REGEX.test(text);
    }

    function resolveHomeRoomFromText(text, fallbackRoom = '') {
        const sourceText = String(text || '').trim();
        if (!sourceText) return fallbackRoom || '';

        if (/厕所|卫生间|洗手间|浴室|洗澡|泡澡|刷牙|洗漱/.test(sourceText)) return 'bathroom';
        if (/厨房|餐桌|吃饭|做饭|热饭|煮饭|接水|烧水|冰箱/.test(sourceText)) return 'kitchen';
        if (/卧室|床|睡|午睡|补觉|赖床|衣柜|书桌/.test(sourceText)) return 'bedroom';
        if (/阳台|晾衣|晒|窗边|通风/.test(sourceText)) return 'balcony';
        if (/玄关|门口|鞋|出门|拿快递|收快递/.test(sourceText)) return 'entryway';
        if (/客厅|沙发|追剧|看电视|打游戏|收拾房间|聊天|发呆/.test(sourceText)) return 'living_room';

        return fallbackRoom || 'living_room';
    }

    function resolveHomeRoomFromScheduleItem(item) {
        if (!item) return 'living_room';
        const locationRoom = resolveHomeRoomFromText(item.location, '');
        if (locationRoom) return locationRoom;
        return resolveHomeRoomFromText(item.activity, 'living_room');
    }

    function getCurrentHomePresence(contact, atDate = new Date()) {
        const currentItem = getCurrentDailyPlanItem(contact, atDate);

        if (currentItem) {
            const atHome = isHomeLocation(currentItem.location) || (!currentItem.location && !PET_OUTSIDE_LOCATION_REGEX.test(currentItem.activity || ''));
            return {
                currentItem,
                atHome,
                roomKey: atHome ? resolveHomeRoomFromScheduleItem(currentItem) : null,
                plannedRoomKey: atHome ? resolveHomeRoomFromScheduleItem(currentItem) : null,
                activityText: String(currentItem.activity || '').trim() || '处理手头的事',
                plannedActivityText: String(currentItem.activity || '').trim() || '处理手头的事',
                locationText: String(currentItem.location || '').trim() || (atHome ? '在家' : '位置未知'),
                plannedTime: `${currentItem.startTime || '--:--'}-${currentItem.endTime || '--:--'}`
            };
        }

        const fallbackActivity = contact && contact.isScheduleEnabled ? calculateCurrentActivity(contact) : { status: '在家里待着', isAwake: true };
        const asleep = fallbackActivity && fallbackActivity.isAwake === false;
        return {
            currentItem: null,
            atHome: true,
            roomKey: asleep ? 'bedroom' : 'living_room',
            plannedRoomKey: asleep ? 'bedroom' : 'living_room',
            activityText: asleep ? '睡觉' : String((fallbackActivity && fallbackActivity.status) || '在家里待着').replace(/^正在/, ''),
            plannedActivityText: asleep ? '睡觉' : String((fallbackActivity && fallbackActivity.status) || '在家里待着').replace(/^正在/, ''),
            locationText: '在家',
            plannedTime: '当前空档'
        };
    }

    function applyHomeMicroMovement(contact, presence, atDate = new Date()) {
        if (!presence || !presence.atHome) return presence;
        if (/睡|补觉|午睡/.test(presence.activityText || '')) return presence;

        const timeBucket = Math.floor(atDate.getTime() / (10 * 60 * 1000));
        const seedBase = `${contact && contact.id ? contact.id : 'pet'}-${presence.plannedTime}-${presence.plannedActivityText}-${timeBucket}`;
        const roll = getPetStableRoll(seedBase);
        if (roll < 0.72) return presence;

        let shift = null;
        if (roll < 0.82) {
            shift = { roomKey: 'bathroom', activityText: '临时去上厕所', note: '原本的安排没变，只是这会儿短暂去了卫生间。' };
        } else if (roll < 0.9) {
            shift = { roomKey: 'kitchen', activityText: '临时去厨房接了杯水', note: '原本的安排没变，只是顺手去厨房接了杯水。' };
        } else if (roll < 0.96) {
            shift = {
                roomKey: atDate.getHours() >= 20 ? 'bathroom' : 'balcony',
                activityText: atDate.getHours() >= 20 ? '临时去洗澡收尾' : '去阳台透透气',
                note: atDate.getHours() >= 20 ? '原本的安排没变，只是这会儿先去冲了个澡。' : '原本的安排没变，只是这会儿去了阳台透气。'
            };
        } else {
            shift = { roomKey: 'entryway', activityText: '去门口拿了点东西', note: '原本的安排没变，只是这会儿人短暂在玄关。' };
        }

        return {
            ...presence,
            roomKey: shift.roomKey,
            activityText: shift.activityText,
            microShiftNote: shift.note
        };
    }

    function updatePetSystemState(contact, options = {}) {
        const petSystem = ensurePetSystem(contact);
        const nowTimestamp = options.nowTimestamp || Date.now();
        let hasChanges = false;

        petSystem.pets.forEach(pet => {
            const elapsedHours = Math.max(0, (nowTimestamp - (Number(pet.lastUpdatedAt) || nowTimestamp)) / (1000 * 60 * 60));
            if (!(elapsedHours > 0)) return;

            const satietyLoss = elapsedHours * (pet.species === 'dog' ? 4.6 : 3.8);
            const hydrationLoss = elapsedHours * (pet.species === 'dog' ? 5.4 : 4.7);
            const funLoss = elapsedHours * 2.4;
            const bowlFoodLoss = elapsedHours * (pet.species === 'dog' ? 2.8 : 2.1);
            const bowlWaterLoss = elapsedHours * 2.7;

            pet.satiety = clampPetNumber(pet.satiety - satietyLoss, 0, 100);
            pet.hydration = clampPetNumber(pet.hydration - hydrationLoss, 0, 100);
            pet.fun = clampPetNumber(pet.fun - funLoss, 0, 100);
            pet.foodBowl = clampPetNumber(pet.foodBowl - bowlFoodLoss, 0, 100);
            pet.waterBowl = clampPetNumber(pet.waterBowl - bowlWaterLoss, 0, 100);

            while (pet.foodBowl > 8 && pet.satiety < 58) {
                pet.foodBowl = clampPetNumber(pet.foodBowl - 8, 0, 100);
                pet.satiety = clampPetNumber(pet.satiety + 14, 0, 100);
            }
            while (pet.waterBowl > 8 && pet.hydration < 64) {
                pet.waterBowl = clampPetNumber(pet.waterBowl - 9, 0, 100);
                pet.hydration = clampPetNumber(pet.hydration + 16, 0, 100);
            }

            if (pet.satiety < 28) pet.health = clampPetNumber(pet.health - elapsedHours * 2.4, 0, 100);
            if (pet.hydration < 26) pet.health = clampPetNumber(pet.health - elapsedHours * 3.2, 0, 100);
            if (pet.fun < 20) pet.health = clampPetNumber(pet.health - elapsedHours * 1.1, 0, 100);

            pet.lastUpdatedAt = nowTimestamp;
            hasChanges = true;
        });

        const presence = applyHomeMicroMovement(contact, getCurrentHomePresence(contact, new Date(nowTimestamp)), new Date(nowTimestamp));
        const canAutoCare = presence.atHome && (nowTimestamp - (Number(petSystem.lastAutoCareAt) || 0)) > (2 * 60 * 60 * 1000);
        if (canAutoCare) {
            const needsCare = petSystem.pets.some(pet => pet.foodBowl < 18 || pet.waterBowl < 18);
            if (needsCare && Math.random() < 0.35) {
                petSystem.pets.forEach(pet => {
                    pet.foodBowl = clampPetNumber(Math.max(pet.foodBowl, 72), 0, 100);
                    pet.waterBowl = clampPetNumber(Math.max(pet.waterBowl, 82), 0, 100);
                    pet.lastUpdatedAt = nowTimestamp;
                });
                petSystem.lastAutoCareAt = nowTimestamp;
                pushPetEvent(contact, createPetEventEntry(
                    'daily',
                    '补了粮和水',
                    `${contact.remark || contact.name || '角色'} 在家时顺手给宠物补了粮和水。`
                ));
                hasChanges = true;
            }
        }

        const canTriggerSupplyIncident = (nowTimestamp - (Number(petSystem.lastSupplyIncidentAt) || 0)) > (12 * 60 * 60 * 1000);
        if (canTriggerSupplyIncident && petSystem.pets.length > 0 && Math.random() < 0.08) {
            const targetPet = petSystem.pets[Math.floor(Math.random() * petSystem.pets.length)];
            const impact = 10 + Math.floor(Math.random() * 18);
            if (Math.random() < 0.5) {
                targetPet.foodBowl = clampPetNumber(targetPet.foodBowl - impact, 0, 100);
                pushPetEvent(contact, createPetEventEntry('daily', '粮盆掉得有点快', `${targetPet.name} 今天吃得比平时快，粮盆见底得更早了。`, { petIds: [targetPet.id] }));
            } else {
                targetPet.waterBowl = clampPetNumber(targetPet.waterBowl - impact, 0, 100);
                pushPetEvent(contact, createPetEventEntry('daily', '水碗消耗得很快', `${targetPet.name} 今天喝水比较凶，水碗掉得比平时快。`, { petIds: [targetPet.id] }));
            }
            petSystem.lastSupplyIncidentAt = nowTimestamp;
            hasChanges = true;
        }

        if (hasChanges && options.persist) {
            saveAppData();
        }

        return { petSystem, presence, hasChanges };
    }

    function pickPetAcquisitionSource(signal, hasExistingPets = false) {
        if (signal && signal.wantsPet) {
            const sourceOptions = hasExistingPets
                ? ['朋友家抱养', '领养站接回', '宠物店认真挑了一只']
                : ['朋友家抱养', '去宠物店带回家', '正式领养'];
            return getPetStableChoice(`${signal.notes}-source`, sourceOptions, sourceOptions[0]);
        }
        const randomSources = ['捡到需要安置的小家伙', '被熟人托付了一只宠物', '临时照顾后决定留下'];
        return getPetStableChoice(`${Date.now()}-random-source`, randomSources, randomSources[0]);
    }

    function addPetToContact(contact, petLike, entryMeta = {}) {
        const petSystem = ensurePetSystem(contact);
        const normalizedPet = normalizePetObject(petLike, contact);
        petSystem.pets.push(normalizedPet);
        petSystem.selectedPetId = normalizedPet.id;
        petSystem.selectedRoom = normalizedPet.homeRoom || getPetSpeciesMeta(normalizedPet.species).defaultRoom;

        const eventTitle = entryMeta.eventTitle || '有了新宠物';
        const eventDescription = entryMeta.eventDescription || `${contact.remark || contact.name || '角色'} 把 ${normalizedPet.name} 接回了家。`;
        pushPetEvent(contact, createPetEventEntry(entryMeta.kind || 'acquire', eventTitle, eventDescription, {
            petIds: [normalizedPet.id],
            source: normalizedPet.source || entryMeta.source || ''
        }));

        ensureDogWalkPlan(contact);
        return normalizedPet;
    }

    function deletePetFromContact(contact, petId) {
        const petSystem = ensurePetSystem(contact);
        const targetId = String(petId || '').trim();
        if (!targetId) return null;

        const targetPet = petSystem.pets.find(pet => pet.id === targetId);
        if (!targetPet) return null;

        petSystem.pets = petSystem.pets.filter(pet => pet.id !== targetId);
        petSystem.eventLog = (petSystem.eventLog || []).reduce((acc, entry) => {
            if (!entry || typeof entry !== 'object') return acc;
            const petIds = Array.isArray(entry.petIds)
                ? entry.petIds.map(id => String(id || '').trim()).filter(Boolean)
                : [];
            if (petIds.length === 0) {
                acc.push(entry);
                return acc;
            }

            const remainingPetIds = petIds.filter(id => id !== targetId);
            if (remainingPetIds.length === 0) {
                return acc;
            }

            acc.push({
                ...entry,
                petIds: remainingPetIds
            });
            return acc;
        }, []);

        if (petSystem.monitorCache && petSystem.monitorCache.roomsByKey && typeof petSystem.monitorCache.roomsByKey === 'object') {
            Object.keys(petSystem.monitorCache.roomsByKey).forEach(roomKey => {
                const roomScene = petSystem.monitorCache.roomsByKey[roomKey];
                if (!roomScene || typeof roomScene !== 'object') return;
                roomScene.visiblePetIds = Array.isArray(roomScene.visiblePetIds)
                    ? roomScene.visiblePetIds.filter(id => String(id || '').trim() !== targetId)
                    : [];
                roomScene.petSpots = Array.isArray(roomScene.petSpots)
                    ? roomScene.petSpots.filter(spot => String(spot && spot.pet_id || '').trim() !== targetId)
                    : [];
            });
        }

        if (petSystem.pets.length === 0) {
            petSystem.selectedPetId = null;
            petSystem.selectedRoom = 'living_room';
            petSystem.monitorCache = createDefaultPetMonitorCache();
            petSystem.lastMonitorError = '';
        } else {
            if (petSystem.selectedPetId === targetId) {
                petSystem.selectedPetId = petSystem.pets[0].id;
            }
        }

        saveAppData();
        return targetPet;
    }

    function maybeTriggerPetButterflyEvent(contact, options = {}) {
        const petSystem = ensurePetSystem(contact);
        updatePetSystemState(contact, { persist: false });

        const nowTimestamp = options.nowTimestamp || Date.now();
        const signal = options.signal || detectPetSuggestionSignals(options.sourceText || '');
        const assistantApproved = options.assistantApproved === true;
        const hasExistingPets = petSystem.pets.length > 0;
        const recentAcquireCount = petSystem.eventLog.filter(entry => entry.kind === 'acquire' || entry.kind === 'manual').length;
        const intentLevel = clampPetNumber(petSystem.adoptionIntent.level || 0, 0, 100);
        if (!hasExistingPets && isPetAdoptionIntentCoolingDown(petSystem, nowTimestamp) && !assistantApproved) {
            return { triggered: false, reason: 'adoption_cooling_down' };
        }
        const hoursSinceRandomAcquire = petSystem.lastRandomAcquisitionAt
            ? (nowTimestamp - petSystem.lastRandomAcquisitionAt) / (1000 * 60 * 60)
            : Infinity;

        let acquisitionChance = 0;
        if (!hasExistingPets) {
            acquisitionChance = signal.wantsPet
                ? (assistantApproved ? 1 : 0)
                : (hoursSinceRandomAcquire > 72 ? 0.0005 : 0);
        } else if (signal.wantsAnother) {
            acquisitionChance = assistantApproved
                ? 1
                : 0;
        } else if (hoursSinceRandomAcquire > (14 * 24)) {
            acquisitionChance = 0.0004 * Math.pow(0.35, Math.min(recentAcquireCount, 4));
        }

        if (acquisitionChance > 0 && Math.random() < acquisitionChance) {
            const species = signal.species || inferPetSpeciesFromText(options.sourceText || '');
            const source = pickPetAcquisitionSource(signal, hasExistingPets);
            const petCount = Math.random() < 0.03 ? 2 : 1;
            const newPets = [];

            for (let index = 0; index < petCount; index++) {
                const pet = addPetToContact(contact, {
                    species,
                    name: buildAutoPetName(species, index),
                    source,
                    seedNote: options.sourceText || (signal && signal.notes) || '',
                    acquiredAt: nowTimestamp,
                    isManual: false
                }, {
                    kind: 'acquire',
                    eventTitle: petCount > 1 ? '一下带回了不止一只' : '家里多了一只新宠物',
                    eventDescription: petCount > 1
                        ? `${contact.remark || contact.name || '角色'} 这次一下带回了 ${petCount} 只${getPetSpeciesMeta(species).label}，家里热闹了不少。`
                        : `${contact.remark || contact.name || '角色'} 通过“${source}”把一只${getPetSpeciesMeta(species).label}带回了家。`,
                    source
                });
                newPets.push(pet);
            }

            petSystem.lastRandomAcquisitionAt = nowTimestamp;
            petSystem.adoptionIntent.level = hasExistingPets ? Math.max(12, intentLevel - 28) : Math.max(18, intentLevel - 45);
            petSystem.adoptionIntent.updatedAt = nowTimestamp;
            void refreshPetWorldFromApi(contact, {
                reason: assistantApproved ? 'pet_adoption' : 'pet_random_acquire',
                focusPetId: newPets[0] ? newPets[0].id : null,
                forceEventCheck: true
            }).catch((error) => {
                console.warn('宠物AI档案/监控生成失败:', error);
            });
            return {
                triggered: true,
                type: 'acquire',
                pets: newPets
            };
        }

        const hoursSinceFollowUp = petSystem.lastFollowUpEventAt
            ? (nowTimestamp - petSystem.lastFollowUpEventAt) / (1000 * 60 * 60)
            : Infinity;
        const canFollowUp = petSystem.pets.length > 0 && hoursSinceFollowUp > 20;
        if (canFollowUp) {
            const followUpChance = options.reason === 'daily' ? 0.12 : 0.04;
            if (Math.random() < followUpChance) {
                const targetPet = petSystem.pets[Math.floor(Math.random() * petSystem.pets.length)];
                const followUpOptions = [
                    {
                        title: '宠物日常',
                        description: `${targetPet.name} 今天格外黏人，跟着 ${contact.remark || contact.name || '角色'} 在家里转来转去。`
                    },
                    {
                        title: '宠物寄养安排',
                        description: `${targetPet.name} 可能需要短暂寄养或托朋友照看一下，得提前想好安排。`
                    },
                    {
                        title: '宠物身体小状况',
                        description: `${targetPet.name} 今天状态有点蔫，需要多观察精神和食欲，但先按轻微异常处理。`
                    },
                    {
                        title: '宠物清洁日',
                        description: `${targetPet.name} 身上和小窝都该清一轮了，家里得抽时间收拾。`
                    }
                ];
                const selectedFollowUp = getPetStableChoice(`${targetPet.id}-${formatPetClock(new Date(nowTimestamp).getHours() * 60)}`, followUpOptions, followUpOptions[0]);
                pushPetEvent(contact, createPetEventEntry('followup', selectedFollowUp.title, selectedFollowUp.description, { petIds: [targetPet.id] }));
                petSystem.lastFollowUpEventAt = nowTimestamp;
                return {
                    triggered: true,
                    type: 'followup',
                    pet: targetPet
                };
            }
        }

        return { triggered: false, type: 'none', pets: [] };
    }

    function getPetHistorySource(contact) {
        if (!contact) return [];
        if (contact.isOfflineMode && Array.isArray(contact.offlineStorylines)) {
            const activeStory = contact.offlineStorylines.find(story => story.id === contact.activeOfflineStoryId);
            if (activeStory && Array.isArray(activeStory.chatHistory)) {
                return activeStory.chatHistory;
            }
        }
        return Array.isArray(contact.onlineChatHistory) ? contact.onlineChatHistory : [];
    }

    function buildPetWorldBookText(contact) {
        return formatWorldBookForPrompt(contact, { itemPrefix: '', emptyText: '无' });
    }

    function buildPetDailyPlanText(contact, atDate = new Date()) {
        const runtimePlan = getDailyPlanItemsForRuntimeContext(contact, atDate);
        if (!contact || runtimePlan.length === 0) return '今日还没有明确日程。';
        const currentItem = getCurrentDailyPlanItem(contact, atDate);
        const annotated = runtimePlan
            .slice()
            .sort((a, b) => String(a.startTime || '').localeCompare(String(b.startTime || '')))
            .map(item => ({
                item,
                temporal: getDailyPlanItemTemporalState(item, atDate)
            }));
        const visiblePastAndCurrent = annotated.filter(entry => entry.temporal.key !== 'future').slice(-8);
        const nextFuturePlans = annotated.filter(entry => entry.temporal.key === 'future').slice(0, 2);
        const visibleEntries = [...visiblePastAndCurrent, ...nextFuturePlans];
        const fallbackEntries = visibleEntries.length ? visibleEntries : annotated.slice(0, 1);
        const lines = fallbackEntries
            .map(({ item, temporal }) => {
                const marker = currentItem === item ? ' [当前时段]' : '';
                const temporalLabel = temporal?.label || '时间未知';
                return `- [${temporalLabel}] ${item.startTime || '--:--'} ~ ${item.endTime || '--:--'} | ${item.activity || '未写活动'} @ ${item.location || '位置未写'}${marker}`;
            });
        return [
            ...lines,
            '规则：已发生/当前时段可以当事实；标注为“稍后计划”的内容只能当未发生的安排，不要让监控画面提前显示未来地点或未来事件。'
        ].join('\n');
    }

    function normalizePetRoomKey(roomKey, fallbackRoom = 'living_room') {
        const rawRoom = String(roomKey || '').trim();
        if (!rawRoom) return fallbackRoom;
        if (rawRoom === 'outside') return 'outside';
        const directMatch = PET_ROOM_CONFIGS.find(room => room.key === rawRoom);
        if (directMatch) return directMatch.key;
        const aliasMatch = PET_ROOM_CONFIGS.find(room => room.aliases.some(alias => rawRoom.includes(alias)));
        return aliasMatch ? aliasMatch.key : fallbackRoom;
    }

    function normalizeAiPetProfileForMerge(existingPet, rawProfile, contact) {
        if (!existingPet) return null;
        const profile = rawProfile && typeof rawProfile === 'object' ? rawProfile : {};
        const locked = existingPet.manualFieldMap && typeof existingPet.manualFieldMap === 'object'
            ? existingPet.manualFieldMap
            : {};
        const proposedHomeRoom = normalizePetRoomKey(
            profile.home_room || profile.homeRoom || existingPet.homeRoom || '',
            existingPet.homeRoom || getPetSpeciesMeta(existingPet.species).defaultRoom
        );
        const merged = normalizePetObject({
            ...existingPet,
            name: locked.name ? existingPet.name : String(profile.name || existingPet.name || '').trim(),
            species: locked.species ? existingPet.species : (profile.species || existingPet.species || ''),
            breed: locked.breed ? existingPet.breed : String(profile.breed || existingPet.breed || '').trim(),
            sex: locked.sex ? existingPet.sex : (profile.sex || existingPet.sex || ''),
            age: locked.age ? existingPet.age : String(profile.age || existingPet.age || '').trim(),
            personality: locked.personality ? existingPet.personality : String(profile.personality || existingPet.personality || '').trim(),
            habits: locked.habits ? existingPet.habits : (profile.habits || existingPet.habits || []),
            homeRoom: locked.homeRoom ? existingPet.homeRoom : (proposedHomeRoom === 'outside' ? (existingPet.homeRoom || getPetSpeciesMeta(existingPet.species).defaultRoom) : proposedHomeRoom),
            source: locked.source ? existingPet.source : String(profile.source || existingPet.source || '').trim(),
            notes: String(profile.notes || existingPet.notes || '').trim(),
            aiProfileGeneratedAt: Date.now(),
            manualFieldMap: locked,
            seedNote: existingPet.seedNote || String(profile.seed_note || '').trim()
        }, contact);
        return merged;
    }

    function shouldAppendAiPetEvent(contact, rawEvent) {
        const petSystem = ensurePetSystem(contact);
        const event = rawEvent && typeof rawEvent === 'object' ? rawEvent : {};
        if (!event.should_add) return false;
        const title = String(event.title || '').trim();
        const description = String(event.description || '').trim();
        if (!title || !description) return false;
        return !petSystem.eventLog.some(entry =>
            String(entry.title || '').trim() === title
            && String(entry.description || '').trim() === description
            && Math.abs(Date.now() - Number(entry.timestamp || 0)) < (12 * 60 * 60 * 1000)
        );
    }

    function buildFallbackPetMonitorRoom(contact, roomKey, snapshot = null) {
        const activeSnapshot = snapshot || buildPetMonitorSnapshot(contact);
        const label = getPetRoomLabel(roomKey);
        const visiblePets = (activeSnapshot.petsWithRooms || []).filter(pet => pet.currentRoom === roomKey);
        const charPresent = !!(activeSnapshot.presence && activeSnapshot.presence.atHome && activeSnapshot.presence.roomKey === roomKey);
        const charText = charPresent
            ? `${contact.remark || contact.name || '角色'} 现在在这里，${activeSnapshot.presence.activityText || '正待在家里'}。`
            : (activeSnapshot.presence && activeSnapshot.presence.atHome
                ? `${contact.remark || contact.name || '角色'} 现在在家里别的房间。`
                : `${contact.remark || contact.name || '角色'} 当前不在家。`);
        const petSpots = visiblePets.map(pet => ({
            pet_id: pet.id,
            action: buildPetMonitorActionText(contact, pet, {
                ...activeSnapshot,
                selectedRoom: roomKey,
                visiblePets,
                charVisible: charPresent
            }),
            mood: String(pet.personality || '').trim(),
            position_hint: getPetRoomLabel(pet.homeRoom || roomKey)
        }));
        return {
            roomKey,
            roomLabel: label,
            overview: `${label}当前${visiblePets.length > 0 || charPresent ? '有动静' : '比较安静'}。`,
            ambience: visiblePets.length > 0 || charPresent ? '镜头里能捕捉到一些生活感。' : '镜头里暂时没有宠物或角色入镜。',
            monitorText: visiblePets.length > 0
                ? `${label}镜头里能看到 ${visiblePets.map(pet => pet.name).join('、')}，${charText}`
                : `${label}镜头里暂时没拍到宠物。${charText}`,
            charPresent,
            charText,
            visiblePetIds: visiblePets.map(pet => pet.id),
            petSpots,
            emptyNote: '这个房间暂时没有宠物入镜。'
        };
    }

    async function buildPetAiRefreshPrompt(contact, options = {}) {
        const petSystem = ensurePetSystem(contact);
        const now = options.now instanceof Date ? options.now : getContactNowDate(contact);
        const historySource = getPetHistorySource(contact);
        const formattedHistory = await formatHistoryForApi(historySource.slice(-12), contact);
        const historyText = formattedHistory.length > 0
            ? formattedHistory.map(msg => `${msg.role === 'user' ? '用户' : (contact.remark || contact.name || '角色')}: ${typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content)}`).join('\n')
            : '无';
        const worldBookText = buildPetWorldBookText(contact);
        const dailyPlanText = buildPetDailyPlanText(contact, now);
        const currentPlanItem = getCurrentDailyPlanItem(contact, now);
        const presenceAnchor = applyHomeMicroMovement(contact, getCurrentHomePresence(contact, now), now);
        const petsPayload = petSystem.pets.map(pet => ({
            id: pet.id,
            archive_reliability: pet.aiProfileGeneratedAt ? 'api_confirmed' : 'provisional_needs_api',
            locked_fields: pet.manualFieldMap || {},
            archive: {
                name: pet.name || '',
                species: pet.species || '',
                breed: pet.breed || '',
                sex: pet.sex || '',
                age: pet.age || '',
                personality: pet.personality || '',
                habits: normalizePetHabitList(pet.habits),
                home_room: pet.homeRoom || '',
                source: pet.source || '',
                notes: pet.notes || ''
            },
            stats: {
                satiety: Math.round(clampPetNumber(pet.satiety, 0, 100)),
                hydration: Math.round(clampPetNumber(pet.hydration, 0, 100)),
                fun: Math.round(clampPetNumber(pet.fun, 0, 100)),
                health: Math.round(clampPetNumber(pet.health, 0, 100)),
                food_bowl: Math.round(clampPetNumber(pet.foodBowl, 0, 100)),
                water_bowl: Math.round(clampPetNumber(pet.waterBowl, 0, 100))
            },
            seed_note: pet.seedNote || ''
        }));
        const recentEvents = (petSystem.eventLog || []).slice(0, 8).map(entry => ({
            kind: entry.kind || 'daily',
            title: entry.title || '',
            description: entry.description || '',
            timestamp: entry.timestamp || 0
        }));
        const payload = {
            refresh_reason: options.reason || 'manual_refresh',
            focus_pet_id: options.focusPetId || '',
            current_time: now.toLocaleString('zh-CN', { hour12: false }),
            character: {
                display_name: contact.remark || contact.name || '角色',
                user_name: contact.userProfile && contact.userProfile.name ? contact.userProfile.name : '用户',
                persona: String(contact.persona || '').trim(),
                world_book: worldBookText
            },
            current_schedule_anchor: {
                current_item: currentPlanItem ? {
                    start: currentPlanItem.startTime || '',
                    end: currentPlanItem.endTime || '',
                    activity: currentPlanItem.activity || '',
                    location: currentPlanItem.location || ''
                } : null,
                local_presence_hint: {
                    at_home: !!presenceAnchor.atHome,
                    room_key: presenceAnchor.roomKey || '',
                    activity: presenceAnchor.activityText || '',
                    planned_time: presenceAnchor.plannedTime || '',
                    note: presenceAnchor.microShiftNote || ''
                },
                daily_plan: dailyPlanText
            },
            recent_chat: historyText,
            recent_pet_events: recentEvents,
            rooms: PET_ROOM_CONFIGS.map(room => ({ key: room.key, label: room.label })),
            pets: petsPayload
        };

        return `你在为一个角色聊天应用生成“宠物档案 + 家用宠物监控 + 宠物事件记录建议”。

必须遵守：
1. 所有内容必须严格参考角色人设、世界书、最近聊天记录、当前日程和已有宠物档案。
2. 宠物行为不能 OOC，不能和档案冲突。胆小、慢热、幼龄、黏人等特征都必须体现在监控和事件里。
3. 角色当前状态也必须结合日程生成，但允许非常轻微、合理的小偏移，例如短暂去厕所、喝水、洗澡收尾、拿快递。不要夸张偏移。
4. 监控页面必须给出全部房间的内容，不允许只生成有宠物的房间。即使房间为空，也要写出镜头看到什么。
5. 角色和宠物可以在不同房间，不要强行把大家塞到同一个房间。
6. 如果某只宠物的 locked_fields 某字段为 true，就把那个字段当成硬约束，不要改写。其余空白或 provisional 字段请根据上下文补完。
7. 不要生成冒犯性、雷霆式、重大变故式内容。宠物事件也只允许细小、自然、连续性的日常变化。
8. 只输出 JSON，不要解释，不要 Markdown，不要代码块。

请输出一个单一 JSON 对象，字段结构必须如下：
{
  "pet_profiles": [
    {
      "id": "对应输入里的宠物id",
      "name": "宠物名字",
      "species": "cat|dog|rabbit|bird|hamster|other",
      "breed": "品种",
      "sex": "male|female|unknown",
      "age": "年龄文本",
      "personality": "一句自然的人设描述",
      "habits": ["习惯1", "习惯2"],
      "home_room": "living_room|bedroom|kitchen|bathroom|balcony|entryway",
      "source": "获得方式",
      "notes": "简短补充备注"
    }
  ],
  "char_state": {
    "at_home": true,
    "current_room": "living_room|bedroom|kitchen|bathroom|balcony|entryway|outside",
    "current_activity": "角色当前在做什么",
    "schedule_anchor": "这次判断主要参考的日程锚点",
    "deviation_note": "如果和日程有轻微偏移，在这里说明；没有就留空"
  },
  "rooms": [
    {
      "room_key": "living_room|bedroom|kitchen|bathroom|balcony|entryway",
      "overview": "该房间镜头的总览",
      "ambience": "环境/气氛一句话",
      "monitor_text": "监控文字说明，1到3句",
      "char_present": true,
      "char_text": "如果角色在这个房间，镜头看到角色在做什么；不在也要说明",
      "visible_pet_ids": ["宠物id1"],
      "pet_spots": [
        {
          "pet_id": "宠物id1",
          "action": "这只宠物在做什么",
          "mood": "状态/情绪",
          "position_hint": "在房间里的位置"
        }
      ],
      "empty_note": "如果这个房间没有宠物入镜，给一句自然说明"
    }
  ],
  "event_update": {
    "should_add": false,
    "kind": "daily|followup|care|health",
    "title": "如果需要新增事件，给标题",
    "description": "如果需要新增事件，给描述",
    "pet_ids": ["相关宠物id"]
  }
}

输入数据如下：
${JSON.stringify(payload, null, 2)}`;
    }

    function buildPetMonitorCacheFromApiResult(contact, result, options = {}) {
        const petSystem = ensurePetSystem(contact);
        const fallbackSnapshot = buildPetMonitorSnapshot(contact);
        const charStateRaw = result && result.char_state && typeof result.char_state === 'object'
            ? result.char_state
            : {};
        const fallbackNow = getContactNowDate(contact);
        const fallbackPresence = fallbackSnapshot.presence || getCurrentHomePresence(contact, fallbackNow);
        const charState = {
            atHome: typeof charStateRaw.at_home === 'boolean' ? charStateRaw.at_home : !!fallbackPresence.atHome,
            currentRoom: charStateRaw.current_room === 'outside'
                ? 'outside'
                : normalizePetRoomKey(charStateRaw.current_room || fallbackPresence.roomKey || '', fallbackPresence.roomKey || 'living_room'),
            currentActivity: String(charStateRaw.current_activity || fallbackPresence.activityText || '').trim() || '在家里待着',
            scheduleAnchor: String(charStateRaw.schedule_anchor || fallbackPresence.plannedTime || '').trim(),
            deviationNote: String(charStateRaw.deviation_note || '').trim()
        };

        const petsById = new Map((petSystem.pets || []).map(pet => [pet.id, pet]));
        const roomsByKey = {};
        const rawRooms = Array.isArray(result && result.rooms) ? result.rooms : [];

        PET_ROOM_CONFIGS.forEach(room => {
            const rawRoom = rawRooms.find(item => normalizePetRoomKey(item && item.room_key, room.key) === room.key);
            if (!rawRoom || typeof rawRoom !== 'object') {
                roomsByKey[room.key] = buildFallbackPetMonitorRoom(contact, room.key, fallbackSnapshot);
                return;
            }
            const derivedCharPresent = !!(charState.atHome && charState.currentRoom === room.key);

            const visiblePetIds = Array.isArray(rawRoom.visible_pet_ids)
                ? rawRoom.visible_pet_ids.map(id => String(id || '').trim()).filter(id => petsById.has(id))
                : [];
            const petSpots = Array.isArray(rawRoom.pet_spots)
                ? rawRoom.pet_spots
                    .filter(item => item && typeof item === 'object')
                    .map(item => ({
                        pet_id: String(item.pet_id || '').trim(),
                        action: String(item.action || '').trim(),
                        mood: String(item.mood || '').trim(),
                        position_hint: String(item.position_hint || '').trim()
                    }))
                    .filter(item => petsById.has(item.pet_id))
                : [];

            roomsByKey[room.key] = {
                roomKey: room.key,
                roomLabel: room.label,
                overview: String(rawRoom.overview || '').trim() || buildFallbackPetMonitorRoom(contact, room.key, fallbackSnapshot).overview,
                ambience: String(rawRoom.ambience || '').trim(),
                monitorText: String(rawRoom.monitor_text || '').trim() || String(rawRoom.overview || '').trim(),
                charPresent: typeof rawRoom.char_present === 'boolean' ? rawRoom.char_present : derivedCharPresent,
                charText: String(rawRoom.char_text || '').trim() || (derivedCharPresent ? `${contact.remark || contact.name || '角色'} 现在在这里，${charState.currentActivity || '正在处理当前这段时间的事'}。` : ''),
                visiblePetIds,
                petSpots,
                emptyNote: String(rawRoom.empty_note || '').trim()
            };
        });

        return {
            generatedAt: Date.now(),
            reason: String(options.reason || '').trim(),
            charState,
            roomsByKey,
            raw: JSON.stringify(result || {})
        };
    }

    async function refreshPetWorldFromApi(contact, options = {}) {
        if (!contact) throw new Error('缺少角色数据');
        const petSystem = ensurePetSystem(contact);
        if (!Array.isArray(petSystem.pets) || petSystem.pets.length === 0) {
            return null;
        }

        petSystem.isMonitorRefreshing = true;
        petSystem.lastMonitorError = '';
        if (typeof renderPetView === 'function') renderPetView();

        try {
            updatePetSystemState(contact, { persist: true });
            const prompt = await buildPetAiRefreshPrompt(contact, options);
            const { parsed, raw } = await callMainApiPrompt(prompt, { temperature: 0.45 });
            const result = parsed || parseJsonLike(raw);
            if (!result || typeof result !== 'object') {
                throw new Error('主API没有返回可解析的宠物监控JSON');
            }

            const profileList = Array.isArray(result.pet_profiles) ? result.pet_profiles : [];
            petSystem.pets = petSystem.pets.map(existingPet => {
                const matched = profileList.find(item => String(item && item.id || '').trim() === existingPet.id)
                    || profileList.find(item => String(item && item.name || '').trim() && String(item.name || '').trim() === String(existingPet.name || '').trim());
                return matched ? normalizeAiPetProfileForMerge(existingPet, matched, contact) : existingPet;
            });

            petSystem.monitorCache = buildPetMonitorCacheFromApiResult(contact, result, options);
            petSystem.lastMonitorError = '';

            if (shouldAppendAiPetEvent(contact, result.event_update || {})) {
                const eventPetIds = Array.isArray(result.event_update.pet_ids)
                    ? result.event_update.pet_ids.map(id => String(id || '').trim()).filter(Boolean)
                    : [];
                pushPetEvent(contact, createPetEventEntry(
                    result.event_update.kind || 'daily',
                    result.event_update.title || '宠物动态',
                    result.event_update.description || '',
                    { petIds: eventPetIds }
                ));
            }

            saveAppData();
            return result;
        } catch (error) {
            petSystem.lastMonitorError = String(error && error.message ? error.message : error);
            throw error;
        } finally {
            petSystem.isMonitorRefreshing = false;
            if (typeof renderPetView === 'function') renderPetView();
        }
    }

    function buildPetMonitorSceneHtmlFromCache(contact, roomScene, selectedPet = null) {
        const petSystem = ensurePetSystem(contact);
        const pets = petSystem.pets || [];
        const petsById = new Map(pets.map(pet => [pet.id, pet]));
        const visiblePetIds = Array.isArray(roomScene && roomScene.visiblePetIds) ? roomScene.visiblePetIds : [];
        const petSpots = Array.isArray(roomScene && roomScene.petSpots) ? roomScene.petSpots : [];
        const visiblePetCards = petSpots.map(spot => {
            const pet = petsById.get(spot.pet_id);
            if (!pet) return '';
            return `
                <div class="pet-monitor-subject ${selectedPet && selectedPet.id === pet.id ? 'focus' : ''}">
                    <div class="pet-monitor-subject-name">${escapeHtml(pet.name)}</div>
                    <div class="pet-monitor-subject-meta">${escapeHtml(getPetSpeciesMeta(pet.species).label)}${pet.breed ? ` · ${escapeHtml(pet.breed)}` : ''}${pet.age ? ` · ${escapeHtml(pet.age)}` : ''}</div>
                    <div class="pet-monitor-subject-action">${escapeHtml(spot.action || spot.mood || '暂时安静待着')}</div>
                </div>
            `;
        }).filter(Boolean).join('');

        const selectedPetRoomHint = selectedPet && !visiblePetIds.includes(selectedPet.id)
            ? (() => {
                const roomEntry = PET_ROOM_CONFIGS.find(room => {
                    const cachedRoom = petSystem.monitorCache && petSystem.monitorCache.roomsByKey
                        ? petSystem.monitorCache.roomsByKey[room.key]
                        : null;
                    return cachedRoom && Array.isArray(cachedRoom.visiblePetIds) && cachedRoom.visiblePetIds.includes(selectedPet.id);
                });
                return roomEntry ? `当前选中的 ${selectedPet.name} 更可能在 ${roomEntry.label}。` : '';
            })()
            : '';

        return `
            <div class="pet-monitor-stage">
                <div class="pet-monitor-head">
                    <span class="pet-monitor-chip">${escapeHtml(roomScene.roomLabel || getPetRoomLabel(roomScene.roomKey || 'living_room'))}镜头</span>
                    <span class="pet-monitor-chip ${roomScene.charPresent ? 'active' : ''}">${roomScene.charPresent ? '角色在镜头里' : '角色不在这个镜头里'}</span>
                    <span class="pet-monitor-chip">${visiblePetIds.length > 0 ? `镜头拍到 ${visiblePetIds.length} 只宠物` : '当前镜头没有宠物入镜'}</span>
                </div>
                <div class="pet-monitor-char">${escapeHtml(roomScene.charText || roomScene.ambience || '镜头正在稳定记录房间状态。')}</div>
                <div class="pet-monitor-subjects">
                    ${visiblePetCards || `<div class="pet-monitor-subject empty">${escapeHtml(roomScene.emptyNote || roomScene.ambience || '这个房间当前比较安静。')}</div>`}
                </div>
                ${(roomScene.overview || selectedPetRoomHint) ? `<div class="pet-monitor-hint">${escapeHtml([roomScene.overview || '', selectedPetRoomHint].filter(Boolean).join(' '))}</div>` : ''}
            </div>
        `;
    }

    function resolvePetCurrentRoom(contact, pet, presence, atDate = new Date()) {
        const seedBase = `${contact && contact.id ? contact.id : 'pet'}-${pet.id}-${Math.floor(atDate.getTime() / (10 * 60 * 1000))}`;
        const restRoom = pet.homeRoom || getPetSpeciesMeta(pet.species).defaultRoom;

        if (presence && presence.atHome && presence.roomKey && getPetStableRoll(`${seedBase}-char`) < (pet.species === 'dog' ? 0.72 : 0.48)) {
            return presence.roomKey;
        }
        if (pet.health < 40) return 'bedroom';
        if (pet.satiety < 35 || pet.hydration < 32) return 'kitchen';
        if (pet.fun < 28 && pet.species === 'dog') return 'entryway';
        if (pet.species === 'bird') return getPetStableChoice(`${seedBase}-bird`, ['balcony', 'living_room'], 'balcony');
        if (pet.species === 'cat') return getPetStableChoice(`${seedBase}-cat`, [restRoom, 'living_room', 'bedroom', 'balcony'], restRoom);
        if (pet.species === 'dog') return getPetStableChoice(`${seedBase}-dog`, [restRoom, 'living_room', 'entryway'], restRoom);
        return getPetStableChoice(`${seedBase}-other`, [restRoom, 'living_room', 'bedroom'], restRoom);
    }

    function buildPetMonitorActionText(contact, pet, snapshot) {
        const habits = normalizePetHabitList(pet.habits);
        const roomKey = pet.currentRoom || pet.homeRoom || 'living_room';
        const seedBase = `${contact && contact.id ? contact.id : 'pet'}-${pet.id}-${roomKey}-${Math.floor(Date.now() / (10 * 60 * 1000))}`;

        if (pet.health < 38) return '缩在软垫边上，精神不算太好，动得很少';
        if (pet.hydration < 34) return roomKey === 'kitchen' ? '守在水碗附近，时不时抬头看看' : '有点惦记喝水，行动显得没那么专心';
        if (pet.satiety < 36) return roomKey === 'kitchen' ? '已经靠到食盆附近了，像是在等加餐' : '明显在惦记吃的，时不时往厨房那边望';
        if (pet.fun < 28 && pet.species === 'dog') return '叼着玩具在门边徘徊，看起来很想出门活动一下';
        if (snapshot && snapshot.charVisible && /黏|亲人|外向|爱凑热闹/.test(String(pet.personality || ''))) {
            return `贴着 ${contact.remark || contact.name || '角色'} 附近转，注意力基本都在对方身上`;
        }
        if (habits.some(item => /窗|阳台/.test(item)) && (roomKey === 'balcony' || roomKey === 'living_room')) {
            return '趴在靠窗的位置往外看，偶尔因为一点动静抬头';
        }
        if (habits.some(item => /高|沙发|扶手/.test(item)) && roomKey === 'living_room') {
            return '占了一个舒服的位置窝着，看起来已经把这里当成自己的地盘';
        }
        if (habits.some(item => /角落|安全区|窝/.test(item)) && (roomKey === 'bedroom' || roomKey === 'living_room')) {
            return '待在自己认定的安全区附近，状态放松但还是会留意周围';
        }

        const speciesActions = {
            cat: ['慢吞吞舔着爪子，顺便盯着屋里的动静', '蜷在软垫边甩尾巴，看起来挺自在', '踩了两下垫子之后又重新趴好'],
            dog: ['在屋里来回转了两圈，最后又靠回常待的位置', '耳朵一直留意门口和人的动静，状态很在线', '玩一会儿又停下来观察周围，精力还算足'],
            rabbit: ['贴着地面慢慢挪动，闻一闻附近的东西再决定要不要靠近', '安静地缩着休息，但耳朵一直会跟着动静转', '绕着熟悉的区域转一小圈后又回到安心的位置'],
            bird: ['站在高一点的位置观察四周，偶尔整理一下羽毛', '头一歪一歪地看人，看起来对环境挺有兴趣', '先安静观察一会儿，确认没事后又开始活动'],
            hamster: ['在自己的活动范围里忙来忙去，像是在整理东西', '停一会儿闻闻周围，再继续折腾自己的小角落', '状态松弛但很专注，完全沉浸在自己的节奏里'],
            other: ['按自己的节奏活动着，看起来已经熟悉这片环境', '一边观察周围一边做自己的事，状态很自然']
        };
        const actionOptions = speciesActions[pet.species] || speciesActions.other;
        return getPetStableChoice(seedBase, actionOptions, actionOptions[0]);
    }

    function buildPetMonitorSceneHtml(contact, snapshot, selectedPet = null) {
        const roomLabel = getPetRoomLabel(snapshot.selectedRoom);
        const selectedPetState = selectedPet
            ? snapshot.petsWithRooms.find(pet => pet.id === selectedPet.id)
            : null;
        const visiblePetCards = (snapshot.visiblePets || []).map(pet => `
            <div class="pet-monitor-subject ${selectedPet && selectedPet.id === pet.id ? 'focus' : ''}">
                <div class="pet-monitor-subject-name">${escapeHtml(pet.name)}</div>
                <div class="pet-monitor-subject-meta">${escapeHtml(getPetSpeciesMeta(pet.species).label)}${pet.breed ? ` · ${escapeHtml(pet.breed)}` : ''}${pet.age ? ` · ${escapeHtml(pet.age)}` : ''}</div>
                <div class="pet-monitor-subject-action">${escapeHtml(buildPetMonitorActionText(contact, pet, snapshot))}</div>
            </div>
        `).join('');

        const selectedHint = selectedPetState && selectedPetState.currentRoom !== snapshot.selectedRoom
            ? `<div class="pet-monitor-hint">当前选中的 ${escapeHtml(selectedPetState.name)} 更可能在 ${escapeHtml(getPetRoomLabel(selectedPetState.currentRoom))}。</div>`
            : '';

        return `
            <div class="pet-monitor-stage">
                <div class="pet-monitor-head">
                    <span class="pet-monitor-chip">${escapeHtml(roomLabel)}镜头</span>
                    <span class="pet-monitor-chip ${snapshot.charVisible ? 'active' : ''}">${snapshot.charVisible ? '角色在画面里' : '角色不在画面里'}</span>
                    <span class="pet-monitor-chip">${snapshot.visiblePets.length > 0 ? `拍到 ${snapshot.visiblePets.length} 只宠物` : '当前镜头较安静'}</span>
                </div>
                <div class="pet-monitor-char">${escapeHtml(snapshot.charVisible ? `${contact.remark || contact.name || '角色'}：${snapshot.presence.activityText}` : `${contact.remark || contact.name || '角色'} 当前不在这个镜头里`)}</div>
                <div class="pet-monitor-subjects">
                    ${visiblePetCards || '<div class="pet-monitor-subject empty">这一格镜头现在没拍到宠物本体，只有环境和角色动静。</div>'}
                </div>
                ${selectedHint}
            </div>
        `;
    }

    function buildPetMonitorNarration(contact, snapshot) {
        const roomLabel = getPetRoomLabel(snapshot.selectedRoom);
        const visiblePets = snapshot.visiblePets || [];
        const presence = snapshot.presence;
        const charText = snapshot.charVisible
            ? `${contact.remark || contact.name || '角色'} 正在这里：${presence.activityText}${presence.microShiftNote ? '。' + presence.microShiftNote : '。'}`
            : `${contact.remark || contact.name || '角色'} 现在${presence.atHome ? `人在家里别的区域（按当前日程更像是在${getPetRoomLabel(presence.roomKey)}）` : '不在家'}。`;

        if (visiblePets.length > 0) {
            const petText = visiblePets
                .map(pet => `${pet.name}${pet.personality ? `（${pet.personality}）` : ''}，${buildPetMonitorActionText(contact, pet, snapshot)}`)
                .join('；');
            return `监控切到${roomLabel}后，能看到 ${petText}。${charText}`;
        }
        if (snapshot.charVisible) {
            return `监控切到${roomLabel}后，这里暂时没拍到宠物本体，但 ${charText}`;
        }
        return `监控切到${roomLabel}后，这里目前比较安静，没拍到宠物。${charText}`;
    }

    function buildPetMonitorDescription(contact, snapshot) {
        const roomLabel = getPetRoomLabel(snapshot.selectedRoom);
        const visiblePets = snapshot.visiblePets || [];
        const petNames = visiblePets.map(pet => pet.name).join('、');
        const presence = snapshot.presence;
        const charText = snapshot.charVisible
            ? `${contact.remark || contact.name || '角色'} 正在这里，${presence.activityText}${presence.microShiftNote ? '。' + presence.microShiftNote : '。'}`
            : `${contact.remark || contact.name || '角色'} 现在${presence.atHome ? `人在家里别的区域（按当前日程更像是在${getPetRoomLabel(presence.roomKey)}）` : '不在家'}。`;

        if (visiblePets.length > 0 && snapshot.charVisible) {
            return `监控切到${roomLabel}后，可以看到 ${charText} ${petNames} 也在这边活动，气氛比较有生活感。`;
        }
        if (visiblePets.length > 0) {
            return `监控切到${roomLabel}后，能看到 ${petNames} 在这里活动。${charText}`;
        }
        if (snapshot.charVisible) {
            return `监控切到${roomLabel}后，这里暂时没拍到宠物，但 ${charText}`;
        }
        return `监控切到${roomLabel}后，这里暂时很安静，没拍到宠物。${charText}`;
    }

    function buildPetMonitorSnapshot(contact) {
        const petSystem = ensurePetSystem(contact);
        updatePetSystemState(contact, { persist: false });

        const selectedRoom = petSystem.selectedRoom || 'living_room';
        const now = getContactNowDate(contact);
        const presence = applyHomeMicroMovement(contact, getCurrentHomePresence(contact, now), now);
        const petsWithRooms = petSystem.pets.map(pet => ({
            ...pet,
            currentRoom: resolvePetCurrentRoom(contact, pet, presence, now)
        }));
        const visiblePets = petsWithRooms.filter(pet => pet.currentRoom === selectedRoom);
        const charVisible = presence.atHome && presence.roomKey === selectedRoom;

        return {
            selectedRoom,
            presence,
            petsWithRooms,
            visiblePets,
            charVisible
        };
    }

    function buildPetPromptContext(contact, options = {}) {
        const petSystem = ensurePetSystem(contact);
        updatePetSystemState(contact, { persist: false });

        const pets = petSystem.pets || [];
        const recentEvents = (petSystem.eventLog || []).slice(0, 4);
        const intentLevel = clampPetNumber(petSystem.adoptionIntent.level || 0, 0, 100);
        const isAdoptionCoolingDown = isPetAdoptionIntentCoolingDown(petSystem, Date.now());
        const dogs = pets.filter(pet => getPetSpeciesMeta(pet.species).needsWalk);
        const lowSupplyPets = pets.filter(pet => pet.foodBowl < 25 || pet.waterBowl < 25);

        if (pets.length === 0 && intentLevel < 20 && !isAdoptionCoolingDown) return '';

        let promptText = `\n### >> 【你的宠物线（独立于普通蝴蝶效应）】`;
        if (pets.length === 0) {
            promptText += `\n- 你目前还没有正式养宠物。`;
            if (isAdoptionCoolingDown) {
                const firmnessText = petSystem.adoptionIntent.rejectionFirmness === 'hard' ? '明确拒绝' : '暂缓/现实条件不足';
                promptText += `\n- 用户最近已经对养宠物这条线做出${firmnessText}，原话/原因：${petSystem.adoptionIntent.rejectionNote || petSystem.adoptionIntent.note || '未记录'}。`;
                promptText += `\n- 在用户主动重新提起并明确改口之前，不要主动推进领养、买宠物、捡宠物，也不要把“想养宠物”写成当前强烈愿望；最多只能偶尔作为被压下去的念头或现实顾虑。`;
                return promptText;
            }
            if (intentLevel >= 20) {
                promptText += `\n- 用户最近多次提起养宠物，你对“养一只宠物”这件事已经出现明确意愿（当前意愿值约 ${intentLevel}/100）。`;
                promptText += `\n- 如果这条线被推进，优先走：朋友家抱养 / 正式领养 / 去宠物店认真挑选；极低概率才走“捡到”或“被送到手上”。`;
                promptText += `\n- 默认不要一下子养很多只；一次多只只允许极低概率。`;
            }
            return promptText;
        }

        const petSummary = pets.map(pet => {
            const speciesLabel = getPetSpeciesMeta(pet.species).label;
            return `${pet.name}(${speciesLabel}${pet.breed ? `/${pet.breed}` : ''}) 饱食${Math.round(pet.satiety)} 水分${Math.round(pet.hydration)} 娱乐${Math.round(pet.fun)} 健康${Math.round(pet.health)}`;
        }).join('；');
        promptText += `\n- 你现在养着的宠物：${petSummary}`;
        promptText += `\n- 宠物档案（后续监控、宠物蝴蝶效应、日常照护都必须优先参考这份档案，避免写出和档案相反的行为）：\n${pets.map(pet => `  - ${buildPetArchiveSummary(pet)} 常待房间：${getPetRoomLabel(pet.homeRoom)}。`).join('\n')}`;

        if (recentEvents.length > 0) {
            promptText += `\n- 最近宠物事件：\n${recentEvents.map(entry => `  - ${entry.title}: ${entry.description}`).join('\n')}`;
        }

        if (lowSupplyPets.length > 0) {
            promptText += `\n- 这些宠物的粮/水偏低：${lowSupplyPets.map(pet => `${pet.name}(粮${Math.round(pet.foodBowl)}/水${Math.round(pet.waterBowl)})`).join('、')}。如果你人在家，可以自然地补粮、换水。`;
        }

        if (dogs.length > 0) {
            promptText += `\n- 你养了狗。天气允许时，日常作息里应自然穿插一段固定遛狗时间；天气差时可以缩短或不遛。`;
        }

        promptText += `\n- 默认不要重复再捡/再养新宠物；除非用户持续主动软磨硬泡，或触发极低概率的独立宠物事件。`;
        promptText += `\n- 写宠物相关内容时，要把性别、年龄、性格、习惯都当成常驻设定：不要让胆小的宠物突然特别莽，不要让幼龄宠物表现得像老成到失真，也不要无视它固定的小习惯和偏好的房间。`;

        if (options.forSchedule) {
            promptText += `\n- 规划日程时，宠物相关事项走独立线：喂食、换水、清理、就医、寄养、遛狗，都可以自然占用当天时段。`;
        }

        return promptText;
    }

    function isWeatherBadForDogWalk(contact) {
        const forecast = contact && contact.weatherCache && Array.isArray(contact.weatherCache.forecastData)
            ? contact.weatherCache.forecastData
            : [];
        if (forecast.length === 0) return false;
        const todayWeather = forecast.find(day => day.dateLabel === '今天') || forecast[0];
        const description = String(todayWeather.description || '').trim();
        return /暴雨|雷暴|雷阵雨|台风|大风|暴雪|冰雹|沙尘|强对流/.test(description);
    }

    function pickDogWalkLocation(contact, fallbackLocation = '家附近') {
        const { map: activeMap } = getActiveMapForDate(contact);
        const locations = Array.isArray(activeMap?.locations) ? activeMap.locations : [];
        const preferred = locations.find(loc => /公园|小区|楼下|附近|绿道|河边|街区/.test(loc.name || ''));
        if (preferred) return preferred.name;
        const usable = locations.find(loc => !PET_OUTSIDE_LOCATION_REGEX.test(loc.name || '') || /公园|小区|附近/.test(loc.name || ''));
        return usable ? usable.name : fallbackLocation;
    }

    function ensureDogWalkPlan(contact) {
        const petSystem = ensurePetSystem(contact);
        const dogs = petSystem.pets.filter(pet => getPetSpeciesMeta(pet.species).needsWalk);
        if (dogs.length === 0 || !Array.isArray(contact.dailyPlan) || contact.dailyPlan.length === 0) return false;
        if (isWeatherBadForDogWalk(contact)) return false;
        if (contact.dailyPlan.some(item => /遛狗|带狗出门|牵着狗散步/.test(String(item.activity || '')))) return false;

        const sortedPlan = [...contact.dailyPlan].sort((a, b) => String(a.startTime || '').localeCompare(String(b.startTime || '')));
        const candidate = sortedPlan.find(item => {
            const start = parsePetClockToMinutes(item.startTime);
            const end = parsePetClockToMinutes(item.endTime);
            const duration = (start >= 0 && end >= 0) ? (end >= start ? end - start : (24 * 60 - start + end)) : 0;
            return item && item.isFlexible !== false && duration >= 40 && start >= 7 * 60 && start <= 21 * 60;
        });

        if (!candidate) return false;

        const start = parsePetClockToMinutes(candidate.startTime);
        const end = parsePetClockToMinutes(candidate.endTime);
        if (start < 0 || end < 0) return false;
        const endNormalized = end >= start ? end : end + 24 * 60;
        const duration = endNormalized - start;
        const preferredStart = start <= 18 * 60 && endNormalized >= 18 * 60
            ? 18 * 60
            : Math.min(start + 10, Math.max(start, endNormalized - 35));
        const walkStart = Math.max(start + 5, preferredStart);
        const walkEnd = Math.min(endNormalized - 5, walkStart + 30);
        if (walkEnd - walkStart < 20) return false;

        const walkLocation = pickDogWalkLocation(contact, isHomeLocation(candidate.location) ? '家附近' : (candidate.location || '家附近'));
        const walkItem = {
            startTime: formatPetClock(walkStart),
            endTime: formatPetClock(walkEnd),
            location: walkLocation,
            activity: `带${dogs[0].name}出去遛一圈`,
            isRandom: false,
            isFlexible: true
        };

        const rebuiltPlan = [];
        contact.dailyPlan.forEach(item => {
            if (item !== candidate) {
                rebuiltPlan.push(item);
                return;
            }

            if (walkStart - start >= 10) {
                rebuiltPlan.push({
                    ...item,
                    endTime: formatPetClock(walkStart)
                });
            }

            rebuiltPlan.push(walkItem);

            if (endNormalized - walkEnd >= 10) {
                rebuiltPlan.push({
                    ...item,
                    startTime: formatPetClock(walkEnd)
                });
            }
        });

        contact.dailyPlan = rebuiltPlan.sort((a, b) => String(a.startTime || '').localeCompare(String(b.startTime || '')));
        return true;
    }

    function getImportedPetHomeFurniturePlacementRule(type) {
        return PET_HOME_FURNITURE_PLACEMENT_RULES[type] || PET_HOME_FURNITURE_PLACEMENT_RULES.default;
    }

    function setImportedPetHomeNodeTransformFromRef(node) {
        if (!node) return;
        const ref = node.userData && node.userData.jsonRef ? node.userData.jsonRef : {};
        node.rotation.set(
            Number(ref.rotationX || 0),
            Number(ref.rotationY || 0),
            Number(ref.rotationZ || 0)
        );
        node.scale.setScalar(Math.max(0.1, Number(ref.scale || 1)));
    }

    function withImportedPetHomeFurnitureBaseScale(node, callback) {
        if (!node) return null;
        const previousRotation = node.rotation.clone();
        const previousScale = node.scale.clone();
        setImportedPetHomeNodeTransformFromRef(node);
        node.updateMatrixWorld(true);
        try {
            return callback();
        } finally {
            node.rotation.copy(previousRotation);
            node.scale.copy(previousScale);
            node.updateMatrixWorld(true);
        }
    }

    function getImportedPetHomePlacementBoundsForNode(node, rotationYOverride = null) {
        const ref = node && node.userData ? node.userData.jsonRef || {} : {};
        const previousPosition = node.position.clone();
        const previousRotation = node.rotation.clone();
        const previousScale = node.scale.clone();

        node.position.set(0, 0, 0);
        node.rotation.set(
            Number(ref.rotationX || 0),
            rotationYOverride == null ? Number(ref.rotationY || 0) : Number(rotationYOverride || 0),
            Number(ref.rotationZ || 0)
        );
        node.scale.setScalar(Math.max(0.1, Number(ref.scale || 1)));
        node.updateMatrixWorld(true);

        const box = new THREE.Box3().setFromObject(node);
        const size = box.getSize(new THREE.Vector3());
        const min = box.min.clone();
        const max = box.max.clone();

        node.position.copy(previousPosition);
        node.rotation.copy(previousRotation);
        node.scale.copy(previousScale);
        node.updateMatrixWorld(true);

        return { box, size, min, max };
    }

    function getImportedPetHomePlacementWorldBoundsForNode(node) {
        const previousRotation = node.rotation.clone();
        const previousScale = node.scale.clone();

        setImportedPetHomeNodeTransformFromRef(node);
        node.updateMatrixWorld(true);
        const box = new THREE.Box3().setFromObject(node);

        node.rotation.copy(previousRotation);
        node.scale.copy(previousScale);
        node.updateMatrixWorld(true);
        return box;
    }

    function findImportedPetHomeFurnitureNodeById(furnitureGroup, id) {
        if (!furnitureGroup || id == null) return null;
        return furnitureGroup.children.find(node => String(node.userData && node.userData.jsonRef && node.userData.jsonRef.id) === String(id)) || null;
    }

    function importedPetHomeFurnitureLocalPointToWorld(node, localX, localZ, localY = 0) {
        if (!node) return null;
        return withImportedPetHomeFurnitureBaseScale(node, () => {
            const point = new THREE.Vector3(localX, localY, localZ);
            return node.localToWorld(point.clone());
        });
    }

    function worldPointToImportedPetHomeFurnitureLocal(node, worldX, worldZ, worldY = 0) {
        if (!node) return null;
        return withImportedPetHomeFurnitureBaseScale(node, () => {
            const point = new THREE.Vector3(worldX, worldY, worldZ);
            return node.worldToLocal(point.clone());
        });
    }

    function getDesiredImportedPetHomeSurfacePointFromSupport(ref, furnitureGroup) {
        if (!ref || ref.supportId == null || ref.supportLocalX == null || ref.supportLocalZ == null) {
            return null;
        }
        const supportNode = findImportedPetHomeFurnitureNodeById(furnitureGroup, ref.supportId);
        if (!supportNode) return null;
        const worldPoint = importedPetHomeFurnitureLocalPointToWorld(
            supportNode,
            Number(ref.supportLocalX),
            Number(ref.supportLocalZ),
            0
        );
        if (!worldPoint) return null;
        return { x: worldPoint.x, z: worldPoint.z };
    }

    function getImportedPetHomePlacementPriority(node) {
        const type = node && node.userData && node.userData.jsonRef ? node.userData.jsonRef.type : '';
        const mode = getImportedPetHomeFurniturePlacementRule(type).mode;
        if (mode === 'surface' || mode === 'surface_or_floor') return 2;
        if (mode === 'wall') return 1;
        return 0;
    }

    function buildImportedPetHomeFloorPlacement(node, desiredX, desiredZ, room) {
        const ref = node && node.userData ? node.userData.jsonRef || {} : {};
        const metrics = getImportedPetHomePlacementBoundsForNode(node, Number(ref.rotationY || 0));
        return {
            x: desiredX,
            y: -metrics.min.y,
            z: desiredZ,
            rotationY: Number(ref.rotationY || 0),
            roomKey: room && room.key ? room.key : null
        };
    }

    function buildImportedPetHomeSurfacePlacement(node, desiredX, desiredZ, room, rule, furnitureGroup, layout) {
        if (!furnitureGroup) return null;

        const ref = node && node.userData ? node.userData.jsonRef || {} : {};
        const metrics = getImportedPetHomePlacementBoundsForNode(node, Number(ref.rotationY || 0));
        const halfX = metrics.size.x / 2;
        const halfZ = metrics.size.z / 2;
        const padding = Number(rule && rule.padding || 0);
        const candidates = [];

        furnitureGroup.children.forEach(otherNode => {
            if (otherNode === node || !(otherNode.userData && otherNode.userData.isFurniture)) return;

            const supportRef = otherNode.userData.jsonRef || {};
            const supportType = supportRef.type || '';
            if (!rule.supportKinds.includes(supportType)) return;

            const supportRoom = resolveImportedPetHomeRoom(
                layout,
                Number(supportRef.x != null ? supportRef.x : otherNode.position.x || 0),
                Number(supportRef.z != null ? supportRef.z : otherNode.position.z || 0),
                supportRef.room || ''
            );

            const supportBox = getImportedPetHomePlacementWorldBoundsForNode(otherNode);
            const safeMinX = supportBox.min.x + halfX + padding;
            const safeMaxX = supportBox.max.x - halfX - padding;
            const safeMinZ = supportBox.min.z + halfZ + padding;
            const safeMaxZ = supportBox.max.z - halfZ - padding;

            const x = safeMinX <= safeMaxX
                ? clampImportedPetHomeNumber(desiredX, safeMinX, safeMaxX)
                : (supportBox.min.x + supportBox.max.x) / 2;
            const z = safeMinZ <= safeMaxZ
                ? clampImportedPetHomeNumber(desiredZ, safeMinZ, safeMaxZ)
                : (supportBox.min.z + supportBox.max.z) / 2;

            const desiredInside = desiredX >= supportBox.min.x && desiredX <= supportBox.max.x
                && desiredZ >= supportBox.min.z && desiredZ <= supportBox.max.z;
            let score = Math.hypot(desiredX - x, desiredZ - z);
            if (desiredInside) score -= 0.4;
            if (room && supportRoom && supportRoom.key === room.key) score -= 0.15;
            if (room && supportRoom && supportRoom.key !== room.key) score += 0.35;
            if (ref.supportId && supportRef.id === ref.supportId) score -= 0.45;

            const supportLocalPoint = worldPointToImportedPetHomeFurnitureLocal(otherNode, x, z, supportBox.max.y);

            candidates.push({
                x,
                y: supportBox.max.y - metrics.min.y,
                z,
                rotationY: Number(ref.rotationY || 0),
                roomKey: supportRoom && supportRoom.key ? supportRoom.key : room && room.key ? room.key : null,
                supportId: supportRef.id,
                supportLocalX: supportLocalPoint ? supportLocalPoint.x : 0,
                supportLocalZ: supportLocalPoint ? supportLocalPoint.z : 0,
                score
            });
        });

        if (!candidates.length) return null;
        candidates.sort((a, b) => a.score - b.score);
        return candidates[0];
    }

    function buildImportedPetHomeWallPlacement(node, desiredX, desiredZ, room, rule) {
        if (!room) return null;

        const ref = node && node.userData ? node.userData.jsonRef || {} : {};
        const preferredSide = String(
            (node && node.userData && node.userData.importedMonitorWallDir)
            || ref._wallDir
            || ''
        );
        const bounds = getImportedPetHomeRoomBounds(room);
        const wallInset = Number(rule && rule.wallInset || 0.03);
        const mountHeight = Number(rule && rule.mountHeight || 0.08);
        const placements = [
            { side: 'north', rotationY: 0 },
            { side: 'south', rotationY: Math.PI },
            { side: 'west', rotationY: -Math.PI / 2 },
            { side: 'east', rotationY: Math.PI / 2 }
        ].map(candidate => {
            const metrics = getImportedPetHomePlacementBoundsForNode(node, candidate.rotationY);
            const halfX = metrics.size.x / 2;
            const halfZ = metrics.size.z / 2;
            let x = desiredX;
            let z = desiredZ;

            if (candidate.side === 'north') {
                x = clampImportedPetHomeNumber(desiredX, bounds.minX + halfX, bounds.maxX - halfX);
                z = bounds.minZ + wallInset - metrics.min.z;
            } else if (candidate.side === 'south') {
                x = clampImportedPetHomeNumber(desiredX, bounds.minX + halfX, bounds.maxX - halfX);
                z = bounds.maxZ - wallInset - metrics.max.z;
            } else if (candidate.side === 'west') {
                x = bounds.minX + wallInset - metrics.min.x;
                z = clampImportedPetHomeNumber(desiredZ, bounds.minZ + halfZ, bounds.maxZ - halfZ);
            } else {
                x = bounds.maxX - wallInset - metrics.max.x;
                z = clampImportedPetHomeNumber(desiredZ, bounds.minZ + halfZ, bounds.maxZ - halfZ);
            }

            return {
                x,
                y: mountHeight - metrics.min.y,
                z,
                rotationY: candidate.rotationY,
                roomKey: room.key,
                score: Math.hypot(desiredX - x, desiredZ - z)
            };
        });

        if (preferredSide) {
            const preferredPlacement = placements.find(candidate => candidate.side === preferredSide);
            if (preferredPlacement) {
                return preferredPlacement;
            }
        }
        placements.sort((a, b) => a.score - b.score);
        return placements[0];
    }

    function buildImportedPetHomeSurfaceOrFloorPlacement(node, desiredX, desiredZ, room, rule, furnitureGroup, layout) {
        return buildImportedPetHomeSurfacePlacement(node, desiredX, desiredZ, room, rule, furnitureGroup, layout)
            || buildImportedPetHomeFloorPlacement(node, desiredX, desiredZ, room);
    }

    function applyPlacementToImportedPetHomeFurnitureNode(node, desiredX, desiredZ, layout, furnitureGroup) {
        if (!node) return null;

        const ref = node.userData && node.userData.jsonRef ? node.userData.jsonRef : {};
        if (ref.manualPlacement) {
            ref.x = Number.isFinite(Number(desiredX)) ? Number(desiredX) : Number(ref.x || 0);
            ref.z = Number.isFinite(Number(desiredZ)) ? Number(desiredZ) : Number(ref.z || 0);
            const room = resolveImportedPetHomeRoom(layout, ref.x, ref.z, ref.room || '');
            if (room && room.key) ref.room = room.key;
            delete ref.supportId;
            delete ref.supportLocalX;
            delete ref.supportLocalZ;
            node.position.set(ref.x, Number(ref.manualY || 0), ref.z);
            setImportedPetHomeNodeTransformFromRef(node);
            node.updateMatrixWorld(true);
            return {
                x: ref.x,
                y: Number(ref.manualY || 0),
                z: ref.z,
                rotationY: Number(ref.rotationY || 0),
                roomKey: ref.room || null,
                manual: true
            };
        }

        const rule = getImportedPetHomeFurniturePlacementRule(ref.type);
        const room = resolveImportedPetHomeRoom(layout, desiredX, desiredZ, ref.room || '');
        let placement = null;

        if (rule.mode === 'surface') {
            placement = buildImportedPetHomeSurfacePlacement(node, desiredX, desiredZ, room, rule, furnitureGroup, layout);
        } else if (rule.mode === 'surface_or_floor') {
            placement = buildImportedPetHomeSurfaceOrFloorPlacement(node, desiredX, desiredZ, room, rule, furnitureGroup, layout);
        } else if (rule.mode === 'wall') {
            placement = buildImportedPetHomeWallPlacement(node, desiredX, desiredZ, room, rule);
        } else {
            placement = buildImportedPetHomeFloorPlacement(node, desiredX, desiredZ, room);
        }

        if (!placement) return null;

        ref.x = placement.x;
        ref.z = placement.z;
        if (placement.rotationY != null) ref.rotationY = placement.rotationY;
        delete ref.rotationX;
        delete ref.rotationZ;
        if (placement.roomKey) ref.room = placement.roomKey;
        else delete ref.room;
        if (placement.supportId != null) ref.supportId = placement.supportId;
        else delete ref.supportId;
        if (placement.supportLocalX != null) ref.supportLocalX = placement.supportLocalX;
        else delete ref.supportLocalX;
        if (placement.supportLocalZ != null) ref.supportLocalZ = placement.supportLocalZ;
        else delete ref.supportLocalZ;

        node.position.set(placement.x, placement.y, placement.z);
        setImportedPetHomeNodeTransformFromRef(node);
        node.updateMatrixWorld(true);
        return placement;
    }

    function refreshImportedPetHomeFurniturePlacements(layout, furnitureGroup) {
        if (!furnitureGroup) return;

        const nodes = furnitureGroup.children
            .filter(node => node.userData && node.userData.isFurniture)
            .sort((a, b) => getImportedPetHomePlacementPriority(a) - getImportedPetHomePlacementPriority(b));

        nodes.forEach(node => {
            const ref = node.userData && node.userData.jsonRef ? node.userData.jsonRef : {};
            const rule = getImportedPetHomeFurniturePlacementRule(ref.type);
            const desiredFromSupport = (rule.mode === 'surface' || rule.mode === 'surface_or_floor')
                ? getDesiredImportedPetHomeSurfacePointFromSupport(ref, furnitureGroup)
                : null;
            const desiredX = Number(desiredFromSupport && desiredFromSupport.x != null ? desiredFromSupport.x : ref.x != null ? ref.x : node.position.x || 0);
            const desiredZ = Number(desiredFromSupport && desiredFromSupport.z != null ? desiredFromSupport.z : ref.z != null ? ref.z : node.position.z || 0);
            const placement = applyPlacementToImportedPetHomeFurnitureNode(node, desiredX, desiredZ, layout, furnitureGroup);
            if (!placement) {
                const fallbackRoom = resolveImportedPetHomeRoom(layout, desiredX, desiredZ, ref.room || '');
                const fallback = buildImportedPetHomeFloorPlacement(node, desiredX, desiredZ, fallbackRoom);
                ref.x = fallback.x;
                ref.z = fallback.z;
                if (fallback.roomKey) ref.room = fallback.roomKey;
                delete ref.supportId;
                delete ref.supportLocalX;
                delete ref.supportLocalZ;
                node.position.set(fallback.x, fallback.y, fallback.z);
                setImportedPetHomeNodeTransformFromRef(node);
                node.updateMatrixWorld(true);
            }

            const resolvedRoom = resolveImportedPetHomeRoom(
                layout,
                Number(ref.x != null ? ref.x : node.position.x || 0),
                Number(ref.z != null ? ref.z : node.position.z || 0),
                ref.room || ''
            );
            node.userData.monitorRoomKey = resolvedRoom && resolvedRoom.key ? resolvedRoom.key : '';
        });
    }

    function getImportedPetHomeBounds(rooms = []) {
        let minX = Infinity;
        let maxX = -Infinity;
        let minZ = Infinity;
        let maxZ = -Infinity;
        rooms.forEach(room => {
            const bounds = getImportedPetHomeRoomBounds(room);
            minX = Math.min(minX, bounds.minX);
            maxX = Math.max(maxX, bounds.maxX);
            minZ = Math.min(minZ, bounds.minZ);
            maxZ = Math.max(maxZ, bounds.maxZ);
        });
        if (!Number.isFinite(minX) || !Number.isFinite(maxX) || !Number.isFinite(minZ) || !Number.isFinite(maxZ)) {
            return { minX: -2, maxX: 2, minZ: -2, maxZ: 2, centerX: 0, centerZ: 0, sizeX: 4, sizeZ: 4 };
        }
        return {
            minX,
            maxX,
            minZ,
            maxZ,
            centerX: (minX + maxX) / 2,
            centerZ: (minZ + maxZ) / 2,
            sizeX: maxX - minX,
            sizeZ: maxZ - minZ
        };
    }

    function buildImportedPetHomeAdjacencyMap(rooms = []) {
        const adjacencyMap = {};
        const tolerance = 0.22;
        const minOverlap = 0.3;

        const setAdjacency = (fromKey, toKey, targetDirection, otherDirection) => {
            if (!adjacencyMap[fromKey]) adjacencyMap[fromKey] = {};
            adjacencyMap[fromKey][toKey] = { targetDirection, otherDirection };
        };

        rooms.forEach(room => {
            if (room && room.key) adjacencyMap[room.key] = adjacencyMap[room.key] || {};
        });

        for (let index = 0; index < rooms.length; index += 1) {
            const currentRoom = rooms[index];
            if (!currentRoom || !currentRoom.key) continue;
            const currentBounds = getImportedPetHomeRoomBounds(currentRoom);

            for (let nextIndex = index + 1; nextIndex < rooms.length; nextIndex += 1) {
                const otherRoom = rooms[nextIndex];
                if (!otherRoom || !otherRoom.key) continue;
                const otherBounds = getImportedPetHomeRoomBounds(otherRoom);

                const overlapX = Math.min(currentBounds.maxX, otherBounds.maxX) - Math.max(currentBounds.minX, otherBounds.minX);
                const overlapZ = Math.min(currentBounds.maxZ, otherBounds.maxZ) - Math.max(currentBounds.minZ, otherBounds.minZ);

                if (Math.abs(currentBounds.maxX - otherBounds.minX) <= tolerance && overlapZ > minOverlap) {
                    setAdjacency(currentRoom.key, otherRoom.key, 'east', 'west');
                    setAdjacency(otherRoom.key, currentRoom.key, 'west', 'east');
                    continue;
                }
                if (Math.abs(currentBounds.minX - otherBounds.maxX) <= tolerance && overlapZ > minOverlap) {
                    setAdjacency(currentRoom.key, otherRoom.key, 'west', 'east');
                    setAdjacency(otherRoom.key, currentRoom.key, 'east', 'west');
                    continue;
                }
                if (Math.abs(currentBounds.maxZ - otherBounds.minZ) <= tolerance && overlapX > minOverlap) {
                    setAdjacency(currentRoom.key, otherRoom.key, 'south', 'north');
                    setAdjacency(otherRoom.key, currentRoom.key, 'north', 'south');
                    continue;
                }
                if (Math.abs(currentBounds.minZ - otherBounds.maxZ) <= tolerance && overlapX > minOverlap) {
                    setAdjacency(currentRoom.key, otherRoom.key, 'north', 'south');
                    setAdjacency(otherRoom.key, currentRoom.key, 'south', 'north');
                }
            }
        }

        return adjacencyMap;
    }

    function buildImportedPetHomePrototype(layout) {
        const workingLayout = {
            rooms: cloneImportedPetHomeValue(layout.rooms || []),
            furniture: cloneImportedPetHomeValue(layout.furniture || [])
        };
        const adjacencyMap = buildImportedPetHomeAdjacencyMap(workingLayout.rooms || []);

        const planGroup = Home3DModels.buildFloorPlan('custom', workingLayout.rooms, workingLayout.furniture);
        planGroup.name = 'pet-imported-home-plan';
        planGroup.userData = {
            ...(planGroup.userData || {}),
            importedHomeAdjacency: adjacencyMap
        };

        const furnitureGroup = new THREE.Group();
        furnitureGroup.name = 'pet-imported-home-furniture';

        workingLayout.furniture.forEach(item => {
            if (!item || item._skipRender) return;
            const structureItem = item.type === 'door' || item.type === 'window';
            const relatedRoomKeys = [String(item.room || '')].filter(Boolean);
            const wallDirByRoom = {};
            if (structureItem && item.room && item._wallDir) {
                wallDirByRoom[String(item.room)] = String(item._wallDir);
            }
            if (structureItem && item._isInterior && adjacencyMap[String(item.room || '')]) {
                Object.entries(adjacencyMap[String(item.room || '')] || {}).forEach(([otherRoomKey, entry]) => {
                    if (String(entry && entry.targetDirection || '') === String(item._wallDir || '')) {
                        relatedRoomKeys.push(String(otherRoomKey || ''));
                        if (otherRoomKey && entry && entry.otherDirection) {
                            wallDirByRoom[String(otherRoomKey)] = String(entry.otherDirection);
                        }
                    }
                });
            }
            const mesh = Home3DModels.createFurniture(
                item.type,
                structureItem && item._isInterior
                    ? { ...item, _isInterior: false }
                    : item
            );
            if (!mesh) return;
            mesh.position.set(Number(item.x || 0), 0, Number(item.z || 0));
            mesh.userData = {
                ...(mesh.userData || {}),
                isFurniture: true,
                jsonRef: item,
                monitorRoomKey: item.room || '',
                importedMonitorStructure: structureItem,
                importedMonitorWallDir: String(item._wallDir || ''),
                importedMonitorWallDirByRoom: wallDirByRoom,
                importedMonitorIsInterior: !!item._isInterior,
                importedMonitorRoomKeys: [...new Set(relatedRoomKeys)]
            };
            furnitureGroup.add(mesh);
        });

        refreshImportedPetHomeFurniturePlacements(workingLayout, furnitureGroup);

        const root = new THREE.Group();
        root.name = 'pet-imported-home-root';
        root.add(planGroup);
        root.add(furnitureGroup);

        return {
            root,
            planGroup,
            furnitureGroup,
            layout: workingLayout,
            bounds: getImportedPetHomeBounds(workingLayout.rooms || []),
            adjacencyMap
        };
    }

    function getImportedPetHomeHalfWallState(view) {
        const isFullWallMode = !view || view.wallMode === 'full';
        const isOverview = !view || view.cameraKey === PET_IMPORTED_HOME_OVERVIEW_KEY;
        const focusX = Number(
            view && view.controls && view.controls.target
                ? view.controls.target.x
                : (view && view.room ? Number(view.room.x || 0) : Number(view && view.bounds && view.bounds.centerX || 0))
        );
        const focusZ = Number(
            view && view.controls && view.controls.target
                ? view.controls.target.z
                : (view && view.room ? Number(view.room.z || 0) : Number(view && view.bounds && view.bounds.centerZ || 0))
        );
        const fromEast = !!(view && view.camera && view.camera.position.x > focusX);
        const fromSouth = !!(view && view.camera && view.camera.position.z > focusZ);
        const hiddenDirections = new Set(isFullWallMode ? [] : [
            fromSouth ? 'south' : 'north',
            fromEast ? 'east' : 'west'
        ]);
        return {
            isFullWallMode,
            isOverview,
            hiddenDirections
        };
    }

    function applyImportedPetHomeViewFilter(root, cameraKey) {
        if (!root) return;
        const isOverview = cameraKey === PET_IMPORTED_HOME_OVERVIEW_KEY;
        const planGroup = root.getObjectByName('pet-imported-home-plan');
        const furnitureGroup = root.getObjectByName('pet-imported-home-furniture');

        if (planGroup) {
            planGroup.children.forEach(child => {
                if (!child || !child.userData) return;
                if (child.userData.type === 'room') {
                    const roomKey = String(child.userData.key || '');
                    const mode = isOverview
                        ? 'overview'
                        : (roomKey === String(cameraKey || '') ? 'target' : 'hidden');

                    child.visible = mode !== 'hidden';
                    child.userData.importedPetMonitorMode = mode;

                    child.children.forEach(node => {
                        if (!node) return;
                        node.visible = mode !== 'hidden';
                    });
                } else if (child.userData.type === 'basePlatform' || child.userData.type === 'roomBorder') {
                    child.visible = isOverview;
                } else {
                    child.visible = true;
                }
            });
        }

        if (furnitureGroup) {
            furnitureGroup.children.forEach(node => {
                const relatedRoomKeys = Array.isArray(node.userData && node.userData.importedMonitorRoomKeys)
                    ? node.userData.importedMonitorRoomKeys.map(key => String(key || ''))
                    : [String(node.userData && node.userData.monitorRoomKey || '')].filter(Boolean);
                node.visible = isOverview || relatedRoomKeys.includes(String(cameraKey || ''));
            });
        }
    }

    function updateImportedPetHomeWallMode(view) {
        if (!view || !view.planGroup) return;
        const roomGroups = view.planGroup.children.filter(child => child && child.userData && child.userData.type === 'room' && child.visible);
        const { isFullWallMode, isOverview, hiddenDirections } = getImportedPetHomeHalfWallState(view);

        roomGroups.forEach(roomGroup => {
            const roomMode = String(roomGroup.userData && roomGroup.userData.importedPetMonitorMode || (isOverview ? 'overview' : 'target'));
            roomGroup.children.forEach(node => {
                if (!node) return;
                if (!(node.userData && node.userData.type === 'wall')) {
                    return;
                }

                const wallDirection = String(node.userData.direction || '');
                const shouldShowGroup = isFullWallMode || !hiddenDirections.has(wallDirection);

                node.visible = shouldShowGroup;
                node.children.forEach(mesh => {
                    if (!mesh || mesh.type !== 'Mesh') return;
                    if (isFullWallMode) {
                        mesh.visible = true;
                        return;
                    }
                    if (!shouldShowGroup) {
                        mesh.visible = false;
                        return;
                    }
                    mesh.visible = roomMode === 'overview'
                        ? !(mesh.userData && mesh.userData.isInteriorSegment)
                        : true;
                });
            });
        });
    }

    function updateImportedPetHomeStructureVisibility(view) {
        if (!view || !view.furnitureGroup) return;
        const { isFullWallMode, isOverview, hiddenDirections } = getImportedPetHomeHalfWallState(view);

        view.furnitureGroup.children.forEach(node => {
            if (!node || !node.userData) return;

            const relatedRoomKeys = Array.isArray(node.userData.importedMonitorRoomKeys)
                ? node.userData.importedMonitorRoomKeys.map(key => String(key || ''))
                : [String(node.userData.monitorRoomKey || '')].filter(Boolean);
            const baseVisible = isOverview || relatedRoomKeys.includes(String(view.cameraKey || ''));

            if (!baseVisible) {
                node.visible = false;
                return;
            }

            const isStructure = !!node.userData.importedMonitorStructure;
            const wallDirByRoom = node.userData.importedMonitorWallDirByRoom && typeof node.userData.importedMonitorWallDirByRoom === 'object'
                ? node.userData.importedMonitorWallDirByRoom
                : null;
            const wallDirection = !isOverview && wallDirByRoom && wallDirByRoom[String(view.cameraKey || '')]
                ? String(wallDirByRoom[String(view.cameraKey || '')] || '')
                : String(node.userData.importedMonitorWallDir || '');
            const isInterior = !!node.userData.importedMonitorIsInterior;

            if (!isStructure || !wallDirection) {
                node.visible = true;
                return;
            }

            const shouldHideEntire = !isFullWallMode && (
                hiddenDirections.has(wallDirection)
                || (isOverview && isInterior)
            );

            node.visible = !shouldHideEntire;
            node.traverse(child => {
                if (!child || child === node) return;
                child.visible = !shouldHideEntire;
            });
        });
    }

    function addImportedPetHomeLights(scene) {
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.68);
        scene.add(ambientLight);

        const hemiLight = new THREE.HemisphereLight(0xFFF5E6, 0xC4A882, 0.42);
        scene.add(hemiLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.84);
        dirLight.position.set(8, 15, 10);
        scene.add(dirLight);
    }

    function applyDefaultImportedPetHomeCameraPose(view, cameraEntry) {
        if (!view || !view.camera) return;
        const room = cameraEntry && cameraEntry.room ? cameraEntry.room : null;
        const bounds = room ? getImportedPetHomeRoomBounds(room) : view.bounds;
        const roomHeight = room ? Math.max(1.2, Number(room.height || 2.8)) : 2.8;
        const sizeX = Math.max(2, Number(bounds.sizeX != null ? bounds.sizeX : bounds.maxX - bounds.minX || 4));
        const sizeZ = Math.max(2, Number(bounds.sizeZ != null ? bounds.sizeZ : bounds.maxZ - bounds.minZ || 4));
        const size = Math.max(sizeX, sizeZ, 3);
        const targetX = room ? Number(room.x || 0) : Number(view.bounds.centerX || 0);
        const targetZ = room ? Number(room.z || 0) : Number(view.bounds.centerZ || 0);
        const targetY = room ? Math.max(0.7, roomHeight * 0.32) : Math.max(0.8, roomHeight * 0.38);

        if (view.controls) {
            view.controls.target.set(targetX, targetY, targetZ);
        }
        view.camera.position.set(
            targetX + size * (room ? 0.74 : 0.92),
            Math.max(room ? 2.3 : 3.8, room ? roomHeight * 1.1 : size * 0.92),
            targetZ + size * (room ? 0.72 : 0.88)
        );
        view.camera.lookAt(new THREE.Vector3(targetX, targetY, targetZ));
        if (view.controls) {
            view.controls.minDistance = Math.max(1.2, size * 0.35);
            view.controls.maxDistance = Math.max(8, size * (room ? 3.2 : 4.5));
            view.controls.enablePan = true;
            view.controls.enableDamping = true;
            view.controls.dampingFactor = 0.08;
            view.controls.update();
        }
    }

    function copyImportedPetHomeViewState(sourceView, targetView) {
        if (!sourceView || !targetView || !sourceView.controls || !targetView.controls) return;
        targetView.camera.position.copy(sourceView.camera.position);
        targetView.controls.target.copy(sourceView.controls.target);
        targetView.camera.quaternion.copy(sourceView.camera.quaternion);
        targetView.controls.update();
    }

    function ensureImportedPetHomeViewSize(view) {
        if (!view || !view.container || !view.renderer || !view.camera) return;
        const width = Math.max(1, Math.floor(view.container.clientWidth || 0));
        const height = Math.max(1, Math.floor(view.container.clientHeight || 0));
        if (width === view.width && height === view.height) return;
        view.width = width;
        view.height = height;
        view.renderer.setSize(width, height, false);
        view.camera.aspect = width / height;
        view.camera.updateProjectionMatrix();
    }

    function createImportedPetHomeControls(camera, domElement) {
        const pointerMap = new Map();
        let lastSinglePoint = null;
        let lastGesture = null;
        const minPolarAngle = 0.05;

        const controls = {
            object: camera,
            domElement,
            enabled: true,
            target: new THREE.Vector3(),
            minDistance: 1.2,
            maxDistance: 18,
            maxPolarAngle: Math.PI / 2.05,
            rotateSpeed: 0.85,
            zoomSpeed: 1,
            panSpeed: 0.8,
            enablePan: true,
            enableDamping: false,
            dampingFactor: 0.08,
            update() {},
            dispose() {
                domElement.removeEventListener('pointerdown', onPointerDown);
                domElement.removeEventListener('pointermove', onPointerMove);
                domElement.removeEventListener('pointerup', onPointerUp);
                domElement.removeEventListener('pointercancel', onPointerUp);
                domElement.removeEventListener('wheel', onWheel);
                domElement.removeEventListener('contextmenu', onContextMenu);
                pointerMap.clear();
                lastSinglePoint = null;
                lastGesture = null;
            }
        };

        const clampCameraToOrbit = () => {
            const offset = camera.position.clone().sub(controls.target);
            const spherical = new THREE.Spherical().setFromVector3(offset);
            spherical.radius = clampImportedPetHomeNumber(spherical.radius, controls.minDistance, controls.maxDistance);
            spherical.phi = clampImportedPetHomeNumber(spherical.phi, minPolarAngle, controls.maxPolarAngle);
            offset.setFromSpherical(spherical);
            camera.position.copy(controls.target).add(offset);
            camera.lookAt(controls.target);
        };

        const rotateBy = (deltaX, deltaY) => {
            const offset = camera.position.clone().sub(controls.target);
            const spherical = new THREE.Spherical().setFromVector3(offset);
            spherical.theta -= deltaX * 0.005 * controls.rotateSpeed;
            spherical.phi -= deltaY * 0.005 * controls.rotateSpeed;
            spherical.phi = clampImportedPetHomeNumber(spherical.phi, minPolarAngle, controls.maxPolarAngle);
            offset.setFromSpherical(spherical);
            camera.position.copy(controls.target).add(offset);
            camera.lookAt(controls.target);
        };

        const zoomBy = (scaleFactor) => {
            if (!Number.isFinite(scaleFactor) || scaleFactor <= 0) return;
            const offset = camera.position.clone().sub(controls.target);
            const spherical = new THREE.Spherical().setFromVector3(offset);
            spherical.radius = clampImportedPetHomeNumber(
                spherical.radius * scaleFactor,
                controls.minDistance,
                controls.maxDistance
            );
            offset.setFromSpherical(spherical);
            camera.position.copy(controls.target).add(offset);
            camera.lookAt(controls.target);
        };

        const panBy = (deltaX, deltaY) => {
            if (!controls.enablePan) return;
            const elementHeight = Math.max(1, domElement.clientHeight || 1);
            const distance = camera.position.distanceTo(controls.target);
            const targetDistance = distance * Math.tan((camera.fov * Math.PI / 180) / 2);
            const moveX = (2 * deltaX * targetDistance / elementHeight) * controls.panSpeed;
            const moveY = (2 * deltaY * targetDistance / elementHeight) * controls.panSpeed;
            const right = new THREE.Vector3();
            const up = new THREE.Vector3();
            camera.getWorldDirection(up);
            right.crossVectors(camera.up, up).normalize().multiplyScalar(moveX);
            up.copy(camera.up).normalize().multiplyScalar(moveY);
            const panOffset = right.add(up);
            controls.target.add(panOffset);
            camera.position.add(panOffset);
            clampCameraToOrbit();
        };

        const buildGestureState = () => {
            const points = Array.from(pointerMap.values());
            if (points.length < 2) return null;
            const [a, b] = points;
            return {
                centerX: (a.x + b.x) / 2,
                centerY: (a.y + b.y) / 2,
                distance: Math.hypot(a.x - b.x, a.y - b.y)
            };
        };

        const onPointerDown = (event) => {
            if (!controls.enabled) return;
            pointerMap.set(event.pointerId, { x: event.clientX, y: event.clientY });
            lastSinglePoint = pointerMap.size === 1 ? { x: event.clientX, y: event.clientY } : null;
            lastGesture = pointerMap.size >= 2 ? buildGestureState() : null;
            try {
                domElement.setPointerCapture?.(event.pointerId);
            } catch (_) {}
            event.preventDefault();
        };

        const onPointerMove = (event) => {
            if (!controls.enabled || !pointerMap.has(event.pointerId)) return;
            pointerMap.set(event.pointerId, { x: event.clientX, y: event.clientY });

            if (pointerMap.size === 1 && lastSinglePoint) {
                const deltaX = event.clientX - lastSinglePoint.x;
                const deltaY = event.clientY - lastSinglePoint.y;
                if (event.pointerType === 'mouse' && (event.buttons === 2 || event.shiftKey)) {
                    panBy(-deltaX * 0.01, deltaY * 0.01);
                } else {
                    rotateBy(deltaX, deltaY);
                }
                lastSinglePoint = { x: event.clientX, y: event.clientY };
            } else if (pointerMap.size >= 2) {
                const gesture = buildGestureState();
                if (gesture && lastGesture) {
                    panBy(-(gesture.centerX - lastGesture.centerX) * 0.01, (gesture.centerY - lastGesture.centerY) * 0.01);
                    if (gesture.distance > 0 && lastGesture.distance > 0) {
                        zoomBy(lastGesture.distance / gesture.distance);
                    }
                }
                lastGesture = gesture;
                lastSinglePoint = null;
            }
            event.preventDefault();
        };

        const onPointerUp = (event) => {
            pointerMap.delete(event.pointerId);
            try {
                domElement.releasePointerCapture?.(event.pointerId);
            } catch (_) {}
            if (pointerMap.size === 1) {
                const remainingPoint = Array.from(pointerMap.values())[0];
                lastSinglePoint = remainingPoint ? { x: remainingPoint.x, y: remainingPoint.y } : null;
                lastGesture = null;
            } else {
                lastSinglePoint = null;
                lastGesture = pointerMap.size >= 2 ? buildGestureState() : null;
            }
        };

        const onWheel = (event) => {
            if (!controls.enabled) return;
            const scaleFactor = Math.exp(event.deltaY * 0.001 * controls.zoomSpeed);
            zoomBy(scaleFactor);
            event.preventDefault();
        };

        const onContextMenu = (event) => {
            event.preventDefault();
        };

        domElement.style.touchAction = 'none';
        domElement.addEventListener('pointerdown', onPointerDown);
        domElement.addEventListener('pointermove', onPointerMove);
        domElement.addEventListener('pointerup', onPointerUp);
        domElement.addEventListener('pointercancel', onPointerUp);
        domElement.addEventListener('wheel', onWheel, { passive: false });
        domElement.addEventListener('contextmenu', onContextMenu);

        return controls;
    }

    function createImportedPetHomeView(container, prototype, cameraEntry, options = {}) {
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, options.main ? 1.5 : 1.1));
        renderer.shadowMap.enabled = false;
        container.innerHTML = '';
        container.appendChild(renderer.domElement);

        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0xE8E4DF);
        addImportedPetHomeLights(scene);

        const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
        const root = prototype.root.clone(true);
        scene.add(root);

        const controls = createImportedPetHomeControls(camera, renderer.domElement);
        controls.rotateSpeed = 0.85;
        controls.zoomSpeed = 1.0;
        controls.panSpeed = 0.8;
        controls.enableDamping = false;
        controls.dampingFactor = 0.08;
        controls.maxPolarAngle = Math.PI / 2.05;

        const view = {
            container,
            renderer,
            scene,
            camera,
            controls,
            root,
            planGroup: root.getObjectByName('pet-imported-home-plan'),
            furnitureGroup: root.getObjectByName('pet-imported-home-furniture'),
            cameraKey: cameraEntry.key,
            cameraLabel: cameraEntry.label,
            room: cameraEntry.room || null,
            wallMode: options.wallMode === 'full' ? 'full' : 'half',
            bounds: prototype.bounds,
            width: 0,
            height: 0
        };

        applyImportedPetHomeViewFilter(root, cameraEntry.key);
        applyDefaultImportedPetHomeCameraPose(view, cameraEntry);
        ensureImportedPetHomeViewSize(view);
        return view;
    }

    function disposeImportedPetHomePrototype(root) {
        if (!root) return;
        const disposedTextures = new Set();
        const disposedMaterials = new Set();
        const disposedGeometries = new Set();
        root.traverse(node => {
            if (node.geometry && !disposedGeometries.has(node.geometry)) {
                node.geometry.dispose?.();
                disposedGeometries.add(node.geometry);
            }
            const materials = Array.isArray(node.material) ? node.material : [node.material];
            materials.forEach(material => {
                if (!material || disposedMaterials.has(material)) return;
                if (material.map && !disposedTextures.has(material.map)) {
                    material.map.dispose?.();
                    disposedTextures.add(material.map);
                }
                material.dispose?.();
                disposedMaterials.add(material);
            });
        });
    }

    function destroyImportedPetHomeMonitorSession() {
        if (!petImportedHomeMonitorSession) return;

        if (petImportedHomeMonitorSession.animationId) {
            cancelAnimationFrame(petImportedHomeMonitorSession.animationId);
        }

        const allViews = [
            ...(petImportedHomeMonitorSession.cellViews || []),
            petImportedHomeMonitorSession.mainView
        ].filter(Boolean);

        allViews.forEach(view => {
            try {
                view.controls && view.controls.dispose && view.controls.dispose();
            } catch (error) {
                console.warn('Failed to dispose pet home controls:', error);
            }
            try {
                view.renderer && view.renderer.dispose && view.renderer.dispose();
            } catch (error) {
                console.warn('Failed to dispose pet home renderer:', error);
            }
            if (view.container) {
                view.container.innerHTML = '';
            }
        });

        disposeImportedPetHomePrototype(petImportedHomeMonitorSession.prototype && petImportedHomeMonitorSession.prototype.root);
        petImportedHomeMonitorSession = null;
    }

    function buildImportedPetHomeMonitorSession(contact, petSystem, layout, camGridEl, monitorSceneEl) {
        const prototype = buildImportedPetHomePrototype(layout);
        const cameraEntries = getImportedPetHomeCameraConfigs(layout).map(entry => ({
            ...entry,
            room: layout.rooms.find(room => String(room && room.key || '') === String(entry.key || '')) || null
        }));

        const selectedCameraKey = cameraEntries.some(entry => entry.key === petSystem.importedHomeSelectedCamera)
            ? petSystem.importedHomeSelectedCamera
            : cameraEntries[0].key;

        camGridEl.innerHTML = cameraEntries.map(entry => `
            <div class="pet-cam-cell ${entry.key === selectedCameraKey ? 'active' : ''}" data-room-key="${escapeHtml(entry.key)}">
                <div class="pet-cam-viewport"></div>
                <div class="pet-cam-label">${escapeHtml(entry.label)}</div>
            </div>
        `).join('');
        monitorSceneEl.innerHTML = '';

        const cellViews = [];
        const cellElements = Array.from(camGridEl.querySelectorAll('[data-room-key]'));

        cameraEntries.forEach(entry => {
            const cellEl = cellElements.find(node => String(node.dataset.roomKey || '') === String(entry.key));
            if (!cellEl) return;
            const viewportEl = cellEl.querySelector('.pet-cam-viewport');
            const view = createImportedPetHomeView(viewportEl, prototype, entry, { main: false });
            cellEl.addEventListener('click', () => {
                const currentContact = appData.aiContacts.find(item => item.id === activeChatContactId);
                if (!currentContact) return;
                const currentPetSystem = ensurePetSystem(currentContact);
                currentPetSystem.importedHomeSelectedCamera = entry.key;
                saveAppData();
                renderPetView();
            });
            cellViews.push({ ...view, cellEl });
        });

        const selectedEntry = cameraEntries.find(entry => entry.key === selectedCameraKey) || cameraEntries[0];
        const mainView = createImportedPetHomeView(monitorSceneEl, prototype, selectedEntry, { main: true });
        const matchingCellView = cellViews.find(view => view.cameraKey === selectedEntry.key);
        if (matchingCellView) {
            copyImportedPetHomeViewState(matchingCellView, mainView);
        }

        const session = {
            contactId: contact.id,
            layoutSignature: layout.signature,
            prototype,
            cameraEntries,
            camGridEl,
            monitorSceneEl,
            cellViews,
            mainView,
            selectedCameraKey,
            wallMode: petSystem.importedHomeWallMode === 'full' ? 'full' : 'half',
            animationId: 0,
            setSelectedCamera(nextKey) {
                const nextEntry = this.cameraEntries.find(entry => entry.key === nextKey) || this.cameraEntries[0];
                this.selectedCameraKey = nextEntry.key;
                this.cellViews.forEach(view => {
                    view.cellEl && view.cellEl.classList.toggle('active', view.cameraKey === nextEntry.key);
                });
                applyImportedPetHomeViewFilter(this.mainView.root, nextEntry.key);
                this.mainView.cameraKey = nextEntry.key;
                this.mainView.cameraLabel = nextEntry.label;
                this.mainView.room = nextEntry.room || null;
                const matchingView = this.cellViews.find(view => view.cameraKey === nextEntry.key);
                if (matchingView) {
                    copyImportedPetHomeViewState(matchingView, this.mainView);
                } else {
                    applyDefaultImportedPetHomeCameraPose(this.mainView, nextEntry);
                }
            },
            setWallMode(nextMode) {
                this.wallMode = nextMode === 'full' ? 'full' : 'half';
                [...this.cellViews, this.mainView].forEach(view => {
                    view.wallMode = this.wallMode;
                });
            }
        };

        const tick = () => {
            const petView = document.getElementById('pet-view');
            if (!petView || petView.classList.contains('hidden') || String(activeChatContactId || '') !== String(session.contactId || '')) {
                destroyImportedPetHomeMonitorSession();
                return;
            }
            session.animationId = requestAnimationFrame(tick);
            [...session.cellViews, session.mainView].forEach(view => {
                ensureImportedPetHomeViewSize(view);
                if (view.controls) {
                    view.controls.update();
                }
                updateImportedPetHomeWallMode(view);
                updateImportedPetHomeStructureVisibility(view);
                view.renderer.render(view.scene, view.camera);
            });
        };
        tick();
        session.setSelectedCamera(selectedCameraKey);
        session.setWallMode(session.wallMode);
        return session;
    }

    function showImportedPetHomeMonitorPlaceholder(monitorSceneEl, message) {
        if (!monitorSceneEl) return;
        if (!message) {
            monitorSceneEl.innerHTML = '';
            return;
        }
        monitorSceneEl.innerHTML = `<div class="pet-monitor-loading">${escapeHtml(message)}</div>`;
    }

    function updatePetHomeImportMeta(contact) {
        const metaEl = document.getElementById('pet-home-import-meta');
        if (!metaEl) return;
        const petSystem = contact ? ensurePetSystem(contact) : null;
        if (!hasImportedPetHomeLayout(petSystem)) {
            metaEl.textContent = '';
            return;
        }
        const layout = petSystem.importedHomeLayout;
        metaEl.textContent = `当前已导入 ${layout.rooms.length} 个房间 / ${Array.isArray(layout.furniture) ? layout.furniture.length : 0} 件家具`;
    }

    function openPetHomeImportModal(contact) {
        const modal = document.getElementById('pet-home-import-modal');
        const textarea = document.getElementById('pet-home-import-textarea');
        const fileInput = document.getElementById('pet-home-import-file');
        if (!modal || !textarea) return;
        if (fileInput) fileInput.value = '';
        textarea.value = '';
        updatePetHomeImportMeta(contact);
        modal.classList.remove('hidden');
        setTimeout(() => textarea.focus(), 0);
    }

    function closePetHomeImportModal() {
        const modal = document.getElementById('pet-home-import-modal');
        const textarea = document.getElementById('pet-home-import-textarea');
        const fileInput = document.getElementById('pet-home-import-file');
        if (fileInput) fileInput.value = '';
        if (textarea) textarea.value = '';
        if (modal) modal.classList.add('hidden');
    }

    function getImportedPetHomeWallModeLabel(petSystem) {
        return petSystem && petSystem.importedHomeWallMode === 'full' ? '全墙' : '半墙';
    }

    function renderImportedPetHomeMonitorOverlay(contact, petSystem, selectedEntry, monitorCaptionEl, monitorInteractiveEl) {
        const pets = Array.isArray(petSystem && petSystem.pets) ? petSystem.pets : [];
        const selectedPet = pets.find(pet => pet.id === petSystem.selectedPetId) || pets[0] || null;
        const roomLabel = selectedEntry && selectedEntry.label ? selectedEntry.label : '全景';
        const contactLabel = contact && (contact.remark || contact.name) ? (contact.remark || contact.name) : 'char';
        const envText = roomLabel;
        const charText = contactLabel;
        const petText = selectedPet
            ? `${selectedPet.name}${selectedPet.species ? ` · ${getPetSpeciesMeta(selectedPet.species).label}` : ''}`
            : '宠物';

        if (monitorCaptionEl) {
            monitorCaptionEl.textContent = `${roomLabel}镜头`;
        }

        if (!monitorInteractiveEl) return;
        const charEscaped = escapeHtml(charText).replace(/'/g, "\\'");
        const petEscaped = escapeHtml(petText).replace(/'/g, "\\'");
        const envEscaped = escapeHtml(envText).replace(/'/g, "\\'");
        monitorInteractiveEl.innerHTML = `
            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${charEscaped}')">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
            </div>
            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${petEscaped}')">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg>
            </div>
            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${envEscaped}')">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg>
            </div>
        `;
    }

    function renderImportedPetHomeMonitor(contact, petSystem, camGridEl, monitorSceneEl, monitorCaptionEl, monitorInteractiveEl) {
        if (!hasImportedPetHomeLayout(petSystem)) {
            destroyImportedPetHomeMonitorSession();
            return false;
        }

        const layout = petSystem.importedHomeLayout;
        const cameraEntries = getImportedPetHomeCameraConfigs(layout);
        const selectedCameraKey = cameraEntries.some(entry => entry.key === petSystem.importedHomeSelectedCamera)
            ? petSystem.importedHomeSelectedCamera
            : cameraEntries[0].key;
        const selectedEntry = cameraEntries.find(entry => entry.key === selectedCameraKey) || cameraEntries[0];

        renderImportedPetHomeMonitorOverlay(contact, petSystem, selectedEntry, monitorCaptionEl, monitorInteractiveEl);

        if (
            petImportedHomeMonitorSession
            && String(petImportedHomeMonitorSession.contactId) === String(contact.id)
            && String(petImportedHomeMonitorSession.layoutSignature || '') === String(layout.signature || '')
            && petImportedHomeMonitorSession.camGridEl === camGridEl
            && petImportedHomeMonitorSession.monitorSceneEl === monitorSceneEl
        ) {
            petImportedHomeMonitorSession.setSelectedCamera(selectedCameraKey);
            petImportedHomeMonitorSession.setWallMode(petSystem.importedHomeWallMode);
            return true;
        }

        destroyImportedPetHomeMonitorSession();
        showImportedPetHomeMonitorPlaceholder(monitorSceneEl, '');
        camGridEl.innerHTML = cameraEntries.map(entry => `
            <div class="pet-cam-cell ${entry.key === selectedCameraKey ? 'active' : ''}" data-room-key="${escapeHtml(entry.key)}">
                <div class="pet-cam-viewport">
                    <div class="pet-monitor-loading">${escapeHtml(entry.label)}</div>
                </div>
                <div class="pet-cam-label">${escapeHtml(entry.label)}</div>
            </div>
        `).join('');

        const loadToken = ++petImportedHomeMonitorLoadToken;
        ensureImportedPetHomeLibraries().then(() => {
            if (loadToken !== petImportedHomeMonitorLoadToken) return;
            const activeContact = appData.aiContacts.find(item => item.id === activeChatContactId);
            if (!activeContact || String(activeContact.id) !== String(contact.id)) return;
            const activePetSystem = ensurePetSystem(activeContact);
            if (!hasImportedPetHomeLayout(activePetSystem)) return;
            if (String(activePetSystem.importedHomeLayout.signature || '') !== String(layout.signature || '')) return;
            destroyImportedPetHomeMonitorSession();
            petImportedHomeMonitorSession = buildImportedPetHomeMonitorSession(activeContact, activePetSystem, activePetSystem.importedHomeLayout, camGridEl, monitorSceneEl);
            petImportedHomeMonitorSession.setSelectedCamera(activePetSystem.importedHomeSelectedCamera);
            petImportedHomeMonitorSession.setWallMode(activePetSystem.importedHomeWallMode);
        }).catch(error => {
            if (loadToken !== petImportedHomeMonitorLoadToken) return;
            console.warn('Imported pet home monitor init failed:', error);
            camGridEl.innerHTML = '';
            showImportedPetHomeMonitorPlaceholder(monitorSceneEl, '');
            if (monitorCaptionEl) {
                monitorCaptionEl.textContent = '';
            }
        });

        return true;
    }

    window.__selectPetRoom = function(roomKey) {
        const c = appData.aiContacts.find(x => x.id === activeChatContactId);
        if(c && c.petSystem) {
            const petSystem = ensurePetSystem(c);
            if (hasImportedPetHomeLayout(petSystem) && getImportedPetHomeCameraConfigs(petSystem.importedHomeLayout).some(entry => entry.key === roomKey)) {
                petSystem.importedHomeSelectedCamera = roomKey;
            } else {
                petSystem.selectedRoom = roomKey;
            }
            saveAppData();
            renderPetView();
        }
    };

    window.__selectPet = function(petId) {
        const c = appData.aiContacts.find(x => x.id === activeChatContactId);
        if(c && c.petSystem) {
            c.petSystem.selectedPetId = petId;
            saveAppData();
            renderPetView();
        }
    };

    window.__deletePet = function(petId, petName) {
        if(confirm('确认删除宠物 ' + petName + ' 吗？')) {
            const c = appData.aiContacts.find(x => x.id === activeChatContactId);
            if(c && c.petSystem) {
                c.petSystem.pets = c.petSystem.pets.filter(p => p.id !== petId);
                if (c.petSystem.selectedPetId === petId) c.petSystem.selectedPetId = null;
                saveAppData();
                renderPetView();
            }
        }
    };

    window.__showPetTooltip = function(htmlContent) {
        const tooltip = document.getElementById('pet-monitor-tooltip');
        if(tooltip) {
            tooltip.innerHTML = htmlContent;
            tooltip.classList.remove('hidden');
            // 自动隐藏逻辑
            if(tooltip.timeout) clearTimeout(tooltip.timeout);
            tooltip.timeout = setTimeout(() => { tooltip.classList.add('hidden'); }, 4000);
        }
    };

    function renderPetViewV2() {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        const emptyStateEl = document.getElementById('pet-empty-state');
        const petListEl = document.getElementById('pet-list');
        const petProfileEl = document.getElementById('pet-profile-content');
        const petEventsEl = document.getElementById('pet-event-log');
        const monitorSceneEl = document.getElementById('pet-monitor-scene');
        const monitorCaptionEl = document.getElementById('pet-monitor-caption');
        const monitorInteractiveEl = document.getElementById('pet-monitor-interactive-layer');
        const camGridEl = document.getElementById('pet-cam-grid');
        const importHomeButton = document.getElementById('pet-import-home-btn');
        const importHomeModal = document.getElementById('pet-home-import-modal');
        const importHomeTextarea = document.getElementById('pet-home-import-textarea');
        const importHomeFileInput = document.getElementById('pet-home-import-file');
        const importHomeFileButton = document.getElementById('pet-home-import-file-btn');
        const importHomeSaveButton = document.getElementById('pet-home-import-save-btn');
        const importHomeClearButton = document.getElementById('pet-home-import-clear-btn');
        const importHomeCloseButton = document.getElementById('pet-home-import-close-btn');
        const importedWallModeButton = document.getElementById('pet-imported-wall-mode-btn');

        if (importHomeButton && !importHomeButton.dataset.idicBound) {
            importHomeButton.dataset.idicBound = '1';
            importHomeButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                openPetHomeImportModal(contact);
            });
        }

        if (importHomeModal && !importHomeModal.dataset.idicBound) {
            importHomeModal.dataset.idicBound = '1';
            importHomeModal.addEventListener('click', event => {
                if (event.target === importHomeModal) {
                    closePetHomeImportModal();
                }
            });
        }

        if (importHomeCloseButton && !importHomeCloseButton.dataset.idicBound) {
            importHomeCloseButton.dataset.idicBound = '1';
            importHomeCloseButton.addEventListener('click', () => {
                closePetHomeImportModal();
            });
        }

        if (importHomeFileButton && importHomeFileInput && !importHomeFileButton.dataset.idicBound) {
            importHomeFileButton.dataset.idicBound = '1';
            importHomeFileButton.addEventListener('click', () => {
                importHomeFileInput.click();
            });
        }

        if (importHomeFileInput && importHomeTextarea && !importHomeFileInput.dataset.idicBound) {
            importHomeFileInput.dataset.idicBound = '1';
            importHomeFileInput.addEventListener('change', () => {
                const file = importHomeFileInput.files && importHomeFileInput.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = () => {
                    importHomeTextarea.value = String(reader.result || '');
                };
                reader.onerror = () => {
                    showToast('房屋 JSON 读取失败', 'error');
                };
                reader.readAsText(file, 'utf-8');
                importHomeFileInput.value = '';
            });
        }

        if (importHomeSaveButton && importHomeTextarea && !importHomeSaveButton.dataset.idicBound) {
            importHomeSaveButton.dataset.idicBound = '1';
            importHomeSaveButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const rawText = String(importHomeTextarea.value || '').trim();
                if (!rawText) {
                    showToast('先粘贴或导入房屋 JSON', 'info');
                    return;
                }
                try {
                    const parsed = parseJsonLike(rawText);
                    if (!parsed) {
                        throw new Error('JSON 无法解析');
                    }
                    const petSystem = ensurePetSystem(contact);
                    petSystem.importedHomeLayout = normalizeImportedPetHomeLayout(parsed, rawText);
                    petSystem.importedHomeSelectedCamera = PET_IMPORTED_HOME_OVERVIEW_KEY;
                    saveAppData();
                    closePetHomeImportModal();
                    destroyImportedPetHomeMonitorSession();
                    renderPetView();
                    showToast('房屋已导入宠物监控', 'success');
                } catch (error) {
                    showToast(`房屋导入失败：${String(error && error.message ? error.message : error)}`, 'error');
                }
            });
        }

        if (importHomeClearButton && !importHomeClearButton.dataset.idicBound) {
            importHomeClearButton.dataset.idicBound = '1';
            importHomeClearButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                petSystem.importedHomeLayout = null;
                petSystem.importedHomeSelectedCamera = PET_IMPORTED_HOME_OVERVIEW_KEY;
                if (petImportedHomeMonitorSession && String(petImportedHomeMonitorSession.contactId) === String(contact.id)) {
                    destroyImportedPetHomeMonitorSession();
                }
                saveAppData();
                closePetHomeImportModal();
                renderPetView();
                showToast('已移除房屋监控', 'success');
            });
        }

        if (importedWallModeButton && !importedWallModeButton.dataset.idicBound) {
            importedWallModeButton.dataset.idicBound = '1';
            importedWallModeButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                if (!hasImportedPetHomeLayout(petSystem)) return;
                petSystem.importedHomeWallMode = petSystem.importedHomeWallMode === 'full' ? 'half' : 'full';
                saveAppData();
                if (petImportedHomeMonitorSession) {
                    petImportedHomeMonitorSession.setWallMode(petSystem.importedHomeWallMode);
                }
                renderPetView();
            });
        }

        const refreshMonitorButton = document.getElementById('pet-refresh-monitor-btn');

        if (!contact || !petListEl || !petProfileEl || !petEventsEl || !monitorSceneEl || !monitorCaptionEl || !camGridEl) {
            return;
        }

        const petSystem = ensurePetSystem(contact);
        const hasImportedHomeLayout = hasImportedPetHomeLayout(petSystem);
        if (importedWallModeButton) {
            importedWallModeButton.classList.toggle('hidden', !hasImportedHomeLayout);
            importedWallModeButton.textContent = getImportedPetHomeWallModeLabel(petSystem);
        }
        if (!hasImportedHomeLayout) {
            const eventResult = petSystem.isMonitorRefreshing
                ? { triggered: false, type: 'none', pets: [] }
                : maybeTriggerPetButterflyEvent(contact, { reason: 'panel_open' });
            if (eventResult && eventResult.triggered) {
                saveAppData();
            }
            updatePetSystemState(contact, { persist: true });
        }

        const pets = petSystem.pets || [];
        const selectedPet = pets.find(pet => pet.id === petSystem.selectedPetId) || pets[0] || null;
        const snapshot = hasImportedHomeLayout ? null : buildPetMonitorSnapshot(contact);
        const hasAiMonitorCache = !hasImportedHomeLayout && !!(petSystem.monitorCache && petSystem.monitorCache.generatedAt && petSystem.monitorCache.roomsByKey && Object.keys(petSystem.monitorCache.roomsByKey).length > 0);

        const messageFavoritesList = document.getElementById('message-favorites-list');
        if (messageFavoritesList && !messageFavoritesList.dataset.idicBound) {
            messageFavoritesList.dataset.idicBound = '1';
            // Bind to document.body to support actions from full screen modal which is outside messageFavoritesList
            document.body.addEventListener('click', (event) => {
                const assetTrigger = event.target.closest('img[data-favorite-preview-asset="1"]');
                if (assetTrigger) {
                    previewMessageFavoriteAsset(assetTrigger.dataset.favoriteId, assetTrigger.dataset.snapshotIndex);
                    return;
                }

                const actionButton = event.target.closest('[data-fav-action]');
                if (!actionButton) return;

                const favoriteId = actionButton.dataset.favoriteId;
                const snapshotIndex = actionButton.dataset.snapshotIndex;
                const action = actionButton.dataset.favAction;

                if (action === 'open-source') {
                    openMessageFavoriteSource(favoriteId);
                } else if (action === 'toggle-love') {
                    toggleMessageFavoriteLove(favoriteId);
                } else if (action === 'edit-note') {
                    editMessageFavoriteNote(favoriteId);
                } else if (action === 'edit-group') {
                    editMessageFavoriteGroups(favoriteId);
                } else if (action === 'remove-favorite') {
                    removeMessageFavoriteItem(favoriteId);
                } else if (action === 'open-html') {
                    openMessageFavoriteHtmlPreview(favoriteId, snapshotIndex);
                } else if (action === 'open-html-code') {
                    openMessageFavoriteHtmlCodePreview(favoriteId, snapshotIndex);
                }
            });
        }

        const selectedRoomKey = PET_ROOM_CONFIGS.some(room => room.key === petSystem.selectedRoom)
            ? petSystem.selectedRoom
            : 'living_room';
        const cachedRoomScene = hasAiMonitorCache ? petSystem.monitorCache.roomsByKey[selectedRoomKey] : null;
        const roomScene = hasImportedHomeLayout ? null : (cachedRoomScene || buildFallbackPetMonitorRoom(contact, selectedRoomKey, snapshot));
        const selectedPetRoomHint = !hasImportedHomeLayout && selectedPet && !(Array.isArray(roomScene.visiblePetIds) && roomScene.visiblePetIds.includes(selectedPet.id))
            ? (() => {
                const roomEntry = PET_ROOM_CONFIGS.find(room => {
                    const cachedRoom = petSystem.monitorCache && petSystem.monitorCache.roomsByKey
                        ? petSystem.monitorCache.roomsByKey[room.key]
                        : null;
                    return cachedRoom && Array.isArray(cachedRoom.visiblePetIds) && cachedRoom.visiblePetIds.includes(selectedPet.id);
                });
                return roomEntry ? `当前选中的 ${selectedPet.name} 更可能在 ${roomEntry.label}。` : '';
            })()
            : '';

        if (refreshMonitorButton) {
            refreshMonitorButton.disabled = !hasImportedHomeLayout && !!petSystem.isMonitorRefreshing;
        }

        if (pets.length === 0 && !hasImportedHomeLayout) {
            if (emptyStateEl) {
                emptyStateEl.classList.add('hidden');
                emptyStateEl.innerHTML = '';
            }
            petListEl.innerHTML = '';
            petProfileEl.innerHTML = '';
            petEventsEl.innerHTML = '';
            camGridEl.innerHTML = '';
            showImportedPetHomeMonitorPlaceholder(monitorSceneEl, '');
            monitorCaptionEl.textContent = '';
            if (monitorInteractiveEl) monitorInteractiveEl.innerHTML = '';
            destroyImportedPetHomeMonitorSession();
            return;
        }

        if (emptyStateEl) {
            emptyStateEl.classList.add('hidden');
            emptyStateEl.innerHTML = '';
        }

        const importedHomeRendered = hasImportedHomeLayout
            ? renderImportedPetHomeMonitor(contact, petSystem, camGridEl, monitorSceneEl, monitorCaptionEl, monitorInteractiveEl)
            : false;

        if (!importedHomeRendered) {
            camGridEl.innerHTML = PET_ROOM_CONFIGS.map(room => {
                const rScene = hasAiMonitorCache && petSystem.monitorCache.roomsByKey[room.key]
                    ? petSystem.monitorCache.roomsByKey[room.key]
                    : null;
                const activeClass = selectedRoomKey === room.key ? 'active' : '';
                const petCount = rScene && rScene.visiblePetIds ? rScene.visiblePetIds.length : 0;
                const badgeHtml = petCount > 0 ? `<div class="pet-cam-badge"><svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg> ${petCount}</div>` : '';
                return `
                    <div class="pet-cam-cell ${activeClass}" data-room-key="${room.key}" onclick="window.__selectPetRoom('${room.key}')">
                        ${badgeHtml}
                        <div class="pet-cam-label">${escapeHtml(room.label)}</div>
                    </div>
                `;
            }).join('');

            if (petSystem.isMonitorRefreshing) {
                monitorCaptionEl.innerHTML = '';
                if (monitorInteractiveEl) monitorInteractiveEl.innerHTML = '';
            } else {
                const charText = roomScene.charText || (snapshot.charVisible ? `${contact.remark || contact.name || '角色'}：${snapshot.presence.activityText}` : '');
                const overviewText = roomScene.monitorText || roomScene.overview || selectedPetRoomHint || '';
                monitorCaptionEl.textContent = overviewText;

                if (monitorInteractiveEl) {
                    let interactiveHtml = '';
                    if (charText) {
                        const charEscaped = escapeHtml(charText).replace(/'/g, "\\'");
                        interactiveHtml += `
                            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${charEscaped}')">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                            </div>
                        `;
                    }

                    const visiblePets = roomScene.visiblePetIds && roomScene.petSpots ? roomScene.petSpots : [];
                    if (visiblePets.length > 0) {
                        let petTooltipHtml = '';
                        visiblePets.forEach(spot => {
                            const pet = pets.find(item => item.id === spot.pet_id);
                            if (pet) {
                                petTooltipHtml += `<div><strong>${escapeHtml(pet.name)}</strong>: ${escapeHtml(spot.action || spot.mood || '正在活动')}</div>`;
                            }
                        });
                        const petEscaped = petTooltipHtml.replace(/'/g, "\\'");
                        interactiveHtml += `
                            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${petEscaped}')">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg>
                            </div>
                        `;
                    } else if (roomScene.emptyNote) {
                        const emptyEscaped = escapeHtml(roomScene.emptyNote).replace(/'/g, "\\'");
                        interactiveHtml += `
                            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${emptyEscaped}')">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg>
                            </div>
                        `;
                    }

                    if (roomScene.ambience) {
                        const envEscaped = escapeHtml(roomScene.ambience).replace(/'/g, "\\'");
                        interactiveHtml += `
                            <div class="pet-cam-icon" onclick="window.__showPetTooltip('${envEscaped}')">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg>
                            </div>
                        `;
                    }

                    monitorInteractiveEl.innerHTML = interactiveHtml;
                }
            }
        }

        if (pets.length === 0) {
            petListEl.innerHTML = '';
            petProfileEl.innerHTML = '';
            petEventsEl.innerHTML = '';
            return;
        }

        petListEl.innerHTML = pets.map(pet => {
            const isActive = selectedPet && selectedPet.id === pet.id;
            const buildBar = (label, value) => {
                const safeVal = value !== undefined ? value : 50;
                const color = safeVal > 70 ? '#6BA3BE' : (safeVal > 30 ? '#ECA06C' : '#E07A5F');
                return `
                    <div style="display: flex; align-items: center; gap: 6px; margin-top: 5px;">
                        <span style="font-size: 11px; color: #7B8C9E; width: 28px; flex-shrink: 0; letter-spacing: 1px;">${label}</span>
                        <div style="flex: 1; height: 6px; background: rgba(180,160,140,0.15); border-radius: 3px; overflow: hidden;">
                            <div style="width: ${Math.max(0, Math.min(100, safeVal))}%; height: 100%; background: ${color}; border-radius: 3px; transition: width 0.3s ease;"></div>
                        </div>
                    </div>
                `;
            };

            return `
                <div class="pet-card ${isActive ? 'active' : ''}" data-pet-id="${pet.id}" onclick="window.__selectPet('${pet.id}')">
                    <div class="pet-card-name">${escapeHtml(pet.name)}</div>
                    <div class="pet-card-breed">${escapeHtml(getPetSpeciesMeta(pet.species).label)}${pet.breed ? ` · ${escapeHtml(pet.breed)}` : ''}</div>
                    <div class="pet-card-status" style="margin-top: 12px;">
                        ${buildBar('饱食', pet.satiety)}
                        ${buildBar('饮水', pet.hydration)}
                        ${buildBar('心情', pet.fun)}
                        ${buildBar('饭盆', pet.foodBowl)}
                        ${buildBar('水碗', pet.waterBowl)}
                    </div>
                </div>
            `;
        }).join('');

        if (selectedPet) {
            const getSatietyDesc = (v) => v > 80 ? '吃得很饱，肚子圆滚滚的' : v > 50 ? '不饿，饮食正常' : v > 20 ? '肚子有些饿了，可能在找吃的' : '非常饥饿，急需喂食';
            const getHydrationDesc = (v) => v > 70 ? '水分充足' : v > 30 ? '偶尔去喝口水' : '口渴了，水碗可能空了';
            const getFunDesc = (v) => v > 80 ? '自娱自乐，非常开心' : v > 40 ? '情绪平稳' : '觉得无聊，需要陪伴';
            const getBowlDesc = (v) => v > 80 ? '几乎是满的' : v > 30 ? '还剩大半' : v > 10 ? '快见底了' : '完全空了';

            petProfileEl.innerHTML = `
                <div style="position: relative;">
                    <button onclick="window.__deletePet('${selectedPet.id}', '${escapeHtml(selectedPet.name)}')" title="删除当前宠物" style="position: absolute; top: -4px; right: -4px; background: transparent; border: none; color: #A0ADB8; cursor: pointer; padding: 4px; border-radius: 4px; transition: all 0.2s;" onmouseover="this.style.color='#E07A5F'; this.style.background='rgba(224,122,95,0.1)';" onmouseout="this.style.color='#A0ADB8'; this.style.background='transparent';">
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
                    </button>
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; padding-right: 24px;">
                        <div><span style="color: #A0ADB8; font-size: 11px;">物种</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetSpeciesMeta(selectedPet.species).label)} ${escapeHtml(selectedPet.breed || '')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">性别/年龄</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetSexLabel(selectedPet.sex))} · ${escapeHtml(selectedPet.age || '未知')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">性格</span><br><strong style="color: #2C3E50;">${escapeHtml(selectedPet.personality || '未记录')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">常待房间</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetRoomLabel(selectedPet.homeRoom))}</strong></div>
                    </div>
                    <div style="border-top: 1px dashed rgba(180,160,140,0.2); padding-top: 12px;">
                        <div style="margin-bottom: 8px;"><strong>状态评估：</strong></div>
                        <ul style="padding-left: 20px; line-height: 1.8; margin: 0;">
                            <li><strong>饱食：</strong>${getSatietyDesc(selectedPet.satiety)}</li>
                            <li><strong>饮水：</strong>${getHydrationDesc(selectedPet.hydration)}</li>
                            <li><strong>情绪：</strong>${getFunDesc(selectedPet.fun)}</li>
                            <li><strong>饭盆状态：</strong>${getBowlDesc(selectedPet.foodBowl)}</li>
                            <li><strong>水碗状态：</strong>${getBowlDesc(selectedPet.waterBowl)}</li>
                        </ul>
                    </div>
                </div>
            `;
        } else {
            petProfileEl.innerHTML = '';
        }

        const recentEvents = (petSystem.eventLog || []).slice(0, 8);
        petEventsEl.innerHTML = recentEvents.length > 0
            ? recentEvents.map(entry => `
                <div style="margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid rgba(180,160,140,0.1);">
                    <div style="display: flex; justify-content: space-between; align-items: center;">
                        <strong style="color: #2C3E50;">${escapeHtml(entry.title || '宠物动态')}</strong>
                        <span style="font-size: 11px; color: #A0ADB8;">${escapeHtml(new Date(entry.timestamp || Date.now()).toLocaleString('zh-CN', {month:'numeric', day:'numeric', hour:'numeric', minute:'numeric'}))}</span>
                    </div>
                    <div style="margin-top: 4px; color: #5A6A7A;">${escapeHtml(entry.description || '')}</div>
                </div>
            `).join('')
            : '';
    }

    function renderPetView() {
        return renderPetViewV2();
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        const emptyStateEl = document.getElementById('pet-empty-state');
        const petListEl = document.getElementById('pet-list');
        const petProfileEl = document.getElementById('pet-profile-content');
        const petEventsEl = document.getElementById('pet-event-log');
        const monitorSceneEl = document.getElementById('pet-monitor-scene');
        const monitorCaptionEl = document.getElementById('pet-monitor-caption');
        const monitorInteractiveEl = document.getElementById('pet-monitor-interactive-layer');
        const camGridEl = document.getElementById('pet-cam-grid');
        const refreshMonitorButton = document.getElementById('pet-refresh-monitor-btn');

        if (!contact || !petListEl || !petProfileEl || !petEventsEl || !monitorSceneEl || !monitorCaptionEl || !camGridEl) {
            return;
        }

        const petSystem = ensurePetSystem(contact);
        const eventResult = petSystem.isMonitorRefreshing
            ? { triggered: false, type: 'none', pets: [] }
            : maybeTriggerPetButterflyEvent(contact, { reason: 'panel_open' });
        if (eventResult && eventResult.triggered) {
            saveAppData();
        }
        updatePetSystemState(contact, { persist: true });

        const pets = petSystem.pets || [];
        const selectedPet = pets.find(pet => pet.id === petSystem.selectedPetId) || pets[0] || null;
        const snapshot = buildPetMonitorSnapshot(contact);
        const hasAiMonitorCache = !!(petSystem.monitorCache && petSystem.monitorCache.generatedAt && petSystem.monitorCache.roomsByKey && Object.keys(petSystem.monitorCache.roomsByKey).length > 0);
        
        const selectedRoomKey = PET_ROOM_CONFIGS.some(room => room.key === petSystem.selectedRoom)
            ? petSystem.selectedRoom
            : 'living_room';
            
        const cachedRoomScene = hasAiMonitorCache ? petSystem.monitorCache.roomsByKey[selectedRoomKey] : null;
        const roomScene = cachedRoomScene || buildFallbackPetMonitorRoom(contact, selectedRoomKey, snapshot);

        if (refreshMonitorButton) {
            refreshMonitorButton.disabled = !!petSystem.isMonitorRefreshing;
        }

        if (pets.length === 0) {
            if (emptyStateEl) emptyStateEl.classList.add('hidden');
            if (emptyStateEl) emptyStateEl.innerHTML = '';
            petListEl.innerHTML = '';
            petProfileEl.innerHTML = '';
            petEventsEl.innerHTML = '';
            camGridEl.innerHTML = '';
            monitorSceneEl.innerHTML = '';
            monitorCaptionEl.textContent = '';
            if (monitorInteractiveEl) monitorInteractiveEl.innerHTML = '';
            return;
        }
        
        if (emptyStateEl) emptyStateEl.classList.add('hidden');

        // 1. 渲染多画面监控网格 (Cam Grid) - 移除 emoji
        camGridEl.innerHTML = PET_ROOM_CONFIGS.map(room => {
            const rScene = hasAiMonitorCache && petSystem.monitorCache.roomsByKey[room.key] 
                ? petSystem.monitorCache.roomsByKey[room.key] 
                : null;
            const activeClass = selectedRoomKey === room.key ? 'active' : '';
            const petCount = rScene && rScene.visiblePetIds ? rScene.visiblePetIds.length : 0;
            const badgeHtml = petCount > 0 ? `<div class="pet-cam-badge"><svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg> ${petCount}</div>` : '';
            
            return `
                <div class="pet-cam-cell ${activeClass}" data-room-key="${room.key}" onclick="window.__selectPetRoom('${room.key}')">
                    ${badgeHtml}
                    <div class="pet-cam-label">${escapeHtml(room.label)}</div>
                </div>
            `;
        }).join('');

        // 2. 渲染主监控描述与交互浮层
        if (petSystem.isMonitorRefreshing) {
            monitorCaptionEl.innerHTML = '';
            if (monitorInteractiveEl) monitorInteractiveEl.innerHTML = '';
        } else {
            const charText = roomScene.charText || (snapshot.charVisible ? `${contact.remark || contact.name || '角色'}：${snapshot.presence.activityText}` : '');
            const overviewText = roomScene.monitorText || roomScene.overview || selectedPetRoomHint || '';
            
            // 底部一句话总览
            monitorCaptionEl.textContent = overviewText;
            
            // 右上角交互图标生成
            if (monitorInteractiveEl) {
                let interactiveHtml = '';
                // 角色图标
                if (charText) {
                    const charEscaped = escapeHtml(charText).replace(/'/g, "\\'");
                    interactiveHtml += `
                        <div class="pet-cam-icon" onclick="window.__showPetTooltip('${charEscaped}')">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                        </div>
                    `;
                }
                
                const visiblePets = roomScene.visiblePetIds && roomScene.petSpots ? roomScene.petSpots : [];
                // 宠物图标
                if (visiblePets.length > 0) {
                    let petTooltipHtml = '';
                    visiblePets.forEach(spot => {
                        const p = pets.find(x => x.id === spot.pet_id);
                        if(p) petTooltipHtml += `<div><strong>${escapeHtml(p.name)}</strong>: ${escapeHtml(spot.action || spot.mood || '正在活动')}</div>`;
                    });
                    const petEscaped = petTooltipHtml.replace(/'/g, "\\'");
                    interactiveHtml += `
                        <div class="pet-cam-icon" onclick="window.__showPetTooltip('${petEscaped}')">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg>
                        </div>
                    `;
                } else if (roomScene.emptyNote) {
                    // 如果没有宠物，但有空状态说明，则显示一个宠物图标来提示“这里没有宠物”
                    const emptyEscaped = escapeHtml(roomScene.emptyNote).replace(/'/g, "\\'");
                    interactiveHtml += `
                        <div class="pet-cam-icon" onclick="window.__showPetTooltip('${emptyEscaped}')">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"></path></svg>
                        </div>
                    `;
                }

                // 环境图标
                if (roomScene.ambience) {
                    const envEscaped = escapeHtml(roomScene.ambience).replace(/'/g, "\\'");
                    interactiveHtml += `
                        <div class="pet-cam-icon" onclick="window.__showPetTooltip('${envEscaped}')">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg>
                        </div>
                    `;
                }
                
                monitorInteractiveEl.innerHTML = interactiveHtml;
            }
        }

        // 3. 渲染宠物列表卡片（采用进度条样式）
        petListEl.innerHTML = pets.map(pet => {
            const isActive = selectedPet && selectedPet.id === pet.id;
            
            // 进度条生成辅助函数
            const buildBar = (label, value) => {
                const safeVal = value !== undefined ? value : 50; // default value if missing
                const color = safeVal > 70 ? '#6BA3BE' : (safeVal > 30 ? '#ECA06C' : '#E07A5F');
                return `
                    <div style="display: flex; align-items: center; gap: 6px; margin-top: 5px;">
                        <span style="font-size: 11px; color: #7B8C9E; width: 28px; flex-shrink: 0; letter-spacing: 1px;">${label}</span>
                        <div style="flex: 1; height: 6px; background: rgba(180,160,140,0.15); border-radius: 3px; overflow: hidden;">
                            <div style="width: ${Math.max(0, Math.min(100, safeVal))}%; height: 100%; background: ${color}; border-radius: 3px; transition: width 0.3s ease;"></div>
                        </div>
                    </div>
                `;
            };
            
            return `
                <div class="pet-card ${isActive ? 'active' : ''}" data-pet-id="${pet.id}" onclick="window.__selectPet('${pet.id}')">
                    <div class="pet-card-name">${escapeHtml(pet.name)}</div>
                    <div class="pet-card-breed">${escapeHtml(getPetSpeciesMeta(pet.species).label)}${pet.breed ? ` · ${escapeHtml(pet.breed)}` : ''}</div>
                    <div class="pet-card-status" style="margin-top: 12px;">
                        ${buildBar('饱食', pet.satiety)}
                        ${buildBar('饮水', pet.hydration)}
                        ${buildBar('心情', pet.fun)}
                        ${buildBar('饭盆', pet.foodBowl)}
                        ${buildBar('水碗', pet.waterBowl)}
                    </div>
                </div>
            `;
        }).join('');

        // 4. 渲染宠物详细信息（语义化）
        if (selectedPet) {
            // 将数值转化为语义
            const getSatietyDesc = (v) => v > 80 ? '吃得很饱，肚子圆滚滚的' : v > 50 ? '不饿，饮食正常' : v > 20 ? '肚子有些饿了，可能在找吃的' : '非常饥饿，急需喂食！';
            const getHydrationDesc = (v) => v > 70 ? '水分充足' : v > 30 ? '偶尔去喝口水' : '口渴了，水碗可能空了';
            const getFunDesc = (v) => v > 80 ? '自娱自乐，非常开心' : v > 40 ? '情绪平稳' : '觉得无聊，需要陪伴';
            const getBowlDesc = (v) => v > 80 ? '几乎是满的' : v > 30 ? '还剩大半' : v > 10 ? '快见底了' : '完全空了';

            petProfileEl.innerHTML = `
                <div style="position: relative;">
                    <button onclick="window.__deletePet('${selectedPet.id}', '${escapeHtml(selectedPet.name)}')" title="删除当前宠物" style="position: absolute; top: -4px; right: -4px; background: transparent; border: none; color: #A0ADB8; cursor: pointer; padding: 4px; border-radius: 4px; transition: all 0.2s;" onmouseover="this.style.color='#E07A5F'; this.style.background='rgba(224,122,95,0.1)';" onmouseout="this.style.color='#A0ADB8'; this.style.background='transparent';">
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
                    </button>
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; padding-right: 24px;">
                        <div><span style="color: #A0ADB8; font-size: 11px;">物种</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetSpeciesMeta(selectedPet.species).label)} ${escapeHtml(selectedPet.breed || '')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">性别/年龄</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetSexLabel(selectedPet.sex))} · ${escapeHtml(selectedPet.age || '未知')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">性格</span><br><strong style="color: #2C3E50;">${escapeHtml(selectedPet.personality || '未记录')}</strong></div>
                        <div><span style="color: #A0ADB8; font-size: 11px;">常待房间</span><br><strong style="color: #2C3E50;">${escapeHtml(getPetRoomLabel(selectedPet.homeRoom))}</strong></div>
                    </div>
                    <div style="border-top: 1px dashed rgba(180,160,140,0.2); padding-top: 12px;">
                        <div style="margin-bottom: 8px;"><strong>状态评估：</strong></div>
                        <ul style="padding-left: 20px; line-height: 1.8; margin: 0;">
                            <li><strong>饱食：</strong>${getSatietyDesc(selectedPet.satiety)}</li>
                            <li><strong>饮水：</strong>${getHydrationDesc(selectedPet.hydration)}</li>
                            <li><strong>情绪：</strong>${getFunDesc(selectedPet.fun)}</li>
                            <li><strong>饭盆状态：</strong>${getBowlDesc(selectedPet.foodBowl)}</li>
                            <li><strong>水碗状态：</strong>${getBowlDesc(selectedPet.waterBowl)}</li>
                        </ul>
                    </div>
                </div>
            `;
        }

        // 5. 渲染事件日志
        const recentEvents = (petSystem.eventLog || []).slice(0, 8);
        petEventsEl.innerHTML = recentEvents.length > 0
            ? recentEvents.map(entry => `
                <div style="margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid rgba(180,160,140,0.1);">
                    <div style="display: flex; justify-content: space-between; align-items: center;">
                        <strong style="color: #2C3E50;">${escapeHtml(entry.title || '宠物动态')}</strong>
                        <span style="font-size: 11px; color: #A0ADB8;">${escapeHtml(new Date(entry.timestamp || Date.now()).toLocaleString('zh-CN', {month:'numeric', day:'numeric', hour:'numeric', minute:'numeric'}))}</span>
                    </div>
                    <div style="margin-top: 4px; color: #5A6A7A;">${escapeHtml(entry.description || '')}</div>
                </div>
            `).join('')
            : '';
    }

    function openManualPetEntryFlow(contact) {
        if (!contact) return;

        const values = {};
        const steps = [
            { key: 'name', message: '先输入宠物名字（可留空自动起名）', defaultValue: '' },
            { key: 'species', message: '输入物种：猫 / 狗 / 兔子 / 鸟 / 仓鼠 / 其他（可留空让主API按角色设定补）', defaultValue: '' },
            { key: 'breed', message: '输入品种（可留空自动补）', defaultValue: '' },
            { key: 'age', message: '输入年龄（如 8个月 / 2岁，可留空自动补）', defaultValue: '' },
            { key: 'sex', message: '输入性别：公 / 母 / 未知（可留空自动补）', defaultValue: '' },
            { key: 'personality', message: '输入性格（如 黏人 / 慢热 / 活泼，可留空自动补）', defaultValue: '' },
            { key: 'habits', message: '输入习惯/小毛病（用顿号或逗号分隔，可留空自动补）', defaultValue: '' }
        ];

        const openStep = (index) => {
            if (index >= steps.length) {
                const species = normalizePetSpeciesInput(values.species || 'other');
                const manualFieldMap = {
                    name: !!String(values.name || '').trim(),
                    species: !!String(values.species || '').trim(),
                    breed: !!String(values.breed || '').trim(),
                    age: !!String(values.age || '').trim(),
                    sex: !!String(values.sex || '').trim(),
                    personality: !!String(values.personality || '').trim(),
                    habits: !!String(values.habits || '').trim()
                };
                const pet = addPetToContact(contact, {
                    name: String(values.name || '').trim() || buildAutoPetName(species),
                    species,
                    breed: String(values.breed || '').trim(),
                    age: String(values.age || '').trim(),
                    sex: String(values.sex || '').trim(),
                    personality: String(values.personality || '').trim(),
                    habits: String(values.habits || '').trim(),
                    source: '手动录入',
                    seedNote: `手动录入宠物：${Object.values(values).filter(Boolean).join(' / ')}`,
                    isManual: true,
                    manualFieldMap
                }, {
                    kind: 'manual',
                    eventTitle: '手动录入了宠物',
                    eventDescription: `${contact.remark || contact.name || '角色'} 的宠物档案新增了一只 ${getPetSpeciesMeta(species).label}。`
                });
                saveAppData();
                renderPetView();
                showToast(`已录入宠物：${pet.name}，正在调用主API生成档案和监控`, 'success');
                void refreshPetWorldFromApi(contact, {
                    reason: 'manual_entry',
                    focusPetId: pet.id,
                    forceEventCheck: true
                }).then(() => {
                    showToast('宠物档案和监控已更新', 'success');
                }).catch((error) => {
                    showToast(`宠物档案/监控生成失败：${String(error && error.message ? error.message : error)}`, 'error');
                });
                return;
            }

            const step = steps[index];
            showCustomPrompt('手动录入宠物', step.message, step.defaultValue, (inputValue) => {
                values[step.key] = String(inputValue || '').trim();
                openStep(index + 1);
            }, true);
        };

        openStep(0);
    }

    function ensurePetViewBindings() {
        if (window.__idicPetViewBindingsReady) return;

        const backButton = document.getElementById('back-to-chat-from-pet');
        if (backButton) {
            backButton.addEventListener('click', () => {
                destroyImportedPetHomeMonitorSession();
                switchToView('chat-window-view');
            });
        }

        const roomTabsEl = document.getElementById('pet-room-tabs');
        if (roomTabsEl) {
            roomTabsEl.addEventListener('click', event => {
                const target = event.target.closest('[data-room-key]');
                if (!target) return;
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                petSystem.selectedRoom = target.dataset.roomKey || 'living_room';
                saveAppData();
                renderPetView();
            });
        }

        const petListEl = document.getElementById('pet-list');
        if (petListEl) {
            petListEl.addEventListener('click', event => {
                const target = event.target.closest('[data-pet-id]');
                if (!target) return;
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                petSystem.selectedPetId = target.dataset.petId || null;
                saveAppData();
                renderPetView();
            });
        }

        const addManualButton = document.getElementById('pet-add-manual-btn');
        if (addManualButton) {
            addManualButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                openManualPetEntryFlow(contact);
                return;

                showCustomPrompt('手动录入宠物', '先输入宠物名字（可留空自动起名）', '', (nameInput) => {
                    const petName = String(nameInput || '').trim();
                    showCustomPrompt('手动录入宠物', '输入物种：猫 / 狗 / 兔子 / 鸟 / 仓鼠 / 其他', '猫', (speciesInput) => {
                        const rawSpecies = String(speciesInput || '猫').trim();
                        const speciesMap = {
                            '猫': 'cat',
                            '狗': 'dog',
                            '兔子': 'rabbit',
                            '兔': 'rabbit',
                            '鸟': 'bird',
                            '鹦鹉': 'bird',
                            '仓鼠': 'hamster',
                            '其他': 'other'
                        };
                        const species = speciesMap[rawSpecies] || speciesMap[rawSpecies.replace(/\s+/g, '')] || inferPetSpeciesFromText(rawSpecies);
                        showCustomPrompt('手动录入宠物', '输入品种/备注（可留空）', '', (breedInput) => {
                            const pet = addPetToContact(contact, {
                                name: petName || buildAutoPetName(species),
                                species,
                                breed: String(breedInput || '').trim(),
                                source: '手动录入',
                                isManual: true
                            }, {
                                kind: 'manual',
                                eventTitle: '手动录入了宠物',
                                eventDescription: `${contact.remark || contact.name || '角色'} 的宠物档案新增了一只 ${getPetSpeciesMeta(species).label}。`
                            });
                            saveAppData();
                            renderPetView();
                            showToast(`已录入宠物：${pet.name}`, 'success');
                        }, true);
                    }, true);
                }, true);
            });
        }

        const refreshMonitorButton = document.getElementById('pet-refresh-monitor-btn');
        if (refreshMonitorButton) {
            refreshMonitorButton.addEventListener('click', async () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                if (hasImportedPetHomeLayout(petSystem)) {
                    if (petImportedHomeMonitorSession) {
                        petImportedHomeMonitorSession.setSelectedCamera(petSystem.importedHomeSelectedCamera);
                    }
                    destroyImportedPetHomeMonitorSession();
                    renderPetView();
                    showToast('监控画面已刷新', 'success');
                    return;
                }
                if (!Array.isArray(petSystem.pets) || petSystem.pets.length === 0) {
                    showToast('先导入房屋 JSON 或录入宠物', 'info');
                    return;
                }
                try {
                    await refreshPetWorldFromApi(contact, {
                        reason: 'manual_refresh',
                        focusPetId: petSystem.selectedPetId || null,
                        forceEventCheck: true
                    });
                    showToast('监控已用主API刷新', 'success');
                } catch (error) {
                    showToast(`监控刷新失败：${String(error && error.message ? error.message : error)}`, 'error');
                }
            });
        }

        const deleteCurrentPetButton = document.getElementById('pet-delete-current-btn');
        if (deleteCurrentPetButton) {
            deleteCurrentPetButton.addEventListener('click', () => {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact) return;
                const petSystem = ensurePetSystem(contact);
                if (petSystem.isMonitorRefreshing) {
                    showToast('主API正在刷新监控，稍等一下再删。', 'info');
                    return;
                }
                const selectedPet = petSystem.pets.find(pet => pet.id === petSystem.selectedPetId) || petSystem.pets[0] || null;
                if (!selectedPet) {
                    showToast('当前没有可删除的宠物。', 'info');
                    return;
                }

                showCustomConfirm(
                    '删除当前宠物',
                    `确定要删除宠物「${selectedPet.name}」吗？\n这会同时移除它的档案、监控缓存中的残留引用，以及只属于它的宠物事件记录。`,
                    () => {
                        const deletedPet = deletePetFromContact(contact, selectedPet.id);
                        renderPetView();
                        showToast(deletedPet ? `已删除宠物：${deletedPet.name}` : '删除失败', deletedPet ? 'success' : 'error');
                    }
                );
            });
        }

        window.setInterval(() => {
            const petView = document.getElementById('pet-view');
            if (petView && !petView.classList.contains('hidden')) {
                renderPetView();
            }
        }, 60 * 1000);

        window.__idicPetViewBindingsReady = true;
    }

    function openPetViewFromFunctionPanel() {
        if (activeGroupChatId) {
            showToast('群聊暂不支持宠物功能。', 'info');
            return;
        }

        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) {
            showToast('请先进入一个角色聊天，再打开宠物页。', 'info');
            return;
        }

        const petSystem = ensurePetSystem(contact);
        ensurePetViewBindings();
        renderPetView();
        if (!hasImportedPetHomeLayout(petSystem) && petSystem.pets.length > 0 && !petSystem.isMonitorRefreshing && (!petSystem.monitorCache.generatedAt || Object.keys(petSystem.monitorCache.roomsByKey || {}).length === 0)) {
            void refreshPetWorldFromApi(contact, {
                reason: 'open_pet_view',
                focusPetId: petSystem.selectedPetId || null,
                forceEventCheck: true
            }).catch((error) => {
                console.warn('打开宠物页时生成监控失败:', error);
            });
        }
        if (typeof closeFunctionsPanel === 'function') closeFunctionsPanel();
        switchToView('pet-view');
    }

    // “聪明的档案管理员” V4.0 (剧情线感知版)
    function findMessageById(messageId) {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return null;

        // 步骤1: 先在“线上”和“待发送”这两个常规区域里找
        let message =
            (contact.onlineChatHistory || []).find(msg => msg.id === messageId) ||
            (contact.unsentMessages || []).find(msg => msg.id === messageId);

        // 步骤2: 如果还没找到，就启动“线下剧情线大搜查”
        if (!message && contact.offlineStorylines && contact.offlineStorylines.length > 0) {
            for (const story of contact.offlineStorylines) {
            // 【全新】为每个角色添加“去八股”开关
                const foundInStory = (story.chatHistory || []).find(msg => msg.id === messageId);
                if (foundInStory) {
                    message = foundInStory;
                    break; // 一旦找到，立刻停止搜查
                }
            }
        }

        return message || null;
    }

    function buildMessageFavoriteSnapshot(message) {
        if (!message || typeof message !== 'object') return null;
        return normalizeMessageFavoriteSnapshot({
            id: message.id,
            role: message.role || message.senderType || 'assistant',
            type: message.type || 'text',
            content: safeMessageFavoriteClone(message.content),
            rawHtmlContent: safeMessageFavoriteClone(message.rawHtmlContent),
            timestamp: message.timestamp || Date.now(),
            mode: message.mode || '',
            quotedMessage: safeMessageFavoriteClone(message.quotedMessage),
            imageId: message.imageId || '',
            stickerId: message.stickerId || '',
            redPacketData: safeMessageFavoriteClone(message.redPacketData),
            relationshipData: safeMessageFavoriteClone(message.relationshipData),
            paymentData: safeMessageFavoriteClone(message.paymentData),
            listenTogetherData: safeMessageFavoriteClone(message.listenTogetherData),
            musicShareData: safeMessageFavoriteClone(message.musicShareData),
            transactionData: safeMessageFavoriteClone(message.transactionData),
            imageGenerationMeta: safeMessageFavoriteClone(message.imageGenerationMeta),
            aiDescription: safeMessageFavoriteClone(message.aiDescription),
            bubbleStyleId: message.bubbleStyleId || '',
            recalledMeta: safeMessageFavoriteClone(message.recalledMeta)
        });
    }

    function isMessageFavoriteImageLikeType(type) {
        const normalizedType = String(type || '').trim().toLowerCase();
        return normalizedType === 'image' || normalizedType === 'sticker';
    }

    function resolveMessageFavoritePrimaryCategory(messages, chatContext) {
        if (!Array.isArray(messages) || messages.length === 0) return 'message';
        if (messages.length > 1) return 'all';

        const message = messages[0] || {};
        const type = String(message.type || 'text').trim().toLowerCase();
        const isOffline = Boolean(chatContext && chatContext.isOfflineMode)
            || String(message.mode || '').trim().toLowerCase() === 'offline';

        if (type === 'html') return 'html';
        if (isOffline) return 'offline';
        if (isMessageFavoriteImageLikeType(type)) return 'image';
        return 'message';
    }

    function getActiveMessageFavoriteChatContext() {
        if (activeGroupChatId) {
            return { isGroup: true };
        }

        const contact = appData.aiContacts.find((item) => String(item.id) === String(activeChatContactId));
        if (!contact) return null;

        const activeStory = contact.isOfflineMode && Array.isArray(contact.offlineStorylines)
            ? contact.offlineStorylines.find((story) => String(story && story.id || '') === String(contact.activeOfflineStoryId || ''))
            : null;

        return {
            contactId: String(contact.id || ''),
            contactName: String(contact.remark || contact.name || '角色').trim() || '角色',
            isOfflineMode: Boolean(contact.isOfflineMode),
            storyId: String(activeStory && activeStory.id || ''),
            storyName: String(activeStory && activeStory.name || '')
        };
    }

    function getSelectedMessagesInDisplayOrder() {
        const orderedMessages = [];
        const seenMessageIds = new Set();
        if (!messageContainer) return orderedMessages;

        messageContainer.querySelectorAll('.message-row[data-message-id]').forEach((row) => {
            const messageId = String(row.dataset.messageId || '');
            if (!messageId || !selectedMessages.has(messageId) || seenMessageIds.has(messageId)) return;
            const message = findMessageById(messageId);
            if (message) {
                orderedMessages.push(message);
                seenMessageIds.add(messageId);
            }
        });

        return orderedMessages;
    }

    function buildMessageFavoriteSourceKey(chatContext, messageIds) {
        const contactId = String(chatContext && chatContext.contactId || '');
        const storyId = String(chatContext && chatContext.storyId || '');
        const modeKey = chatContext && chatContext.isOfflineMode ? 'offline' : 'online';
        return `${contactId}|${storyId}|${modeKey}|${messageIds.join(',')}`;
    }

    function collectSelectedMessagesToFavorites() {
        const chatContext = getActiveMessageFavoriteChatContext();
        if (!chatContext) return;
        if (chatContext.isGroup) {
            showToast('群聊暂不支持收藏', 'info');
            return;
        }

        const selectedMessageRows = getSelectedMessagesInDisplayOrder();
        if (!selectedMessageRows.length) {
            showToast('没有可收藏的消息', 'info');
            return;
        }

        const store = getMessageFavoritesStore();
        const messageSnapshots = selectedMessageRows
            .map(buildMessageFavoriteSnapshot)
            .filter(Boolean);
        if (!messageSnapshots.length) {
            showToast('收藏失败', 'error');
            return;
        }

        const messageIds = messageSnapshots.map((snapshot) => String(snapshot.id || '')).filter(Boolean);
        const sourceKey = buildMessageFavoriteSourceKey(chatContext, messageIds);
        const now = Date.now();
        const existingItem = store.items.find((item) => String(item.sourceKey || '') === sourceKey);

        if (existingItem) {
            existingItem.favoritedAt = now;
            store.preferences.category = existingItem.category || 'all';
            saveAppData();
            exitSelectMode();
            showToast('已收藏', 'success');
            return;
        }

        const favoriteItem = {
            id: `fav_msg_${now}_${Math.random().toString(36).slice(2, 8)}`,
            category: resolveMessageFavoritePrimaryCategory(selectedMessageRows, chatContext),
            sourceKey,
            favoritedAt: now,
            note: '',
            isLoved: false,
            customGroupIds: [],
            messageIds,
            messageSnapshots,
            messageStartTimestamp: Number(messageSnapshots[0] && messageSnapshots[0].timestamp) || now,
            messageEndTimestamp: Number(messageSnapshots[messageSnapshots.length - 1] && messageSnapshots[messageSnapshots.length - 1].timestamp) || now,
            chatContext: {
                contactId: String(chatContext.contactId || ''),
                contactName: String(chatContext.contactName || ''),
                isOfflineMode: Boolean(chatContext.isOfflineMode),
                storyId: String(chatContext.storyId || ''),
                storyName: String(chatContext.storyName || '')
            }
        };

        store.items.unshift(favoriteItem);
        store.preferences.category = favoriteItem.category;
        saveAppData();
        exitSelectMode();
        showToast('已收藏', 'success');
    }

