        function ngramSimilarity(a, b, n = 2) {
            const getNgrams = (value) => {
                const text = String(value || '').trim();
                const set = new Set();
                for (let i = 0; i <= text.length - n; i++) set.add(text.slice(i, i + n));
                return set;
            };
            const sa = getNgrams(a);
            const sb = getNgrams(b);
            const intersection = [...sa].filter(x => sb.has(x)).length;
            return intersection / Math.max(sa.size + sb.size - intersection, 1);
        }

        function isSemanticDuplicate(theme, history, threshold = 0.4) {
            return history.some(h => ngramSimilarity(theme, h) >= threshold);
        }

