                    if (luck > 95) { // 锦鲤附体 (1大好 + 2-4普通好) -> 总计3-5
                        if (majorPositiveEvents.length > 0) selectedEvents.push(majorPositiveEvents.shift());
                        selectedEvents.push(...positiveNormalEvents.slice(0, Math.floor(Math.random() * 3) + 2));
                    } else if (luck > 85) { // 相当幸运 (3-5普通好)
                        selectedEvents.push(...positiveNormalEvents.slice(0, Math.floor(Math.random() * 3) + 3));
                    } else if (luck > 65) { // 小有运气 (1普通好 + 2-4中性) -> 总计3-5
                        if (positiveNormalEvents.length > 0) selectedEvents.push(positiveNormalEvents.shift());
                        selectedEvents.push(...neutralEvents.slice(0, Math.floor(Math.random() * 3) + 2));
                    } else if (luck > 35) { // 平平无奇 (3-5中性事件)
                        selectedEvents.push(...neutralEvents.slice(0, Math.floor(Math.random() * 3) + 3));
                    } else if (luck > 15) { // 运气偏低 (1普通坏事 + 2-4中性) -> 总计3-5
                        if (negativeNormalEvents.length > 0) selectedEvents.push(negativeNormalEvents.shift());
                        selectedEvents.push(...neutralEvents.slice(0, Math.floor(Math.random() * 3) + 2));
                    } else if (luck > 5) { // 诸事不顺 (3-5普通坏事)
                        selectedEvents.push(...negativeNormalEvents.slice(0, Math.floor(Math.random() * 3) + 3));
                    } else { // 灾难性的一天 (1大坏事 + 2-4普通坏事) -> 总计3-5
                        if (majorNegativeEvents.length > 0) selectedEvents.push(majorNegativeEvents.shift());
                        selectedEvents.push(...negativeNormalEvents.slice(0, Math.floor(Math.random() * 3) + 2));
                    }

