            const requestPayload = {
                model: appData.appSettings.apiModel,
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.85
            };
            let response = null;
            let lastFetchError = null;
            for (let attempt = 0; attempt < 3; attempt += 1) {
                try {
                    response = await fetch(requestUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                        body: JSON.stringify(requestPayload)
                    });
                    break;
                } catch (fetchError) {
                    lastFetchError = fetchError;
                    console.warn(`[状态快照] 请求失败，准备重试(${attempt + 1}/3):`, fetchError && fetchError.message ? fetchError.message : fetchError);
                    if (attempt < 2) await sleep(1200 + attempt * 1800);
                }
            }
            if (!response) throw lastFetchError || new Error('状态快照请求未返回响应');
            if (!response.ok) throw new Error(`API 请求失败: ${response.status} ${await response.text()}`);
            const data = await response.json();
            const responseText = data?.choices?.[0]?.message?.content || '';
            const jsonMatch = responseText.match(/{[\s\S]*}/);
            if (!jsonMatch) throw new Error('AI未返回可解析的状态快照JSON');
            const parsed = JSON.parse(jsonMatch[0]);
