    async function renderMovieChatMessage(messageData) {
        const contact = appData.aiContacts.find(c => c.id === activeMovieContactId);
        if (!contact) return;

        const container = document.getElementById('movie-chat-container');
        // 复用我们强大的 createMessageElement 函数来创建气泡！
        // 关键：我们传入一个假的 activeChatContactId 来“骗”过它，让它能正确找到头像
        const tempActiveId = activeChatContactId;
        activeChatContactId = activeMovieContactId;
        const messageElement = await createMessageElement(messageData.content, messageData.role, { ...messageData, isNew: false });
        activeChatContactId = tempActiveId;

        container.appendChild(messageElement);
        container.scrollTop = container.scrollHeight;
    }

