                    const weatherKeywords = ['天气', '气温', '度', '晴', '雨', '雪', '风', '阴', '°C'];
                    const mentionedWeather = newMessages.some(m =>
                        m.content && typeof m.content === 'string' && weatherKeywords.some(keyword => m.content.includes(keyword))
                    );

