    /**
     * 总入口：为个性装扮页面的所有控件绑定事件
     */
    async function forceGenerateCompassOptions() {
                            // ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲
        if (isGeneratingCompassOptions) return;

        isGeneratingCompassOptions = true; // 上锁！

        const optionsContainer = document.getElementById('sex-compass-options-container');
        const scriptPreview = document.getElementById('sex-compass-script-text');

        optionsContainer.innerHTML = '<p style="color: #ccc; text-align: center; padding: 40px 0;">导演正在构思剧本，请稍候...</p>';
        scriptPreview.textContent = '等待导演生成剧本...';
        document.getElementById('ai-proposed-action-display').classList.add('hidden');

        try {

            const lastScript = stagedCompassScript || "";
            const isContinuation = lastScript !== "";

            const options = await generateCompassOptions(isContinuation, lastScript);

            if (options) {
                compassOptionsData = options; // 将新选项存入“硬盘”
                renderCompassOptions(compassOptionsData);
                scriptPreview.textContent = '请为下一回合选择动作...';
            } else {
                throw new Error("AI未能返回有效的选项数据。");
            }
        } catch (error) {
                console.error("线下重写失败:", error);
            optionsContainer.innerHTML = `<p style="color: #ff8a80; text-align: center; padding: 40px 0;">剧本构思失败！<br>${error.message}<br>请稍后重试或点击刷新。</p>`;
        } finally {
            isGeneratingCompassOptions = false; // 无论成功失败，都要解锁！
        }
    }

