    /**
     * 它的唯一职责，就是把我们的内部聊天记录，转换成AI能看懂的、格式完美的“剧本台词”。
     * @param {object} optionsData - 从API获取的JSON数据
     */
    function renderCompassOptions(optionsData) {
        const container = document.getElementById('sex-compass-options-container');
        container.innerHTML = '';

        const aiActionDisplay = document.getElementById('ai-proposed-action-display');
        const aiActionText = document.getElementById('ai-proposed-action-text');

        // 【核心改造】检查新的 aiActions 数组
        if (optionsData.aiActions && optionsData.aiActions.length > 0) {
            currentAiProposedAction = optionsData.aiActions; // 保存整个行动清单
                                // ▲▲▲▲▲ 【【【修复完毕】】】 ▲▲▲▲▲
            const actionsHtml = currentAiProposedAction.map(action =>
                `- ${action.part}：${action.action}`
            ).join('<br>'); // 用换行符连接每一条
            aiActionText.innerHTML = actionsHtml; // 使用 innerHTML 来渲染换行
            aiActionDisplay.classList.remove('hidden');
        } else {
            currentAiProposedAction = null;
            aiActionDisplay.classList.add('hidden');
        }

        let groupIndex = 0;
        for (const status in optionsData) {
            // 【【【终极数据迁移修复 V2.0：强制拆迁队】】】
                                            // 【核心改造】只有在“一起听歌”模式下才广播
            if (status === 'aiActions' || status === 'userArousalChange' || status === 'charArousalChange') {
                continue; // 如果是，就直接跳过，处理下一个
            }

            const options = optionsData[status];
                                        // 【【【权限检查站】】】
            if (!Array.isArray(options)) continue;

            const groupDiv = document.createElement('div');
            groupDiv.className = 'body-part-group';

            const title = document.createElement('h4');
            title.textContent = status;
            groupDiv.appendChild(title);

            options.forEach(option => {
                const label = document.createElement('label');
                label.className = 'compass-option';

                const radio = document.createElement('input');
                radio.type = 'radio';
                radio.name = `compass-group-${groupIndex}`;
                radio.value = option.key;

                if (option.key === 'rest') {
                    radio.checked = true;
                }

                label.appendChild(radio);
                label.append(` ${option.label}`);
                groupDiv.appendChild(label);
            });

            container.appendChild(groupDiv);
            groupIndex++;
        }
    }

