    function setVoiceInputMode(mode) {
        const finalMode = (mode === 'tencent') ? 'tencent' : 'manual';
        if (finalMode === 'tencent' && !isTencentAsrConfigured()) {
            alert('请先在设置中填写腾讯云语音识别的 SecretId/SecretKey。');
            return setVoiceInputMode('manual');
        }
        voiceInputMode = finalMode;
        if (voiceModeButtons && voiceModeButtons.length) {
            voiceModeButtons.forEach(btn => {
                btn.classList.toggle('active', btn.dataset.voiceMode === voiceInputMode);
            });
        }
        if (voiceRecordPanel) {
            voiceRecordPanel.classList.toggle('hidden', voiceInputMode !== 'tencent');
        }
        if (voiceRecordBtn) {
            voiceRecordBtn.classList.toggle('hidden', voiceInputMode !== 'tencent');
        }
        if (voiceStopBtn) {
            voiceStopBtn.classList.add('hidden');
        }
        if (voiceTextLabel) {
            voiceTextLabel.textContent = '';
        }
        if (voiceTextInput) {
            voiceTextInput.placeholder = voiceInputMode === 'tencent'
                ? '你的收藏夹是空的哦'
            : '';
        }
        isVoiceResultEditable = false;
        updateVoiceResultDisplay();
        if (voiceInputMode === 'tencent') {
            updateVoiceRecordStatus('准备就绪');
        }
        if (voiceInputMode === 'manual') {
            stopVoiceRecording(true);
        }
        if (appData.appSettings.voiceInputMode !== voiceInputMode) {
            appData.appSettings.voiceInputMode = voiceInputMode;
            saveAppData();
        }
    }

    function updateVoiceRecordStatus(text) {
        if (voiceRecordStatus) voiceRecordStatus.textContent = text;
    }

    function updateVoiceResultDisplay() {
        if (!voiceTextInput || !voiceResultText || !voiceResultRow) return;
        const textValue = voiceTextInput.value.trim();
        const hasText = textValue.length > 0;

        if (voiceInputMode === 'tencent') {
            voiceResultRow.classList.remove('hidden');
            voiceResultText.classList.remove('hidden');
            voiceResultText.textContent = hasText ? textValue : '识别结果将显示在这里...';
            voiceResultText.classList.toggle('is-empty', !hasText);
            if (voiceEditBtn) voiceEditBtn.classList.toggle('hidden', !hasText);

            if (isVoiceResultEditable) {
                voiceTextInput.classList.remove('hidden');
                voiceResultText.classList.add('hidden');
            } else {
                voiceTextInput.classList.add('hidden');
            }
        } else {
            voiceResultRow.classList.add('hidden');
            voiceResultText.classList.add('hidden');
            if (voiceEditBtn) voiceEditBtn.classList.add('hidden');
            voiceTextInput.classList.remove('hidden');
        }
    }

    function setVoiceResultEditable(enable) {
        isVoiceResultEditable = enable;
        updateVoiceResultDisplay();
        if (enable && voiceTextInput) {
            voiceTextInput.focus();
        }
    }

    function formatVoiceRecordTime(ms) {
        const totalSeconds = Math.floor(ms / 1000);
        const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
        const seconds = (totalSeconds % 60).toString().padStart(2, '0');
        return `${minutes}:${seconds}`;
    }

    function updateVoiceRecordTimer() {
        if (!voiceRecordTimer) return;
        const elapsed = Date.now() - voiceRecordStartTime;
        voiceRecordTimer.textContent = formatVoiceRecordTime(elapsed);
    }

    function resetVoiceRecorderUI() {
        if (voiceRecordTimerId) {
            clearInterval(voiceRecordTimerId);
            voiceRecordTimerId = null;
        }
        if (voiceRecordTimeoutId) {
            clearTimeout(voiceRecordTimeoutId);
            voiceRecordTimeoutId = null;
        }
        if (voiceRecordTimer) voiceRecordTimer.textContent = '00:00';
        if (voiceRecordBtn) {
                                // ▲▲▲▲▲ 【【【指令接收器安装完毕】】】 ▲▲▲▲▲
            voiceRecordBtn.classList.toggle('hidden', voiceInputMode !== 'tencent');
        }
        if (voiceStopBtn) voiceStopBtn.classList.add('hidden');
        if (voiceWaveVisual) voiceWaveVisual.classList.remove('recording');
        if (voiceRecordStream) {
            voiceRecordStream.getTracks().forEach(track => track.stop());
            voiceRecordStream = null;
        }
        voiceRecorder = null;
        voiceRecordChunks = [];
        voiceRecordCancelled = false;
        lastVoiceRecordMimeType = '';
    }

    async function startVoiceRecording() {
        if (voiceInputMode !== 'tencent') return;
        if (!isTencentAsrConfigured()) {
            alert('请先在设置中填写腾讯云语音识别的 SecretId/SecretKey。');
            return;
        }
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            alert('当前浏览器不支持录音功能。');
            return;
        }
        if (!window.MediaRecorder) {
            alert('当前浏览器不支持录音功能。');
            return;
        }
        if (voiceRecorder && voiceRecorder.state === 'recording') return;

        try {
            voiceRecordCancelled = false;
            voiceRecordChunks = [];
            await ensureMicrophoneAccessReady();
            voiceRecordStream = await navigator.mediaDevices.getUserMedia(buildMicrophoneConstraints());
            const preferredType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
                ? 'audio/webm;codecs=opus'
                : (MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : '');
            lastVoiceRecordMimeType = preferredType;
            voiceRecorder = new MediaRecorder(voiceRecordStream, preferredType ? { mimeType: preferredType } : undefined);
            voiceRecorder.ondataavailable = (event) => {
                if (event.data && event.data.size > 0) {
                    voiceRecordChunks.push(event.data);
                }
            };
            voiceRecorder.onstop = async () => {
                if (voiceRecordCancelled) {
                    resetVoiceRecorderUI();
                    updateVoiceRecordStatus('已取消');
                    return;
                }
                const blob = new Blob(voiceRecordChunks, { type: lastVoiceRecordMimeType || 'audio/webm' });
                resetVoiceRecorderUI();
                await handleVoiceRecognition(blob);
            };
            voiceRecorder.start();
            voiceRecordStartTime = Date.now();
            updateVoiceRecordTimer();
            voiceRecordTimerId = setInterval(updateVoiceRecordTimer, 200);
            voiceRecordTimeoutId = setTimeout(() => stopVoiceRecording(false), 60000);
        updateVoiceRecordStatus('准备就绪');
            if (voiceWaveVisual) voiceWaveVisual.classList.add('recording');
            if (voiceRecordBtn) voiceRecordBtn.classList.add('hidden');
            if (voiceStopBtn) voiceStopBtn.classList.remove('hidden');
        } catch (error) {
            console.error('自由发言失败:', error);
            updateVoiceRecordStatus(normalizeMediaCaptureErrorMessage(error, '录音失败'));
            resetVoiceRecorderUI();
        }
    }

    function stopVoiceRecording(cancelled = false) {
        if (!voiceRecorder || voiceRecorder.state === 'inactive') {
            if (cancelled) resetVoiceRecorderUI();
            return;
        }
        voiceRecordCancelled = cancelled;
        try {
            voiceRecorder.stop();
        } catch (error) {
            console.error('重新生成公开名片失败:', error);
            resetVoiceRecorderUI();
        }
    }

    function percentileVoiceNumber(sortedValues, ratio) {
        if (!Array.isArray(sortedValues) || sortedValues.length === 0) return 0;
        const index = Math.max(0, Math.min(sortedValues.length - 1, Math.floor((sortedValues.length - 1) * ratio)));
        return sortedValues[index];
    }

    function averageVoiceNumbers(values) {
        if (!Array.isArray(values) || values.length === 0) return 0;
        return values.reduce((sum, value) => sum + value, 0) / values.length;
    }

    function stdVoiceNumbers(values) {
        if (!Array.isArray(values) || values.length < 2) return 0;
        const mean = averageVoiceNumbers(values);
        const variance = values.reduce((sum, value) => sum + Math.pow(value - mean, 2), 0) / values.length;
        return Math.sqrt(variance);
    }

    function dbFromRms(rms) {
        return 20 * Math.log10(Math.max(Number(rms) || 0, 0.0000001));
    }

    function labelVoiceVolume(activeDb) {
        if (activeDb < -36) return '声音很轻，像贴近耳边或压低声音';
        if (activeDb < -28) return '音量偏轻，整体比较柔和';
        if (activeDb < -18) return '音量正常，距离麦克风适中';
        if (activeDb < -10) return '音量偏大，情绪或发声更外放';
        return '音量很大，可能靠近麦克风或情绪很强';
    }

    function labelVoiceEnvironment(noiseFloorDb, speechCoverage, burstCount) {
        let label = '';
        if (noiseFloorDb < -58) {
            label = '环境很安静，底噪很低';
        } else if (noiseFloorDb < -48) {
            label = '环境较安静，有轻微底噪';
        } else if (noiseFloorDb < -38) {
            label = '背景底噪明显，像普通室内设备声、风声或远处人声';
        } else {
            label = '背景噪声偏强，语音后面可能混着风声、人声、街道声或设备声';
        }
        if (burstCount >= 3) {
            label += '，中间夹杂几次短促杂音或碰撞声';
        }
        if (speechCoverage < 0.35) {
            label += '，空白/环境声占比偏高';
        }
        return label;
    }

    function labelVoicePauses(pauseCount, longestPauseSec, pauseRatio) {
        if (pauseRatio > 0.45 || longestPauseSec > 1.4) return '停顿很多，断续感明显';
        if (longestPauseSec > 0.8) return '有明显停顿，像在想词或压着情绪';
        if (pauseCount >= 4) return '有多次短停顿，口语感明显';
        return '停顿较少，表达比较连贯';
    }

    function countVoiceSpeechUnits(text) {
        const source = String(text || '');
        const cjk = source.match(/[\u3400-\u9fff]/g) || [];
        const latinWords = source.replace(/[\u3400-\u9fff]/g, ' ').match(/[A-Za-z0-9]+/g) || [];
        return cjk.length + latinWords.length;
    }

    function labelVoicePace(unitsPerSecond) {
        if (!Number.isFinite(unitsPerSecond) || unitsPerSecond <= 0) return '语速无法判断';
        if (unitsPerSecond < 1.8) return '语速很慢';
        if (unitsPerSecond < 2.8) return '语速偏慢';
        if (unitsPerSecond < 4.2) return '语速自然';
        if (unitsPerSecond < 5.6) return '语速偏快';
        return '语速很快';
    }

    function estimateVoicePitchForFrame(samples, start, frameSize, sampleRate) {
        let energy = 0;
        for (let i = 0; i < frameSize; i++) {
            const sample = samples[start + i] || 0;
            energy += sample * sample;
        }
        const rms = Math.sqrt(energy / frameSize);
        if (rms < 0.008) return 0;

        const minLag = Math.max(2, Math.floor(sampleRate / 500));
        const maxLag = Math.min(frameSize - 2, Math.floor(sampleRate / 70));
        let bestLag = 0;
        let bestCorr = 0;
        for (let lag = minLag; lag <= maxLag; lag++) {
            let sum = 0;
            let sumA = 0;
            let sumB = 0;
            const limit = frameSize - lag;
            for (let i = 0; i < limit; i++) {
                const a = samples[start + i] || 0;
                const b = samples[start + i + lag] || 0;
                sum += a * b;
                sumA += a * a;
                sumB += b * b;
            }
            const corr = sum / Math.sqrt(Math.max(sumA * sumB, 0.0000001));
            if (corr > bestCorr) {
                bestCorr = corr;
                bestLag = lag;
            }
        }

        if (!bestLag || bestCorr < 0.35) return 0;
        return sampleRate / bestLag;
    }

    function estimateVoicePitchStats(samples, sampleRate, activeFrames, hopSize, frameSize) {
        const totalFrames = Array.isArray(activeFrames) ? activeFrames.length : 0;
        if (!samples || !totalFrames) return null;
        const stride = Math.max(1, Math.floor(totalFrames / 90));
        const pitches = [];
        let sampledActiveFrames = 0;

        for (let frameIndex = 0; frameIndex < totalFrames; frameIndex += stride) {
            if (!activeFrames[frameIndex]) continue;
            const start = frameIndex * hopSize;
            if (start + frameSize >= samples.length) break;
            sampledActiveFrames++;
            const pitch = estimateVoicePitchForFrame(samples, start, frameSize, sampleRate);
            if (pitch > 0) {
                pitches.push({ hz: pitch, timeSec: start / sampleRate });
            }
        }

        if (!pitches.length) {
            return {
                label: '音高不明显',
                meanHz: 0,
                stdHz: 0,
                rangeHz: 0,
                slopeHz: 0,
                voicedRatio: 0
            };
        }

        const values = pitches.map((item) => item.hz);
        const meanHz = averageVoiceNumbers(values);
        const stdHz = stdVoiceNumbers(values);
        const minHz = Math.min(...values);
        const maxHz = Math.max(...values);
        const slopeHz = pitches.length > 1 ? pitches[pitches.length - 1].hz - pitches[0].hz : 0;
        let label = '语调有自然起伏';
        if (stdHz < 15) label = '语调比较平稳';
        else if (stdHz > 45) label = '语调起伏明显';
        if (slopeHz > 35) label += '，尾段略上扬';
        if (slopeHz < -35) label += '，尾段略下沉';

        return {
            label,
            meanHz: roundVoiceMetric(meanHz, 1),
            stdHz: roundVoiceMetric(stdHz, 1),
            rangeHz: roundVoiceMetric(maxHz - minHz, 1),
            slopeHz: roundVoiceMetric(slopeHz, 1),
            voicedRatio: roundVoiceMetric(pitches.length / Math.max(1, sampledActiveFrames), 2)
        };
    }

    function inferVoiceDelivery(analysis, pace) {
        const pitch = analysis.pitchStats || {};
        if (
            analysis.durationSec > 3
            && pitch.voicedRatio > 0.55
            && pitch.stdHz > 35
            && analysis.speechCoverage > 0.65
            && analysis.pauseRatio < 0.3
        ) {
            return '可能带唱腔、哼唱或拉长音，不像完全平铺直叙的说话';
        }
        if (
            analysis.pauseCount >= 2
            && analysis.energyStdDb < 6
            && pace
            && /自然|偏慢/.test(pace.label || '')
        ) {
            return '像朗读或念台词，节奏比较规整';
        }
        return '更像自然口语表达';
    }

    function inferVoiceEmotion(analysis, pace) {
        const pitch = analysis.pitchStats || {};
        const paceLabel = pace ? pace.label || '' : '';
        if (analysis.activeDb > -18 && /快/.test(paceLabel) && pitch.stdHz > 35) {
            return '可能偏兴奋、急切或情绪外放';
        }
        if (analysis.activeDb < -32 && analysis.pauseRatio > 0.35) {
            return '可能偏轻声、疲惫、犹豫或情绪压低';
        }
        if (analysis.pauseRatio > 0.4) {
            return '停顿多，可能在思考、迟疑或克制情绪';
        }
        if (analysis.energyStdDb > 8 || pitch.stdHz > 45) {
            return '情绪起伏比较明显';
        }
        if (analysis.activeDb < -30) {
            return '整体偏轻柔、谨慎或贴近耳语';
        }
        return '整体情绪较平稳';
    }

    function buildVoiceAcousticMessageMeta(transcript, analysis) {
        if (!analysis || typeof analysis !== 'object') return null;
        const units = countVoiceSpeechUnits(transcript);
        const activeSec = Math.max(0.5, analysis.activeSpeechSec || analysis.durationSec || 0);
        const unitsPerSecond = units > 0 ? units / activeSec : 0;
        const pace = {
            label: labelVoicePace(unitsPerSecond),
            unitsPerSecond: roundVoiceMetric(unitsPerSecond, 2),
            overallUnitsPerSecond: roundVoiceMetric(units / Math.max(0.5, analysis.durationSec || activeSec), 2)
        };
        const delivery = inferVoiceDelivery(analysis, pace);
        const emotion = inferVoiceEmotion(analysis, pace);
        const prosody = [
            analysis.pitchStats?.label || '',
            analysis.energyStdDb > 8 ? '音量起伏较大' : '音量起伏较平稳'
        ].filter(Boolean).join('，');
        const summary = [
            `${roundVoiceMetric(analysis.durationSec, 1)}秒语音`,
            pace.label,
            analysis.volumeLabel,
            analysis.pauseLabel,
            emotion
        ].filter(Boolean).join('；');

        return {
            source: 'local_acoustic_analysis',
            transcript: String(transcript || ''),
            durationSec: roundVoiceMetric(analysis.durationSec, 2),
            environment: analysis.environmentLabel,
            volume: {
                label: analysis.volumeLabel,
                activeDb: roundVoiceMetric(analysis.activeDb, 1),
                peakDb: roundVoiceMetric(analysis.peakDb, 1)
            },
            pace,
            pauses: {
                label: analysis.pauseLabel,
                count: analysis.pauseCount,
                longestSec: roundVoiceMetric(analysis.longestPauseSec, 2),
                ratio: roundVoiceMetric(analysis.pauseRatio, 2)
            },
            prosody,
            emotion,
            delivery,
            pitch: analysis.pitchStats,
            summary,
            confidence: '本地声学估计，适合感知语速、停顿、音量、底噪和大致语气'
        };
    }

    function analyzeVoiceAudioBuffer(audioBuffer) {
        if (!audioBuffer || !audioBuffer.length || !audioBuffer.sampleRate) return null;
        const sampleRate = audioBuffer.sampleRate;
        const length = audioBuffer.length;
        const durationSec = audioBuffer.duration || (length / sampleRate);
        const channelCount = Math.max(1, audioBuffer.numberOfChannels || 1);
        const mono = new Float32Array(length);

        for (let channel = 0; channel < channelCount; channel++) {
            const channelData = audioBuffer.getChannelData(channel);
            for (let i = 0; i < length; i++) {
                mono[i] += channelData[i] / channelCount;
            }
        }

        const frameSize = Math.max(512, Math.min(2048, Math.floor(sampleRate * 0.046)));
        const hopSize = Math.max(256, Math.floor(frameSize / 2));
        const frameDb = [];
        let peak = 0;

        for (let start = 0; start + 32 < length; start += hopSize) {
            const end = Math.min(length, start + frameSize);
            let sum = 0;
            for (let i = start; i < end; i++) {
                const sample = mono[i] || 0;
                sum += sample * sample;
                peak = Math.max(peak, Math.abs(sample));
            }
            frameDb.push(dbFromRms(Math.sqrt(sum / Math.max(1, end - start))));
        }

        if (!frameDb.length) return null;
        const sortedDb = frameDb.slice().sort((a, b) => a - b);
        const noiseFloorDb = percentileVoiceNumber(sortedDb, 0.2);
        const medianDb = percentileVoiceNumber(sortedDb, 0.5);
        const speechThresholdDb = Math.max(noiseFloorDb + 8, -48);
        const activeFrames = frameDb.map((value) => value > speechThresholdDb);
        const activeDbValues = frameDb.filter((_, index) => activeFrames[index]);
        const activeFrameCount = activeDbValues.length;
        const speechCoverage = activeFrameCount / Math.max(1, frameDb.length);
        const activeSpeechSec = activeFrameCount * (hopSize / sampleRate);
        const activeDb = activeDbValues.length ? averageVoiceNumbers(activeDbValues) : averageVoiceNumbers(frameDb);
        const energyStdDb = stdVoiceNumbers(activeDbValues.length ? activeDbValues : frameDb);

        let pauseCount = 0;
        let longestPauseSec = 0;
        let currentPauseFrames = 0;
        let hasStartedSpeech = false;
        const minPauseFrames = Math.max(1, Math.round(0.25 / (hopSize / sampleRate)));
        activeFrames.forEach((active) => {
            if (active) {
                if (hasStartedSpeech && currentPauseFrames >= minPauseFrames) {
                    pauseCount++;
                    longestPauseSec = Math.max(longestPauseSec, currentPauseFrames * (hopSize / sampleRate));
                }
                currentPauseFrames = 0;
                hasStartedSpeech = true;
            } else if (hasStartedSpeech) {
                currentPauseFrames++;
            }
        });
        if (currentPauseFrames >= minPauseFrames) {
            pauseCount++;
            longestPauseSec = Math.max(longestPauseSec, currentPauseFrames * (hopSize / sampleRate));
        }
        const pauseRatio = 1 - speechCoverage;

        let burstCount = 0;
        for (let i = 1; i < frameDb.length - 1; i++) {
            if (
                frameDb[i] > medianDb + 18
                && frameDb[i] - frameDb[i - 1] > 9
                && frameDb[i] - frameDb[i + 1] > 6
            ) {
                burstCount++;
            }
        }

        const pitchStats = estimateVoicePitchStats(mono, sampleRate, activeFrames, hopSize, frameSize);
        const volumeLabel = labelVoiceVolume(activeDb);
        const environmentLabel = labelVoiceEnvironment(noiseFloorDb, speechCoverage, burstCount);
        const pauseLabel = labelVoicePauses(pauseCount, longestPauseSec, pauseRatio);

        return {
            durationSec,
            sampleRate,
            noiseFloorDb,
            activeDb,
            peakDb: dbFromRms(peak),
            energyStdDb,
            speechCoverage,
            activeSpeechSec,
            pauseCount,
            longestPauseSec,
            pauseRatio,
            burstCount,
            pitchStats,
            volumeLabel,
            environmentLabel,
            pauseLabel
        };
    }

    async function analyzeVoiceBlob(blob) {
        const arrayBuffer = await blob.arrayBuffer();
        const audioContext = new (window.AudioContext || window.webkitAudioContext)();
        try {
            const audioBuffer = await audioContext.decodeAudioData(arrayBuffer.slice(0));
            return analyzeVoiceAudioBuffer(audioBuffer);
        } finally {
            if (audioContext && typeof audioContext.close === 'function') {
                audioContext.close();
            }
        }
    }

    async function handleVoiceRecognition(blob) {
        try {
            isVoiceRecognizing = true;
            lastVoiceAcousticAnalysis = null;
            updateVoiceRecordStatus('准备就绪');
            const acousticAnalysisPromise = analyzeVoiceBlob(blob).catch((error) => {
                console.warn('语音声学分析失败:', error);
                return null;
            });
            const wavBuffer = await convertBlobToWav(blob, getTargetSampleRate());
            const dataLen = wavBuffer.byteLength;
            if (dataLen > 3 * 1024 * 1024) {
                throw new Error('音频超过 3MB 限制');
            }
            const base64Data = arrayBufferToBase64(wavBuffer);
            const result = await tencentSentenceRecognition(base64Data, dataLen);
            const acousticAnalysis = await acousticAnalysisPromise;
            const localVoiceMeta = buildVoiceAcousticMessageMeta(result, acousticAnalysis);
            if (result && isVoiceUnderstandingEnhancementConfigured()) {
                updateVoiceRecordStatus('识别完成，正在增强理解...');
            }
            lastVoiceAcousticAnalysis = result
                ? await enhanceVoiceMessageMeta(result, localVoiceMeta, base64Data, { audioFormat: 'wav' })
                : localVoiceMeta;
            voiceTextInput.value = result ? result.trim() : '';
            isVoiceResultEditable = false;
            updateVoiceResultDisplay();
            const enhancedByAliyun = lastVoiceAcousticAnalysis && lastVoiceAcousticAnalysis.enhancementProvider === 'aliyun';
            updateVoiceRecordStatus(result
                ? (enhancedByAliyun ? '识别完成，已记录阿里云增强声音细节' : (lastVoiceAcousticAnalysis ? '识别完成，已记录声音细节' : '识别完成'))
                : '未识别到内容');
        } catch (error) {
            console.error('刷新建议失败:', error);
            updateVoiceRecordStatus(`识别失败：${error.message || error}`);
        } finally {
            isVoiceRecognizing = false;
        }
    }

    function getTargetSampleRate() {
        const config = appData.appSettings.tencentAsr || {};
        const engine = (config.engServiceType || '16k_zh').toLowerCase();
        if (engine.startsWith('8k')) return 8000;
        if (engine.startsWith('16k')) return 16000;
        return 16000;
    }

    async function convertBlobToWav(blob, targetSampleRate) {
        const arrayBuffer = await blob.arrayBuffer();
        const audioContext = new (window.AudioContext || window.webkitAudioContext)();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer.slice(0));
        let workingBuffer = audioBuffer;
        if (targetSampleRate && audioBuffer.sampleRate !== targetSampleRate) {
            workingBuffer = await resampleAudioBuffer(audioBuffer, targetSampleRate);
        }
        const wavBuffer = encodeWavFromAudioBuffer(workingBuffer);
        audioContext.close();
        return wavBuffer;
    }

    async function resampleAudioBuffer(audioBuffer, targetSampleRate) {
        const channelCount = audioBuffer.numberOfChannels;
        const duration = audioBuffer.duration;
        const frameCount = Math.ceil(duration * targetSampleRate);
        const offlineContext = new OfflineAudioContext(channelCount, frameCount, targetSampleRate);
        const source = offlineContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineContext.destination);
        source.start(0);
        return offlineContext.startRendering();
    }

    function encodeWavFromAudioBuffer(audioBuffer) {
        const numChannels = audioBuffer.numberOfChannels;
        const sampleRate = audioBuffer.sampleRate;
        const length = audioBuffer.length;
        const output = new ArrayBuffer(44 + length * 2);
        const view = new DataView(output);
        writeWavHeader(view, sampleRate, length);

        const channelData = [];
        for (let ch = 0; ch < numChannels; ch++) {
            channelData.push(audioBuffer.getChannelData(ch));
        }

        let offset = 44;
        for (let i = 0; i < length; i++) {
            let sample = 0;
            for (let ch = 0; ch < numChannels; ch++) {
                sample += channelData[ch][i];
            }
            sample /= numChannels;
            sample = Math.max(-1, Math.min(1, sample));
            view.setInt16(offset, sample < 0 ? sample * 0x8000 : sample * 0x7FFF, true);
            offset += 2;
        }
        return output;
    }

    function writeWavHeader(view, sampleRate, sampleCount) {
        const byteRate = sampleRate * 2;
        view.setUint32(0, 0x52494646, false); // "RIFF"
        view.setUint32(4, 36 + sampleCount * 2, true);
        view.setUint32(8, 0x57415645, false); // "WAVE"
        view.setUint32(12, 0x666d7420, false); // "fmt "
        view.setUint32(16, 16, true);
        view.setUint16(20, 1, true);
        view.setUint16(22, 1, true);
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, byteRate, true);
        view.setUint16(32, 2, true);
        view.setUint16(34, 16, true);
        view.setUint32(36, 0x64617461, false); // "data"
        view.setUint32(40, sampleCount * 2, true);
    }

    function arrayBufferToBase64(buffer) {
        const bytes = new Uint8Array(buffer);
        let binary = '';
        const chunkSize = 0x8000;
        for (let i = 0; i < bytes.length; i += chunkSize) {
            binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
        }
        return btoa(binary);
    }

    function isTencentAsrConfigured() {
        const config = appData.appSettings.tencentAsr || {};
        return Boolean(config.secretId && config.secretKey);
    }

    function isVoiceUnderstandingEnhancementConfigured() {
        const config = normalizeVoiceUnderstandingSettings(appData?.appSettings?.voiceUnderstanding);
        return Boolean(config.enabled && config.apiKey && config.baseUrl && config.model);
    }

    function stringifyVoiceUnderstandingField(value) {
        if (value === undefined || value === null) return '';
        if (typeof value === 'string') return sanitizeVoicePromptText(value, 360);
        if (typeof value === 'number' || typeof value === 'boolean') return String(value);
        if (Array.isArray(value)) {
            return sanitizeVoicePromptText(value.map(stringifyVoiceUnderstandingField).filter(Boolean).join('，'), 360);
        }
        if (typeof value === 'object') {
            const direct = value.label || value.summary || value.description || value.text || value.value || value.name;
            if (direct) return stringifyVoiceUnderstandingField(direct);
            try {
                return sanitizeVoicePromptText(JSON.stringify(value), 360);
            } catch (error) {
                return '';
            }
        }
        return '';
    }

    function pickVoiceUnderstandingField(source, keys) {
        if (!source || typeof source !== 'object') return '';
        for (const key of keys) {
            if (Object.prototype.hasOwnProperty.call(source, key)) {
                const text = stringifyVoiceUnderstandingField(source[key]);
                if (text) return text;
            }
        }
        return '';
    }

    function parseVoiceUnderstandingJsonText(text) {
        const raw = String(text || '').trim();
        if (!raw) return null;
        const candidates = [
            raw,
            raw.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim()
        ];
        const firstBrace = raw.indexOf('{');
        const lastBrace = raw.lastIndexOf('}');
        if (firstBrace >= 0 && lastBrace > firstBrace) {
            candidates.push(raw.slice(firstBrace, lastBrace + 1));
        }
        for (const candidate of candidates) {
            if (!candidate) continue;
            try {
                const parsed = JSON.parse(candidate);
                if (parsed && typeof parsed === 'object') return parsed;
            } catch (error) { }
        }
        return null;
    }

    function normalizeVoiceUnderstandingResult(payload) {
        const safePayload = payload && typeof payload === 'object' ? payload : {};
        const rawText = stringifyVoiceUnderstandingField(safePayload.text || safePayload.output || safePayload.result || '');
        const parsed = (safePayload.parsed && typeof safePayload.parsed === 'object')
            ? safePayload.parsed
            : parseVoiceUnderstandingJsonText(rawText);
        const source = parsed && typeof parsed === 'object' ? parsed : {};
        const paceText = pickVoiceUnderstandingField(source, ['pace', 'speechRate', 'speech_rate', 'speed', '语速']);
        const pauseText = pickVoiceUnderstandingField(source, ['pauses', 'pause', 'breathing', '停顿', '呼吸']);
        return {
            provider: 'aliyun',
            model: stringifyVoiceUnderstandingField(safePayload.model) || '',
            rawText,
            parsed,
            summary: pickVoiceUnderstandingField(source, ['summary', 'caption', 'description', 'overall', '听感摘要', '摘要']),
            environment: pickVoiceUnderstandingField(source, ['environment', 'background', 'backgroundNoise', 'background_noise', 'noise', '环境音', '底噪']),
            pace: paceText ? { label: paceText } : null,
            pauses: pauseText ? { label: pauseText } : null,
            prosody: pickVoiceUnderstandingField(source, ['prosody', 'tone', 'intonation', '语气', '语调']),
            emotion: pickVoiceUnderstandingField(source, ['emotion', 'mood', 'affect', '情绪', '情绪倾向']),
            delivery: pickVoiceUnderstandingField(source, ['delivery', 'speakingStyle', 'speaking_style', 'style', '表达方式']),
            aiUnderstanding: pickVoiceUnderstandingField(source, ['aiUnderstanding', 'enhancedSummary', 'analysis', 'details', '细节'])
                || rawText
        };
    }

    function mergeVoiceUnderstandingMeta(localMeta, remoteMeta) {
        const hasLocal = localMeta && typeof localMeta === 'object';
        const hasRemote = remoteMeta && typeof remoteMeta === 'object';
        if (!hasRemote) return hasLocal ? localMeta : null;
        const merged = hasLocal ? { ...localMeta } : {};
        const assignIfText = (key, value) => {
            const text = stringifyVoiceUnderstandingField(value);
            if (text) merged[key] = text;
        };
        assignIfText('summary', remoteMeta.summary);
        assignIfText('environment', remoteMeta.environment);
        assignIfText('prosody', remoteMeta.prosody);
        assignIfText('emotion', remoteMeta.emotion);
        assignIfText('delivery', remoteMeta.delivery);
        assignIfText('aiUnderstanding', remoteMeta.aiUnderstanding || remoteMeta.rawText);
        if (remoteMeta.pace && typeof remoteMeta.pace === 'object') {
            merged.pace = { ...(hasLocal && localMeta.pace ? localMeta.pace : {}), ...remoteMeta.pace };
        }
        if (remoteMeta.pauses && typeof remoteMeta.pauses === 'object') {
            merged.pauses = { ...(hasLocal && localMeta.pauses ? localMeta.pauses : {}), ...remoteMeta.pauses };
        }
        merged.source = hasLocal ? `${localMeta.source || 'local_acoustic_analysis'}+aliyun_voice_understanding` : 'aliyun_voice_understanding';
        merged.enhancementProvider = 'aliyun';
        merged.enhancementModel = remoteMeta.model || '';
        merged.enhancedAt = Date.now();
        merged.confidence = hasLocal
            ? '本地声学分析 + 阿里云百炼语音理解增强'
            : '阿里云百炼语音理解增强';
        return merged;
    }

    async function aliyunVoiceUnderstanding(base64Audio, options = {}) {
        const config = normalizeVoiceUnderstandingSettings(appData?.appSettings?.voiceUnderstanding);
        if (!config.apiKey) {
            throw new Error('未配置阿里云百炼 API Key');
        }
        const response = await fetch(buildServerlessFunctionUrl('/.netlify/functions/aliyun-audio-understanding'), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                apiKey: config.apiKey,
                baseUrl: config.baseUrl,
                model: config.model,
                audioBase64: base64Audio,
                audioFormat: options.audioFormat || 'wav',
                transcript: options.transcript || '',
                localMeta: options.localMeta || null,
                prompt: config.prompt || DEFAULT_VOICE_UNDERSTANDING_PROMPT
            })
        });
        const payloadResult = await readResponsePayloadSafely(response);
        const data = payloadResult.data || {};
        if (!response.ok) {
            throw buildVoiceFunctionResponseError('阿里云语音理解增强', payloadResult, response);
        }
        if (!payloadResult.ok) {
            throw buildVoiceFunctionResponseError('阿里云语音理解增强', payloadResult, response);
        }
        return normalizeVoiceUnderstandingResult(data);
    }

    async function enhanceVoiceMessageMeta(transcript, localMeta, base64Audio, options = {}) {
        if (!base64Audio || !isVoiceUnderstandingEnhancementConfigured()) {
            return localMeta || null;
        }
        try {
            const remoteMeta = await aliyunVoiceUnderstanding(base64Audio, {
                transcript,
                localMeta,
                audioFormat: options.audioFormat || 'wav'
            });
            return mergeVoiceUnderstandingMeta(localMeta, remoteMeta);
        } catch (error) {
            console.warn('阿里云语音理解增强失败，已使用本地声学分析:', error);
            return localMeta || null;
        }
    }

    async function tencentSentenceRecognition(base64Data, dataLen) {
        const config = appData.appSettings.tencentAsr || {};
        const secretId = (config.secretId || '').trim();
        const secretKey = (config.secretKey || '').trim();
        if (!secretId || !secretKey) {
            throw new Error('未配置腾讯云 SecretId/SecretKey');
        }

        const response = await fetch(buildServerlessFunctionUrl('/.netlify/functions/tencent-asr'), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                secretId,
                secretKey,
                region: (config.region || '').trim(),
                engServiceType: config.engServiceType || '16k_zh',
                voiceFormat: config.voiceFormat || 'wav',
                data: base64Data,
                dataLen
            })
        });

        const payloadResult = await readResponsePayloadSafely(response);
        const data = payloadResult.data || {};
        if (!response.ok) {
            throw buildVoiceFunctionResponseError('腾讯云语音识别', payloadResult, response);
        }
        if (!payloadResult.ok) {
            throw buildVoiceFunctionResponseError('腾讯云语音识别', payloadResult, response);
        }
        if (data.Response && data.Response.Error) {
            throw new Error(`${data.Response.Error.Code}: ${data.Response.Error.Message}`);
        }
        return data.Response ? data.Response.Result : '';
    }
