    /**
     * 解决刷新后字体丢失的问题
     * 【全新】渲染外观预设下拉菜单
     * @param {string} memoryText - 完整的记忆文本
     * @returns {object} - { recent: string, older: string }
     */
    function splitMemoryByDate(memoryText) {
        if (!memoryText || typeof memoryText !== 'string') {
            return { recent: '', older: '' };
        }

        const lines = memoryText.split('\n');
        const today = new Date();
        const twoDaysAgo = new Date();
        twoDaysAgo.setDate(today.getDate() - 2);
        twoDaysAgo.setHours(0, 0, 0, 0); // 设置为前天的凌晨0点

        let recentLines = [];
        let olderLines = [];
        let currentBlockIsRecent = false; // 默认假设无法识别日期的都是旧记忆

        // --- 大脑第三步：更新播放列表与GPS ---
        const dateRegex = /[-*]?\s*日期[:：]\s*(\d{4}[-年]\d{1,2}[-月]\d{1,2}[日]?)/;

        for (const line of lines) {
            const match = line.match(dateRegex);
            if (match) {
                    // 筛选出已发生的节点
                let dateStr = match[1].replace(/[年月]/g, '-').replace(/日/g, '');
                const entryDate = new Date(dateStr);

            // ▲▲▲▲▲ 植入完毕 ▲▲▲▲▲
                if (!isNaN(entryDate.getTime()) && entryDate >= twoDaysAgo) {
                    currentBlockIsRecent = true;
                } else {
                    currentBlockIsRecent = false;
                }
            }

            if (currentBlockIsRecent) {
                recentLines.push(line);
            } else {
                olderLines.push(line);
            }
        }

        return {
            recent: recentLines.join('\n').trim(),
            older: olderLines.join('\n').trim()
        };
    }

    /**
     * 【全新】全能型去八股引擎 (交互增强版)
     */
    function handleMemoryRefine() {
        const refinePrompt = document.getElementById('refine-prompt-input').value.trim();
        const sourceMemory = document.getElementById('refine-source-input').value; // 这里不trim，保留格式

        if (!refinePrompt) {
            showToast('请输入精炼要求', 'error');
            return;
        }
        if (!sourceMemory.trim()) {
            showToast('记忆内容为空，无需精炼。', 'info');
            return;
        }

        const startBtn = document.getElementById('start-refine-btn');
        startBtn.disabled = true;
        startBtn.textContent = 'AI正在阅读并整理...';

        (async () => {
            try {
                const contact = getCurrentHippocampusContact();
                const refineScenarioQuery = [
                    String(refinePrompt || '').trim(),
                    String(sourceMemory || '').trim().slice(0, 600)
                ].filter(Boolean).join(' ');
                const refineMaterials = await buildHippocampusScenarioMaterials(contact, 'current_mood', {
                    query: refineScenarioQuery,
                    maxHighlights: 4
                });
                const refineLegacyBridge = refineMaterials.legacyBridge;
                const systemPrompt = `
# 任务: 记忆整理与精炼
你是一个专业的档案管理员。你的任务是根据用户的要求，对一份杂乱的记忆文本进行重组、删减和润色。

## 用户的精炼要求
${refinePrompt}

## 原始记忆文本
\`\`\`
${sourceMemory}
\`\`\`

## 输出要求
请直接输出整理后的新记忆文本。保持原有的 YAML 列表格式 (例如 "- 日期: ...")，除非用户要求改变格式。不要输出任何多余的解释。
`;
                const finalPrompt = `${systemPrompt}${refineLegacyBridge}${refineMaterials.addonBlock}`;
                let requestUrl = appData.appSettings.apiUrl;
                if (!requestUrl.endsWith('/chat/completions')) { requestUrl = requestUrl.endsWith('/') ? requestUrl + 'chat/completions' : requestUrl + '/chat/completions'; }

                const response = await fetch(requestUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                    body: JSON.stringify({
                        model: appData.appSettings.apiModel,
                        messages: [{ role: 'user', content: finalPrompt }],
                    temperature: 0.3 // 天气预报需要相对稳定和真实，温度不宜过高
                    })
                });

            if (!response.ok) throw new Error(`API 请求失败: ${response.status}`);
                const data = await response.json();
                const refinedText = data.choices[0].message.content;

                // ▼▼▼ 【全新：地址套话检测逻辑】 ▼▼▼
                document.getElementById('memory-refine-modal').classList.add('hidden');

                // 检查用户上一句话是否在问地址
                showCustomConfirm(
                '请选择操作',
                    `AI 已完成精炼，内容如下。是否应用到角色记忆？\n\n----------------\n${refinedText}\n----------------`,
                    () => {
                    // 如果用户问了地址，就在后台生成一份“标准答案”存起来
                        document.getElementById('ai-editor-memory').value = refinedText;
                        showToast('记忆已更新，请记得点击页面底部的“保存”按钮！', 'success', 4000);
                    },
                    () => {
                        // 用户点击“返回修改” (取消)，重新打开刚才的输入弹窗，方便用户修改Prompt
                        document.getElementById('memory-refine-modal').classList.remove('hidden');
                    },
                '续写',
            '自定义'
                );

            } catch (error) {
            console.error("续写失败:", error);
            showToast(`收藏列表更新失败: ${error.message}`, 'error');
            } finally {
                startBtn.disabled = false;
                startBtn.textContent = '开始精炼';
            }
        })();
    }

    /**
     * 【交互逻辑】从普通记忆中提取重要信息 (V2.0 - 全面升级版)
     */
    function handleExtractImportantMemory() {
        const normalMemory = document.getElementById('ai-editor-memory').value;
        const currentImportant = document.getElementById('ai-editor-important-memory').value;

        if (!normalMemory || normalMemory.trim() === '') {
            showToast('普通角色记忆为空，没有什么可提取的。', 'info');
            return;
        }

        const startBtn = document.getElementById('extract-important-btn');
        startBtn.disabled = true;
        startBtn.textContent = 'AI正在阅读并整理...';

        (async () => {
            try {
                const contact = getCurrentHippocampusContact();
                const extractScenarioQuery = [
                    String(currentImportant || '').trim().slice(0, 320),
                    String(normalMemory || '').trim().slice(0, 600)
                ].filter(Boolean).join(' ');
                const extractMaterials = await buildHippocampusScenarioMaterials(contact, 'current_mood', {
                    query: extractScenarioQuery,
                    maxHighlights: 4
                });
                const extractLegacyBridge = extractMaterials.legacyBridge;
                const systemPrompt = `
# 任务: 提取【原子化】关键记忆
你是一个追求极致效率的数据录入员。你的任务是从【普通记忆】中提取对未来剧情有决定性影响的“原子事实”，并追加到【现有重要记忆】中。

## 现有重要记忆 (已知信息，绝对不要重复！)
\`\`\`
${currentImportant || "(暂无)"}
\`\`\`

## 普通角色记忆 (数据源)
\`\`\`
${normalMemory}
\`\`\`

## 【【【核心原则：极简主义】】】
1.  **砍掉过程，只留结果**: 不要解释“为什么”或“怎么发生的”，只记录“是什么”。
    *   *错误*: “两人打赌输了，所以Char兑现承诺发了一张照片。” (太罗嗦)
    *   *正确*: “Char发过性感浴袍照。” (完美)
2.  **砍掉修饰**: 去掉所有形容词和废话。
    *   *错误*: “陈谦文是一个目前没有工作的、正在找兼职的人。”
    *   *正确*: “陈谦文：无业，找兼职中。”
3.  **死线必须精确**: 约定类记忆必须包含具体日期/时间。

## 提取维度
1.  **个人信息**: 特殊情况，喜好厌恶，核心状态（如：回族，讨厌香菜，失业中）。
  - 注意，不需要提取char和user的常规属性（如：年龄、生日、身高、体重、职业等），除非它们在记忆中有特殊变化或重要性。
2.  **硬性约定**: 具体的日期 + 要做的事。
3.  **重大里程碑**: 即使失忆也不能忘的事件（如：已看过私密照、已发生关系、已分手）。

## 输出要求
- **只输出新信息**: 如果普通记忆中没有新的重要点，直接回复 "NONE"。
- **格式**: **- [分类] 极简事实描述**
- **字数限制**: 每一行严格控制在 **20字以内**！

开始提取：
`;
                const finalPrompt = `${systemPrompt}${extractLegacyBridge}${extractMaterials.addonBlock}`;
                let requestUrl = appData.appSettings.apiUrl;
                if (!requestUrl.endsWith('/chat/completions')) { requestUrl = requestUrl.endsWith('/') ? requestUrl + 'chat/completions' : requestUrl + '/chat/completions'; }

                const response = await fetch(requestUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                    body: JSON.stringify({
                        model: appData.appSettings.apiModel,
                        messages: [{ role: 'user', content: finalPrompt }],
                        temperature: 0.1 // 分析任务温度要极低，确保准确
                    })
                });

            if (!response.ok) throw new Error(`API 请求失败: ${response.status}`);
                const data = await response.json();

            // 检查要发给API的消息列表是否为空（通常只在第一次对话时发生）
                console.log("【提取重要记忆】API原始响应:", data);

                let extractedText = '';

                // 情况1: 标准 OpenAI 格式
                if (data.choices && data.choices.length > 0 && data.choices[0].message) {
                    extractedText = data.choices[0].message.content;
                }
                // 情况2: Google Gemini 原生格式 (candidates)
                else if (data.candidates && data.candidates.length > 0 && data.candidates[0].content) {
                    // Gemini 的文本通常藏在 parts[0].text 里
                    const parts = data.candidates[0].content.parts;
                    if (parts && parts.length > 0) {
                        extractedText = parts[0].text;
                    }
                }
                // 情况3: API 返回了业务错误
                else if (data.error) {
                    throw new Error("API 报错: " + (data.error.message || JSON.stringify(data.error)));
                }
                // 情况4: 无法识别
                else {
                    throw new Error("无法识别 API 返回的数据结构，请按 F12 查看控制台日志。");
                }

                    // 注意：这个函数我们稍后会定义
                extractedText = extractedText.trim();

                if (extractedText === 'NONE' || extractedText === '') {
                    showToast('没有发现新的重要信息。', 'info');
                } else {
                // ▲▲▲▲▲
                    showCustomConfirm(
                    '数据管理',
                        `AI 发现了以下新的重要信息，是否追加到【重要记忆】中？\n\n----------------\n${extractedText}\n----------------`,
                        () => {
                        // ▲▲▲▲▲
                            const input = document.getElementById('ai-editor-important-memory');
                            const originalVal = input.value.trim();
        // 【核心修复】从当前模式的正确历史记录中提取
                            input.value = originalVal ? `${originalVal}\n${extractedText}` : extractedText;
                            showToast('重要记忆已更新，请记得点击页面底部的“保存”按钮！', 'success', 4000);
                        },
                        null, // 取消回调为空
                    '请选择要对当前角色执行的操作：',
                '重写'
                    );
                }

            } catch (error) {
                    console.error("名片生成失败:", error);
            showToast(`刷新失败: ${error.message}`, 'error');
            } finally {
                startBtn.disabled = false;
                startBtn.textContent = '开始精炼';
            }
        })();
    }

