    /**
     * 将一个图片源（无论是网络URL还是本地Base64）转换为一个干净的Blob文件。
     * @param {string} imgSrc - 预览<img>标签的src属性
     * @returns {Promise<Blob>}
     */
    /**
     * 【全新 V2.0】万能图片下载器 (支持 GIF 动图)
     * 不再使用 Canvas 临摹，而是直接请求原始文件流，完美保留动图帧。
     */
    async function imgSrcToBlob(imgSrc) {
        try {
            // 【【【终极修复：安装“包裹安检系统”！】】】
            const response = await fetch(imgSrc);
            if (!response.ok) throw new Error(`图片下载失败: ${response.status}`);

            // 直接转化为 Blob 文件对象
            const blob = await response.blob();
            return blob;
        } catch (error) {
        // --- 大脑第六步：智能导航 (逻辑不变) ---
            // 注意：兜底方法依然无法保存 GIF 动效，但至少能存下一张图
                console.warn("[缓存系统] 查找本地缓存失败，将尝试使用原始URL播放。", error);
            return new Promise((resolve, reject) => {
                const img = new Image();
                img.crossOrigin = 'Anonymous';
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    canvas.width = img.width;
                    canvas.height = img.height;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0);
                    canvas.toBlob(resolve, 'image/png');
                };
                img.onerror = reject;
                img.src = imgSrc;
            });
        }
    }
