    function getVoiceCallTransientStatusText() {
        if (!voiceCallActive) return '';
        if (voiceCallCurrentSpeaker === 'assistant') return '对方正在说话';
        if (voiceCallCurrentSpeaker === 'user') return '你正在说话';
        if (voiceCallCurrentSpeaker === 'recognizing') return '正在识别';
        return '';
    }

    function appendVoiceCallPlainText(container, text) {
        const parts = String(text || '').split('\n');
        parts.forEach((part, index) => {
            if (index > 0) {
                container.appendChild(document.createElement('br'));
            }
            if (part) {
                container.appendChild(document.createTextNode(part));
            }
        });
    }

    function buildVoiceCallRichTextFragment(text) {
        const fragment = document.createDocumentFragment();
        const source = String(text || '');
        const actionPattern = /(#[^#\n]{1,80}#|\*[^*\n]{1,80}\*|（[^（）()\n]{1,80}[）)]|\([^()\n]{1,80}\))/g;
        let lastIndex = 0;
        let match;

        while ((match = actionPattern.exec(source)) !== null) {
            if (match.index > lastIndex) {
                appendVoiceCallPlainText(fragment, source.slice(lastIndex, match.index));
            }

            const token = match[0];
            const actionText = token.slice(1, -1).trim();
            if (token.startsWith('(') && token.endsWith(')') && isSupportedMinimaxTtsAffectTag(actionText)) {
                lastIndex = match.index + token.length;
                continue;
            }
            if (actionText) {
                const actionSpan = document.createElement('span');
                actionSpan.className = 'vc-action-text';
                actionSpan.textContent = actionText;
                fragment.appendChild(actionSpan);
            }
            lastIndex = match.index + token.length;
        }

        if (lastIndex < source.length) {
            appendVoiceCallPlainText(fragment, source.slice(lastIndex));
        }

        return fragment;
    }

    function stripVoiceCallActionDescriptions(text, options = {}) {
        return stripVoicePerformanceDescriptions(text, options);
    }

    function getVoiceCallDisplayContent(message) {
        if (!message || typeof message !== 'object') return '';
        return String(message.displayContent || message.content || '');
    }

    function applyVoiceCallActionDescriptionRendering(root, rawText) {
        if (!root) return;
        const messageBubble = root.querySelector('.message');
        if (!messageBubble) return;
        if (
            messageBubble.classList.contains('message-voice')
            || messageBubble.classList.contains('message-voice-call-record')
            || messageBubble.classList.contains('message-video-call-record')
        ) {
            return;
        }
        messageBubble.classList.add('vc-rich-message');
        messageBubble.replaceChildren(buildVoiceCallRichTextFragment(rawText));
    }

    function writeVoiceCallMiniTransientStatus() {
        const transientStatusText = getVoiceCallTransientStatusText();
        if (!transientStatusText) return false;

        const miniStatus = document.getElementById('voice-call-mini-status');
        const liveDuration = document.getElementById('vc-live-duration');
        if (miniStatus) miniStatus.textContent = transientStatusText;
        if (liveDuration) liveDuration.textContent = transientStatusText;
        return true;
    }

    function refreshVoiceCallMiniFeedbackState() {
        renderVoiceCallMiniHistory();
        if (!writeVoiceCallMiniTransientStatus()) {
            if (voiceCallMiniStatusOverrideTimer) {
                clearInterval(voiceCallMiniStatusOverrideTimer);
                voiceCallMiniStatusOverrideTimer = null;
            }
            syncVoiceCallMiniStatus();
            return;
        }

        if (voiceCallMiniStatusOverrideTimer) return;
        voiceCallMiniStatusOverrideTimer = setInterval(() => {
            if (!writeVoiceCallMiniTransientStatus()) {
                clearInterval(voiceCallMiniStatusOverrideTimer);
                voiceCallMiniStatusOverrideTimer = null;
                syncVoiceCallMiniStatus();
            }
        }, 240);
    }

    function syncVoiceCallMiniStatus() {
        const miniStatus = document.getElementById('voice-call-mini-status');
        const liveDuration = document.getElementById('vc-live-duration');
        const statusText = (document.getElementById('vc-status') && document.getElementById('vc-status').textContent)
            || (voiceCallActive ? '通话中' : '');
        if (miniStatus) miniStatus.textContent = statusText;
        if (liveDuration) liveDuration.textContent = statusText || '--:--';
    }

    function renderVoiceCallMiniHistory() {
        const historyEl = document.getElementById('voice-call-mini-history');
        if (!historyEl) return;
        historyEl.innerHTML = '';
        voiceCallHistory.forEach((msg) => {
            if (!msg || !String(msg.content || '').trim()) return;
            const bubble = document.createElement('div');
            bubble.className = `voice-call-mini-msg ${msg.role === 'user' ? 'user' : 'assistant'}`;
            bubble.replaceChildren(buildVoiceCallRichTextFragment(getVoiceCallDisplayContent(msg)));
            historyEl.appendChild(bubble);
        });
        if (voiceCallActive && voiceCallCurrentSpeaker === 'assistant') {
            const pendingBubble = document.createElement('div');
            pendingBubble.className = 'voice-call-mini-msg assistant loading-dots';
            pendingBubble.textContent = '对方正在说话';
            historyEl.appendChild(pendingBubble);
        }
        historyEl.scrollTop = historyEl.scrollHeight;
    }

    function updateVoiceCallMuteButtons() {
        const muteBtn = document.getElementById('vc-mute-btn');
        if (muteBtn) {
            muteBtn.classList.toggle('muted', isUserMuted);
            const micOn = muteBtn.querySelector('.icon-mic-on');
            const micOff = muteBtn.querySelector('.icon-mic-off');
            if (micOn) micOn.classList.toggle('hidden', isUserMuted);
            if (micOff) micOff.classList.toggle('hidden', !isUserMuted);
        }
        const liveMuteBtn = document.getElementById('vc-live-mute-btn');
        if (liveMuteBtn) {
            liveMuteBtn.classList.toggle('active', isUserMuted);
            liveMuteBtn.textContent = isUserMuted ? '已静音' : '静音';
        }
    }

