    const packageAndDownload = async (includeHistory) => {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) {
            showCustomAlert('错误', '打包时找不到当前角色。');
            return;
        }

                // 1. 获取目标
            let loadingToast = showToast('正在准备数据...', 'info', 0);
        try {
            validateCosExportSettings(getCosExportSettings());
            const characterToExport = JSON.parse(JSON.stringify(contact));
        // 【核心修复】在这里盖上“已处理”的邮戳，防止重复生成
            if (loadingToast) dismissToast(loadingToast);
            if (!includeHistory) {
                delete characterToExport.onlineChatHistory;
                delete characterToExport.offlineChatHistory;
                delete characterToExport.voiceCallLogs;
                loadingToast = showToast('正在整理角色设定...', 'info', 0);
            } else {
                loadingToast = showToast('正在整理角色与聊天记录...', 'info', 0);
            }

            characterToExport.isPartner = appData.appSettings.partnerId === contact.id;

            const imageData = {};
                    // 筛选1：过去发生的节点 (作为背景故事)
            const imageKeys = {
                avatar: `${contact.id}_avatar`,
                user_avatar: `${contact.id}_user_avatar`,
                photo: `${contact.id}_photo`
            };
            for (const genericKey in imageKeys) {
                const specificKey = imageKeys[genericKey];
                const imageBlob = await db.getImage(specificKey);
                if (imageBlob) { imageData[genericKey] = await blobToBase64(imageBlob); }
            }

    // 【【【这个辅助函数现在已经不再被上面的代码使用，但为了不破坏你的文件结构，我们保留它】】】
        // 步骤2：将剧本内容存入“暂存保险箱”
            const allSongsToPack = [
                ...(characterToExport.musicProfile.originalSongs || []),
                ...(characterToExport.musicProfile.auditionClips || [])
            ];

        // 步骤3：清空临时的剧本草稿，并关闭罗盘
            for (const song of allSongsToPack) {
                if (song.id) {
                    const audioBlob = await db.getImage(song.id);
                    if (audioBlob) {
                        // 我们直接用歌曲的ID作为key，存入图片数据包
                        imageData[song.id] = await blobToBase64(audioBlob);
                    }
                }
            }

            const backupData = {
                type: 'AI_CHARACTER_BACKUP_V1',
                characterData: characterToExport,
                imageData: imageData
            };

            const backupString = JSON.stringify(backupData, null, 2);
            const blob = new Blob([backupString], { type: 'application/json' });
            const fileName = buildRoleExportFileName('character', contact.remark || contact.name, includeHistory ? 'full' : 'persona');

            if (loadingToast) loadingToast.textContent = '正在上传到您的腾讯云 COS... 0%';
            await new Promise(r => setTimeout(r, 30));

            const exportResult = await uploadBlobToCos(blob, fileName, (progress) => {
                if (loadingToast) {
                    loadingToast.textContent = `正在上传到您的腾讯云 COS... ${progress}%`;
                }
            });

            if (loadingToast) dismissToast(loadingToast);
            loadingToast = null;
            showToast(`角色 [${contact.remark}] 已上传成功`, 'success');
            showCosExportResult(exportResult);

        } catch (error) {
            if (loadingToast) dismissToast(loadingToast);
            console.error('角色数据导出失败:', error);
            showCustomAlert('导出失败', getErrorMessage(error, '角色数据导出失败，请重试'));
        }
    };

