    /**
     * 将Base64编码的文本“翻译”回Blob文件对象
     */
    async function dataURLToBlob(dataurl) {
        const source = String(dataurl || '').trim();
        if (!source) {
            throw new Error('图片数据为空，无法恢复');
        }
        const match = source.match(/^data:([^;,]+)?(?:;charset=[^;,]+)?(;base64)?,(.*)$/i);
        if (!match) {
            throw new Error('图片数据格式无效，无法恢复');
        }
        const mimeType = match[1] || 'application/octet-stream';
        const isBase64 = Boolean(match[2]);
        const body = match[3] || '';

        if (isBase64) {
            const binary = atob(body);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i += 1) {
                bytes[i] = binary.charCodeAt(i);
            }
            return new Blob([bytes], { type: mimeType });
        }

        return new Blob([decodeURIComponent(body)], { type: mimeType });
    }

    function parseJsonMaybe(text) {
        const source = String(text || '').trim();
        if (!source) return null;
        try {
            return JSON.parse(source);
        } catch (_) {
            return null;
        }
    }

    function decodeBase64Utf8(value) {
        const source = String(value || '').trim();
        if (!source) return '';
        try {
            const binary = atob(source);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i += 1) {
                bytes[i] = binary.charCodeAt(i);
            }
            return new TextDecoder('utf-8').decode(bytes);
        } catch (_) {
            try {
                return decodeURIComponent(escape(atob(source)));
            } catch (__) {
                return '';
            }
        }
    }

    function decodePngTextBytes(bytes) {
        if (!(bytes instanceof Uint8Array)) return '';
        try {
            return new TextDecoder('utf-8').decode(bytes);
        } catch (_) {
            return Array.from(bytes).map(code => String.fromCharCode(code)).join('');
        }
    }

    function parsePngTextChunks(arrayBuffer) {
        const bytes = new Uint8Array(arrayBuffer || []);
        const signature = [137, 80, 78, 71, 13, 10, 26, 10];
        if (bytes.length < 12 || !signature.every((value, index) => bytes[index] === value)) return {};
        const result = {};
        let offset = 8;
        const readUint32 = (pos) => (
            ((bytes[pos] << 24) >>> 0)
            + (bytes[pos + 1] << 16)
            + (bytes[pos + 2] << 8)
            + bytes[pos + 3]
        ) >>> 0;
        while (offset + 8 <= bytes.length) {
            const length = readUint32(offset);
            const type = decodePngTextBytes(bytes.slice(offset + 4, offset + 8));
            const dataStart = offset + 8;
            const dataEnd = dataStart + length;
            if (dataEnd > bytes.length) break;
            const data = bytes.slice(dataStart, dataEnd);
            if (type === 'tEXt') {
                const zeroIndex = data.indexOf(0);
                if (zeroIndex > 0) {
                    const key = decodePngTextBytes(data.slice(0, zeroIndex)).trim();
                    const text = decodePngTextBytes(data.slice(zeroIndex + 1)).trim();
                    if (key && text) result[key] = text;
                }
            } else if (type === 'iTXt') {
                let cursor = 0;
                const readNullTerminated = () => {
                    const end = data.indexOf(0, cursor);
                    if (end < 0) return '';
                    const text = decodePngTextBytes(data.slice(cursor, end));
                    cursor = end + 1;
                    return text;
                };
                const key = readNullTerminated().trim();
                const compressionFlag = data[cursor] || 0;
                cursor += 2; // compression flag + method
                readNullTerminated(); // language tag
                readNullTerminated(); // translated keyword
                if (key && (compressionFlag === 0 || typeof pako !== 'undefined')) {
                    let text = '';
                    if (compressionFlag === 0) {
                        text = decodePngTextBytes(data.slice(cursor)).trim();
                    } else {
                        try {
                            text = new TextDecoder('utf-8').decode(pako.inflate(data.slice(cursor))).trim();
                        } catch (_) {
                            text = '';
                        }
                    }
                    if (text) result[key] = text;
                }
            } else if (type === 'zTXt' && typeof pako !== 'undefined') {
                const zeroIndex = data.indexOf(0);
                if (zeroIndex > 0) {
                    const key = decodePngTextBytes(data.slice(0, zeroIndex)).trim();
                    const compressed = data.slice(zeroIndex + 2);
                    try {
                        const text = new TextDecoder('utf-8').decode(pako.inflate(compressed)).trim();
                        if (key && text) result[key] = text;
                    } catch (_) { }
                }
            }
            offset = dataEnd + 4;
            if (type === 'IEND') break;
        }
        return result;
    }

    function extractSillyTavernCardPayload(raw) {
        if (!raw) return null;
        if (typeof raw === 'string') {
            const directJson = parseJsonMaybe(raw);
            if (directJson) return extractSillyTavernCardPayload(directJson);
            const decoded = decodeBase64Utf8(raw);
            const decodedJson = parseJsonMaybe(decoded);
            return decodedJson ? extractSillyTavernCardPayload(decodedJson) : null;
        }
        if (!isImportedPlainObject(raw)) return null;
        if (raw.spec === 'chara_card_v2' || raw.spec === 'chara_card_v3' || raw.data || raw.name || raw.description) {
            return raw;
        }
        const candidates = ['chara', 'ccv3', 'character', 'card', 'character_card', 'characterCard', 'payload'];
        for (const key of candidates) {
            if (raw[key]) {
                const payload = extractSillyTavernCardPayload(raw[key]);
                if (payload) return payload;
            }
        }
        return null;
    }

    function collectSillyTavernKeywordList(value) {
        if (Array.isArray(value)) {
            return value
                .flatMap(collectSillyTavernKeywordList)
                .map(item => String(item || '').trim())
                .filter(Boolean);
        }
        if (value && typeof value === 'object') {
            return Object.values(value)
                .flatMap(collectSillyTavernKeywordList)
                .map(item => String(item || '').trim())
                .filter(Boolean);
        }
        return String(value || '')
            .split(/[,，;；\n\r]+/)
            .map(item => item.trim())
            .filter(Boolean);
    }

    function normalizeSillyTavernWorldBookEntries(rawBook) {
        const source = rawBook && typeof rawBook === 'object' ? rawBook : {};
        const entrySource = Array.isArray(rawBook)
            ? rawBook
            : (source.entries || source.world_info || source.worldInfo || source.items || []);
        const rawEntries = Array.isArray(entrySource)
            ? entrySource
            : (entrySource && typeof entrySource === 'object' ? Object.values(entrySource) : []);
        return rawEntries.map((entry, index) => {
            if (!entry || typeof entry !== 'object') return null;
            const keys = []
                .concat(collectSillyTavernKeywordList(entry.keys))
                .concat(collectSillyTavernKeywordList(entry.key))
                .concat(collectSillyTavernKeywordList(entry.keywords))
                .map(item => String(item || '').trim())
                .filter(Boolean);
            const key = String(entry.comment || entry.name || entry.title || keys[0] || `酒馆词条 ${index + 1}`).trim();
            const value = String(entry.content || entry.value || entry.text || '').trim();
            if (!key && !value) return null;
            const secondaryKeys = []
                .concat(collectSillyTavernKeywordList(entry.keys_secondary))
                .concat(collectSillyTavernKeywordList(entry.secondary_keys))
                .concat(collectSillyTavernKeywordList(entry.secondaryKeys));
            const keywords = keys.concat(secondaryKeys).map(item => String(item || '').trim()).filter(Boolean).join('，');
            const depthValue = entry.depth !== undefined
                ? entry.depth
                : (entry.insertion_depth !== undefined
                    ? entry.insertion_depth
                    : (entry.scan_depth !== undefined ? entry.scan_depth : entry.scanDepth));
            const insertionDepthValue = entry.insertion_depth !== undefined
                ? entry.insertion_depth
                : (entry.insertionDepth !== undefined ? entry.insertionDepth : depthValue);
            const scanDepthValue = entry.scan_depth !== undefined
                ? entry.scan_depth
                : (entry.scanDepth !== undefined ? entry.scanDepth : undefined);
            return {
                id: createWorldBookId('stwb'),
                key: key || `酒馆词条 ${index + 1}`,
                value,
                enabled: entry.disable !== true && entry.enabled !== false,
                triggerMode: entry.constant === true ? 'always' : 'keyword',
                keywords,
                groupId: 'sillytavern-import',
                sortOrder: Number.isFinite(Number(entry.order !== undefined ? entry.order : entry.sortOrder)) ? Number(entry.order !== undefined ? entry.order : entry.sortOrder) : index,
                depth: Math.max(0, Math.floor(Number(depthValue) || 4)),
                insertionDepth: Number.isFinite(Number(insertionDepthValue)) ? Math.max(0, Math.floor(Number(insertionDepthValue))) : undefined,
                scanDepth: Number.isFinite(Number(scanDepthValue)) ? Math.max(0, Math.floor(Number(scanDepthValue))) : undefined,
                position: String(entry.position || entry.insertion_position || entry.insertionPosition || '').trim(),
                insertionPosition: String(entry.insertion_position || entry.insertionPosition || entry.position || '').trim(),
                selective: Boolean(entry.selective),
                probability: Number.isFinite(Number(entry.probability)) ? Number(entry.probability) : undefined,
                useProbability: entry.useProbability === true || entry.use_probability === true,
                caseSensitive: entry.caseSensitive === true || entry.case_sensitive === true,
                matchWholeWords: entry.matchWholeWords === true || entry.match_whole_words === true,
                recursive: entry.recursive === true || entry.recursion === true,
                source: 'sillytavern'
            };
        }).filter(Boolean);
    }

    function addSillyTavernOpeningRemarkCandidate(target, seen, value) {
        if (!target || !seen || value === undefined || value === null) return;
        if (Array.isArray(value)) {
            value.forEach(item => addSillyTavernOpeningRemarkCandidate(target, seen, item));
            return;
        }
        if (value && typeof value === 'object') {
            const preferred = value.content
                || value.message
                || value.text
                || value.greeting
                || value.first_mes
                || value.firstMessage
                || value.first_message
                || value.value;
            if (preferred !== undefined && preferred !== null) {
                addSillyTavernOpeningRemarkCandidate(target, seen, preferred);
                return;
            }
            Object.values(value).forEach(item => {
                if (typeof item === 'string') addSillyTavernOpeningRemarkCandidate(target, seen, item);
            });
            return;
        }
        const text = String(value || '').trim();
        if (!text) return;
        const key = text.replace(/\s+/g, ' ').trim();
        if (!key || seen.has(key)) return;
        seen.add(key);
        target.push(text);
    }

    function collectSillyTavernOpeningRemarks(payload, data) {
        const result = [];
        const seen = new Set();
        const sources = [data, payload].filter(item => item && typeof item === 'object');
        sources.forEach(source => {
            [
                source.first_mes,
                source.firstMessage,
                source.first_message,
                source.greeting,
                source.opening,
                source.openingRemark
            ].forEach(value => addSillyTavernOpeningRemarkCandidate(result, seen, value));
        });
        sources.forEach(source => {
            [
                source.alternate_greetings,
                source.alternateGreetings,
                source.alternate_first_mes,
                source.alternate_first_messages,
                source.alternateFirstMessages,
                source.greetings,
                source.openingRemarks,
                source.openings,
                source.first_messages,
                source.firstMessages
            ].forEach(value => addSillyTavernOpeningRemarkCandidate(result, seen, value));
            if (source.extensions && typeof source.extensions === 'object') {
                [
                    source.extensions.alternate_greetings,
                    source.extensions.alternateGreetings,
                    source.extensions.openingRemarks,
                    source.extensions.openings
                ].forEach(value => addSillyTavernOpeningRemarkCandidate(result, seen, value));
            }
        });
        return result;
    }

    function normalizeContactOpeningRemarkOptions(contact) {
        const result = [];
        const seen = new Set();
        if (!contact || typeof contact !== 'object') return result;
        addSillyTavernOpeningRemarkCandidate(result, seen, contact.defaultOpeningRemark);
        addSillyTavernOpeningRemarkCandidate(result, seen, contact.sillyTavernOpeningRemarks);
        addSillyTavernOpeningRemarkCandidate(result, seen, contact.openingRemarks);
        addSillyTavernOpeningRemarkCandidate(result, seen, contact.firstMessages);
        return result;
    }

    function normalizeSillyTavernCharacterCard(raw) {
        const payload = extractSillyTavernCardPayload(raw);
        if (!payload) return null;
        const data = isImportedPlainObject(payload.data) ? payload.data : payload;
        const name = String(data.name || payload.name || '').trim();
        const description = String(data.description || data.desc || '').trim();
        const personality = String(data.personality || '').trim();
        const scenario = String(data.scenario || '').trim();
        const systemPrompt = String(data.system_prompt || data.systemPrompt || '').trim();
        const postHistory = String(data.post_history_instructions || data.postHistoryInstructions || '').trim();
        const openingRemarks = collectSillyTavernOpeningRemarks(payload, data);
        const firstMessage = openingRemarks[0] || String(data.first_mes || data.firstMessage || '').trim();
        const exampleMessages = String(data.mes_example || data.example_dialogue || '').trim();
        const persona = [
            description ? `角色描述：\n${description}` : '',
            personality ? `性格：\n${personality}` : '',
            scenario ? `场景：\n${scenario}` : ''
        ].filter(Boolean).join('\n\n');
        const book = data.character_book
            || data.characterBook
            || data.world_book
            || data.worldBook
            || data.world_info
            || data.worldInfo
            || data.lorebook
            || data.book
            || payload.character_book
            || payload.world_book
            || payload.worldBook
            || payload.world_info
            || payload.worldInfo
            || (data.extensions && (
                data.extensions.world_book
                || data.extensions.worldBook
                || data.extensions.world_info
                || data.extensions.worldInfo
                || data.extensions.character_book
                || data.extensions.characterBook
            ))
            || (payload.extensions && (
                payload.extensions.world_book
                || payload.extensions.worldBook
                || payload.extensions.world_info
                || payload.extensions.worldInfo
                || payload.extensions.character_book
                || payload.extensions.characterBook
            ));
        const worldBookEntries = normalizeSillyTavernWorldBookEntries(book);
        const regexScripts = extractSillyTavernRegexScripts(payload, 'character')
            .concat(extractSillyTavernRegexScripts(data, 'character'));
        const uniqueRegexScripts = [];
        const seenRegexIds = new Set();
        regexScripts.forEach((script) => {
            const id = toHippocampusTrimmedString(script && script.id);
            if (id && seenRegexIds.has(id)) return;
            if (id) seenRegexIds.add(id);
            uniqueRegexScripts.push(Object.assign({}, script, { sourceType: 'character' }));
        });
        if (!name && !persona && !systemPrompt && openingRemarks.length === 0 && worldBookEntries.length === 0 && uniqueRegexScripts.length === 0) return null;
        return {
            name,
            persona,
            systemPrompt,
            postHistory,
            firstMessage,
            openingRemarks,
            exampleMessages,
            creatorNotes: String(data.creator_notes || data.creatorNotes || '').trim(),
            worldBookEntries,
            regexScripts: uniqueRegexScripts
        };
    }

    function applySillyTavernCharacterCardToContact(contact, card) {
        if (!contact || !card) return false;
        if (card.name) {
            contact.name = card.name;
            contact.remark = card.name;
        }
        if (card.persona) contact.persona = card.persona;
        const styleParts = [
            card.systemPrompt ? `酒馆系统提示：\n${card.systemPrompt}` : '',
            card.postHistory ? `酒馆后置提示：\n${card.postHistory}` : '',
            card.exampleMessages ? `示例对话：\n${card.exampleMessages}` : ''
        ].filter(Boolean);
        if (styleParts.length > 0) {
            contact.chatStyle = styleParts.join('\n\n');
        }
        const importedOpeningRemarks = Array.isArray(card.openingRemarks) && card.openingRemarks.length > 0
            ? card.openingRemarks
            : (card.firstMessage ? [card.firstMessage] : []);
        if (importedOpeningRemarks.length > 0) {
            const mergedOpeningRemarks = [];
            const seenOpeningRemarks = new Set();
            addSillyTavernOpeningRemarkCandidate(mergedOpeningRemarks, seenOpeningRemarks, contact.defaultOpeningRemark);
            addSillyTavernOpeningRemarkCandidate(mergedOpeningRemarks, seenOpeningRemarks, contact.sillyTavernOpeningRemarks);
            addSillyTavernOpeningRemarkCandidate(mergedOpeningRemarks, seenOpeningRemarks, importedOpeningRemarks);
            contact.defaultOpeningRemark = importedOpeningRemarks[0];
            contact.sillyTavernOpeningRemarks = mergedOpeningRemarks;
        }
        if (Array.isArray(card.worldBookEntries) && card.worldBookEntries.length > 0) {
            appendWorldBookEntriesToTarget(contact, card.worldBookEntries, {
                groupId: 'sillytavern-import',
                groupName: '酒馆导入'
            });
        }
        if (Array.isArray(card.regexScripts) && card.regexScripts.length > 0) {
            const existing = normalizeSillyTavernRegexScripts(contact.regexScripts, 'character');
            const seen = new Set(existing.map(script => toHippocampusTrimmedString(script.id)).filter(Boolean));
            card.regexScripts.forEach((script) => {
                const normalized = normalizeSillyTavernRegexScript(script, existing.length, 'character');
                if (seen.has(normalized.id)) return;
                seen.add(normalized.id);
                existing.push(Object.assign({}, normalized, { sourceType: 'character' }));
            });
            contact.regexScripts = existing;
        }
        return true;
    }

    function extractImportedWorldBookEntries(raw) {
        const directEntries = normalizeSillyTavernWorldBookEntries(raw);
        if (directEntries.length > 0) return directEntries;
        const card = normalizeSillyTavernCharacterCard(raw);
        if (card && Array.isArray(card.worldBookEntries) && card.worldBookEntries.length > 0) {
            return card.worldBookEntries;
        }
        const source = raw && typeof raw === 'object' ? raw : {};
        const candidates = [
            source.character_book,
            source.characterBook,
            source.world_book,
            source.worldBook,
            source.world_info,
            source.worldInfo,
            source.lorebook,
            source.book,
            source.data && source.data.character_book,
            source.data && source.data.characterBook,
            source.data && source.data.world_book,
            source.data && source.data.worldBook,
            source.data && source.data.world_info,
            source.data && source.data.worldInfo,
            source.extensions && source.extensions.world_book,
            source.extensions && source.extensions.worldBook,
            source.extensions && source.extensions.world_info,
            source.extensions && source.extensions.worldInfo
        ];
        for (const candidate of candidates) {
            const entries = normalizeSillyTavernWorldBookEntries(candidate);
            if (entries.length > 0) return entries;
        }
        return [];
    }

    function isImportedPlainObject(value) {
        return !!value && typeof value === 'object' && !Array.isArray(value);
    }

    function coerceImportedContactList(value) {
        if (Array.isArray(value)) return value;
        if (!isImportedPlainObject(value)) return [];
        const looksLikeSingleContact = Boolean(
            value.name
            || value.remark
            || value.persona
            || value.onlineChatHistory
            || value.offlineChatHistory
            || value.chatHistory
        );
        if (looksLikeSingleContact) return [value];
        return Object.values(value).filter(isImportedPlainObject);
    }

    function collectLegacyImportedContacts(data) {
        if (!isImportedPlainObject(data)) return [];
        const keys = [
            'aiContacts',
            'contacts',
            'contactList',
            'characters',
            'aiCharacters',
            'friends',
            'contact',
            'aiContact'
        ];
        for (const key of keys) {
            const list = coerceImportedContactList(data[key]);
            if (list.length > 0) return list;
        }
        return [];
    }

    function normalizeImportedContactForCurrentVersion(value, fallbackId) {
        const source = isImportedPlainObject(value && value.contact) && !value.name && !value.persona
            ? value.contact
            : value;
        if (!isImportedPlainObject(source)) return null;
        const contactData = source;
        if (contactData.id === undefined || contactData.id === null || contactData.id === '') {
            contactData.id = fallbackId;
        }
        if (!contactData.name) {
            contactData.name = contactData.remark || `AI_${String(contactData.id).slice(-4)}`;
        }
        if (!contactData.remark) contactData.remark = contactData.name;
        if (contactData.persona === undefined || contactData.persona === null) {
            contactData.persona = contactData.description || contactData.prompt || '';
        }
        if (!Array.isArray(contactData.onlineChatHistory)) contactData.onlineChatHistory = [];
        if (!Array.isArray(contactData.offlineChatHistory)) contactData.offlineChatHistory = [];
        if (!Array.isArray(contactData.offlineStorylines)) contactData.offlineStorylines = [];
        if (!Array.isArray(contactData.voiceCallLogs)) contactData.voiceCallLogs = [];
        if (!Array.isArray(contactData.videoCallLogs)) contactData.videoCallLogs = [];
        if (!Array.isArray(contactData.moments)) contactData.moments = [];
        if (!Array.isArray(contactData.worldBook)) contactData.worldBook = [];
        contactData.regexScripts = normalizeSillyTavernRegexScripts(contactData.regexScripts || contactData.regex_scripts, 'character');
        if (contactData.mountGlobalWorldBook === undefined) contactData.mountGlobalWorldBook = true;
        normalizeWorldBookSettings(contactData);
        if (!Array.isArray(contactData.stickerGroups)) contactData.stickerGroups = [];
        if (!isImportedPlainObject(contactData.userProfile)) {
            contactData.userProfile = { name: '用户', persona: '' };
        } else {
            if (!contactData.userProfile.name) contactData.userProfile.name = '用户';
            if (contactData.userProfile.persona === undefined) contactData.userProfile.persona = '';
        }
        return contactData;
    }

    function normalizeImportedAppDataForCurrentVersion(rawAppData) {
        const data = isImportedPlainObject(rawAppData) ? rawAppData : {};
        const importedContacts = collectLegacyImportedContacts(data);
        const fallbackSeed = Date.now();
        data.aiContacts = importedContacts
            .map((item, index) => normalizeImportedContactForCurrentVersion(item, fallbackSeed + index))
            .filter(Boolean);

        if (!isImportedPlainObject(data.appSettings)) data.appSettings = {};
        if (!isImportedPlainObject(data.globalUserProfile)) {
            const legacyUser = isImportedPlainObject(data.currentUser) ? data.currentUser : {};
            data.globalUserProfile = {
                name: legacyUser.name || '用户',
                avatarKey: legacyUser.avatarKey || 'global_user_avatar',
                favoriteSongs: Array.isArray(legacyUser.favoriteSongs) ? legacyUser.favoriteSongs : [],
                messageFavorites: createDefaultMessageFavoritesState()
            };
        }
        if (!Array.isArray(data.groupChats)) data.groupChats = [];
        if (!Array.isArray(data.groupMemorySyncLogs)) data.groupMemorySyncLogs = [];
        if (!Array.isArray(data.sillyTavernPresets)) data.sillyTavernPresets = [];
        if (!isImportedPlainObject(data.sillyTavernMacroVars)) data.sillyTavernMacroVars = {};
        data.globalRegexScripts = normalizeSillyTavernRegexScripts(data.globalRegexScripts || data.global_regex_scripts, 'global');
        if (!Array.isArray(data.globalWorldBookPresets)) data.globalWorldBookPresets = [];
        data.globalWorldBook = normalizeGlobalWorldBookSource(data.globalWorldBook || {});
        if (data.appSettings.defaultOfflinePresetId === undefined) data.appSettings.defaultOfflinePresetId = '';
        if (!isImportedPlainObject(data.socialGraph)) {
            data.socialGraph = { mutualFriendEdges: {}, currentCoGroupCount: {} };
        }
        if (!isImportedPlainObject(data.socialGraph.mutualFriendEdges)) data.socialGraph.mutualFriendEdges = {};
        if (!isImportedPlainObject(data.socialGraph.currentCoGroupCount)) data.socialGraph.currentCoGroupCount = {};
        if (!Array.isArray(data.globalBagguRules)) data.globalBagguRules = [];
        if (!Array.isArray(data.bagguHistory)) data.bagguHistory = [];
        if (!isImportedPlainObject(data.wallet)) {
            data.wallet = { balance: 0, transactions: [], hasConverted: false, legacyCache: null };
        }
        return data;
    }

    function resolveImportedAppDataPayload(backupData) {
        if (!isImportedPlainObject(backupData)) return null;
        if (isImportedPlainObject(backupData.appData)) {
            return normalizeImportedAppDataForCurrentVersion(backupData.appData);
        }
        const legacyContacts = collectLegacyImportedContacts(backupData);
        if (legacyContacts.length > 0 || backupData.appSettings || backupData.globalUserProfile || backupData.currentUser) {
            return normalizeImportedAppDataForCurrentVersion(backupData);
        }
        return null;
    }

    /**
     * 【全新 V6.0 双格式智能导入】导入全部应用数据
     * 自动检测 .idic (二进制) 和 .json.gz (旧格式)
     */
    async function importAllData() {
        const input = document.createElement('input');
        input.type = 'file';
        input.multiple = true;
        input.accept = '.idic,.json,.gz,.part1,.part2,.part3,.part4,.part5,*/*'; // 添加 */* 解决手机端无法选择未知后缀(.idic)的问题

        input.onchange = async (event) => {
            const files = Array.from(event.target.files);
            if (files.length === 0) return;

        const loadingToast = showToast('正在读取备份文件...', 'info', 0);

            try {
                let combinedBuffer;

        // --- 发送请求与处理返回的部分 ---
                if (files.length > 1) {
                    showToast(`正在合并 ${files.length} 个分包...`, 'info', 0);
                    files.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));

                    if (!files[0].name.includes('part1')) {
                        throw new Error("文件缺失：请确保选中了所有分包，并且包含 .part1 文件。");
                    }

                    const combinedBlob = new Blob(files);
                    combinedBuffer = await combinedBlob.arrayBuffer();
                } else {
                    combinedBuffer = await files[0].arrayBuffer();
                }

        // --- 司令部：统一管理所有日记相关的“电闸” ---
                const isIdic = isIdicFormat(combinedBuffer);
                console.log(`[Import] detected backup format: ${isIdic ? 'IDIC' : 'legacy JSON/GZ'}`);

                if (isIdic) {
                    // ===== IDIC 二进制格式导入 =====
                    await importIdicData(combinedBuffer, loadingToast);
                } else {
                    // ===== 旧格式 JSON.GZ 导入 =====
                    await importLegacyData(combinedBuffer, loadingToast);
                }

            } catch (error) {
                if (loadingToast) loadingToast.remove();
            console.error('[Import] 导入全部数据失败:', error);
                let errorMsg = error.message;
                if (error.name === 'RangeError' || error.message.includes('memory')) {
                    errorMsg = `内存不足。建议使用 IDIC 格式重新备份（IDIC 格式内存占用极低），或使用"仅文字"模式。`;
                }
                showCustomAlert('导入失败', errorMsg);
            }
        };

        input.click();
    }

    /**
     * 【IDIC 格式导入引擎】直接解析二进制，图片以原始 Blob 写入 IndexedDB
     * 全程不经过 Base64，内存占用极低
     */
    async function importIdicData(arrayBuffer, loadingToast) {
        if (loadingToast) loadingToast.textContent = '正在解析 IDIC 文件...';
        await new Promise(r => setTimeout(r, 100));

        const { appData: parsedWrapper, images } = await parseIdicFile(arrayBuffer);
        arrayBuffer = null; // 释放

                // 如果没有url（这种情况几乎不可能发生，但作为安全保障），就抛出错误
        const coreAppData = resolveImportedAppDataPayload(parsedWrapper);
        if (!coreAppData) {
            throw new Error("IDIC 文件损坏：找不到核心数据 (appData)！");
        }

        const contactCount = coreAppData.aiContacts ? coreAppData.aiContacts.length : 0;
        const imageCount = Object.keys(images).length;
        console.log(`[IDIC Import] 解析成功: ${contactCount} 个角色, ${imageCount} 张图片`);

        if (loadingToast) loadingToast.remove();

    // ▲▲▲▲▲ ▲▲▲▲▲
        showCustomConfirm(
            '确认导入 (IDIC 格式)',
            `解析成功！\n\n📅 备份时间: ${new Date(parsedWrapper.timestamp || Date.now()).toLocaleString()}\n👥 包含角色: ${contactCount} 个\n🖼️ 包含图片: ${imageCount} 张\n📦 格式: IDIC 二进制 (高性能)\n\n⚠️ 警告：这将覆盖当前浏览器的所有数据！`,
            async () => {
                const importToast = showToast('正在写入数据库...', 'info', 0);
                try {
                    // 【步骤 A】清空 IndexedDB
                    await new Promise((resolve, reject) => {
                        const clearTx = db._db.transaction(['appDataStore', 'images'], 'readwrite');
                        clearTx.objectStore('appDataStore').clear();
                        clearTx.objectStore('images').clear();
                        clearTx.oncomplete = resolve;
                        clearTx.onerror = (e) => reject(e.target.error);
                    });

                    // 【步骤 B】写入核心数据
                    await db.saveObject('appData', coreAppData);
                    localStorage.removeItem('myAiChatApp_V8_Data');
                    localStorage.removeItem('myAiChatApp_HasDataEverBeenSaved');

            // 步骤B：如果不是Suno歌曲，那它就一定是网易云歌曲
                    const imageEntries = Object.entries(images);
                    const BATCH_SIZE = 20;

                    for (let i = 0; i < imageEntries.length; i += BATCH_SIZE) {
                        const batch = imageEntries.slice(i, i + BATCH_SIZE);

                        // IDIC 格式的优势：图片已经是 Blob，不需要 fetch(dataUrl) 转换！
                        await new Promise((resolve, reject) => {
                            const tx = db._db.transaction(['images'], 'readwrite');
                            const store = tx.objectStore('images');
                            batch.forEach(([key, blob]) => store.put(blob, key));
                            tx.oncomplete = resolve;
                            tx.onerror = (e) => reject(e.target.error);
                            tx.onabort = (e) => reject(new Error("Transaction aborted"));
                        });

                        if (importToast) {
                            const percent = Math.round(((i + BATCH_SIZE) / imageEntries.length) * 100);
                            importToast.textContent = `恢复图片... ${Math.min(percent, 100)}%`;
                        }
                        await new Promise(r => setTimeout(r, 10));
                    }

                    if (importToast) importToast.remove();
                    showToast('✅ IDIC 导入成功！正在重启应用...', 'success', 2000);
                    setTimeout(() => location.reload(), 1500);

                } catch (err) {
                    if (importToast) importToast.remove();
                    console.error(err);
                    showCustomAlert('导入失败', err && err.message ? err.message : String(err));
                }
            }
        );
    }

    /**
     * 【旧格式导入引擎】处理 .json.gz 格式 (完全保留原逻辑)
     */
    async function importLegacyData(combinedBuffer, loadingToast) {
                    // 如果用户此时正好在编辑页，就顺便更新一下
        if (loadingToast) loadingToast.textContent = '正在解压数据...';
        await new Promise(r => setTimeout(r, 100));

        let jsonString;
        try {
            if (typeof pako === 'undefined') throw new Error("缺少pako库");
            const unzippedArray = pako.ungzip(new Uint8Array(combinedBuffer));
            combinedBuffer = null;
            jsonString = new TextDecoder().decode(unzippedArray);
        } catch (e) {
            console.log("非Gzip文件或解压失败，尝试直接读取...", e);
            jsonString = new TextDecoder("utf-8").decode(combinedBuffer);
            combinedBuffer = null;
        }

        // 解析 JSON
        if (loadingToast) loadingToast.textContent = '正在解析 JSON...';
        await new Promise(r => setTimeout(r, 100));

        let backupData = JSON.parse(jsonString);
        jsonString = null;

        const normalizedAppData = resolveImportedAppDataPayload(backupData);
        if (!normalizedAppData) {
            throw new Error("备份文件损坏：找不到核心数据 (appData)！");
        }

        const contactCount = normalizedAppData.aiContacts ? normalizedAppData.aiContacts.length : 0;
        console.log(`[Legacy Import] 解析成功，发现 ${contactCount} 个角色。`);

        if (loadingToast) loadingToast.remove();

                // 私密好友模式下允许保留名片内容，但默认不公开
        showCustomConfirm(
            '确认导入旧备份',
            `检测到 ${contactCount} 个角色。\n\n这会覆盖当前本地全部数据。`,
            async () => {
                const importToast = showToast('正在写入数据库...', 'info', 0);
                try {
        // 【核心改造】现在我们创建的是一个带有“包装盒”的完整结构
                    await new Promise((resolve, reject) => {
                        const clearTx = db._db.transaction(['appDataStore', 'images'], 'readwrite');
                        clearTx.objectStore('appDataStore').clear();
                        clearTx.objectStore('images').clear();
                        clearTx.oncomplete = resolve;
                        clearTx.onerror = (e) => reject(e.target.error);
                    });

            // 如果是线下模式，就去当前激活的剧情线里，拿出它专属的聊天记录册
                    const appDataToWrite = normalizedAppData;
                    const imageDataToWrite = backupData.imageData;
                    backupData = null;

                    await db.saveObject('appData', appDataToWrite);
                    localStorage.removeItem('myAiChatApp_V8_Data');
                    localStorage.removeItem('myAiChatApp_HasDataEverBeenSaved');

            // 尝试解析为LRC格式
                    if (imageDataToWrite) {
                        const imageEntries = Object.entries(imageDataToWrite);
                        const BATCH_SIZE = 20;

                        for (let i = 0; i < imageEntries.length; i += BATCH_SIZE) {
                            const batch = imageEntries.slice(i, i + BATCH_SIZE);

                            const preparedBlobs = await Promise.all(batch.map(async ([key, dataUrl]) => {
                                const res = await fetch(dataUrl);
                                const blob = await res.blob();
                                return { key, blob };
                            }));

                            await new Promise((resolve, reject) => {
                                const tx = db._db.transaction(['images'], 'readwrite');
                                const store = tx.objectStore('images');
                                preparedBlobs.forEach(item => store.put(item.blob, item.key));
                                tx.oncomplete = resolve;
                                tx.onerror = (e) => reject(e.target.error);
                                tx.onabort = (e) => reject(new Error("Transaction aborted"));
                            });

                            if (importToast) {
                                const percent = Math.round(((i + BATCH_SIZE) / imageEntries.length) * 100);
                                importToast.textContent = `恢复图片... ${Math.min(percent, 100)}%`;
                            }
                            await new Promise(r => setTimeout(r, 10));
                        }
                    }

                    if (importToast) importToast.remove();
                    showToast('导入成功！正在重启应用...', 'success', 2000);
                    setTimeout(() => location.reload(), 1500);

                } catch (err) {
                    if (importToast) importToast.remove();
                    console.error(err);
                    showCustomAlert('导入失败', err && err.message ? err.message : String(err));
                }
            }
        );
    }

    // ================================================================
