    // ================================================================
    // ▼▼▼ 【GitHub 核心系统 V2.0：支持自动分包与超大文件】 ▼▼▼
    // ================================================================

    // ================================================================
    // ▼▼▼ 【GitHub 核心系统 V3.0：UI修复 + 缓存穿透 + 自动分包】 ▼▼▼
    // ================================================================



        // 更新迷你播放条
    async function downloadRawFile(url, token) {
        // 【核心修复】添加时间戳 ?t=... 强制刷新，防止读取到旧的缓存
        const noCacheUrl = `${url}?t=${Date.now()}`;
        const response = await fetch(noCacheUrl, {
            headers: {
                'Authorization': `token ${token}`,
                'Accept': 'application/vnd.github.v3.raw'
            }
        });
        if (!response.ok) throw new Error(`文件不存在 (${response.status})`);
        return await response.arrayBuffer();
    }


    // 辅助：获取文件 SHA (用于覆盖写入) - 【修复版：强力防缓存】
    async function getFileSha(url, token) {
        try {
            // 【核心修复】添加随机时间戳 ?t=... 防止手机浏览器缓存 API 的 404 结果
            // 【【【全新植入：为删除按钮绑定专属任务】】】
            const noCacheUrl = `${url}?t=${Date.now()}-${Math.random()}`;
            const response = await fetch(noCacheUrl, {
                headers: {
                    'Authorization': `token ${token}`,
                    'Accept': 'application/vnd.github.v3+json'
                },
                cache: 'no-store' // 再次声明不缓存
            });
            if (response.ok) {
                const data = await response.json();
                return data.sha;
            }
        } catch (e) { }
        return null;
    }

    // --- 核心功能 1：执行 GitHub 备份 (双格式支持版) ---
    async function executeGithubBackup(isSilent = false) {
        saveGithubSettings();
        const gh = appData.appSettings.github;

        if (!gh || !gh.token || !gh.owner || !gh.repo) {
            if (!isSilent) showToast('请填写完整的 GitHub 信息！', 'error');
            return;
        }

        // 【【【核心修复：让“施工队长”换上新地图！】】】
        const runBackup = async (format, mode) => {
            let loadingToast = null;

            try {
                if (!isSilent) loadingToast = showToast('正在连接 GitHub...', 'info', 0);

                const repoCheckUrl = `https://api.github.com/repos/${gh.owner}/${gh.repo}`;
                const repoResponse = await fetch(repoCheckUrl, {
                    headers: { 'Authorization': `token ${gh.token}` }
                });

                if (!repoResponse.ok) {
                    if (repoResponse.status === 404) throw new Error(`找不到仓库 [${gh.owner}/${gh.repo}]`);
                    else throw new Error(`连接失败: ${repoResponse.status}`);
                }

                if (!isSilent && loadingToast) loadingToast.textContent = '正在处理数据...';
                await new Promise(r => setTimeout(r, 50));

                // --- 辅助：ArrayBuffer 转纯净 Base64 ---
                const arrayBufferToBase64Clean = (buffer) => {
                    return new Promise((resolve, reject) => {
                        const blob = new Blob([buffer]);
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            const base64 = reader.result.split(',')[1].replace(/\s/g, '');
                            resolve(base64);
                        };
                        reader.onerror = reject;
                        reader.readAsDataURL(blob);
                    });
                };

        // --- 【【【核心改造：加载全新的双性别系统】】】 ---
                const cleanupOldParts = async (baseUrl, currentTotalParts, token) => {
                    try {
                        for (let k = 1; k <= 10; k++) {
                            const nextPartUrl = `${baseUrl}.part${currentTotalParts + k}`;
                            const checkSha = await getFileSha(nextPartUrl, token);
                            if (checkSha) {
                                await fetch(nextPartUrl, {
                                    method: 'DELETE',
                                    headers: { 'Authorization': `token ${token}`, 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ message: 'Auto Cleanup Redundant Parts', sha: checkSha })
                                });
                            } else { break; }
                        }
                    } catch (cleanupErr) { console.warn("清理旧包失败，不影响备份结果"); }
                };

                // --- 辅助：上传分包到 GitHub ---
                const uploadChunks = async (dataBuffer, baseUrl, format, mode, isSilent, loadingToast) => {
                    const CHUNK_SIZE = 12 * 1024 * 1024;
                    const totalSize = dataBuffer.byteLength;
                    const totalParts = Math.ceil(totalSize / CHUNK_SIZE);

                    if (!isSilent && loadingToast) loadingToast.textContent = `准备上传: 共 ${totalParts} 个分包 (${(totalSize / 1024 / 1024).toFixed(1)} MB)...`;

                    for (let i = 0; i < totalParts; i++) {
                        const start = i * CHUNK_SIZE;
                        const end = Math.min(start + CHUNK_SIZE, totalSize);
                        const chunk = dataBuffer.slice(start, end);
                        const contentBase64 = await arrayBufferToBase64Clean(chunk);

                        let currentUrl = totalParts > 1 ? `${baseUrl}.part${i + 1}` : baseUrl;

                        if (!isSilent && loadingToast) loadingToast.textContent = `正在上传 ${i + 1}/${totalParts} (请勿锁屏)...`;

                        const sha = await getFileSha(currentUrl, gh.token);
                        const payload = {
                            message: isSilent ? `Auto Backup ${format.toUpperCase()} (${mode}) part ${i + 1}` : `Manual Backup ${format.toUpperCase()} (${mode}) part ${i + 1}`,
                            content: contentBase64
                        };
                        if (sha) payload.sha = sha;

                        const uploadResponse = await fetch(currentUrl, {
                            method: 'PUT',
                            headers: { 'Authorization': `token ${gh.token}`, 'Content-Type': 'application/json' },
                            body: JSON.stringify(payload)
                        });

                        if (!uploadResponse.ok) {
                            const errText = await uploadResponse.text();
                            let errMsg = `状态码 ${uploadResponse.status}`;
                            try { errMsg = JSON.parse(errText).message || errMsg; } catch (e) { }
                            if (uploadResponse.status === 422) {
                                throw new Error(`GitHub 拒绝写入 (422)。\n原因可能是：\n1. 文件被占用\n2. SHA校验失败(网络卡顿)\n3. 路径名包含非法字符\n详细: ${errMsg}`);
                            }
                            throw new Error(`分包 ${i + 1} 上传失败: ${errMsg}`);
                        }
                    }

    // 【全新】编辑器的“状态管理器”
                if (!isSilent && loadingToast) loadingToast.textContent = '正在处理数据...';
                    await cleanupOldParts(baseUrl, totalParts, gh.token);
                };

                // ===== 根据格式分流 =====
                if (format === 'idic') {
                    // --- IDIC 格式 ---
                    let imageEntries = [];
                    if (mode !== 'text_only') {
                    if (!isSilent && loadingToast) loadingToast.textContent = '正在清理旧备份...';
                        const allImages = await db.getAllImages();
                        const imageKeys = Object.keys(allImages);

                        for (let i = 0; i < imageKeys.length; i++) {
                            const key = imageKeys[i];
                            const originalBlob = allImages[key];
                            if (originalBlob instanceof Blob) {
                                let blobToProcess = originalBlob;
                                const isGif = originalBlob.type === 'image/gif';
                                if (mode === 'raw') { blobToProcess = originalBlob; }
                                else if (mode === 'smart') {
                                    if (isGif) { blobToProcess = originalBlob; }
                                    else if (key.startsWith('chatimg-') || key.startsWith('upload-') || key.startsWith('cover-') || key.includes('_photo') || key.includes('_bg')) {
                                        try { blobToProcess = await compressImageBlob(originalBlob, 0.7, 1024, 'image/jpeg'); } catch (e) { }
                                    } else {
                                        try { blobToProcess = await compressImageBlob(originalBlob, 0.8, 512, null); } catch (e) { }
                                    }
                                } else if (mode === 'force_jpg') {
                                    try { blobToProcess = await compressImageBlob(originalBlob, 0.5, 1024, 'image/jpeg'); } catch (e) { }
                                }
                                imageEntries.push({ key, blob: blobToProcess });
                            }
                            if (i % 50 === 0) await new Promise(r => setTimeout(r, 5));
                        }
                    }

                    if (!isSilent && loadingToast) loadingToast.textContent = '正在打包 IDIC 文件...';
                    const appDataExport = { version: "IDIC_V1", timestamp: Date.now(), mode: mode, appData: appData };
                    const idicBlob = await buildIdicFile(appDataExport, imageEntries);
                    imageEntries = null;

                    let safePath = gh.path.trim().replace(/^\/+/, '');
                    safePath = safePath.replace(/\.(json\.gz|json|gz|zip)$/i, '');
                    if (!safePath.endsWith('.idic')) safePath += '.idic';
                    const baseUrl = `https://api.github.com/repos/${gh.owner}/${gh.repo}/contents/${safePath}`;

                    const idicBuffer = await idicBlob.arrayBuffer();
                    await uploadChunks(idicBuffer, baseUrl, format, mode, isSilent, loadingToast);

                } else {
                    // --- 旧格式 JSON.GZ ---
                    let imageDataBase64 = {};
                    if (mode !== 'text_only') {
                        if (!isSilent && loadingToast) loadingToast.textContent = '正在压缩图片 (GIF保留)...';
                        const allImages = await db.getAllImages();
                        const imageKeys = Object.keys(allImages);

                        for (let i = 0; i < imageKeys.length; i++) {
                            const key = imageKeys[i];
                            const originalBlob = allImages[key];
                            if (originalBlob instanceof Blob) {
                                let blobToProcess = originalBlob;
                                const isGif = originalBlob.type === 'image/gif';
                                if (mode === 'raw') { blobToProcess = originalBlob; }
                                else if (mode === 'smart') {
                                    if (isGif) { blobToProcess = originalBlob; }
                                    else if (key.startsWith('chatimg-') || key.startsWith('upload-') || key.startsWith('cover-') || key.includes('_photo') || key.includes('_bg')) {
                                        try { blobToProcess = await compressImageBlob(originalBlob, 0.7, 1024, 'image/jpeg'); } catch (e) { blobToProcess = originalBlob; }
                                    } else {
                                        try { blobToProcess = await compressImageBlob(originalBlob, 0.8, 512, null); } catch (e) { blobToProcess = originalBlob; }
                                    }
                                } else if (mode === 'force_jpg') {
                                    try { blobToProcess = await compressImageBlob(originalBlob, 0.5, 1024, 'image/jpeg'); } catch (e) { blobToProcess = originalBlob; }
                                }
                                imageDataBase64[key] = await blobToBase64(blobToProcess);
                            }
                            if (i % 50 === 0) await new Promise(r => setTimeout(r, 5));
                        }
                    }

                    const backupData = { version: "V6_HYBRID_COMPRESS", timestamp: Date.now(), mode: mode, appData: appData, imageData: imageDataBase64 };
                    if (typeof pako === 'undefined') throw new Error("压缩库加载失败");

                        if (!isSilent && loadingToast) loadingToast.textContent = '正在处理图片...';
                    await new Promise(r => setTimeout(r, 20));
                    const jsonString = JSON.stringify(backupData);
                    const compressedData = pako.gzip(jsonString);

                    let safePath = gh.path.trim().replace(/^\/+/, '');
                    if (!safePath.endsWith('.json.gz') && !safePath.endsWith('.zip')) safePath += '.json.gz';
                    const baseUrl = `https://api.github.com/repos/${gh.owner}/${gh.repo}/contents/${safePath}`;

                    await uploadChunks(compressedData.buffer, baseUrl, format, mode, isSilent, loadingToast);
                }

                gh.lastBackupTime = Date.now();
                saveAppData();

                if (loadingToast) loadingToast.remove();
                if (!isSilent) {
                    showToast(`☁️ 备份成功 (${format === 'idic' ? 'IDIC' : 'JSON.GZ'})！`, 'success');
                } else {
                    showToast(`✅ 自动备份完成 (${getModeName(mode)})`, 'success');
                }

            } catch (error) {
                if (loadingToast) loadingToast.remove();
                console.error("GitHub 上传失败:", error);
                if (!isSilent) showCustomAlert('上传失败', error.message || String(error));
                else showToast(`❌ 自动备份失败: ${error.message}`, 'error', 5000);
            }
        };

        const getModeName = (m) => {
            if (m === 'raw') return '无损';
            if (m === 'force_jpg') return '强力压缩';
            if (m === 'text_only') return '纯文字';
            return '智能压缩';
        };

        if (!isSilent) {
            showFormatAndModeSelector((selectedFormat, selectedMode) => {
                gh.backupFormat = selectedFormat;
                gh.backupMode = selectedMode;
                saveAppData();
                runBackup(selectedFormat, selectedMode);
            });
        } else {
            const autoFormat = gh.backupFormat || 'idic';
            const autoMode = gh.backupMode || 'smart';
            runBackup(autoFormat, autoMode);
        }
    }

        // 这是解决高光和字体颜色冲突的关键！
    document.getElementById('github-upload-btn').addEventListener('click', () => {
        executeGithubBackup(false);
    });

    // --- 核心功能 2：智能拉取恢复 (双格式自动检测版) ---
    document.getElementById('github-download-btn').addEventListener('click', async () => {
        const tokenInput = document.getElementById('github-token');
        const ownerInput = document.getElementById('github-owner');
        const repoInput = document.getElementById('github-repo');
        const pathInput = document.getElementById('github-path');

        if (tokenInput) tokenInput.value = tokenInput.value.trim();
        if (ownerInput) ownerInput.value = ownerInput.value.trim();
        if (repoInput) repoInput.value = repoInput.value.trim();
        if (pathInput) pathInput.value = pathInput.value.trim();
        saveGithubSettings();

        const gh = appData.appSettings.github;
        if (!gh.token || !gh.owner || !gh.repo) {
            showToast('请先在设置里填写 GitHub 信息', 'error');
            return;
        }

        const downloadPartWithRetry = async (url, token, retries = 3) => {
            const noCacheUrl = `${url}?t=${Date.now()}`;
            let lastError;
            for (let i = 0; i < retries; i++) {
                try {
                    const response = await fetch(noCacheUrl, {
                        headers: { 'Authorization': `token ${token}`, 'Accept': 'application/vnd.github.v3.raw' }
                    });
                    if (response.status === 404) return { found: false };
                    if (!response.ok) throw new Error(`HTTP ${response.status}`);
                    const buffer = await response.arrayBuffer();
                    return { found: true, buffer: buffer };
                } catch (e) {
                    console.warn(`下载失败 (尝试 ${i + 1}/${retries}): ${e.message}`);
                    lastError = e;
                    await new Promise(r => setTimeout(r, 1000));
                }
            }
            throw lastError;
        };

        showCustomConfirm(
                            '从 GitHub 拉取备份',
            '确定要从 GitHub 拉取备份并恢复到本地吗？当前本地数据会被备份数据覆盖。',
            async () => {
                const loadingToast = showToast('正在连接 GitHub...', 'info', 0);
                try {
                    const safePath = gh.path.trim().replace(/^\/+/, '');
                    const baseUrl = `https://api.github.com/repos/${gh.owner}/${gh.repo}/contents/${safePath}`;
                    let combinedBuffer = null;

                // 1. 检查用户点击的是不是删除按钮
                    try {
                        const result = await downloadPartWithRetry(baseUrl, gh.token, 1);
                        if (result.found) combinedBuffer = result.buffer;
                    } catch (e) { console.log("单文件检查跳过:", e.message); }

        // 2. 清空所有罗盘相关的数据，彻底重置
                    if (!combinedBuffer) {
                        let parts = [];
                        let partIndex = 1;
                        let keepFetching = true;

                        while (keepFetching) {
                            const partUrl = `${baseUrl}.part${partIndex}`;
                            if (loadingToast) loadingToast.textContent = `正在下载分包 ${partIndex}...`;
                            try {
                                const result = await downloadPartWithRetry(partUrl, gh.token, 5);
                                if (result.found) { parts.push(result.buffer); partIndex++; }
                                else {
                                    keepFetching = false;
                                    if (partIndex === 1) throw new Error(`未找到备份文件: ${safePath}\n(请检查 Token 权限或文件名)`);
                                }
                            } catch (e) {
                                throw new Error(`分包 ${partIndex} 下载失败，网络不稳定，请稍后重试。\n(${e.message})`);
                            }
                        }

                        if (loadingToast) loadingToast.textContent = '正在合并分包...';
                        const totalLength = parts.reduce((acc, buf) => acc + buf.byteLength, 0);
                        const mergedArray = new Uint8Array(totalLength);
                        let offset = 0;
                        for (const buf of parts) { mergedArray.set(new Uint8Array(buf), offset); offset += buf.byteLength; }
                        combinedBuffer = mergedArray.buffer;
                    }

                    // 3. 【核心修复】失败前移除加载弹窗
                    const isIdic = isIdicFormat(combinedBuffer);
                    console.log(`[GitHub Restore] 格式: ${isIdic ? 'IDIC' : 'JSON.GZ'}`);

                    if (isIdic) {
                        // IDIC 格式恢复
                        if (loadingToast) loadingToast.textContent = '正在解析 IDIC 文件...';
                        await new Promise(r => setTimeout(r, 200));
                        const { appData: parsedWrapper, images } = await parseIdicFile(combinedBuffer);
                        const coreAppData = resolveImportedAppDataPayload(parsedWrapper);
                        if (!coreAppData) throw new Error("IDIC 文件损坏：'appData' 字段缺失！");

                        const contactCount = coreAppData.aiContacts ? coreAppData.aiContacts.length : 0;
                        const imageCount = Object.keys(images).length;
                        if (loadingToast) loadingToast.textContent = '正在写入核心数据...';

                        const clearTx = db._db.transaction(['appDataStore', 'images'], 'readwrite');
                        clearTx.objectStore('appDataStore').clear();
                        clearTx.objectStore('images').clear();
                        await new Promise(r => clearTx.oncomplete = r);

                        localStorage.removeItem('myAiChatApp_V8_Data');
                        localStorage.removeItem('myAiChatApp_HasDataEverBeenSaved');

                        const dataTx = db._db.transaction(['appDataStore'], 'readwrite');
                        dataTx.objectStore('appDataStore').put(coreAppData, 'appData');
                        await new Promise((resolve, reject) => { dataTx.oncomplete = resolve; dataTx.onerror = (e) => reject(e.target.error); });

                        const imgEntries = Object.entries(images);
                        const BATCH_SIZE = 20;
                        for (let i = 0; i < imgEntries.length; i += BATCH_SIZE) {
                            const batch = imgEntries.slice(i, i + BATCH_SIZE);
                            const imgTx = db._db.transaction(['images'], 'readwrite');
                            const imgStore = imgTx.objectStore('images');
                            batch.forEach(([key, blob]) => imgStore.put(blob, key));
                            await new Promise(r => imgTx.oncomplete = r);
                            if (loadingToast) {
                                const percent = Math.round(((i + BATCH_SIZE) / imgEntries.length) * 100);
                                loadingToast.textContent = `恢复图片... ${Math.min(percent, 100)}%`;
                            }
                        }

                        if (loadingToast) loadingToast.remove();
                        document.getElementById('github-settings-modal').classList.add('hidden');
                        showToast(`✅ IDIC 恢复成功！${contactCount} 个角色, ${imageCount} 张图片。正在重启...`, 'success', 3000);
                        setTimeout(() => location.reload(), 2000);

                    } else {
        // 【核心修复】在关闭编辑器时，也把“桌面”清理干净！
                        if (loadingToast) loadingToast.textContent = '正在解压 (大文件请耐心等待)...';
                        await new Promise(r => setTimeout(r, 200));
                        let jsonString;
                        try {
                            if (typeof pako === 'undefined') throw new Error("缺少pako库");
                            const unzippedArray = pako.ungzip(new Uint8Array(combinedBuffer));
                            jsonString = new TextDecoder().decode(unzippedArray);
                        } catch (e) {
            console.log("非Gzip文件或解压失败，尝试直接读取...", e);
                            jsonString = new TextDecoder().decode(combinedBuffer);
                        }

                        const backupData = JSON.parse(jsonString);
                        const restoredAppData = resolveImportedAppDataPayload(backupData);
                        if (!restoredAppData) throw new Error("备份文件严重损坏：'appData' 字段缺失！");

                        const contactCount = restoredAppData.aiContacts ? restoredAppData.aiContacts.length : 0;
                        if (loadingToast) loadingToast.textContent = '正在写入核心数据...';

                        const clearTx = db._db.transaction(['appDataStore', 'images'], 'readwrite');
                        clearTx.objectStore('appDataStore').clear();
                        clearTx.objectStore('images').clear();
                        await new Promise(r => clearTx.oncomplete = r);

                        localStorage.removeItem('myAiChatApp_V8_Data');
                        localStorage.removeItem('myAiChatApp_HasDataEverBeenSaved');

                        const dataTx = db._db.transaction(['appDataStore'], 'readwrite');
                        dataTx.objectStore('appDataStore').put(restoredAppData, 'appData');
                        await new Promise((resolve, reject) => { dataTx.oncomplete = resolve; dataTx.onerror = (e) => reject(e.target.error); });

                        if (backupData.imageData) {
                            const imageEntries = Object.entries(backupData.imageData);
                            const BATCH_SIZE = 20;
                            for (let i = 0; i < imageEntries.length; i += BATCH_SIZE) {
                                const batch = imageEntries.slice(i, i + BATCH_SIZE);
                                const preparedBlobs = await Promise.all(batch.map(async ([key, dataUrl]) => {
                                    const blob = await dataURLToBlob(dataUrl);
                                    return { key, blob };
                                }));
                                const imgTx = db._db.transaction(['images'], 'readwrite');
                                const imgStore = imgTx.objectStore('images');
                                preparedBlobs.forEach(item => imgStore.put(item.blob, item.key));
                                await new Promise(r => imgTx.oncomplete = r);
                                if (loadingToast) {
                                    const percent = Math.round(((i + BATCH_SIZE) / imageEntries.length) * 100);
                                    loadingToast.textContent = `恢复图片... ${Math.min(percent, 100)}%`;
                                }
                            }
                        }

                        if (loadingToast) loadingToast.remove();
                        document.getElementById('github-settings-modal').classList.add('hidden');
                        showToast(`✅ 成功恢复 ${contactCount} 个角色！正在重启...`, 'success', 3000);
                        setTimeout(() => location.reload(), 2000);
                    }

                } catch (error) {
                    if (loadingToast) loadingToast.remove();
                    console.error("GitHub 恢复失败:", error);
                    document.getElementById('github-settings-modal').classList.add('hidden');
                    showCustomAlert('恢复中断', error.message);
                }
            },
            null, '确定覆盖', '取消', true
        );
    });

