    function getGroupMemberTitleText(group, member) {
        if (!member) return '';
        const owner = group.owner && group.owner.type === member.memberType && String(group.owner.id) === String(member.memberId);
        if (owner) return '群主';
        if (member.memberType === 'user' && Boolean(group.userIsAdmin)) return '管理员';
        if (member.memberType === 'char' && group.admins.includes(String(member.memberId))) return '管理员';
        return '';
    }

    function updateGroupMemberManagerModeLabel() {
        if (groupMemberAddBtn) {
            groupMemberAddBtn.textContent = groupMemberManagerMode === 'invite' ? '确认邀请' : '＋ 邀请';
        }
        if (groupMemberRemoveBtn) {
            groupMemberRemoveBtn.textContent = groupMemberManagerMode === 'remove' ? '确认移除' : '－ 移除';
        }
        if (groupMemberModeLabel) {
            const modeText = groupMemberManagerMode === 'invite'
                ? '当前：邀请模式'
                : (groupMemberManagerMode === 'remove' ? '当前：移除模式' : '当前：浏览模式');
            groupMemberModeLabel.textContent = modeText;
        }
    }

    async function resolveGroupMemberAvatarForUi(group, memberType, memberId) {
        try {
            if (memberType === 'user') {
                const avatarKey = group?.settings?.myProfileInGroup?.avatarKey || `${group?.id || 'group'}_user_avatar`;
                const blob = await db.getImage(avatarKey);
                if (blob) return URL.createObjectURL(blob);
                return 'https://i.postimg.cc/cLPP10Vm/4.jpg';
            }
            const blob = await db.getImage(`${memberId}_avatar`);
            if (blob) return URL.createObjectURL(blob);
        } catch (_) { }
        return 'https://i.postimg.cc/kXq06mNq/ai-default.png';
    }

    async function renderGroupSettingsOverview(group) {
        if (!group) return;
        if (gsCoverName) gsCoverName.textContent = group.name || '群聊';
        if (gsCoverMeta) {
            const count = Array.isArray(group.members) ? group.members.length : 0;
            gsCoverMeta.textContent = `${count}名成员 · ${group.settings?.mode === 'advanced' ? '进阶模式' : '经典模式'}`;
        }
        if (gsCoverRemark) {
            gsCoverRemark.textContent = `群备注：${String(group.remark || '').trim() || '未设置'}`;
        }
        if (gsCoverAvatarPreview) {
            if (group.avatarMode === 'custom' && group.avatarImageKey) {
                try {
                    const blob = await db.getImage(group.avatarImageKey);
                    gsCoverAvatarPreview.src = blob ? URL.createObjectURL(blob) : buildGroupCompositeAvatarDataUrl(group);
                } catch (_) {
                    gsCoverAvatarPreview.src = buildGroupCompositeAvatarDataUrl(group);
                }
            } else {
                gsCoverAvatarPreview.src = buildGroupCompositeAvatarDataUrl(group);
            }
        }
        if (gsMemberPreviewStrip) {
            gsMemberPreviewStrip.innerHTML = '';
            const previewMembers = Array.isArray(group.members) ? group.members.slice(0, 12) : [];
            for (const member of previewMembers) {
                const avatar = document.createElement('img');
                avatar.className = 'qq-strip-avatar';
                avatar.alt = resolveGroupMemberDisplayName(group, member.memberType, member.memberId);
                avatar.src = await resolveGroupMemberAvatarForUi(group, member.memberType, member.memberId);
                gsMemberPreviewStrip.appendChild(avatar);
            }
        }
    }

    function refreshGroupSettingsOverview(group) {
        renderGroupSettingsOverview(group).catch((error) => {
            console.error('刷新群设置概览失败:', error);
        });
    }

    function getGroupMemberSearchText(group, member, contact) {
        const nickname = String(resolveGroupMemberDisplayName(group, member.memberType, member.memberId) || '');
        const realName = String(contact?.name || '');
        const remark = String(contact?.remark || '');
        const title = String(member?.title || '');
        return `${nickname} ${realName} ${remark} ${title}`.toLowerCase();
    }

    async function renderGroupMemberManagerList() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupMemberManagerList) return;
        groupMemberManagerList.innerHTML = '';
        updateGroupMemberManagerModeLabel();
        const removing = groupMemberManagerMode === 'remove';
        const inviting = groupMemberManagerMode === 'invite';
        const keyword = String(groupMemberSearchInput?.value || '').trim().toLowerCase();

        if (inviting) {
            const inGroupIds = new Set(getGroupCharIds(group));
            const candidates = (appData.aiContacts || []).filter((c) => {
                const cid = String(c.id);
                if (inGroupIds.has(cid)) return false;
                if (!keyword) return true;
                const realName = String(c.name || '').toLowerCase();
                const remark = String(c.remark || '').toLowerCase();
                return realName.includes(keyword) || remark.includes(keyword);
            });
            if (!candidates.length) {
                groupMemberManagerList.innerHTML = '<p class="placeholder-text" style="padding:16px;">没有可邀请成员</p>';
                return;
            }
            for (const contact of candidates) {
                let avatarUrl = 'https://i.postimg.cc/kXq06mNq/ai-default.png';
                try {
                    const blob = await db.getImage(`${contact.id}_avatar`);
                    if (blob) avatarUrl = URL.createObjectURL(blob);
                } catch (_) { }
                const realName = String(contact.name || '').trim() || '未命名角色';
                const remarkName = String(contact.remark || '').trim() || realName;
                const row = document.createElement('label');
                row.className = 'qq-group-member-row';
                row.innerHTML = `
                    <input type="checkbox" class="group-invite-check" value="${contact.id}">
                    <img src="${avatarUrl}" class="qq-group-member-avatar" alt="avatar">
                    <div class="qq-group-member-main">
                        <div class="qq-group-member-name">${realName}</div>
                        <div class="qq-group-member-sub">备注：${remarkName}</div>
                    </div>
                `;
                groupMemberManagerList.appendChild(row);
            }
            return;
        }

        const ownerEntries = [];
        const adminEntries = [];
        const memberEntries = [];
        (group.members || []).forEach((member) => {
            const isOwner = group.owner?.type === member.memberType && String(group.owner?.id) === String(member.memberId);
            const isAdmin = (member.memberType === 'char' && Array.isArray(group.admins) && group.admins.includes(String(member.memberId)))
                || (member.memberType === 'user' && Boolean(group.userIsAdmin));
            if (isOwner) {
                ownerEntries.push(member);
            } else if (isAdmin) {
                adminEntries.push(member);
            } else {
                memberEntries.push(member);
            }
        });
        const sectionDefs = [
            { title: '群主', rows: ownerEntries },
            { title: '管理员', rows: adminEntries },
            { title: '群成员', rows: memberEntries }
        ];
        let renderedCount = 0;
        for (const section of sectionDefs) {
            const filteredRows = section.rows.filter((member) => {
                const contact = member.memberType === 'char' ? getContactById(member.memberId) : null;
                const text = getGroupMemberSearchText(group, member, contact);
                return !keyword || text.includes(keyword);
            });
            if (!filteredRows.length) continue;

            const titleEl = document.createElement('div');
            titleEl.className = 'qq-group-member-section-title';
            titleEl.textContent = `${section.title} (${filteredRows.length})`;
            groupMemberManagerList.appendChild(titleEl);

            for (const member of filteredRows) {
                const contact = member.memberType === 'char' ? getContactById(member.memberId) : null;
                const displayName = resolveGroupMemberDisplayName(group, member.memberType, member.memberId);
                const roleText = getGroupMemberTitleText(group, member);
                const muteText = member.isMutedUntil > Date.now()
                    ? `禁言至 ${new Date(member.isMutedUntil).toLocaleTimeString('zh-CN', { hour12: false })}`
                    : '';
                const realName = member.memberType === 'char'
                    ? (String(contact?.name || '').trim() || '未命名角色')
                    : String(appData?.globalUserProfile?.name || '你');
                const remarkName = member.memberType === 'char'
                    ? (String(contact?.remark || '').trim() || realName)
                    : '用户本人';
                const avatarUrl = await resolveGroupMemberAvatarForUi(group, member.memberType, member.memberId);
                const canManage = member.memberType === 'char' && !removing;
                const row = document.createElement('div');
                row.className = `qq-group-member-row ${canManage ? 'is-pressable' : ''}`;
                if (canManage) row.dataset.memberId = String(member.memberId);
                row.innerHTML = `
                    ${removing && member.memberType === 'char' ? `<input type="checkbox" class="group-remove-check" value="${member.memberId}">` : ''}
                    <img src="${avatarUrl}" class="qq-group-member-avatar" alt="avatar">
                    <div class="qq-group-member-main">
                        <div class="qq-group-member-name">
                            <span>${displayName}</span>
                            ${roleText ? `<span class="qq-group-role-tag">${roleText}</span>` : ''}
                        </div>
                        <div class="qq-group-member-sub">真名：${realName} · 备注：${remarkName}${muteText ? ` · ${muteText}` : ''}</div>
                    </div>
                    ${canManage ? `<button class="group-member-manage-btn" data-member-id="${member.memberId}">管理</button>` : ''}
                `;
                groupMemberManagerList.appendChild(row);
                renderedCount += 1;
            }
        }
        if (renderedCount === 0) {
            groupMemberManagerList.innerHTML = '<p class="placeholder-text" style="padding:16px;">未找到匹配成员</p>';
        }
    }

