    function inviteSelectedMembersToActiveGroup() {
        const group = getGroupById(activeGroupChatId);
        if (!group) return;
        const actorRole = getCurrentUserRoleInGroup(group);
        if (!['owner', 'admin'].includes(actorRole)) {
            showToast('你当前没有邀请成员权限', 'error');
            return;
        }
        const selected = Array.from(document.querySelectorAll('.group-invite-check:checked')).map((node) => String(node.value));
        if (!selected.length) {
            showToast('请至少选择1个成员', 'info');
            return;
        }
        selected.forEach((cid) => {
            if (group.members.some((m) => m.memberType === 'char' && String(m.memberId) === cid)) return;
            const contact = getContactById(cid);
            group.members.push(normalizeGroupMember({
                memberType: 'char',
                memberId: cid,
                joinedAt: Date.now(),
                groupNickname: getCharDisplayName(contact),
                title: ''
            }));
            adjustCurrentCoGroupCount(group, cid, 1);
            appendSystemPromptToSingleChat(cid, `你被邀请进入了群聊《${group.name}》。`);
            if (contact) contact.isPrivateFriend = false;
            appendGroupSystemMessage(group, `${getCharDisplayName(contact)} 已加入群聊`);
        });
        group.updatedAt = Date.now();
        markMutualFriendsByGroup(group);
        rebuildCurrentCoGroupCount();
        enforcePrivateFriendRuleForAllContacts();
        refreshAllGroupMembershipSnapshotCaches();
        saveAppData();
        renderChatList();
        updateChatHeader();
        renderGroupMemberManagerList();
        refreshGroupSettingsOverview(group);
    }

    function removeSelectedMembersFromActiveGroup() {
        const group = getGroupById(activeGroupChatId);
        if (!group) return;
        const actorRole = getCurrentUserRoleInGroup(group);
        if (!['owner', 'admin'].includes(actorRole)) {
            showToast('你当前没有移除成员权限', 'error');
            return;
        }
        const selected = Array.from(document.querySelectorAll('.group-remove-check:checked')).map((node) => String(node.value));
        if (!selected.length) {
            showToast('请先勾选要移除的成员', 'info');
            return;
        }
        selected.forEach((cid) => {
            const idx = group.members.findIndex((m) => m.memberType === 'char' && String(m.memberId) === cid);
            if (idx < 0) return;
            if (actorRole === 'member') return;
            if (actorRole === 'admin' && group.admins.includes(cid)) return;
            if (group.owner?.type === 'char' && String(group.owner.id) === cid && actorRole !== 'owner') return;
            const contact = getContactById(cid);
            group.members.splice(idx, 1);
            group.admins = group.admins.filter((id) => String(id) !== cid);
            adjustCurrentCoGroupCount(group, cid, -1);
            appendSystemPromptToSingleChat(cid, `你已被移出群聊《${group.name}》。`);
            appendGroupSystemMessage(group, `${getCharDisplayName(contact)} 已被移出群聊`);
            if (contact) enforcePrivateFriendRuleForContact(contact);
        });
        group.updatedAt = Date.now();
        rebuildCurrentCoGroupCount();
        enforcePrivateFriendRuleForAllContacts();
        refreshAllGroupMembershipSnapshotCaches();
        saveAppData();
        renderChatList();
        updateChatHeader();
        renderGroupMemberManagerList();
        refreshGroupSettingsOverview(group);
    }

    function renderGroupMemberProfileWorldbookList(contact, member) {
        if (!groupMemberProfileWorldbookList) return;
        groupMemberProfileWorldbookList.classList.add('qq-check-list-worldbook');
        groupMemberProfileWorldbookList.innerHTML = '';
        const worldbookEntries = getEnabledWorldBookEntries(contact);
        const selected = new Set(Array.isArray(member?.mountedWorldBookKeys) ? member.mountedWorldBookKeys.map((x) => String(x)) : []);
        if (!worldbookEntries.length) {
            groupMemberProfileWorldbookList.innerHTML = '<div class="qq-check-item-empty">该角色暂无可挂载世界书</div>';
            return;
        }
        worldbookEntries.forEach((entry) => {
            const key = String(entry?.key || '').trim();
            if (!key) return;
            const label = document.createElement('label');
            label.className = 'qq-check-item';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.value = key;
            checkbox.checked = selected.has(key);
            const textWrap = document.createElement('div');
            textWrap.className = 'qq-check-item-text';
            const title = document.createElement('span');
            title.className = 'qq-check-item-title';
            title.textContent = key;
            const desc = document.createElement('span');
            desc.className = 'qq-check-item-desc';
            const summaryRaw = String(entry?.value || '').replace(/\s+/g, ' ').trim();
            const summary = summaryRaw.length > 48 ? `${summaryRaw.slice(0, 48)}...` : summaryRaw;
            desc.textContent = summary || '（无详细内容）';
            textWrap.appendChild(title);
            textWrap.appendChild(desc);
            label.appendChild(checkbox);
            label.appendChild(textWrap);
            groupMemberProfileWorldbookList.appendChild(label);
        });
    }

    function renderGroupMemberProfileStickerList(member) {
        if (!groupMemberProfileStickerList) return;
        groupMemberProfileStickerList.innerHTML = '';
        const stickerGroups = Object.keys(appData.globalAiStickers || {});
        const selected = new Set(Array.isArray(member?.mountedStickerGroups) ? member.mountedStickerGroups.map((x) => String(x)) : []);
        if (!stickerGroups.length) {
            groupMemberProfileStickerList.innerHTML = '<div class="qq-check-item-empty">表情包仓库暂无分组</div>';
            return;
        }
        stickerGroups.forEach((groupName) => {
            const label = document.createElement('label');
            label.className = 'qq-check-item';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.value = groupName;
            checkbox.checked = selected.has(groupName);
            const text = document.createElement('span');
            text.textContent = groupName;
            label.appendChild(checkbox);
            label.appendChild(text);
            groupMemberProfileStickerList.appendChild(label);
        });
    }

    function collectCheckedValues(container) {
        if (!container) return [];
        return Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
            .map((node) => String(node.value || '').trim())
            .filter(Boolean);
    }

    async function openGroupMemberProfileView(memberId) {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupMemberProfileView) return;
        const member = getGroupMemberRecord(group, 'char', memberId);
        const contact = getContactById(memberId);
        if (!member || !contact) return;
        activeGroupProfileMemberId = String(memberId);
        const displayName = getCharDisplayName(contact);
        if (groupMemberProfileName) groupMemberProfileName.textContent = displayName;
        if (groupMemberProfileRemark) groupMemberProfileRemark.textContent = `真名：${contact.name || displayName} · 备注：${contact.remark || displayName}`;
        if (groupMemberProfileNicknameInput) {
            groupMemberProfileNicknameInput.value = String(member.groupNickname || displayName);
        }
        if (groupMemberProfilePersonaInput) {
            groupMemberProfilePersonaInput.value = String(member.extraPersona || '');
        }
        renderGroupMemberProfileWorldbookList(contact, member);
        renderGroupMemberProfileStickerList(member);
        if (groupMemberProfileAvatarPreview) {
            groupMemberProfileAvatarPreview.src = 'https://i.postimg.cc/kXq06mNq/ai-default.png';
            try {
                const avatarUrl = await resolveGroupMemberAvatarForUi(group, 'char', memberId);
                if (avatarUrl) groupMemberProfileAvatarPreview.src = avatarUrl;
            } catch (_) { }
        }
        switchToView('group-member-profile-view');
    }

    async function saveGroupMemberProfileView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !activeGroupProfileMemberId) return;
        const memberId = String(activeGroupProfileMemberId);
        const member = getGroupMemberRecord(group, 'char', memberId);
        const contact = getContactById(memberId);
        if (!member || !contact) return;
        const displayName = getCharDisplayName(contact);
        member.groupNickname = String(groupMemberProfileNicknameInput?.value || '').trim() || displayName;
        member.extraPersona = String(groupMemberProfilePersonaInput?.value || '').trim();
        member.mountedWorldBookKeys = collectCheckedValues(groupMemberProfileWorldbookList);
        member.mountedStickerGroups = collectCheckedValues(groupMemberProfileStickerList);
        appendGroupSystemMessage(group, `${displayName} 的本群信息已更新`);
        group.updatedAt = Date.now();
        refreshAllGroupMembershipSnapshotCaches();
        saveAppData();
        renderChatList();
        updateChatHeader();
        refreshGroupSettingsOverview(group);
        await renderGroupMemberManagerList();
        switchToView('group-member-manager-view');
        showToast('已保存本群信息', 'success');
    }

    function runGroupMemberAction(memberId, actionKey) {
        const group = getGroupById(activeGroupChatId);
        if (!group) return;
        const member = getGroupMemberRecord(group, 'char', memberId);
        if (!member) return;
        const contact = getContactById(memberId);
        const actorRole = getCurrentUserRoleInGroup(group);
        const targetRole = getGroupActorRole(group, 'char', memberId);
        const displayName = getCharDisplayName(contact);
        const commit = () => {
            group.updatedAt = Date.now();
            refreshAllGroupMembershipSnapshotCaches();
            saveAppData();
            renderChatList();
            renderGroupMemberManagerList();
            if (activeGroupChatId === group.id) {
                renderGroupChatHistory(group).catch(() => { });
            }
            updateChatHeader();
            refreshGroupSettingsOverview(group);
        };
        if (actionKey === 'profile') {
            openGroupMemberProfileView(memberId);
            return;
        }
        if (actionKey === 'toggleAdmin') {
            if (actorRole !== 'owner') {
                showToast('仅群主可设置管理员', 'error');
                return;
            }
            if (group.admins.includes(String(memberId))) {
                group.admins = group.admins.filter((id) => String(id) !== String(memberId));
                appendGroupSystemMessage(group, `群主撤销了${displayName}的管理员身份`);
            } else {
                group.admins.push(String(memberId));
                appendGroupSystemMessage(group, `群主将${displayName}设为管理员`);
            }
            commit();
            return;
        }
        if (actionKey === 'transferOwner') {
            if (actorRole !== 'owner') {
                showToast('仅群主可移交群主', 'error');
                return;
            }
            showCustomConfirm(
                '移交群主',
                `确定将群主移交给 ${displayName} 吗？`,
                () => {
                    group.owner = { type: 'char', id: String(memberId) };
                    group.userIsAdmin = true;
                    group.admins = group.admins.filter((id) => String(id) !== String(memberId));
                    const actorName = resolveGroupMemberDisplayName(group, 'user', 'user');
                    appendGroupSystemMessage(group, `${actorName}将群主移交给${displayName}`);
                    commit();
                },
                null,
                '确认移交',
                '取消',
                true
            );
            return;
        }
        if (actionKey === 'setTitle') {
            if (actorRole !== 'owner') {
                showToast('仅群主可设置群头衔', 'error');
                return;
            }
            showCustomPrompt(
                '设置群头衔',
                `请输入 ${displayName} 的群头衔：`,
                member.title || '',
                (value) => {
                    member.title = String(value || '').trim();
                    appendGroupSystemMessage(group, `${displayName} 的群头衔更新为 ${member.title || '无'}`);
                    commit();
                },
                true
            );
            return;
        }
        if (actionKey === 'unmute') {
            if (!['owner', 'admin'].includes(actorRole)) {
                showToast('你没有禁言管理权限', 'error');
                return;
            }
            if (actorRole === 'admin' && targetRole !== 'member') {
                showToast('管理员只能解禁普通成员', 'error');
                return;
            }
            member.isMutedUntil = 0;
            appendGroupSystemMessage(group, `${displayName} 已解除禁言`);
            commit();
            return;
        }
        const muteMap = { mute10: 10, mute60: 60, mute1440: 1440 };
        if (Object.prototype.hasOwnProperty.call(muteMap, actionKey)) {
            if (!['owner', 'admin'].includes(actorRole)) {
                showToast('你没有禁言管理权限', 'error');
                return;
            }
            if (actorRole === 'admin' && targetRole !== 'member') {
                showToast('管理员只能禁言普通成员', 'error');
                return;
            }
            const mins = Number(muteMap[actionKey]) || 10;
            member.isMutedUntil = Date.now() + mins * 60 * 1000;
            appendGroupSystemMessage(group, `${displayName} 被禁言 ${mins} 分钟`);
            commit();
        }
    }

    function updateGroupMemberActionSheetState(group, memberId) {
        if (!groupMemberActionList) return;
        const member = getGroupMemberRecord(group, 'char', memberId);
        if (!member) return;
        const actorRole = getCurrentUserRoleInGroup(group);
        const targetRole = getGroupActorRole(group, 'char', memberId);
        const isAdmin = Array.isArray(group.admins) && group.admins.includes(String(memberId));
        const canOwnerOnly = actorRole === 'owner';
        const canMuteByRole = actorRole === 'owner' || (actorRole === 'admin' && targetRole === 'member');
        groupMemberActionList.querySelectorAll('[data-action]').forEach((btn) => {
            const action = String(btn.dataset.action || '');
            if (action === 'toggleAdmin') {
                btn.textContent = isAdmin ? '取消管理员' : '设置为管理员';
                btn.disabled = !canOwnerOnly;
                return;
            }
            if (action === 'transferOwner' || action === 'setTitle') {
                btn.disabled = !canOwnerOnly;
                return;
            }
            if (action === 'unmute') {
                btn.disabled = !canMuteByRole || !(member.isMutedUntil > Date.now());
                return;
            }
            if (action === 'mute10' || action === 'mute60' || action === 'mute1440') {
                btn.disabled = !canMuteByRole;
            }
        });
    }

    function openGroupMemberActionSheet(memberId) {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupMemberActionSheet) return;
        const member = getGroupMemberRecord(group, 'char', memberId);
        if (!member) return;
        groupMemberActionTargetId = String(memberId);
        updateGroupMemberActionSheetState(group, memberId);
        groupMemberActionSheet.classList.remove('hidden');
    }

    function manageSingleGroupMember(memberId) {
        openGroupMemberActionSheet(memberId);
    }

    function renderGroupSearchResultRows(group, rows, title = '查找结果') {
        if (!groupSearchResultPanel) return;
        const visibleRows = Array.isArray(rows) ? rows.filter((msg) => !isHiddenGroupSystemMessage(msg)) : [];
        if (!visibleRows.length) {
            groupSearchResultPanel.textContent = `${title}\n未找到匹配记录`;
            return;
        }
        const previewLines = visibleRows.slice(0, 200).map((msg) => {
            const stamp = formatGroupMessageTimeForPrompt(msg);
            const sender = msg.senderType === 'system'
                ? '系统'
                : resolveGroupMemberDisplayName(group, msg.senderType, msg.senderId);
            const content = String(msg.content || '').replace(/\s+/g, ' ').trim() || `[${msg.type || '消息'}]`;
            return `[${stamp}] ${sender}: ${content}`;
        });
        groupSearchResultPanel.textContent = `${title}\n共 ${visibleRows.length} 条\n\n${previewLines.join('\n\n')}`;
    }

    function openGroupAnnouncementEditorView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupAnnouncementEditorView) return;
        if (groupAnnouncementEditorTextarea) {
            groupAnnouncementEditorTextarea.value = String(group.announcement || '');
        }
        switchToView('group-announcement-editor-view');
    }

    function openGroupSearchRecordsView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupSearchRecordsView) return;
        if (groupSearchKeywordInput) groupSearchKeywordInput.value = '';
        if (groupSearchDateInput) groupSearchDateInput.value = '';
        if (groupSearchMemberInput) groupSearchMemberInput.value = '';
        const memberDisabled = Boolean(group.settings?.anonymousEnabled);
        if (groupSearchMemberInput) groupSearchMemberInput.disabled = memberDisabled;
        if (groupSearchMemberBtn) groupSearchMemberBtn.disabled = memberDisabled;
        if (groupSearchAnonHint) groupSearchAnonHint.classList.toggle('hidden', !memberDisabled);
        if (groupSearchResultPanel) groupSearchResultPanel.textContent = '暂无结果';
        switchToView('group-search-records-view');
    }

    async function openGroupMyInfoView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupMyInfoView) return;
        const profile = group.settings?.myProfileInGroup || createDefaultGroupSettings().myProfileInGroup;
        if (groupMyInfoNicknameInput) {
            groupMyInfoNicknameInput.value = String(profile.nickname || appData?.globalUserProfile?.name || '你');
        }
        if (groupMyInfoPersonaInput) groupMyInfoPersonaInput.value = String(profile.persona || '');
        if (groupMyInfoGenderInput) groupMyInfoGenderInput.value = String(profile.genderIdentity || '');
        if (groupMyInfoBioSexInput) groupMyInfoBioSexInput.value = String(profile.biologicalSex || '');
        pendingGroupMyInfoAvatarFile = null;
        if (groupMyInfoAvatarUploadInput) groupMyInfoAvatarUploadInput.value = '';
        if (groupMyInfoAvatarPreview) {
            groupMyInfoAvatarPreview.src = 'https://i.postimg.cc/cLPP10Vm/4.jpg';
            try {
                const key = profile.avatarKey || `${group.id}_user_avatar`;
                const blob = await db.getImage(key);
                if (blob) {
                    groupMyInfoAvatarPreview.src = URL.createObjectURL(blob);
                }
            } catch (_) { }
        }
        switchToView('group-my-info-view');
    }

    function openGroupContextSettingsView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupContextSettingsView) return;
        if (groupPersonalizationContextClassicInput) {
            groupPersonalizationContextClassicInput.value = String(group.settings.contextLimitClassic || 30);
        }
        if (groupPersonalizationContextAdvancedInput) {
            groupPersonalizationContextAdvancedInput.value = String(group.settings.contextLimitAdvanced || 100);
        }
        switchToView('group-context-settings-view');
        setTimeout(() => enforceGroupViewRuntimeLayout('group-context-settings-view'), 0);
    }

    function openGroupBubbleSettingsView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupBubbleSettingsView) return;
        if (!group.settings.bubbleStyle || typeof group.settings.bubbleStyle !== 'object') {
            group.settings.bubbleStyle = { globalStyleId: null, perMemberStyleId: {} };
        }
        loadGroupPersonalizationBubbleState(group);
        switchToView('group-bubble-settings-view');
        setTimeout(() => enforceGroupViewRuntimeLayout('group-bubble-settings-view'), 0);
    }

    function openGroupPersonalizationView() {
        const group = getGroupById(activeGroupChatId);
        if (!group || !groupPersonalizationView) return;
        if (groupPersonalizationTitleToggle) {
            groupPersonalizationTitleToggle.checked = Boolean(group.settings.groupTitleEnabled);
        }
        pendingGroupBackgroundFile = null;
        if (groupPersonalizationBgUploadInput) groupPersonalizationBgUploadInput.value = '';
        switchToView('group-personalization-view');
        setTimeout(() => enforceGroupViewRuntimeLayout('group-personalization-view'), 0);
    }

    function ensureGroupSettingsRows(group) {
        const block = document.querySelector('#group-settings-view .qq-settings-block');
        if (!block) {
            return { modeRow: null, anonymousRow: null, anonymousToggle: null };
        }

        let modeRow = document.getElementById('gs-mode');
        if (!modeRow || !block.contains(modeRow)) {
            modeRow = document.createElement('div');
            modeRow.id = 'gs-mode';
            modeRow.className = 'qq-settings-row';
            modeRow.innerHTML = '<span>群聊模式</span><span class="arrow">›</span>';
        } else if (!modeRow.classList.contains('qq-settings-row')) {
            modeRow.classList.add('qq-settings-row');
        }
        modeRow.innerHTML = '<span>群聊模式</span><span class="arrow">›</span>';
        modeRow.onclick = () => handleGroupSettingsAction('mode');

        let anonymousToggle = document.getElementById('gs-anonymous-toggle');
        let anonymousRow = anonymousToggle ? anonymousToggle.closest('.qq-settings-row') : null;
        if (!anonymousRow || !block.contains(anonymousRow)) {
            anonymousRow = document.createElement('div');
            anonymousRow.className = 'qq-settings-row';
            anonymousRow.id = 'gs-anonymous-row';
            anonymousRow.innerHTML = '<span>开启匿名</span><label class="switch"><input type="checkbox" id="gs-anonymous-toggle"><span class="slider"></span></label>';
            anonymousToggle = anonymousRow.querySelector('#gs-anonymous-toggle');
        } else {
            anonymousRow.id = 'gs-anonymous-row';
        }

        const personalizationRow = block.querySelector('#gs-personalization');
        if (personalizationRow) {
            personalizationRow.insertAdjacentElement('afterend', modeRow);
            modeRow.insertAdjacentElement('afterend', anonymousRow);
        } else {
            if (!block.contains(modeRow)) block.appendChild(modeRow);
            if (!block.contains(anonymousRow)) block.appendChild(anonymousRow);
        }

        anonymousToggle = document.getElementById('gs-anonymous-toggle');
        if (anonymousToggle) {
            anonymousToggle.checked = Boolean(group?.settings?.anonymousEnabled);
            anonymousToggle.onchange = () => {
                const activeGroup = getGroupById(activeGroupChatId);
                if (!activeGroup) return;
                activeGroup.settings.anonymousEnabled = Boolean(anonymousToggle.checked);
                activeGroup.updatedAt = Date.now();
                saveAppData();
                showToast(activeGroup.settings.anonymousEnabled ? '已开启匿名发言' : '已关闭匿名发言', 'info');
            };
        }
        return { modeRow, anonymousRow, anonymousToggle };
    }

    function openGroupSettings() {
        const group = getGroupById(activeGroupChatId);
        if (!group) return;
        const { anonymousToggle } = ensureGroupSettingsRows(group);
        if (gsPinToggle) gsPinToggle.checked = Boolean(group.isPinned);
        if (anonymousToggle) anonymousToggle.checked = Boolean(group.settings?.anonymousEnabled);
        if (gsAnonymousToggle) gsAnonymousToggle.checked = Boolean(group.settings?.anonymousEnabled);
        refreshGroupSettingsOverview(group);
        renderGroupSceneTimeSettings(group);
        switchToView('group-settings-view');
        setTimeout(() => enforceGroupViewRuntimeLayout('group-settings-view'), 0);
    }

    function handleGroupSettingsAction(actionKey) {
        const group = getGroupById(activeGroupChatId);
        if (!group) return;
        if (actionKey === 'announcement') {
            openGroupAnnouncementEditorView();
            return;
        }
        if (actionKey === 'search') {
            openGroupSearchRecordsView();
            return;
        }
        if (actionKey === 'myInfo') {
            openGroupMyInfoView();
            return;
        }
        if (actionKey === 'personalization') {
            openGroupPersonalizationView();
            return;
        }
        if (actionKey === 'name') {
            const actorRole = getCurrentUserRoleInGroup(group);
            if (!['owner', 'admin'].includes(actorRole)) {
                showToast('仅群主或管理员可修改群聊名称', 'error');
                return;
            }
            showCustomPrompt('群聊名称', '请输入新的群聊名称：', group.name || '', (value) => {
                const name = String(value || '').trim();
                if (!name) return;
                if (name === String(group.name || '')) return;
                const actorName = resolveGroupMemberDisplayName(group, 'user', 'user');
                group.name = name;
                group.updatedAt = Date.now();
                appendGroupSystemMessage(group, `${actorName}将群聊名称改为“${name}”`);
                saveAppData();
                updateChatHeader();
                renderChatList();
                renderGroupChatHistory(group);
                refreshGroupSettingsOverview(group);
            });
            return;
        }
        if (actionKey === 'remark') {
            showCustomPrompt('群聊备注', '请输入群聊备注（仅你可见）：', group.remark || '', (value) => {
                group.remark = String(value || '').trim();
                group.updatedAt = Date.now();
                saveAppData();
                renderChatList();
                refreshGroupSettingsOverview(group);
            });
            return;
        }
        if (actionKey === 'announcement') {
            showCustomPrompt('群公告', '请输入群公告：', group.announcement || '', (value) => {
                group.announcement = String(value || '').trim();
                group.updatedAt = Date.now();
                appendGroupSystemMessage(group, `群公告已更新：${group.announcement || '（空）'}`);
                saveAppData();
                renderGroupChatHistory(group);
                refreshGroupSettingsOverview(group);
            });
            return;
        }
        if (actionKey === 'mode') {
            showCustomConfirm(
                '群聊模式',
                '经典模式：一次API控制全员，成本较低。\n进阶模式：先排序再逐角色调用，成本较高但一致性更强。',
                () => {
                    group.settings.mode = 'classic';
                    group.advancedRoundState = null;
                    saveAppData();
                    updateChatHeader();
                    showToast('已切换为经典模式', 'success');
                    refreshGroupSettingsOverview(group);
                },
                () => {
                    group.settings.mode = 'advanced';
                    group.advancedRoundState = null;
                    saveAppData();
                    updateChatHeader();
                    showToast('已切换为进阶模式', 'success');
                    refreshGroupSettingsOverview(group);
                },
                '经典模式',
                '进阶模式'
            );
            return;
        }
        if (actionKey === 'apps') {
            showToast('群应用接口已预留，小游戏功能开发中', 'info');
            return;
        }
        if (actionKey === 'search') {
            showCustomConfirm(
                '查找聊天记录',
                '请选择查找方式：左=关键词，右=日期。成员查找请在下一步输入 member:成员名',
                () => {
                    showCustomPrompt('关键词查找', '输入关键词：', '', (keyword) => {
                        const key = String(keyword || '').trim();
                        if (!key) return;
                        const rows = (group.chatHistory || []).filter((msg) => !isHiddenGroupSystemMessage(msg) && String(msg.content || '').includes(key));
                        showCustomAlert('查找结果', `关键词 "${key}" 匹配 ${rows.length} 条记录`);
                    }, true);
                },
                () => {
                    showCustomPrompt('日期查找', '输入日期（YYYY-MM-DD）', '', (dateText) => {
                        const key = String(dateText || '').trim();
                        if (!key) return;
                        const rows = (group.chatHistory || []).filter((msg) => {
                            if (isHiddenGroupSystemMessage(msg)) return false;
                            const date = new Date(msg.timestamp || Date.now());
                            const dateStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                            return dateStr === key;
                        });
                        showCustomAlert('查找结果', `日期 ${key} 匹配 ${rows.length} 条记录`);
                    }, true);
                },
                '关键词',
                '按日期'
            );
            if (!group.settings.anonymousEnabled) {
                showCustomPrompt('成员查找（可选）', '输入成员显示名，留空可跳过：', '', (nameText) => {
                    const name = String(nameText || '').trim();
                    if (!name) return;
                    const rows = (group.chatHistory || []).filter((msg) => {
                        if (isHiddenGroupSystemMessage(msg)) return false;
                        const sender = resolveGroupMemberDisplayName(group, msg.senderType, msg.senderId);
                        return String(sender).includes(name);
                    });
                    showCustomAlert('查找结果', `成员 "${name}" 匹配 ${rows.length} 条记录`);
                }, true);
            } else {
                showToast('匿名开启时不支持按成员查找', 'info');
            }
            return;
        }
        if (actionKey === 'myInfo') {
            const profile = group.settings.myProfileInGroup || createDefaultGroupSettings().myProfileInGroup;
            showCustomPrompt('我在本群的信息', '请输入你的群昵称：', profile.nickname || String(appData?.globalUserProfile?.name || '你'), (nickname) => {
                profile.nickname = String(nickname || '').trim();
                showCustomPrompt('我在本群的人设', '请输入你在本群的人设：', profile.persona || '', (persona) => {
                    profile.persona = String(persona || '');
                    showCustomPrompt('我在本群的心理性别', '例如：女 / 男 / 非二元', profile.genderIdentity || '', (genderIdentity) => {
                        profile.genderIdentity = String(genderIdentity || '').trim();
                        showCustomPrompt('我在本群的生理性别', '例如：女 / 男 / 其他', profile.biologicalSex || '', (bioSex) => {
                            profile.biologicalSex = String(bioSex || '').trim();
                            const commitMyInfo = () => {
                                group.settings.myProfileInGroup = profile;
                                const userMember = getGroupMemberRecord(group, 'user', 'user');
                                if (userMember) userMember.groupNickname = profile.nickname || userMember.groupNickname;
                                group.updatedAt = Date.now();
                                saveAppData();
                                updateChatHeader();
                                showToast('已保存本群信息', 'success');
                                refreshGroupSettingsOverview(group);
                            };
                            showCustomConfirm(
                                '群内头像',
                                '是否上传你在本群的专属头像？',
                                () => {
                                    const picker = document.createElement('input');
                                    picker.type = 'file';
                                    picker.accept = 'image/*';
                                    picker.addEventListener('change', async (event) => {
                                        const file = event.target.files && event.target.files[0];
                                        if (!file) {
                                            commitMyInfo();
                                            return;
                                        }
                                        const avatarKey = `${group.id}_user_avatar`;
                                        await db.saveImage(avatarKey, file);
                                        profile.avatarKey = avatarKey;
                                        commitMyInfo();
                                    });
                                    picker.click();
                                },
                                () => {
                                    commitMyInfo();
                                },
                                '上传',
                                '跳过',
                                true
                            );
                        }, true);
                    }, true);
                }, true);
            });
            return;
        }
        if (actionKey === 'personalization') {
            showCustomPrompt(
                '群个性设置',
                '输入上下文条数，格式：经典,进阶（例如 30,100）。经典建议少一点，进阶可多一点。',
                `${group.settings.contextLimitClassic},${group.settings.contextLimitAdvanced}`,
                (value) => {
                    const parts = String(value || '').split(',').map((x) => Number(x.trim()));
                    if (parts.length >= 1 && Number.isFinite(parts[0])) {
                        group.settings.contextLimitClassic = Math.max(5, parts[0]);
                    }
                    if (parts.length >= 2 && Number.isFinite(parts[1])) {
                        group.settings.contextLimitAdvanced = Math.max(10, parts[1]);
                    }
                    if (!group.settings.bubbleStyle || typeof group.settings.bubbleStyle !== 'object') {
                        group.settings.bubbleStyle = { globalStyleId: null, perMemberStyleId: {} };
                    }
                    const finishPersonalization = () => {
                        const currentGlobalStyle = group.settings.bubbleStyle.globalStyleId || '';
                        const perMemberText = Object.entries(group.settings.bubbleStyle.perMemberStyleId || {})
                            .map(([key, val]) => `${key}:${val}`)
                            .join(',');
                        showCustomPrompt(
                            '群气泡样式',
                            '输入全局样式ID（可留空）。例如：default / soft / candy / mono',
                            currentGlobalStyle,
                            (styleIdText) => {
                                const styleId = String(styleIdText || '').trim();
                                group.settings.bubbleStyle.globalStyleId = styleId || null;
                                showCustomPrompt(
                                    '单人气泡样式',
                                    '可选：输入 成员ID:样式ID，多个用逗号分隔。成员ID可填 user 或 charId',
                                    perMemberText,
                                    async (mappingText) => {
                                        const nextMapping = {};
                                        String(mappingText || '')
                                            .split(',')
                                            .map((x) => x.trim())
                                            .filter(Boolean)
                                            .forEach((row) => {
                                                const [keyRaw, valRaw] = row.split(':');
                                                const key = String(keyRaw || '').trim();
                                                const val = String(valRaw || '').trim();
                                                if (!key || !val) return;
                                                nextMapping[key] = val;
                                            });
                                        group.settings.bubbleStyle.perMemberStyleId = nextMapping;
                                        group.updatedAt = Date.now();
                                        saveAppData();
                                        if (activeGroupChatId === group.id) {
                                            await applyGroupVisualSettings(group);
                                            await renderGroupChatHistory(group);
                                        }
                                        showToast('群个性设置已保存', 'success');
                                    },
                                    true
                                );
                            },
                            true
                        );
                    };
                    const askUploadBackground = () => {
                        showCustomConfirm(
                            '聊天背景',
                            '是否上传“当天群聊背景”？',
                            () => {
                                const picker = document.createElement('input');
                                picker.type = 'file';
                                picker.accept = 'image/*';
                                picker.addEventListener('change', async (event) => {
                                    const file = event.target.files && event.target.files[0];
                                    if (!file) {
                                        finishPersonalization();
                                        return;
                                    }
                                    const dateTag = new Date().toISOString().slice(0, 10);
                                    const bgKey = `${group.id}_bg_${dateTag}`;
                                    await db.saveImage(bgKey, file);
                                    group.settings.dailyBackgroundImageKey = bgKey;
                                    group.updatedAt = Date.now();
                                    saveAppData();
                                    if (activeGroupChatId === group.id) {
                                        await applyGroupVisualSettings(group);
                                    }
                                    showToast('群背景已更新', 'success');
                                    finishPersonalization();
                                });
                                picker.click();
                            },
                            () => {
                                finishPersonalization();
                            },
                            '上传',
                            '跳过',
                            true
                        );
                    };
                    showCustomConfirm(
                        '群头衔显示',
                        '是否在群聊中显示群头衔？',
                        () => {
                            group.settings.groupTitleEnabled = true;
                            group.updatedAt = Date.now();
                            saveAppData();
                            showToast('已启用群头衔显示', 'success');
                            askUploadBackground();
                        },
                        () => {
                            group.settings.groupTitleEnabled = false;
                            group.updatedAt = Date.now();
                            saveAppData();
                            showToast('已关闭群头衔显示', 'success');
                            askUploadBackground();
                        },
                        '开启',
                        '关闭',
                        true
                    );
                    showToast('群上下文条数已更新', 'success');
                }
            );
            return;
        }
        if (actionKey === 'deleteRecords') {
            showCustomConfirm(
                '删除群聊记录',
                '将清空群聊记录，并重置群主/管理员/头衔/禁言状态，是否继续？',
                () => {
                    group.chatHistory = [];
                    group.owner = { type: 'user', id: 'user' };
                    group.userIsAdmin = false;
                    group.admins = [];
                    (group.members || []).forEach((member) => {
                        member.title = '';
                        member.isMutedUntil = 0;
                    });
                    group.contextResetIndex = 0;
                    group.memorySyncCheckpointAt = 0;
                    group.advancedRoundState = null;
                    group.updatedAt = Date.now();
                    saveAppData();
                    renderChatList();
                    renderGroupChatHistory(group);
                    showToast('群聊记录已删除并初始化管理状态', 'success');
                    refreshGroupSettingsOverview(group);
                }
            );
            return;
        }
        if (actionKey === 'refreshMemory') {
            showCustomConfirm(
                '刷新群聊记忆',
                '不删除聊天记录，只隔离历史上下文。是否继续？',
                () => {
                    group.contextResetIndex = (group.chatHistory || []).length;
                    group.advancedRoundState = null;
                    group.updatedAt = Date.now();
                    saveAppData();
                    showToast('群聊上下文已隔离', 'success');
                    refreshGroupSettingsOverview(group);
                }
            );
            return;
        }
        if (actionKey === 'dissolve') {
            const actorRole = getCurrentUserRoleInGroup(group);
            if (actorRole !== 'owner') {
                showToast('仅群主可解散群聊', 'error');
                return;
            }
            showCustomConfirm(
                '解散群聊',
                `确定解散群聊《${group.name}》吗？`,
                () => {
                    appData.groupChats = (appData.groupChats || []).filter((item) => String(item.id) !== String(group.id));
                    rebuildCurrentCoGroupCount();
                    if (activeGroupChatId === group.id) {
                        activeGroupChatId = null;
                        switchToView('chat-list-view');
                        updateThreadComposerMode();
                    }
                    refreshAllGroupMembershipSnapshotCaches();
                    saveAppData();
                    renderChatList();
                    showToast('群聊已解散', 'success');
                }
            );
            return;
        }
        if (actionKey === 'avatar') {
            const picker = document.createElement('input');
            picker.type = 'file';
            picker.accept = 'image/*';
            picker.addEventListener('change', async (event) => {
                const file = event.target.files && event.target.files[0];
                if (!file) return;
                const imageKey = `${group.id}_avatar`;
                await db.saveImage(imageKey, file);
                revokeChatListAvatarCache(imageKey);
                group.avatarMode = 'custom';
                group.avatarImageKey = imageKey;
                group.updatedAt = Date.now();
                saveAppData();
                renderChatList();
                showToast('群头像已更新', 'success');
                refreshGroupSettingsOverview(group);
            });
            picker.click();
        }
    }

    function getMutualFriendsForActiveContact() {
        const contact = getContactById(activeChatContactId);
        if (!contact) return [];
        return getMutualFriendIdsFor(contact.id).map((id) => getContactById(id)).filter(Boolean);
    }

    function renderMutualFriendsModal() {
        if (!mutualFriendsList) return;
        const contact = getContactById(activeChatContactId);
        if (!contact) return;
        const friends = getMutualFriendsForActiveContact();
        if (!friends.length) {
            mutualFriendsList.innerHTML = '<p class="placeholder-text">暂无共友</p>';
            return;
        }
        mutualFriendsList.innerHTML = '';
        friends.forEach((friend) => {
            const row = document.createElement('div');
            row.className = 'settings-item';
            row.style.flexDirection = 'column';
            row.style.alignItems = 'stretch';
            row.style.gap = '8px';
            const impression = String(contact.mutualFriendImpressions?.[String(friend.id)] || '');
            row.innerHTML = `
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
                    <strong>${getCharDisplayName(friend)}</strong>
                    <button class="remove-mutual-friend-btn" data-target-id="${friend.id}">移除共友</button>
                </div>
                <textarea class="mutual-impression-input" data-target-id="${friend.id}" rows="3" placeholder="你对该共友的印象...">${impression}</textarea>
            `;
            mutualFriendsList.appendChild(row);
        });
    }

    function openMutualFriendsModal() {
        if (!mutualFriendsModal) return;
        renderMutualFriendsModal();
        mutualFriendsModal.classList.remove('hidden');
    }

    function closeMutualFriendsModal() {
        if (mutualFriendsModal) mutualFriendsModal.classList.add('hidden');
    }

