    function renderScheduleDayChips(days) {
        const activeDays = normalizeScheduleDays(days);
        const dayNames = ['日', '一', '二', '三', '四', '五', '六'];
        return `<div class="schedule-day-chips">${dayNames.map((name, index) => `
            <button type="button" class="schedule-day-chip ${activeDays.includes(index) ? 'active' : ''}" data-day="${index}">${name}</button>
        `).join('')}</div>`;
    }

    function attachScheduleDayChipHandlers(container) {
        if (!container) return;
        container.querySelectorAll('.schedule-day-chip').forEach(button => {
            button.onclick = () => button.classList.toggle('active');
        });
    }

    function collectDaysFromScheduleCard(card) {
        const days = Array.from(card.querySelectorAll('.schedule-day-chip.active'))
            .map(button => Number(button.dataset.day))
            .filter(day => Number.isInteger(day));
        return normalizeScheduleDays(days);
    }

