                                const rawCursor = Number(meta.lastDehydrateCursorAbs);
                                const hasCursor = Number.isFinite(rawCursor) && rawCursor >= 0;
                                const rawLastDehydrateAt = meta.lastDehydrateAt;
                                const hasValidLastDehydrateAt = (
                                    rawLastDehydrateAt instanceof Date
                                    || Number.isFinite(Number(rawLastDehydrateAt))
                                    || Number.isFinite(Date.parse(String(rawLastDehydrateAt || '')))
                                );
