                    if (!friends.length) {
                        showToast('当前没有可生成印象的共友', 'info');
                        return;
                    }
                    for (const friend of friends) {
                        const prompt = `请你作为角色“${getCharDisplayName(contact)}”，根据以下共友公开资料生成一句对TA的印象（不超过20字）：\n共友名：${getCharDisplayName(friend)}\n公开名片:${friend.publicProfileCard || '(私密好友，仅知道名字)'}\n只输出一句印象文本。`;
                        try {
                            const mutualImpressionScenarioQuery = [
                                contact.persona,
                                friend.publicProfileCard,
                                friend.persona
                            ]
                                .filter(Boolean)
                                .join(' ')
                                .replace(/\s+/g, ' ')
                                .slice(0, 320);
                            const mutualImpressionMaterials = await buildHippocampusScenarioMaterials(contact, 'current_mood', {
                                query: mutualImpressionScenarioQuery,
                                maxHighlights: 3
                            });
                            const mutualImpressionLegacyBridge = mutualImpressionMaterials.legacyBridge;
                            const finalPrompt = `${prompt}${mutualImpressionLegacyBridge}${mutualImpressionMaterials.addonBlock}`;
                            const { raw } = await callMainApiPrompt(finalPrompt, { temperature: 0.7 });
                            if (!contact.mutualFriendImpressions || typeof contact.mutualFriendImpressions !== 'object') {
                                contact.mutualFriendImpressions = {};
                            }
                            contact.mutualFriendImpressions[String(friend.id)] = String(raw || '').trim();
                        } catch (error) {
                            console.error('导入角色数据失败:', error);
                        }
                    }
                    saveAppData();
