                        const changed = finalizeGroupPoll(group, pollMessage, 'user', 'user', 'manual');
                        if (!changed) {
                            showToast('投票已结束', 'info');
                            return;
                        }
                        saveAppData();
                        renderChatList();
                        await renderGroupChatHistory(group);
                        return;
