            function openAccountingModal() {
                stagedAccountingEntries = [];
                document.getElementById('accounting-entry-list').innerHTML = '';
                document.getElementById('accounting-item-input').value = '';
                document.getElementById('accounting-amount-input').value = '';
                accountingModal.classList.remove('hidden');
            }

            function closeAccountingModal() {
                accountingModal.classList.add('hidden');
            }

            function stageAccountingEntry() {
                const itemInput = document.getElementById('accounting-item-input');
                const amountInput = document.getElementById('accounting-amount-input');
                const description = itemInput.value.trim();
                const amount = parseFloat(amountInput.value);

                if (!description || isNaN(amount) || amount <= 0) {
                    showToast('请输入有效的记账项目和金额', 'error');
                    return;
                }

                const remarks = document.getElementById('accounting-remarks-input').value.trim();
                const type = document.querySelector('#accounting-type-selector .type-button.active').dataset.type;
                stagedAccountingEntries.push({ description, amount, remarks, type }); // 把类型也暂存起来
                renderStagedEntries();
                itemInput.value = '';
                amountInput.value = '';
                    // 延迟结算人生履历
                // itemInput.focus();
            }

            function renderStagedEntries() {
                const list = document.getElementById('accounting-entry-list');
                list.innerHTML = '<h4>已添加：</h4>';
                stagedAccountingEntries.forEach(entry => {
                    const div = document.createElement('div');
                    div.textContent = `${entry.description}: ${entry.amount.toFixed(2)} 元`;
                    list.appendChild(div);
                });
            }

            async function commitAccountingEntries() {
                    // 只要还有未来节点，就强制保持进行中
                const itemInput = document.getElementById('accounting-item-input');
                const amountInput = document.getElementById('accounting-amount-input');
                if (itemInput.value.trim() && amountInput.value.trim()) {
                    stageAccountingEntry();
                }

                if (stagedAccountingEntries.length === 0) {
                    showToast('请先添加至少一条记账项目', 'error');
                    return;
                }

        // 1. 修改弹窗标题
                const newTransactions = stagedAccountingEntries.map(entry => ({
                    id: `tx-${Date.now()}-${Math.random()}`,
                    description: entry.description,
                    amount: entry.amount,
                    remarks: entry.remarks || '',
                    type: entry.type || 'expense', // 从暂存数据里读取类型
                    timestamp: Date.now()
                }));
                appData.userLedger.push(...newTransactions);
                saveAppData();

                // 2. 检查模式
                const totalItems = newTransactions.length;
            // ▼▼▼ 【全新】每天检查一次：是否需要更新社交资料 ▼▼▼
                const contentForAI = newTransactions.map(tx =>
                    `${tx.description}(${tx.amount.toFixed(2)}元${tx.remarks ? ', ' + tx.remarks : ''})`
                ).join('；');

                await dispatchAndDisplayUserMessage({
                    type: 'accounting',
                    content: `[记账] ${contentForAI}`, // 将详细信息发给AI
                    transactionData: newTransactions
                });

                closeAccountingModal();
            }

                    // 其他所有系统消息，照常过滤掉

                // 对于“撤回”消息，将其翻译成AI能理解的系统提示。

                // 1. 检查总开关
            document.getElementById('close-schedule-editor-btn').addEventListener('click', () => {
                switchToView('contact-settings-view');
            });
            document.getElementById('save-schedule-btn').addEventListener('click', saveSchedule);
            document.getElementById('add-work-item-btn').addEventListener('click', () => {
                openScheduleItemEditor('work', null); // null 代表新建
            });
            document.getElementById('add-leisure-item-btn').addEventListener('click', () => {
                openScheduleItemEditor('leisure', null); // null 代表新建
            });

            // 2. 夜间模式按钮：点击后切换主题
            document.getElementById('cancel-item-editor-btn').addEventListener('click', () => {
                document.getElementById('schedule-item-editor-modal').classList.add('hidden');
            });
            document.getElementById('save-item-editor-btn').addEventListener('click', saveScheduleItem);
                            // 【核心修改】在发送前先压缩图片！(质量0.6, 最大宽/高 800px)
            document.getElementById('delete-item-editor-btn').addEventListener('click', deleteScheduleItem);


            // 4. 其他功能按钮暂时只给一个提示
            document.getElementById('schedule-editor-modal').addEventListener('click', (e) => {
                if (e.target.classList.contains('delete-schedule-item-btn')) {
                    const type = e.target.dataset.type;
                    const index = parseInt(e.target.dataset.index, 10);
                    showCustomConfirm('删除确认', '确定要删除这个活动吗？', () => {
                        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                        if (contact && Array.isArray(contact.schedule[type])) {
                            contact.schedule[type].splice(index, 1);
                            renderScheduleItems(type, contact.schedule[type]);
                        }
                    });
                }
            });
            // ▲▲▲▲▲
            function renderOfflineStorylines() {
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                // 【【【终极核心修复V2.0：直接通过ID寻找正确的容器】】】
                const container = document.getElementById('storyline-list-container');
                if (!contact || !container) return;

                container.innerHTML = '';
                if (contact.offlineStorylines.length === 0) {
            container.innerHTML = '<p class="placeholder-text" style="padding: 20px;">播放列表是空的</p>';
                    return;
                }

                contact.offlineStorylines.forEach(story => {
                    const isActive = story.id === contact.activeOfflineStoryId;
                    const itemDiv = document.createElement('div');
                    // 【UI升级】模仿账本页，换上 ledger-item 这套“高级礼服”
                    itemDiv.className = `ledger-item`;
                    itemDiv.innerHTML = `
                <div class="ledger-item-details">
                    <div class="ledger-item-header">
                        <span class="desc">${story.name} ${isActive ? '<span class="active-story-tag" style="font-size: 12px; color: #3B83A2; margin-left: 8px;">当前</span>' : ''}</span>
                    </div>
                </div>
                <div class="ledger-item-actions">
                    <button class="edit-storyline-btn" data-story-id="${story.id}" title="编辑存档">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                </button>
                <button class="delete-storyline-btn" data-story-id="${story.id}" title="删除存档">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18m-2 14H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m-6 5v6m4-6v6"/></svg>
                </button>
            </div>
            `;
        // 如果今天已经更新过，且不是强制刷新，则跳过
                    itemDiv.addEventListener('click', (e) => {
                        if (!e.target.closest('.delete-storyline-btn')) {
                            contact.activeOfflineStoryId = story.id;
                            saveAppData();
                            renderOfflineStorylines(); // 重新渲染以更新高亮状态
                            showToast(`已切换到剧情线: ${story.name}`, 'success', 1500);
                        }
                    });
                    container.appendChild(itemDiv);
                });
            }

            /**
             * 【终极修复版：真正驱动“下拉菜单”的全新控制器】
             * @param {Array} storyOptions - 格式为 [{id: 'story-123', text: '冒险故事'}] 的数组
             * @param {Function} callback - 用户选择后的回调函数，会返回选择的ID或null
             */
            function showStorylineSelectionModal(storyOptions, callback) {
                const modal = document.getElementById('storyline-select-modal');
                    // 【核心修正】根据发言人（role）使用不同的描述
                const dropdown = document.getElementById('storyline-select-dropdown');
                const cancelBtn = document.getElementById('cancel-storyline-select-btn');
                const confirmBtn = document.getElementById('confirm-storyline-select-btn');

                // 2. 清空旧的<option>选项
                dropdown.innerHTML = '';

                // 3. 【核心修正】用 <option> 元素来填充下拉列表
                storyOptions.forEach(option => {
                    const optionElement = document.createElement('option');
                    optionElement.value = option.id; // 把故事ID作为值
                    optionElement.textContent = option.text; // 把故事名字作为显示的文本
                    dropdown.appendChild(optionElement);
                });

                        // 4. 重新绘制表情包面板
                const confirmHandler = () => {
                    modal.classList.add('hidden');
        // 只要不是已完成或失败，就每天自然涨一点
                    callback(dropdown.value);
            // 【修复】先移除旧的，再显示新的，并赋值给变量
                    confirmBtn.removeEventListener('click', confirmHandler);
                    cancelBtn.removeEventListener('click', cancelHandler);
                };

                // 5. 绑定交互事件
                const cancelHandler = () => {
                    modal.classList.add('hidden');
                    callback(null); // 用户取消，返回null
                // 创建新的并赋值，以便稍后管理
                    confirmBtn.removeEventListener('click', confirmHandler);
                    cancelBtn.removeEventListener('click', cancelHandler);
                };

            // 6. 【关键】拼接并保存
                confirmBtn.removeEventListener('click', confirmHandler);
                cancelBtn.removeEventListener('click', cancelHandler);

                // 7. 正式绑定新的事件
                confirmBtn.addEventListener('click', confirmHandler);
                cancelBtn.addEventListener('click', cancelHandler);

                // 8. 最后，显示弹窗
                modal.classList.remove('hidden');
            }

            // 【修复】获取结果后，无论成功与否，都要移除这个特定的弹窗
            let currentEditingStoryId = null; // 用一个“便利贴”记住正在编辑哪个存档
            let currentOfflineOpeningRemarkOptions = [];

            function getCurrentEditingOfflineStoryContext() {
                if (!currentEditingStoryId) return null;
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                if (!contact || !Array.isArray(contact.offlineStorylines)) return null;
                const story = contact.offlineStorylines.find(s => s.id === currentEditingStoryId);
                if (!story) return null;
                return { contact, story, settings: ensureOfflineStorySettings(story, contact) };
            }

            function renderOfflinePresetSelect(story) {
                const select = document.getElementById('offline-preset-select');
                if (!select) return;
                const settings = story ? ensureOfflineStorySettings(story, appData.aiContacts.find(c => c.id === activeChatContactId)) : {};
                const presets = ensureSillyTavernPresetLibrary();
                select.innerHTML = '<option value="">不挂预设</option>' + presets.map((preset) => {
                    const selected = String(settings.presetId || '') === String(preset.id || '') ? 'selected' : '';
                    return `<option value="${escapeHtml(preset.id)}" ${selected}>${escapeHtml(preset.name)}</option>`;
                }).join('');
                if (settings.useGlobalPreset) {
                    const defaultPreset = getDefaultOfflinePreset();
                    select.value = defaultPreset ? defaultPreset.id : '';
                }
                syncOfflinePresetControls(story);
            }

            function syncOfflinePresetControls(story = null, overrideUseGlobal = null) {
                const toggle = document.getElementById('offline-use-global-preset-toggle');
                const select = document.getElementById('offline-preset-select');
                const context = story
                    ? { story, settings: ensureOfflineStorySettings(story, appData.aiContacts.find(c => c.id === activeChatContactId)) }
                    : getCurrentEditingOfflineStoryContext();
                const useGlobal = overrideUseGlobal === null
                    ? (context ? context.settings.useGlobalPreset !== false : true)
                    : Boolean(overrideUseGlobal);
                if (toggle) toggle.checked = useGlobal;
                if (select) {
                    select.disabled = useGlobal;
                    if (useGlobal) {
                        const defaultPreset = getDefaultOfflinePreset();
                        select.value = defaultPreset ? defaultPreset.id : '';
                        select.title = defaultPreset
                            ? `正在跟随全局默认：${defaultPreset.name}`
                            : '还没有设置全局默认线下预设';
                    } else {
                        if (context) select.value = context.settings.presetId || '';
                        select.title = '这条剧情线单独使用这里选择的预设';
                    }
                }
            }

            function importOfflinePresetForCurrentStory() {
                const context = getCurrentEditingOfflineStoryContext();
                if (!context) return;
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = '.json,application/json,text/plain,*/*';
                input.onchange = (event) => {
                    const file = event.target.files && event.target.files[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = (readerEvent) => {
                        try {
                            const rawText = String(readerEvent.target && readerEvent.target.result || '');
                            const parsed = parseJsonMaybe(rawText) || rawText;
                            const fallbackName = String(file.name || '酒馆预设').replace(/\.[^.]+$/, '');
                            const preset = normalizeSillyTavernPresetPayload(parsed, fallbackName);
                            if (!preset || !preset.content) {
                                throw new Error('没有读到可用的预设内容。');
                            }
                            ensureSillyTavernPresetLibrary().push(preset);
                            context.settings.useGlobalPreset = false;
                            context.settings.presetId = preset.id;
                            saveAppData();
                            renderOfflinePresetSelect(context.story);
                            showToast(`已导入预设：${preset.name}`, 'success');
                        } catch (error) {
                            showCustomAlert('导入失败', error && error.message ? error.message : String(error));
                        }
                    };
                    reader.readAsText(file);
                };
                input.click();
            }

            function loadOfflinePresetIntoTextarea() {
                const select = document.getElementById('offline-preset-select');
                const textarea = document.getElementById('offline-preset-prompt');
                if (!select || !textarea) return;
                const preset = getSillyTavernPresetById(select.value);
                if (!preset) {
                    showToast('先选择一个预设', 'info');
                    return;
                }
                textarea.value = preset.content || '';
                showToast('已放进文本框，可以直接修改', 'success');
            }

            function saveOfflinePresetFromTextarea() {
                const context = getCurrentEditingOfflineStoryContext();
                const select = document.getElementById('offline-preset-select');
                const textarea = document.getElementById('offline-preset-prompt');
                if (!context || !select || !textarea) return;
                const content = normalizeSillyTavernPresetContent(textarea.value);
                if (!content) {
                    showToast('文本框是空的，不能保存成预设', 'info');
                    return;
                }
                const existing = getSillyTavernPresetById(select.value);
                showCustomPrompt(
                    existing ? '覆盖当前预设' : '保存新预设',
                    '给这个预设起个名字：',
                    existing ? existing.name : '我的酒馆预设',
                    (nameInput) => {
                        const name = toHippocampusTrimmedString(nameInput) || (existing ? existing.name : '我的酒馆预设');
                        const library = ensureSillyTavernPresetLibrary();
                        let target = existing;
                        if (target) {
                            target.name = name;
                            target.content = content;
                            target.updatedAt = new Date().toISOString();
                        } else {
                            target = {
                                id: createSillyTavernPresetId(),
                                name,
                                content,
                                source: 'manual',
                                importedAt: new Date().toISOString(),
                                updatedAt: new Date().toISOString()
                            };
                            library.push(target);
                        }
                        context.settings.useGlobalPreset = false;
                        context.settings.presetId = target.id;
                        textarea.value = '';
                        saveAppData();
                        renderOfflinePresetSelect(context.story);
                        showToast('预设已保存', 'success');
                    },
                    true
                );
            }

            function deleteOfflinePresetForCurrentStory() {
                const context = getCurrentEditingOfflineStoryContext();
                const select = document.getElementById('offline-preset-select');
                if (!context || !select) return;
                const preset = getSillyTavernPresetById(select.value);
                if (!preset) {
                    showToast('先选择一个预设', 'info');
                    return;
                }
                showCustomConfirm('删除预设', `确定删除预设「${preset.name}」吗？`, () => {
                    appData.sillyTavernPresets = ensureSillyTavernPresetLibrary().filter((item) => String(item.id) !== String(preset.id));
                    if (String(appData.appSettings.defaultOfflinePresetId || '') === String(preset.id)) {
                        appData.appSettings.defaultOfflinePresetId = '';
                    }
                    if (String(context.settings.presetId || '') === String(preset.id)) {
                        context.settings.presetId = '';
                    }
                    saveAppData();
                    renderOfflinePresetSelect(context.story);
                    showToast('预设已删除', 'success');
                }, null, '删除', '取消', true);
            }

            function renderOfflineStoryWorldBookMountList(contact, story) {
                const container = document.getElementById('offline-worldbook-mount-list');
                if (!container) return;
                const settings = ensureOfflineStorySettings(story, contact);
                const mounted = new Set((settings.mountedWorldBookIds || []).map(item => String(item || '').trim()).filter(Boolean));
                const entries = getEnabledWorldBookEntries(contact);
                if (!entries.length) {
                    container.innerHTML = '<p class="placeholder-text">这个角色还没有启用的世界书条目。</p>';
                    return;
                }
                container.innerHTML = entries.map((entry) => {
                    const entryId = String(entry.id || '').trim();
                    const checked = settings.worldBookMode !== 'selected' || mounted.has(entryId);
                    const title = escapeHtml(entry.key || '未命名条目');
                    const depth = Number.isFinite(Number(entry.depth)) ? Number(entry.depth) : 4;
                    return `
                        <label class="checkbox-item">
                            <input type="checkbox" class="offline-worldbook-entry-check" value="${escapeHtml(entryId)}" ${checked ? 'checked' : ''}>
                            <span>${title}<small style="margin-left:6px;color:#8a8a8a;">depth ${depth}</small></span>
                        </label>
                    `;
                }).join('');
            }

            function compactOfflineOpeningRemarkText(text, maxLength = 90) {
                const compact = String(text || '').replace(/\s+/g, ' ').trim();
                if (compact.length <= maxLength) return compact;
                return `${compact.slice(0, Math.max(0, maxLength - 3))}...`;
            }

            function getOfflineOpeningRemarkKey(text) {
                return String(text || '').replace(/\s+/g, ' ').trim();
            }

            function updateOfflineOpeningRemarkPreview() {
                const select = document.getElementById('offline-opening-remark-select');
                const preview = document.getElementById('offline-opening-remark-preview');
                if (!select || !preview) return;
                const rawValue = String(select.value || '');
                const index = rawValue === '' ? -1 : Number(rawValue);
                const text = Number.isInteger(index) && index >= 0 ? currentOfflineOpeningRemarkOptions[index] : '';
                if (!text) {
                    preview.textContent = '可以不选，直接在下面手写；也可以留空，让剧情线从用户第一句话开始。';
                    return;
                }
                preview.textContent = compactOfflineOpeningRemarkText(text, 260);
            }

            function renderOfflineOpeningRemarkPicker(contact, settings) {
                const picker = document.getElementById('offline-opening-remark-picker');
                const select = document.getElementById('offline-opening-remark-select');
                if (!picker || !select) return;
                currentOfflineOpeningRemarkOptions = normalizeContactOpeningRemarkOptions(contact);
                if (!currentOfflineOpeningRemarkOptions.length) {
                    picker.style.display = 'none';
                    select.innerHTML = '';
                    updateOfflineOpeningRemarkPreview();
                    return;
                }
                picker.style.display = '';
                select.innerHTML = [
                    '<option value="">不使用角色卡开场白（手写/留空）</option>',
                    ...currentOfflineOpeningRemarkOptions.map((text, index) => {
                        const label = `开场白 ${index + 1}：${compactOfflineOpeningRemarkText(text, 72)}`;
                        return `<option value="${index}">${escapeHtml(label)}</option>`;
                    })
                ].join('');
                const currentTextKey = getOfflineOpeningRemarkKey(settings && settings.openingRemark);
                const selectedIndex = currentTextKey
                    ? currentOfflineOpeningRemarkOptions.findIndex(text => getOfflineOpeningRemarkKey(text) === currentTextKey)
                    : -1;
                select.value = selectedIndex >= 0 ? String(selectedIndex) : '';
                updateOfflineOpeningRemarkPreview();
            }

            function applySelectedOfflineOpeningRemark() {
                const select = document.getElementById('offline-opening-remark-select');
                const textarea = document.getElementById('offline-opening-remark');
                if (!select || !textarea) return;
                const rawValue = String(select.value || '');
                const index = rawValue === '' ? -1 : Number(rawValue);
                const text = Number.isInteger(index) && index >= 0 ? currentOfflineOpeningRemarkOptions[index] : '';
                if (!text) {
                    showToast('先选一条角色卡开场白，或者直接在下面手写。', 'info');
                    return;
                }
                textarea.value = text;
                showToast('已填入这条开场白。', 'success');
            }

            function clearOfflineOpeningRemark() {
                const select = document.getElementById('offline-opening-remark-select');
                const textarea = document.getElementById('offline-opening-remark');
                if (select) select.value = '';
                if (textarea) textarea.value = '';
                updateOfflineOpeningRemarkPreview();
            }

            function ensureOfflineOpeningRemarkMessage(story) {
                if (!story || typeof story !== 'object') return false;
                const settings = ensureOfflineStorySettings(story);
                const openingText = String(settings.openingRemark || '').trim();
                if (!openingText) return false;
                if (!Array.isArray(story.chatHistory)) story.chatHistory = [];
                const hasSameOpening = story.chatHistory.some(message => (
                    message
                    && message.role === 'assistant'
                    && message.isOpeningRemark === true
                    && String(message.content || '').trim() === openingText
                ));
                if (hasSameOpening) return false;
                const hasVisibleMessage = story.chatHistory.some(message => (
                    message
                    && message.type !== 'system'
                    && message.type !== 'recalled'
                    && String(message.content || '').trim()
                ));
                if (hasVisibleMessage) return false;
                story.chatHistory.unshift({
                    id: `opening-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
                    role: 'assistant',
                    content: openingText,
                    type: 'text',
                    timestamp: Date.now(),
                    mode: 'offline',
                    isOpeningRemark: true
                });
                return true;
            }

            function openStorylineEditor(storyId) {
                currentEditingStoryId = storyId;
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                const story = contact.offlineStorylines.find(s => s.id === storyId);
                if (!story) return;

            // 【续集模式】
                document.getElementById('storyline-editor-name').value = story.name;
                document.getElementById('storyline-editor-memory').value = story.memory || '';

            // 【新事件模式】：启动头脑风暴！
            // ★★★【排队锁核心逻辑开始】★★★
                const settings = ensureOfflineStorySettings(story, contact);
                document.getElementById('offline-word-limit').value = settings.wordLimit || '';
                document.getElementById('offline-perspective').value = settings.perspective;
                document.getElementById('offline-prevent-control-toggle').checked = settings.preventControl;
                document.getElementById('offline-start-prompt').value = settings.startPrompt || '';
                renderOfflinePresetSelect(story);
                const presetPromptInput = document.getElementById('offline-preset-prompt');
                if (presetPromptInput) presetPromptInput.value = settings.presetPrompt || '';
                const worldBookModeInput = document.getElementById('offline-worldbook-mode');
                if (worldBookModeInput) worldBookModeInput.value = settings.worldBookMode || 'contact';
                const worldBookDepthInput = document.getElementById('offline-worldbook-depth');
                if (worldBookDepthInput) worldBookDepthInput.value = String(settings.worldBookDepth || 4);
                renderOfflineStoryWorldBookMountList(contact, story);
                document.getElementById('offline-opening-remark').value = settings.openingRemark || '';
                renderOfflineOpeningRemarkPicker(contact, settings);

            // 只有进入这个块的代码是“单行道”，一次只能通过一个角色
                document.getElementById('storyline-editor-modal').classList.remove('hidden');
            }

            function closeStorylineEditor() {
                document.getElementById('storyline-editor-modal').classList.add('hidden');
                currentEditingStoryId = null; // 清空便利贴
            }

            function saveStoryline() {
                if (!currentEditingStoryId) return;
                const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
                const story = contact.offlineStorylines.find(s => s.id === currentEditingStoryId);
                if (!story) return;

            // 更新现有日记 (逻辑不变)
                const newName = document.getElementById('storyline-editor-name').value.trim();
                const newMemory = document.getElementById('storyline-editor-memory').value;
                if (newName) story.name = newName;
                story.memory = newMemory;

                if (!story.settings) story.settings = {};
                story.settings.wordLimit = parseInt(document.getElementById('offline-word-limit').value) || 0;
                story.settings.perspective = document.getElementById('offline-perspective').value;
                story.settings.preventControl = document.getElementById('offline-prevent-control-toggle').checked;
                story.settings.startPrompt = document.getElementById('offline-start-prompt').value.trim();
                story.settings.openingRemark = document.getElementById('offline-opening-remark').value.trim();
                const presetPromptInput = document.getElementById('offline-preset-prompt');
                story.settings.presetPrompt = presetPromptInput ? presetPromptInput.value.trim() : '';
                const globalPresetToggle = document.getElementById('offline-use-global-preset-toggle');
                story.settings.useGlobalPreset = globalPresetToggle ? globalPresetToggle.checked : true;
                const presetSelect = document.getElementById('offline-preset-select');
                if (!story.settings.useGlobalPreset) {
                    story.settings.presetId = presetSelect ? presetSelect.value : '';
                }
                const worldBookModeInput = document.getElementById('offline-worldbook-mode');
                story.settings.worldBookMode = worldBookModeInput ? worldBookModeInput.value : 'contact';
                const worldBookDepthInput = document.getElementById('offline-worldbook-depth');
                story.settings.worldBookDepth = Math.max(0, Math.floor(Number(worldBookDepthInput ? worldBookDepthInput.value : 4) || 4));
                story.settings.mountedWorldBookIds = Array.from(document.querySelectorAll('#offline-worldbook-mount-list .offline-worldbook-entry-check:checked'))
                    .map(input => String(input.value || '').trim())
                    .filter(Boolean);
                ensureOfflineStorySettings(story, contact);

            // ★★★【排队锁核心逻辑结束】★★★
                const wasNew = story.isNew; // 检查它是不是带着“新员工”标签进来的
                if (wasNew) {
                    delete story.isNew; // 撕掉临时标签，让它变成老员工
                }

                const insertedOpeningRemark = ensureOfflineOpeningRemarkMessage(story);

        // 随机抽取一个权重值
                if (wasNew) {
                    const offlineToggle = document.getElementById('cs-offline-mode-toggle');
                    contact.activeOfflineStoryId = story.id;
                    contact.isOfflineMode = true;
                    if (offlineToggle) offlineToggle.checked = true;
                }

                saveAppData();
                renderOfflineStorylines();
                closeStorylineEditor();
                showToast('剧情线已保存！', 'success');

                if (wasNew || insertedOpeningRemark) {
                    openChat(contact.id); // 打开聊天，此时开场白会显示出来
                }
            }

