                const contact = appData.aiContacts.find(c => c.id === activeMovieContactId);
                const movieTitle = document.getElementById('movie-title').textContent;
                const chatLog = currentMovieChatHistory.map(m => `${m.role === 'user' ? (contact.userProfile.name || '用户') : contact.name}: ${m.content}`).join('\n');
                const summaryPrompt = `# 任务: 总结观影讨论\n你和用户刚刚一起看完了电影《${movieTitle}》。请总结以下你们在观影过程中的聊天内容，重点是双方对情节的看法和感想。\n\n# 聊天记录\n${chatLog}\n\n# 输出要求\n以第三人称视角，输出一段简明扼要的YAML格式总结。`;

