                            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                            body: JSON.stringify({ model: appData.appSettings.apiModel, messages: [{ role: 'user', content: summaryPrompt }], temperature: 0.2 })
