        function seerActionPhase() {
            werewolfGameInstance.phase = 'night_seer';
            const myPlayer = werewolfGameInstance.players.find(p => p.id === 'user');
            if (myPlayer.role === 'SEER' && myPlayer.isAlive) {
                updateGameStatusUI(`第 ${werewolfGameInstance.day} 夜`, "预言家请睁眼");
                showStageSubtitle("你是预言家，请选择要查验的玩家...");
                enableSeatSelection('check');
                hideActionButtons();
            } else {
                showToast("预言家正在查验身份...", "info", 0); // 0表示不自动消失，直到查验完成
                setTimeout(aiSeerAction, 3000);
            }
        }

        function witchActionPhase() {
            // 【核心修复】进入女巫阶段的第一件事：强制清除上一阶段（预言家）残留的所有弹窗！
            // 这样无论用户是不是女巫，那个“预言家...”的弹窗都会被消掉。
            document.querySelectorAll('.global-toast-item').forEach(el => el.remove());

            werewolfGameInstance.phase = 'night_witch';
            const myPlayer = werewolfGameInstance.players.find(p => p.id === 'user');
            const deadId = werewolfGameInstance.actions.wolfKill;
            const deadPlayer = werewolfGameInstance.players.find(p => p.id === deadId);

            if (myPlayer.role === 'WITCH' && myPlayer.isAlive) {
                updateGameStatusUI(`第 ${werewolfGameInstance.day} 夜`, "女巫请睁眼");
                if (!werewolfGameInstance.config.witchHealUsed && deadPlayer) {
                    showStageSubtitle(`昨晚 ${deadPlayer.index + 1}号玩家 (${deadPlayer.name}) 死亡，是否使用解药？`); // 修正index显示
                    showActionButtons('witch_heal', "使用解药", "不救");
                } else if (!werewolfGameInstance.config.witchPoisonUsed) {
                    showStageSubtitle("是否使用毒药？（点击头像选择毒杀目标）");
                    enableSeatSelection('poison');
                    showActionButtons('witch_pass', "不毒", "确认毒杀");
                } else {
                    showStageSubtitle("你的药水已用完。");
                    setTimeout(endNightPhase, 2000);
                }
            } else {
                showStageSubtitle("女巫正在配置药水...");
                setTimeout(aiWitchAction, 3000);
            }
        }

        function endNightPhase() {
            werewolfGameInstance.phase = 'day_announce';
            showStageSubtitle("天亮了...");

            // --- 【新增】记录夜间行动到历史 ---
            const currentHistory = werewolfGameInstance.history.find(h => h.day === werewolfGameInstance.day);
            if (currentHistory) {
                currentHistory.nightEvents = {
                    wolfKillTarget: werewolfGameInstance.actions.wolfKill,
                    witchHealUsed: werewolfGameInstance.actions.witchHeal,
                    witchPoisonTarget: werewolfGameInstance.actions.witchPoison,
                    // 注意：预言家查验通常是即时反馈，这里我们假设 actions 里存了 seerCheck 
                    // (你需要去 aiSeerAction 里加一行 werewolfGameInstance.actions.seerCheckTarget = targetId)
                    seerCheckTarget: werewolfGameInstance.actions.seerCheckTarget
                };
                console.log(`[WW-LOG] 第 ${werewolfGameInstance.day} 夜行动已归档`, currentHistory.nightEvents);
            }
            // -------------------------------

            let deadList = [];
            const wolfKillId = werewolfGameInstance.actions.wolfKill;
            const witchHeal = werewolfGameInstance.actions.witchHeal;
            const witchPoisonId = werewolfGameInstance.actions.witchPoison;

            if (wolfKillId && !witchHeal) deadList.push(wolfKillId);
            if (witchPoisonId) deadList.push(witchPoisonId);

            // 【新增】把死亡名单也记入历史，方便所有人查看
            if (currentHistory) {
                currentHistory.nightEvents.deadList = deadList;
            }


            deadList.forEach(id => {
                const p = werewolfGameInstance.players.find(pl => pl.id === id);
                if (p) {
                    p.isAlive = false;
                    const seat = document.querySelector(`.ww-seat[data-index="${p.index}"]`);
                    if (seat) seat.classList.add('dead');
                }
            });

            setTimeout(() => {
                // 【核心修复】过滤掉无效的玩家ID (防止 AI 返回错误的 ID 导致崩溃)
                const validDeadPlayers = deadList.map(id => werewolfGameInstance.players.find(pl => pl.id === id)).filter(p => p);

                if (validDeadPlayers.length === 0) {
                    showStageSubtitle("昨晚是平安夜。");
                } else {
                    const deadNames = validDeadPlayers.map(p => `${p.index + 1}号`).join('、');
                    showStageSubtitle(`昨晚 ${deadNames} 死亡。`);
                }

                if (checkGameOver()) return;
                setTimeout(startDayDiscussion, 3000);
            }, 2000);
        }

        // 6. 白天讨论 (正式版)
        async function startDayDiscussion() {
            const thisSessionId = werewolfGameInstance.currentSessionId;
            werewolfGameInstance.phase = 'day_discuss';
            updateGameStatusUI(`第 ${werewolfGameInstance.day} 天`, "自由讨论");

            // 隐藏操作按钮，专心听发言
            hideActionButtons();

            // 获取所有存活玩家，按座位号排序
            const alivePlayers = werewolfGameInstance.players
                .filter(p => p.isAlive)
                .sort((a, b) => a.index - b.index);

            if (alivePlayers.length === 0) return;

            // 随机决定从几号开始发言（模拟随机麦序）
            const startIndex = Math.floor(Math.random() * alivePlayers.length);
            // 重排数组，形成发言顺序
            const speakOrder = [
                ...alivePlayers.slice(startIndex),
                ...alivePlayers.slice(0, startIndex)
            ];

            // 显示开场提示
            const firstPlayer = speakOrder[0];
            addGameLog(`天亮了。从 ${firstPlayer.index + 1}号玩家 开始顺序发言...`, 'system');
            await sleep(2500); // 等待2.5秒让用户看清提示
            // 【检查点 1】
            if (werewolfGameInstance.currentSessionId !== thisSessionId) return;

            // --- 启动发言循环 (使用 for 循环带索引，以便知道谁是前一个) ---
            for (let i = 0; i < speakOrder.length; i++) {
                const player = speakOrder[i];

                // 【检查点 2】每次循环开始前，检查是否已退出游戏
                if (werewolfGameInstance.currentSessionId !== thisSessionId) {
                    console.log("检测到游戏已退出，终止发言循环。");
                    return;
                }
                // 高亮当前发言玩家
                highlightSpeaker(player.index);

                // 【修改】更新顶部状态条，而不是中间大字
                showSystemToast(`${player.index + 1}号 (${player.name}) 发言中...`);

                let speechContent = "";
                let orderInfo = "";
                if (i === 0) {
                    orderInfo = "【发言顺序】：你是本轮【第一个】发言的玩家。请开启话题，不要点评前面的人（因为没人）。";
                } else {
                    const prevPlayer = speakOrder[i - 1];
                    orderInfo = `【发言顺序】：你是第 ${i + 1} 位发言。上一位发言的是 ${prevPlayer.index + 1}号。请根据前置位的发言进行逻辑分析。`;
                }

                if (player.isAi) {
                    try {
                        // 【核心修改】使用新的上下文生成器构建 Prompt
                        const richContext = await generateWerewolfContext(player);

                        const prompt = `
${richContext}

# 任务: 轮流发言
现在是白天讨论环节。轮到你发言了。
请基于【游戏历史】、【你的身份】、【场上局势】以及你的【人设】，发表一段观点。如果你的游戏水平较高，可以尽可能全面、详细。如果你的游戏水平较低，可以浑水摸鱼。
- 如果你是狼人，请努力伪装，或者跟随主流观点，或者轻踩嫌疑人。
- 如果你是好人，请分析昨晚的死亡情况，或点评前一位玩家的发言。
- 不要带引号。
`;
                        showSystemToast(`${player.name} 正在思考...`);

                        const response = await callAiForWerewolf(prompt);
                        // 【检查点 3】AI生成后检查
                        if (werewolfGameInstance.currentSessionId !== thisSessionId) return;
                        speechContent = response;
                    } catch (e) {
                        console.error("AI发言失败:", e);
                        speechContent = "（...走神了...）过。";
                    }
                } else {
                    // >>> 用户发言 <<<
                    // 弹出输入框让用户输入
                    // 【检查点 4】在弹窗前检查
                    if (werewolfGameInstance.currentSessionId !== thisSessionId) return;
                    speechContent = await promptUserForSpeech();
                    // 【检查点 5】用户输入完后检查
                    if (werewolfGameInstance.currentSessionId !== thisSessionId) return;

                }
                // --- 【新增】记录发言到历史 ---
                // --- 记录到历史 ---
                const currentHistory = werewolfGameInstance.history.find(h => h.day === werewolfGameInstance.day);
                if (currentHistory) {
                    currentHistory.speeches.push({
                        speakerId: player.id,
                        content: speechContent,
                        timestamp: Date.now()
                    });
                }

                // 【核心修改】使用新写的 showSpeech 函数，实现双屏显示
                showSpeech(player.index, speechContent);

                // 阅读时间
                const readTime = Math.min(10000, Math.max(3000, speechContent.length * 200));
                await sleep(readTime);

                if (werewolfGameInstance.currentSessionId !== thisSessionId) return;
                unhighlightSpeaker(player.index);
            }

            if (werewolfGameInstance.currentSessionId !== thisSessionId) return;

            // 发言结束
            showSystemToast("发言结束，请开始投票。");
            addGameLog("--- 发言结束，进入投票阶段 ---", "system");
            showActionButtons('start_vote', "进入投票");

        }

        // --- 辅助：构建狼人杀 Prompt ---
        function buildWerewolfPrompt(player) {
            const g = werewolfGameInstance;
            const myRoleData = WEREWOLF_ROLES[player.role];

            // 获取昨晚死亡名单的描述
            let deadInfo = "昨晚是平安夜";
            if (g.deadPlayersThisNight && g.deadPlayersThisNight.length > 0) {
                const deadNames = g.deadPlayersThisNight.map(id => {
                    const p = g.players.find(pl => pl.id === id);
                    return `${p.index + 1}号`;
                }).join('、');
                deadInfo = `昨晚 ${deadNames} 死亡`;
            }

            // 简单的 AI 策略指导
            let strategy = "";
            if (player.role === 'WOLF') {
                strategy = `
                - **你的底牌是狼人**，但你必须**伪装成好人**（平民或神职）。
                - **绝对不要**承认自己是狼人。
                - 你可以试着把浑水摸鱼，或者跟风踩一个看起来像狼的好人。
                - 如果有队友被怀疑，你可以选择适当捞一手，或者果断倒钩（卖队友保自己）。
                `;
            } else if (player.role === 'SEER') {
                strategy = `
                - **你是预言家**。这是好人阵营的核心。
                - 如果你有查验信息，应该**尽快报出来**（例如：'昨晚查了X号，是金水/查杀'）。
                - 如果还没有查出狼，就号召大家一起找狼。
                `;
            } else {
                strategy = `
                - **你是好人**（${myRoleData.name}）。
                - 认真听别人的发言，找出逻辑漏洞。
                - 不要划水太严重，否则会被当成抗推位。
                `;
            }

            // 获取场上存活信息，方便AI点名
            const aliveList = g.players.filter(p => p.isAlive).map(p => `${p.index + 1}号`).join('、');

            const prompt = `
# 任务: 玩狼人杀并发言
你正在进行一场狼人杀游戏。今天是第 ${g.day} 天的白天讨论环节。

## 【【【自我认知 (最重要)】】】
- **你是 ${player.index + 1} 号玩家** (${player.name})。
- 轮到你发言了。请以“${player.index + 1}号”的身份发言。

## 游戏局势
- **你的底牌**: 【${myRoleData.name}】
- **昨晚情况**: ${deadInfo}
- **场上存活**: ${aliveList}

## 你的行动策略
${strategy}

## 你的AI设定
- 游戏水平: ${player.gameProfile ? player.gameProfile.skillLevel : 0.5} (0.1=萌新乱玩, 0.9=逻辑大神)
- 你的性格: ${appData.aiContacts.find(c => c.id === player.id)?.persona || "普通人"}

## 发言要求
- 请用简短、口语化的语言进行一轮发言（50字以内）。
- **不要**带引号。
- 结尾可以说“过”或者“这就我的看法”。
- 如果你是预言家，必须报出验人信息（如果有）。
- 如果你是狼人，切记不要暴露！
`;
            return prompt;
        }
        // --- 辅助：调用 API (终极调试版) ---
        async function callAiForWerewolf(prompt) {
            // 【核心新增】这里是请求发出前的日志
            console.groupCollapsed("%c🐺【狼人杀 AI 思考请求】(点击展开查看 Prompt)", "color: #FF5722; font-weight: bold; font-size: 12px;");
            console.log("%c👇 发送给 AI 的完整指令 (Prompt):", "color: #2196F3; font-weight: bold;");
            console.log(prompt); // 这里会显示完整的 Prompt 文本，保留换行
            console.groupEnd();

            let requestUrl = appData.appSettings.apiUrl;
            if (!requestUrl.endsWith('/chat/completions')) {
                requestUrl = requestUrl.endsWith('/') ? requestUrl + 'chat/completions' : requestUrl + '/chat/completions';
            }

            try {
                const response = await fetch(requestUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                    body: JSON.stringify({
                        model: appData.appSettings.apiModel,
                        messages: [{ role: 'user', content: prompt }],
                        temperature: 0.8
                    })
                });

                if (!response.ok) throw new Error(`API状态码错误: ${response.status}`);
                const data = await response.json();

                let aiReplyContent = "";

                // 1. OpenAI 标准格式
                if (data.choices && data.choices.length > 0 && data.choices[0].message && data.choices[0].message.content) {
                    aiReplyContent = data.choices[0].message.content.trim();
                }
                // 兼容部分非标准接口（choices[0].text）
                else if (data.choices && data.choices.length > 0 && data.choices[0].text) {
                    aiReplyContent = data.choices[0].text.trim();
                }
                // 2. Gemini 格式
                else if (data.candidates && data.candidates.length > 0 && data.candidates[0].content && data.candidates[0].content.parts) {
                    aiReplyContent = data.candidates[0].content.parts[0].text.trim();
                }
                // 3. 简化格式
                else if (data.reply) aiReplyContent = data.reply;
                else if (data.content) aiReplyContent = data.content;
                else {
                    console.error("无法识别的 API 格式:", data);
                    throw new Error("格式无法识别，请按F12查看控制台的[狼人杀API原始数据]");
                }

                // 【核心新增】这里是收到回复后的日志
                console.groupCollapsed("%c🤖【狼人杀 AI 回复结果】(点击展开查看)", "color: #4CAF50; font-weight: bold; font-size: 12px;");
                console.log("%c👇 AI 返回的原始内容:", "color: #4CAF50; font-weight: bold;");
                console.log(aiReplyContent);
                console.groupEnd();

                return aiReplyContent;

            } catch (e) {
                console.error("API调用严重错误:", e);
                // 为了不让游戏卡死，返回一个默认兜底回复
                return "（...思考中...）过。";
            }
        }

        // --- 辅助：用户发言输入框 (行内版) ---
        function promptUserForSpeech() {
            return new Promise((resolve) => {
                const inputArea = document.getElementById('ww-user-speech-input');
                const inputField = document.getElementById('ww-speech-text');
                const sendBtn = document.getElementById('ww-speech-send-btn');

                // 1. 显示输入栏
                inputArea.classList.remove('hidden');
                inputField.value = '';
                inputField.focus();

                // 提示用户
                addGameLog("👉 轮到你发言了，请在下方输入...", "system");

                // 定义发送处理函数
                const handleSend = () => {
                    const text = inputField.value.trim();
                    if (!text) return; // 禁止空发

                    // 2. 隐藏输入栏
                    inputArea.classList.add('hidden');

                    // 3. 移除事件监听 (防止重复绑定)
                    sendBtn.removeEventListener('click', handleSend);
                    inputField.removeEventListener('keydown', handleEnter);

                    // 4. 返回结果
                    resolve(text);
                };

                const handleEnter = (e) => {
                    if (e.key === 'Enter') handleSend();
                };

                // 绑定事件
                sendBtn.addEventListener('click', handleSend);
                inputField.addEventListener('keydown', handleEnter);
            });
        }

        // --- 辅助：高亮/取消高亮 ---
        function highlightSpeaker(index) {
            const seat = document.querySelector(`.ww-seat[data-index="${index}"]`);
            if (seat) seat.classList.add('speaking');
        }
        function unhighlightSpeaker(index) {
            const seat = document.querySelector(`.ww-seat[data-index="${index}"]`);
            if (seat) seat.classList.remove('speaking');
        }

        // --- 交互逻辑 (点击事件) ---
        function setupSeatInteractions() {
            // 必须先解绑旧事件（虽然这里是初始化，但保险起见），简单起见我们假设init会重置DOM
            const tableArea = document.getElementById('werewolf-table-area');
            // 移除旧的监听器比较麻烦，我们利用“每次init都清空innerHTML”的特性，
            // 实际上我们只需要给新的 .ww-seat 绑定事件，或者在 tableArea 上做事件委托
            // 这里使用 cloneNode 来清除 tableArea 上的所有旧监听器
            const newTableArea = tableArea.cloneNode(true);
            tableArea.parentNode.replaceChild(newTableArea, tableArea);

            // 绑定新的委托
            newTableArea.addEventListener('click', (e) => {
                const seat = e.target.closest('.ww-seat');
                if (!seat || !seat.classList.contains('interactive')) return;

                // 【核心修复】获取真正的用户对象
                const myPlayer = werewolfGameInstance.players.find(p => p.id === 'user');

                // 如果用户死了，点击无效
                if (!myPlayer || !myPlayer.isAlive) {
                    showToast('你已出局，无法操作', 'error');
                    return;
                }

                const index = parseInt(seat.dataset.index);
                const targetPlayer = werewolfGameInstance.players.find(p => p.index === index);

                newTableArea.querySelectorAll('.ww-seat').forEach(el => el.classList.remove('selected'));
                seat.classList.add('selected');

                if (werewolfGameInstance.phase === 'night_wolf') {
                    werewolfGameInstance.actions.tempWolfTarget = targetPlayer.id;
                } else if (werewolfGameInstance.phase === 'night_seer') {
                    revealIdentity(targetPlayer);
                } else if (werewolfGameInstance.phase === 'night_witch') {
                    werewolfGameInstance.actions.tempPoisonTarget = targetPlayer.id;
                }
                // 【全新】投票阶段选择
                else if (werewolfGameInstance.phase === 'day_vote') {
                    if (targetPlayer.id === 'user') {
                        showToast('不能投给自己！', 'warning');
                        seat.classList.remove('selected');
                        return;
                    }
                    werewolfGameInstance.actions.tempVoteTarget = targetPlayer.id;
                }
            });

            // 底部按钮也要重新绑定
            const controls = document.querySelector('.werewolf-controls');
            const newControls = controls.cloneNode(true);
            controls.parentNode.replaceChild(newControls, controls);

            newControls.addEventListener('click', (e) => {
                const btn = e.target.closest('.ww-btn');
                if (!btn) return;
                const action = btn.dataset.action;
                // 【核心修复】死人投票校验
                if (action === 'vote_confirm') {
                    const myPlayer = werewolfGameInstance.players.find(p => p.id === 'user');
                    if (!myPlayer || !myPlayer.isAlive) {
                        showToast('你已死亡，正在等待结果...', 'info');
                        resolveVotingPhase();
                        return;
                    }
                }


                handleGameAction(action);
            });
        }

        function handleGameAction(action) {
            if (action === 'kill_confirm') {
                if (werewolfGameInstance.actions.tempWolfTarget) {
                    werewolfGameInstance.actions.wolfKill = werewolfGameInstance.actions.tempWolfTarget;
                    showToast('已确认袭击目标', 'success');
                    clearInteraction();
                    setTimeout(seerActionPhase, 1000);
                } else {
                    showToast('请先选择一个目标', 'error');
                }
            }
            else if (action === 'witch_heal') {
                werewolfGameInstance.actions.witchHeal = true;
                werewolfGameInstance.config.witchHealUsed = true;
                showToast('已使用解药', 'success');
                clearInteraction();
                setTimeout(endNightPhase, 1000);
            }
            else if (action === 'witch_pass') {
                if (!werewolfGameInstance.actions.witchHeal) {
                    if (werewolfGameInstance.actions.tempPoisonTarget) {
                        werewolfGameInstance.actions.witchPoison = werewolfGameInstance.actions.tempPoisonTarget;
                        werewolfGameInstance.config.witchPoisonUsed = true;
                        showToast('已使用毒药', 'success');
                    }
                    clearInteraction();
                    setTimeout(endNightPhase, 1000);
                }
            }
            // ▼▼▼ 【全新】投票与流程控制逻辑 ▼▼▼
            else if (action === 'start_vote') {
                startVotingPhase();
            }
            else if (action === 'vote_confirm') {
                if (werewolfGameInstance.actions.tempVoteTarget) {
                    // 记录用户的票
                    if (!werewolfGameInstance.actions.votes) werewolfGameInstance.actions.votes = {};
                    werewolfGameInstance.actions.votes['user'] = werewolfGameInstance.actions.tempVoteTarget;

                    showToast('投票成功', 'success');
                    clearInteraction();

                    // 触发AI投票并结算
                    resolveVotingPhase();
                } else {
                    showToast('请选择一名玩家进行投票', 'error');
                }
            }
            else if (action === 'next_night') {
                // 进入下一夜
                werewolfGameInstance.day++;
                startNightPhase();
            }
        }

        // --- 【全新】投票阶段逻辑 ---

        // 1. 开启投票 UI
        function startVotingPhase() {
            werewolfGameInstance.phase = 'day_vote';
            updateGameStatusUI(`第 ${werewolfGameInstance.day} 天`, "全员投票");

            const myPlayer = werewolfGameInstance.players.find(p => p.id === 'user');
            if (myPlayer.isAlive) {
                showStageSubtitle("请点击头像，投票选出你心目中的狼人...");
                enableSeatSelection('vote'); // 只有活着才能选人
                showActionButtons('vote_confirm', "确认投票");
            } else {
                showStageSubtitle("你已出局，无法参与投票，请观战...");
                // 死人不需要操作按钮，直接等待倒计时或自动推进
                // 为了防止卡死，这里可以设置一个自动推进的触发（或者等待其他AI投完）
                // 简单起见，我们让死人也点一下“确认”（但不选人）来推进，或者给一个“跳过”按钮
                showActionButtons('vote_confirm', "观看投票结果 (你已死亡)");
            }

            werewolfGameInstance.actions.votes = {};
            werewolfGameInstance.actions.tempVoteTarget = null;
        }

        // --- 辅助：单个AI思考投票逻辑 (包含记忆与人设) ---
        // --- 辅助：单个AI思考投票逻辑 (线上防幻觉 + 逻辑修正版) ---
        async function aiVoteDecision(player) {
            const actorPublicSummary = buildWerewolfActorPublicSummary(player);
            const userProfileText = buildWerewolfUserFullProfileText();
            const seatState = buildWerewolfSeatStatusSnapshot({
                includeCard: true,
                includeStatus: true,
                includeSignature: true,
                includeNetName: true,
                includeUserMarker: true
            });
            const publicHistory = buildWerewolfPublicHistorySummary();

            // 2. 准备候选人名单 (排除自己)
            const candidates = werewolfGameInstance.players
                .filter(p => p.isAlive && p.id !== player.id)
                .map((candidate) => formatWerewolfPlayerDescriptor(candidate, {
                    bracketed: false,
                    includeCard: true,
                    includeSignature: false,
                    includeNetName: true,
                    includeStatus: false,
                    includeUserMarker: true
                }))
                .join('\n');

            // 3. 不同身份的策略 (【修复】狼人增加队友名单)
            let strategy = "";
            if (player.role === 'WOLF') {
                // 【核心修复】获取狼队友名单
                const wolfTeammates = werewolfGameInstance.players
                    .filter(p => p.role === 'WOLF' && p.id !== player.id)
                    .map(p => `${p.index + 1}号`)
                    .join('、');

                strategy = `
                - **你是狼人**。
                - **【重要情报】你的狼队友是：${wolfTeammates || "无（你是孤狼）"}**。
                - **行动铁律**: 
                    1. 优先投票给好人（平民或神职）。
                    2. **绝对不要**投票给你的狼队友，除非为了“倒钩”做身份（即队友已经暴露，你通过踩他来装好人），或执行狼队自刀战术。
                    3. 观察场上局势，如果好人阵营在集火某个好人，请务必跟票把他冲出去。
                `;
            } else if (player.role === 'SEER') {
                strategy = `
                - **你是预言家**。
                - **目标**: 必须投给你查杀的狼人！如果没有查杀，投给场上发言最差、逻辑最爆炸的人。
                - **号召**: 你是全场逻辑的核心，你的票型代表了验人结果。
                `;
            } else {
                strategy = `
                - **你是好人**。
                - **目标**: 跟随预言家（如果可信）的票型，或者投给发言有明显逻辑漏洞的人。
                `;
            }

            const prompt = `
# 任务: 狼人杀白天投票
现在是第 ${werewolfGameInstance.day} 天的投票环节。
你需要决定把票投给谁。

## 你的身份信息
- **你是 ${player.index + 1}号玩家** (${getWerewolfPlayerProfile(player).gameName})。
- **你的底牌**: 【${WEREWOLF_ROLES[player.role]?.name || player.role}】。

## 你的公开资料
${actorPublicSummary}

## 用户完整资料
${userProfileText}

## 全场座位表 (状态快照)
${seatState}

## 之前每一轮的公开行动、发言与票型
${publicHistory}

## 候选人名单
${candidates}

## 称呼规则
- 你在游戏内只能用每个人的“游戏内称呼/网名”来叫人，绝对不要直呼真名。

## 你的身份策略
${strategy}

## 【【【线上游戏物理法则 (绝对铁律)】】】
1.  **无视觉信息**: 这是一个**纯文字/语音**的线上游戏。你**看不见**任何人的表情、动作、眼神或反应！
    -   **绝对禁止**使用“他眼神躲闪”、“他表情不自然”、“他反应平淡”、“他手抖了”作为理由。
    -   **只能**依据：发言内容、语气、逻辑、票型、死亡情况。
2.  **时序逻辑**: 发言是**按顺序**进行的。
    -   **前置位**的人（先发言的）**不可能**对**后置位**的人（后发言的）的指控做出“反应”。
    -   *示例*: 如果 3 号先发言，4 号预言家后发言查杀 3 号。3 号不可能有“反应”，因为轮到他时 4 号还没说话！3 号只能在下一轮辩解。

## 【【【狼人杀基础逻辑库 (Common Sense)】】】
在思考时，请参考以下公认的游戏逻辑，不要产生违反常识的判断：
1.  **平安夜逻辑**: 第一天如果是平安夜，**99% 的情况是女巫使用了借药救人**。这是最正常的现象，**绝不是**“逻辑不通”。如果有玩家跳女巫报银水（救了谁），这非常可信。
2.  **预言家力度**: 在没有对跳（两个预言家）的情况下，唯一预言家的查杀是最硬的逻辑。平民通常应该跟票预言家。
3.  **查杀逻辑**: 如果你是平民，且场上有预言家发了查杀，除非你觉得这个预言家是假的，否则应该优先投查杀对象。

## 思考步骤
1.  **回顾局势**: 昨晚死了谁？有没有人跳神职？
2.  **分析发言**: 谁的发言有逻辑漏洞？谁在划水？
3.  **应用铁律**: 检查你的理由是否违反了“无视觉”或“时序”规则？

## 输出要求
请输出一个JSON对象:
{
  "targetIndex": 数字 (你投票目标的座位号，例如 3),
  "reason": "简短的投票理由。必须基于发言逻辑，严禁描写表情动作。"
}
`;
            try {
                const response = await callAiForWerewolf(prompt);
                const jsonMatch = response.match(/\{[\s\S]*\}/);
                if (jsonMatch) {
                    const res = JSON.parse(jsonMatch[0]);
                    const targetIndex = parseInt(res.targetIndex) - 1;
                    const target = werewolfGameInstance.players.find(p => p.index === targetIndex);

                    if (target && target.isAlive) {
                        console.log(`[AI投票] ${player.index + 1}号 投给了 ${target.index + 1}号。理由: ${res.reason}`);
                        return { voterId: player.id, targetId: target.id };
                    }
                }
            } catch (e) {
                console.error(`${player.name} 投票思考失败`, e);
            }

            // 兜底：随机投一个 (除了自己)
            const validTargets = werewolfGameInstance.players.filter(p => p.isAlive && p.id !== player.id);
            const randomTarget = validTargets[Math.floor(Math.random() * validTargets.length)];
            return { voterId: player.id, targetId: randomTarget.id };
        }

        // 2. 结算投票 (AI 并行思考 + 计票 + 公布)
        async function resolveVotingPhase() {
            const thisSessionId = werewolfGameInstance.currentSessionId;

            showStageSubtitle("玩家正在思考，请稍候...");

            // 显示一个全屏loading或者提示，因为并行调用可能会稍微卡顿一下（取决于网络）
            const loadingToast = showToast("正在等待所有玩家投票...", "info", 0);

            // A. AI 并行投票
            const aliveAiPlayers = werewolfGameInstance.players.filter(p => p.isAlive && p.isAi);

            // 创建所有AI的思考任务
            const votePromises = aliveAiPlayers.map(ai => aiVoteDecision(ai));

            // 【核心】并行执行，等待所有结果
            try {
                const results = await Promise.all(votePromises);

                // 检查游戏是否中途退出
                if (werewolfGameInstance.currentSessionId !== thisSessionId) {
                    if (loadingToast) loadingToast.remove();
                    return;
                }

                // 填入票箱
                results.forEach(res => {
                    if (res) {
                        werewolfGameInstance.actions.votes[res.voterId] = res.targetId;
                    }
                });

            } catch (e) {
                console.error("AI投票过程出错", e);
            } finally {
                if (loadingToast) loadingToast.remove();
            }

            // B. 统计票数 (后续逻辑保持不变，直接复制即可，但我为了完整性还是写出来)
            showStageSubtitle("投票结束，正在验票...");
            await sleep(1000);

            const votes = werewolfGameInstance.actions.votes;

            // 记录投票结果到历史 (重要！下一轮AI思考全靠这个)
            const currentHistory = werewolfGameInstance.history.find(h => h.day === werewolfGameInstance.day);
            if (currentHistory) {
                currentHistory.votes = JSON.parse(JSON.stringify(votes));
                console.log(`[WW-LOG] 第 ${werewolfGameInstance.day} 天投票数据已归档`);
            }

            const voteCounts = {};
            const voteDetails = [];

            for (const voterId in votes) {
                const targetId = votes[voterId];
                voteCounts[targetId] = (voteCounts[targetId] || 0) + 1;

                const voter = werewolfGameInstance.players.find(p => p.id == voterId);
                const target = werewolfGameInstance.players.find(p => p.id == targetId);
                if (voter && target) {
                    voteDetails.push(`<div class="vote-result-item">
                        <span>${voter.index + 1}号 ${voter.name}</span>
                        <span class="vote-arrow">➡</span>
                        <span>${target.index + 1}号 ${target.name}</span>
                    </div>`);
                }
            }

            // C. 展示投票详情 (写入日志)
            addGameLog("=== 投票结果 ===", "vote");
            voteDetails.forEach(detailHtml => {
                // 这里我们把 div 标签剥离，或者直接把HTML塞进去
                // voteDetails 之前生成的是 div，我们直接作为 HTML 插入
                addGameLog(detailHtml, "vote");
            });

            await sleep(5000); // 给用户多一点时间看票型
            if (werewolfGameInstance.currentSessionId !== thisSessionId) return;

            // D. 寻找票数最高者
            let maxVotes = 0;
            let maxTargets = [];

            for (const targetId in voteCounts) {
                const count = voteCounts[targetId];
                if (count > maxVotes) {
                    maxVotes = count;
                    maxTargets = [targetId];
                } else if (count === maxVotes) {
                    maxTargets.push(targetId);
                }
            }

            // E. 处决逻辑 (修复版)
            if (maxTargets.length === 1) {
                const exiledId = maxTargets[0];
                const exiledPlayer = werewolfGameInstance.players.find(p => p.id == exiledId);

                if (exiledPlayer) {
                    exiledPlayer.isAlive = false;

                    // 【核心修复】将结果写入历史对象，并打印日志确认
                    if (currentHistory) {
                        currentHistory.exiledId = exiledId;
                        console.log(`[WW-LOG] 记录放逐: ${exiledPlayer.index + 1}号`);
                    }

                    showStageSubtitle(`决议已定。\n${exiledPlayer.index + 1}号玩家 (${exiledPlayer.name}) 被放逐。`);

                    // 将座位变黑
                    const seat = document.querySelector(`.ww-seat[data-index="${exiledPlayer.index}"]`);
                    if (seat) seat.classList.add('dead', 'exiled');
                }

                if (checkGameOver()) return;

            } else {
                // 【核心修复】平票也要记录，不然AI会以为没发生
                if (currentHistory) {
                    currentHistory.exiledId = null;
                    console.log(`[WW-LOG] 记录放逐: 无人`);
                }
                showStageSubtitle("平票 (或无人投票)，无人出局，直接进入黑夜。");
            }

            // F. 准备进入下一夜
            showActionButtons('next_night', "入夜");
        }
        // --- 辅助功能 (这些就是之前丢掉的代码，现在补回来了) ---

