        // 【全新】打开“从现有歌曲创建”弹窗的函数
                document.getElementById('sl-excellent').value = w.excellent;
                document.getElementById('sl-very-good').value = w.veryGood;
                document.getElementById('sl-good').value = w.good;
                document.getElementById('sl-average').value = w.average;
                document.getElementById('sl-low').value = w.low;
