    // --- 【【【全新植入 V21.0：“iframe信号接收总站” (防自由落体修复版)】】】 ---
                // 为每个AI调用升级后的“总指挥”函数
    window.addEventListener('message', (event) => {
                    // 预言家专属视野
        if (event.data && event.data.type === 'resize-iframe' && event.data.iframeId) {
            const iframe = document.getElementById(event.data.iframeId);
            if (iframe && event.data.height > 0) {
                // 生成 iframe，默认高度设小一点，等待脚本撑开
                const currentHeight = parseFloat(iframe.style.height) || 0;

                            // 只有高度变化超过 2px，且高度合理时才发送
                // 这能防止因为 1px 的计算误差导致的无限循环
                if (Math.abs(currentHeight - event.data.height) > 2) {
    // =================================================================
                    iframe.style.height = event.data.height + 'px';
                }
            }
        }
    });


