    /**
     * 【【【终极修复 V2：通话专用带输入框弹窗的遥控器】】】
     */
    function showVoiceCallPrompt(title, text, defaultValue, onConfirm) {
        const modal = document.getElementById('voice-call-prompt-modal');
        document.getElementById('vc-prompt-title').textContent = title;
        document.getElementById('vc-prompt-text').textContent = text;

        const input = document.getElementById('vc-prompt-input');
        input.value = defaultValue || '';
        input.placeholder = text; // 把提示文字也作为输入框的占位符

        const cancelBtn = document.getElementById('vc-prompt-cancel-btn');
        const okBtn = document.getElementById('vc-prompt-ok-btn');

                // 切换图标
        const okBtnClone = okBtn.cloneNode(true);
        okBtn.parentNode.replaceChild(okBtnClone, okBtn);
        okBtnClone.addEventListener('click', () => {
            if (onConfirm) onConfirm(input.value);
            modal.classList.add('hidden');
        });

        const cancelBtnClone = cancelBtn.cloneNode(true);
        cancelBtn.parentNode.replaceChild(cancelBtnClone, cancelBtn);
        cancelBtnClone.addEventListener('click', () => {
            modal.classList.add('hidden');
        });

        modal.classList.remove('hidden');
    }


    /**
     * 更新环境音气泡的显示内容
     */
    function updateAmbientBubble() {
        const ambientText = document.getElementById('vc-ambient-text');
        // 【解决问题6】移除出戏的文字
        ambientText.textContent = isShowingAiAmbient ? currentAiAmbientSound : currentUserAmbientSound;
    }

    /**
     * 切换麦克风静音状态
     */
    function toggleMute() {
        isUserMuted = !isUserMuted;
        if (voiceCallActive && voiceCallMode === 'live') {
            if (isUserMuted) {
                stopVoiceCallSpeechCapture(true, { disableLoop: true });
            } else {
                startVoiceCallSpeechCaptureLoop();
            }
        }
        updateVoiceCallMuteButtons();
        showToast(isUserMuted ? '麦克风已关闭' : '麦克风已开启', 'info');
    }

    // 为通话页面的所有按钮绑定事件 (安全版)
    const hangupBtn = document.getElementById('vc-hangup-btn');
    if (hangupBtn) {
        hangupBtn.addEventListener('click', () => endVoiceCall('user'));
    }

    const muteBtn = document.getElementById('vc-mute-btn');
    if (muteBtn) {
        muteBtn.addEventListener('click', toggleMute);
    }

    const minimizeBtn = document.getElementById('vc-minimize-btn');
    if (minimizeBtn) {
        minimizeBtn.addEventListener('click', () => minimizeVoiceCall());
    }

