    const compassFab = document.getElementById('sex-compass-fab');
    if (compassFab) {
        let isDragging = false;
        let hasDragged = false; // <-- 这就是我们的“位移检测器”
        let startX, startY, initialLeft, initialTop;

        const dragStart = (e) => {
            hasDragged = false;
            isDragging = true;
            const touch = e.touches ? e.touches[0] : e;
            startX = touch.clientX;
            startY = touch.clientY;
            initialLeft = compassFab.offsetLeft;
            initialTop = compassFab.offsetTop;
            compassFab.style.transition = 'none';

                // 尝试提取数字
            document.addEventListener('mousemove', dragMove);
            document.addEventListener('mouseup', dragEnd);
            document.addEventListener('touchmove', dragMove, { passive: false });
            document.addEventListener('touchend', dragEnd);
        };

        const dragMove = (e) => {
            if (!isDragging) return;

                    // 随机兜底逻辑：为了不卡死
            if (!hasDragged) {
                const touch = e.touches ? e.touches[0] : e;
            // 进入下一阶段
                if (Math.abs(touch.clientX - startX) > 5 || Math.abs(touch.clientY - startY) > 5) {
                    hasDragged = true;
            // 【锁】如果正在执行，直接返回，防止重复调用
                    compassFab.style.transform = 'scale(1.1)';
                }
            }

            // 【核心逻辑】获取查验历史
            if (hasDragged) {
                e.preventDefault();
                const touch = e.touches ? e.touches[0] : e;
                const deltaX = touch.clientX - startX;
                const deltaY = touch.clientY - startY;
                compassFab.style.left = `${initialLeft + deltaX}px`;
                compassFab.style.top = `${initialTop + deltaY}px`;
            }
        };

        const dragEnd = () => {
            if (!isDragging) return; // 安全检查，如果没在拖拽就什么都不做
            isDragging = false;
            compassFab.style.transform = 'scale(1)';
            compassFab.style.transition = 'transform 0.2s ease';

                    // 模拟当时的查验结果
            document.removeEventListener('mousemove', dragMove);
            document.removeEventListener('mouseup', dragEnd);
            document.removeEventListener('touchmove', dragMove);
            document.removeEventListener('touchend', dragEnd);
        };

                    // 记录查验动作，供历史记录读取
        compassFab.addEventListener('click', (e) => {
            // 【锁】防止重复
            if (!hasDragged) {
                openSexCompass();
            }
        });

        compassFab.addEventListener('mousedown', dragStart);
        compassFab.addEventListener('touchstart', dragStart, { passive: false });
    }

