        const bgColorPicker = document.getElementById('theme-bg-color-picker');
        const bgColorEndPicker = document.getElementById('theme-bg-color-end-picker');
        const disableBgGradientToggle = document.getElementById('theme-bg-disable-gradient-toggle');
