    /**
     * 【辅助函数】根据索引获取正确的日期标签
     * index 0 = 昨天, 1 = 今天, 2 = 明天, 其他 = M月D日
     */
    function getCorrectDateLabel(index) {
        const today = new Date();
        const targetDate = new Date(today);

        // 我们的数组结构是：[昨天, 今天, 明天, 后天...]
        // 所以 index 0 对应 offset -1
        targetDate.setDate(today.getDate() + (index - 1));

        if (index === 0) return '昨天';
        if (index === 1) return '今天';
        if (index === 2) return '明天';

        return `${targetDate.getMonth() + 1}月${targetDate.getDate()}日`;
    }
