    /**
     * 渲染名片UI
     */
    async function renderAiProfileCard(contact) {
        const profile = contact.socialProfile;
        const modal = document.getElementById('ai-profile-card-modal');

        // A. 渲染背景
        const header = document.getElementById('profile-card-header');
        if (profile.bgImageKey) {
            try {
                const blob = await db.getImage(profile.bgImageKey);
                if (blob) {
                    header.style.backgroundImage = `url(${URL.createObjectURL(blob)})`;
                }
            } catch (e) { }
        } else if (profile.bgGradient) {
            header.style.backgroundImage = profile.bgGradient;
        } else {
            header.style.background = "#ccc"; // 默认
        }

        // B. 渲染头像
        const avatarImg = document.getElementById('profile-card-avatar');
        const avatarBlob = await db.getImage(`${contact.id}_avatar`);
        avatarImg.src = avatarBlob ? URL.createObjectURL(avatarBlob) : 'https://i.postimg.cc/kXq06mNq/ai-default.png';

        // C. 渲染文字信息
        document.getElementById('profile-nickname').textContent = profile.nickname || contact.name;
        document.getElementById('profile-realname').textContent = contact.name;
        document.getElementById('profile-signature').textContent = profile.signature || "（暂无个性签名）";

                // ... (复制你之前的生成代码) ...
        const tagsContainer = document.getElementById('profile-tags-container');
        tagsContainer.innerHTML = '';
        if (profile.tags && profile.tags.length > 0) {
            profile.tags.forEach(tag => {
                const span = document.createElement('span');
                span.className = 'info-badge';
                span.textContent = tag;
                // 这是一个取舍。这里我选择：如果替换了，就只显示替换后的纯文本。
                const colors = ['#e3f2fd', '#f3e5f5', '#e8f5e9', '#fff3e0'];
                const textColors = ['#1565c0', '#7b1fa2', '#2e7d32', '#ef6c00'];
                const randIndex = Math.floor(Math.random() * colors.length);
                span.style.backgroundColor = colors[randIndex];
                span.style.color = textColors[randIndex];
                tagsContainer.appendChild(span);
            });
        }
    }

    /**
     * 调用API生成AI的社交资料 (V3.0 - 强健解析版)
     */
    async function generateAiSocialProfile(contact) {
        // 1. 准备上下文：世界书
        const worldBookString = formatWorldBookForPrompt(contact, { emptyText: '无特殊世界观设定' });

        // 2. 准备上下文：用户人设
        const userPersona = (contact.userProfile && contact.userProfile.persona)
            ? contact.userProfile.persona
            : '普通网友';

        const prompt = `
# 任务: 设计社交媒体个人资料
你是一个AI角色。请根据你的【完整背景设定】，为自己设计一个在社交APP上使用的个人资料。

## 你的核心背景
- **核心人设**: ${contact.persona}
- **世界观设定**: 
${worldBookString}

## 关于你的聊天对象 (用户)
- **TA的人设**: ${userPersona}
(请根据你对用户的态度，决定你的网名是高冷、亲切还是搞怪)

## 设计要求
1.  **网名**: 不要用真名！起一个符合你性格、好听、独特的网名。
    - 示例: "落日飞车", "Momo", "一只特立独行的猪", "User9527".
    - 如果是古风角色，可以是雅致的词；如果是赛博朋克，可以是代号。
2.  **个性签名**: 一句符合你当前心境或性格的短句（30字以内）。可以是歌词、吐槽、文艺句或空白。
3.  **个人标签 (可选)**: 生成 **0 到 5 个** 短标签。
    - **内容自由**: 可以是年龄、星座、MBTI，也可以是“心情不好”、“正在听歌”、“铲屎官”、“熬夜冠军”等任何符合你人设的短语。
    - **自主决策**: 如果你觉得现在不需要标签，或者只想展示一个，完全由你决定。如果你的人设比较高冷或佛系，可以不生成星座、mbti等花里胡哨的标签，或者干脆不生成任何标签。
4.  **主题色**: 选择两个HEX颜色代码，代表你的风格（用于生成背景渐变）。

## 【【【严格的输出格式要求】】】
你的回复【必须】是一个能被JSON解析的、单一的JSON对象。
**绝对禁止**在JSON对象之外输出任何文字、解释或备注！

## 输出格式示例:
\`\`\`json
{
  "nickname": "网名",
  "signature": "个性签名内容",
  "tags": ["24岁", "天蝎座", "INFP"],
  "colors": ["#ff9a9e", "#fecfef"]
}
\`\`\`
`;
        try {
            let requestUrl = appData.appSettings.apiUrl.endsWith('/chat/completions') ? appData.appSettings.apiUrl : appData.appSettings.apiUrl + '/chat/completions';
            const response = await fetch(requestUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                body: JSON.stringify({
                    model: appData.appSettings.apiModel,
                    messages: [{ role: 'user', content: prompt }],
                    temperature: 1.0 // 高温度，更有创意
                })
            });

            const data = await response.json();

            // 【核心修复：包裹安检系统】
            if (!data.choices || data.choices.length === 0 || !data.choices[0].message) {
                throw new Error("API 返回数据无效");
            }

            const content = data.choices[0].message.content;
            console.log("AI返回的名片原始数据:", content); // 方便调试

            // --- 【核心修复：智能 JSON 提取器】 ---
            let jsonString = '';

            // 策略1：尝试提取 Markdown 代码块 ```json ... ```
            const codeBlockMatch = content.match(/```json\s*([\s\S]*?)\s*```/i) || content.match(/```\s*([\s\S]*?)\s*```/);
            if (codeBlockMatch) {
                jsonString = codeBlockMatch[1];
            } else {
                // 策略2：如果没有代码块，尝试提取最外层的 {}
                const braceMatch = content.match(/\{[\s\S]*\}/);
                if (braceMatch) {
                    jsonString = braceMatch[0];
                } else {
                    jsonString = content; // 实在不行就硬解析
                }
            }

            // 策略3：清理可能存在的单行注释 (AI有时会写 // 注释)
            jsonString = jsonString.replace(/\/\/.*$/gm, '');

            // --- 解析 ---
            const result = JSON.parse(jsonString);

            // 更新数据
            contact.socialProfile.nickname = result.nickname;
            contact.socialProfile.signature = result.signature;
            contact.socialProfile.tags = result.tags;
            // 生成渐变CSS
            if (result.colors && result.colors.length >= 2) {
                contact.socialProfile.bgGradient = `linear-gradient(135deg, ${result.colors[0]}, ${result.colors[1]})`;
            }
            contact.socialProfile.lastUpdate = Date.now();

            saveAppData();
            showToast('AI已更新了名片！', 'success');

        } catch (e) {
            console.error("生成名片失败:", e);
            showCustomAlert('生成失败', `AI返回的数据格式有误，请重试。\n\n错误信息: ${e.message}`);
        }
    }

