    // 【新增】移除个人资料背景的逻辑
    async function removeProfileBackground() {
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact || !contact.socialProfile) return;

        if (contact.socialProfile.bgImageKey) {
    // 1. 安全检查，确保我们在正确的页面
            try {
                await db.deleteImage(contact.socialProfile.bgImageKey);
            } catch (e) { console.warn("清理旧背景失败", e); }

                    // 2. 保存文件到数据库
            contact.socialProfile.bgImageKey = null;

                // 3. 显示到界面时，也用同一个身份证号
            saveAppData();
            renderAiProfileCard(contact); // 重新渲染，它会自动变回默认的渐变色
            showToast('背景图片已移除', 'success');
        } else {
            showToast('请先勾选要移除的成员', 'info');
        }
    }

                    // 确认是拖拽后，才开始放大
    document.getElementById('profile-bg-upload').addEventListener('change', async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        const key = `${contact.id}_profile_card_bg`;
        await db.saveImage(key, file);

        if (!contact.socialProfile) contact.socialProfile = {}; // 安全检查
        contact.socialProfile.bgImageKey = key;

        saveAppData();
        renderAiProfileCard(contact); // 重新渲染以显示新图
        showToast('背景已更换', 'success');
    });

    // ================================================================
            // 只有在确认拖拽后，才真正移动按钮
    // ================================================================

    // ================================================================
    // 【【【全新重构】QQ风格用户资料卡逻辑】】】
    // ================================================================

    let tempUserTags = [];

    function getDefaultUserAvatarUrl() {
        return 'https://i.postimg.cc/cLPP10Vm/4.jpg';
    }

    function ensureGlobalUserProfileForCard() {
        if (!appData.globalUserProfile || typeof appData.globalUserProfile !== 'object') {
            appData.globalUserProfile = {};
        }
        const user = appData.globalUserProfile;
        if (!user.name) user.name = '默认昵称';
        if (!user.avatarKey) user.avatarKey = 'global_user_avatar';
        if (!user.signature) user.signature = '';
        if (!Array.isArray(user.tags)) user.tags = [];
        if (!user.status) user.status = '在线';
        if (!user.backgroundKey) user.backgroundKey = null;
        return user;
    }

    function revokeProfileObjectUrl(element, datasetKey) {
        if (!element || !element.dataset || !element.dataset[datasetKey]) return;
        try {
            URL.revokeObjectURL(element.dataset[datasetKey]);
        } catch (e) { }
        delete element.dataset[datasetKey];
    }

    function setProfileImageElement(img, blob, fallbackUrl) {
        if (!img) return;
        revokeProfileObjectUrl(img, 'profileObjectUrl');
        if (blob) {
            const url = URL.createObjectURL(blob);
            img.src = url;
            img.dataset.profileObjectUrl = url;
        } else {
            img.src = fallbackUrl;
        }
    }

    function setProfileHeaderBackground(header, blob) {
        if (!header) return;
        revokeProfileObjectUrl(header, 'profileBgObjectUrl');
        header.style.backgroundSize = 'cover';
        header.style.backgroundPosition = 'center';
        header.style.backgroundRepeat = 'no-repeat';
        if (blob) {
            const url = URL.createObjectURL(blob);
            header.style.backgroundImage = `url(${url})`;
            header.dataset.profileBgObjectUrl = url;
        } else {
            header.style.backgroundImage = 'none';
            header.style.backgroundColor = '#ccc';
        }
    }

    function loadImageForCrop(file) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            const url = URL.createObjectURL(file);
            img.onload = () => {
                URL.revokeObjectURL(url);
                resolve(img);
            };
            img.onerror = () => {
                URL.revokeObjectURL(url);
                reject(new Error('图片加载失败'));
            };
            img.src = url;
        });
    }

    function createSquareAvatarBlobFromImage(img, crop, size = 512) {
        return new Promise((resolve, reject) => {
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(
                img,
                crop.x,
                crop.y,
                crop.size,
                crop.size,
                0,
                0,
                size,
                size
            );
            canvas.toBlob((blob) => {
                if (blob) resolve(blob);
                else reject(new Error('头像裁剪失败'));
            }, 'image/jpeg', 0.9);
        });
    }

    async function createCenteredSquareAvatarBlob(file, size = 512) {
        const img = await loadImageForCrop(file);
        const cropSize = Math.min(img.naturalWidth, img.naturalHeight);
        return createSquareAvatarBlobFromImage(img, {
            x: Math.max(0, (img.naturalWidth - cropSize) / 2),
            y: Math.max(0, (img.naturalHeight - cropSize) / 2),
            size: cropSize
        }, size);
    }

    async function openAvatarCropper(file) {
        const img = await loadImageForCrop(file);
        const minImageSide = Math.min(img.naturalWidth, img.naturalHeight);
        let cropSize = minImageSide;
        let cropX = Math.max(0, (img.naturalWidth - cropSize) / 2);
        let cropY = Math.max(0, (img.naturalHeight - cropSize) / 2);
        let isDragging = false;
        let dragStart = null;
        let previewUrl = '';

        return new Promise((resolve, reject) => {
            const overlay = document.createElement('div');
            overlay.className = 'avatar-cropper-overlay';

            const modal = document.createElement('div');
            modal.className = 'avatar-cropper-modal';

            const title = document.createElement('h3');
            title.textContent = '裁剪头像';

            const stage = document.createElement('div');
            stage.className = 'avatar-cropper-stage';

            const canvas = document.createElement('canvas');
            canvas.width = 280;
            canvas.height = 280;
            stage.appendChild(canvas);

            const tip = document.createElement('p');
            tip.className = 'avatar-cropper-tip';
            tip.textContent = '拖动图片选区，缩放后保存为正方形头像';

            const slider = document.createElement('input');
            slider.type = 'range';
            slider.min = '0';
            slider.max = '100';
            slider.value = '0';
            slider.className = 'avatar-cropper-slider';

            const actions = document.createElement('div');
            actions.className = 'avatar-cropper-actions';

            const cancelBtn = document.createElement('button');
            cancelBtn.type = 'button';
            cancelBtn.className = 'avatar-cropper-btn avatar-cropper-btn-secondary';
            cancelBtn.textContent = '取消';

            const confirmBtn = document.createElement('button');
            confirmBtn.type = 'button';
            confirmBtn.className = 'avatar-cropper-btn avatar-cropper-btn-primary';
            confirmBtn.textContent = '保存头像';

            actions.append(cancelBtn, confirmBtn);
            modal.append(title, stage, tip, slider, actions);
            overlay.appendChild(modal);
            document.body.appendChild(overlay);

            const ctx = canvas.getContext('2d');
            const stageSize = canvas.width;

            const cleanup = () => {
                if (previewUrl) URL.revokeObjectURL(previewUrl);
                window.removeEventListener('mousemove', moveDrag);
                window.removeEventListener('mouseup', endDrag);
                window.removeEventListener('touchmove', moveDrag);
                window.removeEventListener('touchend', endDrag);
                overlay.remove();
            };

            const clampCrop = () => {
                cropSize = Math.max(1, Math.min(minImageSide, cropSize));
                cropX = Math.max(0, Math.min(img.naturalWidth - cropSize, cropX));
                cropY = Math.max(0, Math.min(img.naturalHeight - cropSize, cropY));
            };

            const render = () => {
                clampCrop();
                ctx.clearRect(0, 0, stageSize, stageSize);
                ctx.fillStyle = '#111';
                ctx.fillRect(0, 0, stageSize, stageSize);
                ctx.drawImage(img, cropX, cropY, cropSize, cropSize, 0, 0, stageSize, stageSize);

                ctx.save();
                ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
                ctx.beginPath();
                ctx.rect(0, 0, stageSize, stageSize);
                ctx.arc(stageSize / 2, stageSize / 2, stageSize / 2 - 2, 0, Math.PI * 2, true);
                ctx.fill('evenodd');
                ctx.restore();

                ctx.strokeStyle = 'rgba(255, 255, 255, 0.92)';
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.arc(stageSize / 2, stageSize / 2, stageSize / 2 - 3, 0, Math.PI * 2);
                ctx.stroke();
            };

            const getPoint = (event) => {
                const source = event.touches && event.touches[0] ? event.touches[0] : event;
                const rect = canvas.getBoundingClientRect();
                return {
                    x: source.clientX - rect.left,
                    y: source.clientY - rect.top
                };
            };

            const startDrag = (event) => {
                event.preventDefault();
                isDragging = true;
                dragStart = {
                    point: getPoint(event),
                    cropX,
                    cropY
                };
            };

            const moveDrag = (event) => {
                if (!isDragging || !dragStart) return;
                event.preventDefault();
                const point = getPoint(event);
                const scale = cropSize / stageSize;
                cropX = dragStart.cropX - (point.x - dragStart.point.x) * scale;
                cropY = dragStart.cropY - (point.y - dragStart.point.y) * scale;
                render();
            };

            const endDrag = () => {
                isDragging = false;
                dragStart = null;
            };

            slider.addEventListener('input', () => {
                const oldSize = cropSize;
                const zoom = Number(slider.value) / 100;
                cropSize = minImageSide * (1 - zoom * 0.75);
                const centerX = cropX + oldSize / 2;
                const centerY = cropY + oldSize / 2;
                cropX = centerX - cropSize / 2;
                cropY = centerY - cropSize / 2;
                render();
            });

            canvas.addEventListener('mousedown', startDrag);
            window.addEventListener('mousemove', moveDrag);
            window.addEventListener('mouseup', endDrag);
            canvas.addEventListener('touchstart', startDrag, { passive: false });
            window.addEventListener('touchmove', moveDrag, { passive: false });
            window.addEventListener('touchend', endDrag);

            cancelBtn.addEventListener('click', () => {
                cleanup();
                resolve(null);
            });

            confirmBtn.addEventListener('click', async () => {
                confirmBtn.disabled = true;
                confirmBtn.textContent = '保存中...';
                try {
                    const blob = await createSquareAvatarBlobFromImage(img, { x: cropX, y: cropY, size: cropSize });
                    cleanup();
                    resolve(blob);
                } catch (error) {
                    cleanup();
                    reject(error);
                }
            });

            render();
        });
    }

    async function refreshUserProfileImages(modal = document.getElementById('user-profile-card-modal')) {
        const user = ensureGlobalUserProfileForCard();
        const avatarImg = modal?.querySelector('#user-profile-avatar') || document.getElementById('user-profile-avatar');
        const header = modal?.querySelector('#user-profile-header') || document.getElementById('user-profile-header');

        try {
            const avatarBlob = user.avatarKey ? await db.getImage(user.avatarKey) : null;
            setProfileImageElement(avatarImg, avatarBlob, getDefaultUserAvatarUrl());
        } catch (e) {
            setProfileImageElement(avatarImg, null, getDefaultUserAvatarUrl());
        }

        try {
            const bgBlob = user.backgroundKey ? await db.getImage(user.backgroundKey) : null;
            setProfileHeaderBackground(header, bgBlob || null);
        } catch (e) {
            setProfileHeaderBackground(header, null);
        }
    }

    async function setUserProfileAvatarFromFile(file, modal = document.getElementById('user-profile-card-modal')) {
        if (!file) return;
        const user = ensureGlobalUserProfileForCard();
        const key = user.avatarKey || 'global_user_avatar';
        await db.saveImage(key, file);
        user.avatarKey = key;
        saveAppData();

        const avatarImg = modal?.querySelector('#user-profile-avatar') || document.getElementById('user-profile-avatar');
        setProfileImageElement(avatarImg, file, getDefaultUserAvatarUrl());
        if (typeof renderMainHeader === 'function') await renderMainHeader();
    }

    async function setUserProfileBackgroundFromFile(file, modal = document.getElementById('user-profile-card-modal')) {
        if (!file) return;
        const user = ensureGlobalUserProfileForCard();
        const oldKey = user.backgroundKey;
        const key = `global_user_bg_${Date.now()}`;
        await db.saveImage(key, file);
        user.backgroundKey = key;
        saveAppData();

        if (oldKey && oldKey !== key) {
            try {
                await db.deleteImage(oldKey);
            } catch (e) {
                console.warn('清理旧用户资料背景失败:', e);
            }
        }

        const header = modal?.querySelector('#user-profile-header') || document.getElementById('user-profile-header');
        setProfileHeaderBackground(header, file);
    }

    function updateUserStatusDisplayInModal(modal, statusText) {
        const display = modal?.querySelector('#user-status-display') || document.getElementById('user-status-display');
        if (!display) return;
        const dot = display.querySelector('.status-dot');
        const text = display.querySelector('.status-text');
        if (text) text.textContent = statusText || '在线';
        if (dot) dot.style.backgroundColor = String(statusText || '').includes('隐身') || String(statusText || '').includes('离线') ? '#ccc' : '#4CAF50';
    }

    function hideUserProfileStatusPopup(modal) {
        const popup = modal?.querySelector('#user-status-popup') || document.getElementById('user-status-popup');
        if (!popup) return;
        popup.classList.remove('show');
        window.setTimeout(() => {
            if (!popup.classList.contains('show')) popup.classList.add('hidden');
        }, 250);
    }

    function showUserProfileStatusPopup(modal) {
        const popup = modal?.querySelector('#user-status-popup') || document.getElementById('user-status-popup');
        if (!popup) return;
        popup.classList.remove('hidden');
        window.requestAnimationFrame(() => popup.classList.add('show'));
    }

    function closeUserProfileCardModal(modal = document.getElementById('user-profile-card-modal')) {
        if (!modal) return;
        modal.classList.add('hidden');
        hideUserProfileStatusPopup(modal);
    }

    async function saveUserProfileCardFromModal(modal = document.getElementById('user-profile-card-modal')) {
        const user = ensureGlobalUserProfileForCard();
        const nameInput = modal?.querySelector('#user-profile-nickname') || document.getElementById('user-profile-nickname');
        const signatureInput = modal?.querySelector('#user-profile-signature') || document.getElementById('user-profile-signature');
        const statusText = modal?.querySelector('#user-status-display .status-text') || document.querySelector('#user-status-display .status-text');
        const newName = String(nameInput?.value || '').trim();
        if (!newName) {
            showToast('昵称不能为空', 'error');
            return;
        }

        user.name = newName;
        user.status = statusText?.textContent || '在线';
        user.signature = String(signatureInput?.value || '').trim();
        user.tags = [...tempUserTags];

        saveAppData();
        if (typeof renderMainHeader === 'function') await renderMainHeader();
        closeUserProfileCardModal(modal);
        showToast('资料已保存', 'success');
    }

    function bindUserProfileCardModal(modal = document.getElementById('user-profile-card-modal')) {
        if (!modal) return null;
        if (modal.dataset.userProfileCardBound === '1') return modal;
        modal.dataset.userProfileCardBound = '1';

        const bgInput = modal.querySelector('#user-profile-bg-upload');
        const avatarInput = modal.querySelector('#user-profile-avatar-upload');

        if (bgInput) {
            bgInput.onchange = async (e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                try {
                    await setUserProfileBackgroundFromFile(file, modal);
                    showToast('背景已更换', 'success');
                } catch (err) {
                    console.error('用户资料背景上传失败:', err);
                    showToast('背景上传失败，请稍后再试', 'error');
                } finally {
                    e.target.value = '';
                }
            };
        }

        if (avatarInput) {
            avatarInput.onchange = async (e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                try {
                    const croppedBlob = await openAvatarCropper(file);
                    if (!croppedBlob) return;
                    await setUserProfileAvatarFromFile(croppedBlob, modal);
                    showToast('头像已更换', 'success');
                } catch (err) {
                    console.error('用户资料头像上传失败:', err);
                    showToast('头像上传失败，请稍后再试', 'error');
                } finally {
                    e.target.value = '';
                }
            };
        }

        modal.addEventListener('click', async (e) => {
            const target = e.target;

            if (target === modal) {
                closeUserProfileCardModal(modal);
                return;
            }

            if (target.closest('#close-user-profile-card-btn')) {
                closeUserProfileCardModal(modal);
                return;
            }

            if (target.closest('#save-user-profile-btn')) {
                await saveUserProfileCardFromModal(modal);
                return;
            }

            if (target.closest('#user-profile-avatar-container')) {
                avatarInput?.click();
                return;
            }

            if (target.closest('#user-profile-header') && !target.closest('.qq-avatar-wrapper')) {
                bgInput?.click();
                return;
            }

            if (target.closest('#user-status-trigger')) {
                showUserProfileStatusPopup(modal);
                return;
            }

            const statusItem = target.closest('.qq-status-item');
            if (statusItem) {
                updateUserStatusDisplayInModal(modal, statusItem.dataset.val || '在线');
                hideUserProfileStatusPopup(modal);
                return;
            }

            if (target.closest('#confirm-custom-status')) {
                const input = modal.querySelector('#custom-status-input');
                const val = String(input?.value || '').trim();
                if (val) {
                    updateUserStatusDisplayInModal(modal, val);
                    hideUserProfileStatusPopup(modal);
                } else {
                    showToast('请输入状态内容', 'info');
                }
                return;
            }

            if (target.closest('#add-user-tag-btn')) {
                addUserTag();
                return;
            }

            const deleteTag = target.closest('.qq-tag-delete');
            if (deleteTag) {
                const tagItem = deleteTag.closest('.qq-tag-item');
                const index = Number.parseInt(tagItem?.dataset.index || '-1', 10);
                if (index >= 0) {
                    tempUserTags.splice(index, 1);
                    renderUserTags();
                }
                return;
            }

            if (!target.closest('#user-status-trigger') && !target.closest('#user-status-popup')) {
                hideUserProfileStatusPopup(modal);
            }
        });

        const tagInput = modal.querySelector('#user-tag-input');
        if (tagInput) {
            tagInput.onkeydown = (e) => {
                if (e.key === 'Enter') addUserTag();
            };
        }

        modal.querySelectorAll('input, textarea').forEach(input => {
            input.addEventListener('click', (e) => {
                e.stopPropagation();
                input.focus();
            });
        });

        return modal;
    }

    async function openUserProfileCard() {
        const user = ensureGlobalUserProfileForCard();
        const modal = bindUserProfileCardModal(document.getElementById('user-profile-card-modal'));
        if (!modal) {
            showToast('用户资料卡未加载，请刷新后再试', 'error');
            return;
        }

        if (typeof closeSideMenu === 'function') {
            closeSideMenu();
        }

                // 1. 保存弹窗引用
        modal.querySelector('#user-profile-nickname').value = user.name;
        modal.querySelector('#user-profile-signature').value = user.signature || '';

            // 2. 游戏历史回顾 (核心：信息差过滤)
        updateUserStatusDisplayInModal(modal, user.status || '在线');

        await refreshUserProfileImages(modal);

        // 5. 为“恢复默认”按钮绑定事件
        tempUserTags = [...(user.tags || [])];
        renderUserTags();

        modal.classList.remove('hidden');
    }

                    // 刷新高级设置UI
    function updateStatusDisplay(statusText) {
        updateUserStatusDisplayInModal(document.getElementById('user-profile-card-modal'), statusText);
    }

    function renderUserTags() {
        const container = document.getElementById('user-tags-container');
        container.innerHTML = '';

                // 1. 保存弹窗引用
        tempUserTags.forEach((tag, index) => {
            const span = document.createElement('span');
            span.className = 'qq-tag-item';
            span.dataset.index = index;

                    // 【核心新增】显示“+”号按钮
            span.innerHTML = `${tag} <span class="qq-tag-delete">脳</span>`;
            container.appendChild(span);
        });

                    // 2. 成功：移除加载弹窗
        const addBtn = document.createElement('div');
        addBtn.className = 'qq-tag-add-btn';

        // 【核心修改】给文字也加上 span class="qq-tag-add-text"
        addBtn.innerHTML = '<span class="qq-tag-add-symbol">+</span> <span class="qq-tag-add-text">添加标签</span>';

        addBtn.onclick = () => {
            const wrapper = document.getElementById('user-tag-input-wrapper');
            const input = document.getElementById('user-tag-input');
            wrapper.classList.remove('hidden');
            input.focus();
            addBtn.style.display = 'none';
        };
        container.appendChild(addBtn);
    }

            // 1. 绑定折叠按钮
    function addUserTag() {
        const input = document.getElementById('user-tag-input');
        const val = input.value.trim();
        if (val) {
            if (!tempUserTags.includes(val)) {
                tempUserTags.push(val);
                renderUserTags();
            } else {
                showToast('这个标签已经有了哦', 'info');
            }
            input.value = ''; // 清空输入框
        }

        // 【【【核心改造：将“点击”事件也纳入管理】】】
        document.getElementById('user-tag-input-wrapper').classList.add('hidden');
    }

            // 只有当“位移检测器”显示没有拖拽过时，才执行打开罗盘的动作
    async function saveUserProfileCard() {
        await saveUserProfileCardFromModal(document.getElementById('user-profile-card-modal'));
    }
    // ================================================================
    // 【【【全新：为电影院的聊天框和发送按钮绑定事件】】】
    // ================================================================

    const musicUploadModal = document.getElementById('music-upload-modal');
    const tabUploadNew = document.getElementById('tab-upload-new');
    const tabMyUploads = document.getElementById('tab-my-uploads');
    const panelUploadNew = document.getElementById('panel-upload-new');
    const panelMyUploads = document.getElementById('panel-my-uploads');

    // 1. 打开/关闭弹窗
