                // 【【【常规线下聊天模式指令 (保持不变)】】】
    function compressImageBlob(blob, quality = 0.5, maxWidth = 1024, forceType = null) {
        return new Promise((resolve, reject) => {
            if (!(blob instanceof Blob)) {
                return reject(new Error("传入的不是有效的图片文件"));
            }

                // 为了保险，我们重新从数据库抓取当前生效的图标（如果用户是在导出当前效果）
            // 如果 forceType 有值 (如 'image/jpeg')，就强制转格式。
            // 如果 forceType 是 null，就沿用图片原本的格式 (blob.type)。
            // 这样 PNG 就能保持 PNG (保留透明)，JPG 保持 JPG。
            const outputType = forceType ? forceType : blob.type;

            const img = new Image();
            let url;
            try {
                url = URL.createObjectURL(blob);
            } catch (e) {
                return reject(new Error("无法创建图片链接"));
            }

            img.src = url;

            img.onload = () => {
                URL.revokeObjectURL(url);
                let width = img.width;
                let height = img.height;

                if (width === 0 || height === 0) {
                    return reject(new Error("图片尺寸无效 (0x0)"));
                }

                if (width > maxWidth) {
                    height = Math.round(height * (maxWidth / width));
                    width = maxWidth;
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');

                // 只有当输出格式是 JPEG 时，才铺白底
                if (outputType === 'image/jpeg') {
                    ctx.fillStyle = '#FFFFFF';
                    ctx.fillRect(0, 0, width, height);
                }

                ctx.drawImage(img, 0, 0, width, height);

                canvas.toBlob((newBlob) => {
                    if (newBlob) resolve(newBlob);
                    else reject(new Error("Canvas 导出失败"));
                }, outputType, quality);
            };

            img.onerror = () => {
                URL.revokeObjectURL(url);
                reject(new Error("图片加载或解码失败"));
            };
        });
    }
    /**
     * 【全新】图片消化系统：将历史记录里的图片转化为文字描述，并删除原图
     * @param {object} contact - 当前角色
     */
    /**
     * 【全新 V4.2】图片消化系统 (Gemini 适配版 + 深度诊断)
     */
    async function transmuteImagesToText(contact) {
        if (!contact) return;

        const history = contact.isOfflineMode ?
            (contact.offlineStorylines.find(s => s.id === contact.activeOfflineStoryId)?.chatHistory || []) :
            contact.onlineChatHistory;

        // 1. 准备图片数据
        if (history.length <= 50) return;

        const oldMessages = history.slice(0, history.length - 50);

        const imagesToProcess = oldMessages.filter(msg =>
            msg.role === 'user' &&
            msg.type === 'image' &&
            msg.imageId &&
            !msg.isDigested
        );

        if (imagesToProcess.length === 0) return;

        console.log(`[图片消化] 启动！待处理: ${imagesToProcess.length} 张`);

        for (const msg of imagesToProcess) {
            try {
                // A. 读取原图
                const originalBlob = await db.getImage(msg.imageId);
                if (!originalBlob) {
                    console.warn(`[图片消化] 原图丢失: ${msg.imageId}`);
                    continue;
                }

                // 确保 Base64 格式正确
                let base64FullString = await new Promise((resolve) => {
                    const reader = new FileReader();
                    reader.onloadend = () => resolve(reader.result);
                    reader.readAsDataURL(originalBlob);
                });

                // B. 请求 AI 描述 (针对 Gemini 优化的 Prompt)
                // Gemini 有时候对 "describe" 比较敏感，用 "analyze" 或 "caption" 会好一些
                const prompt = "Analyze this image and provide a brief visual caption in Chinese. 客观描述图片画面内容（物体、场景、颜色），不要发表观点，不要加前缀。";

                let requestUrl = appData.appSettings.apiUrl;
                if (!requestUrl.endsWith('/chat/completions')) { requestUrl = requestUrl.endsWith('/') ? requestUrl + 'chat/completions' : requestUrl + '/chat/completions'; }

                const response = await fetch(requestUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                    body: JSON.stringify({
                        model: appData.appSettings.apiModel,
                        messages: [
                            {
                                role: "user", content: [
                                    { type: "text", text: prompt },
                                    { type: "image_url", image_url: { url: base64FullString } }
                                ]
                            }
                        ],
                        temperature: 0.5 // 降低温度，让描述更客观，减少被安全拦截的概率
                    })
                });

                if (response.ok) {
                    const data = await response.json();
                    const choice = data.choices ? data.choices[0] : null;
                    let description = choice && choice.message ? choice.message.content : "";

                // ▲▲▲▲▲ 植入完毕 ▲▲▲▲▲
                    if (!description || description.trim().length < 1) {
                        console.group(`[图片消化] ⚠️ 收到空回复，开始诊断...`);
                        console.log("完整 API 响应:", JSON.stringify(data, null, 2));

                        if (choice && choice.finish_reason === 'content_filter') {
                            console.error(">> 原因: 触发了内容安全过滤 (Safety Filter)。");
                        } else if (choice && choice.finish_reason === 'length') {
                            console.error(">> 原因: Token 长度不足。");
                        } else {
                            console.error(">> 原因: 未知。可能是代理对 Gemini 格式转换的问题。");
                        }
                        console.groupEnd();

                        continue; // 跳过本次处理，保留原图
                    }

                    description = description.trim();

                    // C. 制作高清缩略图 (500px, 0.6质量)
                    const thumbnailBlob = await compressImageBlob(originalBlob, 0.6, 500);

                    // D. 覆盖保存
                    await db.saveImage(msg.imageId, thumbnailBlob);

                    // 成功后移除
                    msg.isDigested = true;
                    msg.aiDescription = description;

                    // E. DOM 实时手术
                    const msgRow = document.querySelector(`.message-row[data-message-id="${msg.id}"]`);
                    if (msgRow) {
                        const imgEl = msgRow.querySelector('img');
                        if (imgEl) {
                            imgEl.style.opacity = "0.9";
                            imgEl.style.cursor = "help";
                            const newUrl = URL.createObjectURL(thumbnailBlob);
                            imgEl.src = newUrl;

    // ▲▲▲▲▲ 总控制器植入完毕 ▲▲▲▲▲
                            const newImgEl = imgEl.cloneNode(true);
                            imgEl.parentNode.replaceChild(newImgEl, imgEl);

                            newImgEl.onclick = (e) => {
                                e.stopPropagation();
                                showCustomAlert('图片记忆', `这张原图已过期 (显示为缩略图)。\n\nTA当时的记忆是：\n“${description}”`);
                            };
                        }
                    }

                } else {
                    const errText = await response.text();
                    console.error(`[图片消化] API 请求错误 (${response.status}): ${errText}`);
                }
            } catch (e) {
                console.error("[图片消化] 异常:", e);
            }
        }

        saveAppData();

    }

