                        // 执行归档
    async function saveAddress() {
        const charSelect = document.getElementById('address-char-select');
        const contactId = charSelect.value;
        const contact = appData.aiContacts.find(c => c.id == contactId);

        if (!contact) return;

        const name = document.getElementById('addr-name-input').value.trim();
        const phone = document.getElementById('addr-phone-input').value.trim();
        const address = document.getElementById('addr-detail-input').value.trim();
        const tagInput = document.querySelector('input[name="addr-tag"]:checked');
        const tag = tagInput ? tagInput.value : '家';

        if (!name || !phone || !address) {
            showToast('请填写完整信息', 'error');
            return;
        }

        // --- 1. 获取 AI 当前的行程地点 ---
        const now = getContactNowDate(contact);
        const currentMinutes = now.getHours() * 60 + now.getMinutes();
        const timeToMinutes = (t) => {
            if (!t) return 0;
            const [h, m] = t.split(/[:：]/).map(Number);
            return h * 60 + m;
        };

        let currentScheduleLocation = "未知/移动中";
        let currentActivity = "未知活动";

        if (contact.dailyPlan && contact.dailyPlan.length > 0) {
            const currentEvent = getCurrentDailyPlanItem(contact, now);

            if (currentEvent) {
                currentScheduleLocation = currentEvent.location;
                currentActivity = currentEvent.activity;
            }
        }

        // --- 2. 获取最近 50 条聊天记录 ---
        const chatLog = resolvePromptDialogueText(contact, {
            limit: 50,
            userLabel: '用户',
            assistantLabel: 'AI',
            mediaPlaceholder: '[多媒体]',
            fallback: '（暂无聊天记录）'
        });

        // --- 3. 呼叫 AI 审计员 ---
        const saveBtn = document.getElementById('save-address-btn');
        const originalBtnText = saveBtn.textContent;
        saveBtn.disabled = true;
        saveBtn.textContent = "AI 正在核对行程与记录...";

        try {
                        // 如果没完结，强制保护！
            let targetUrl, targetKey, targetModel;
            const secApi = appData.appSettings.secondaryApi1;

            if (secApi && secApi.url && secApi.key) {
                targetUrl = secApi.url; targetKey = secApi.key; targetModel = secApi.model || 'gpt-3.5-turbo';
            } else {
                targetUrl = appData.appSettings.apiUrl; targetKey = appData.appSettings.apiKey; targetModel = appData.appSettings.apiModel;
            }
            if (!targetUrl.endsWith('/chat/completions')) targetUrl += (targetUrl.endsWith('/') ? '' : '/') + 'chat/completions';

            const auditPrompt = `
# 任务: 地址真实性严格审计
用户正在尝试保存一个关于你的地址信息。你需要扮演“审计员”，判断这个地址是否准确。

## 待审核数据 (用户填写)
- 地址: "${address}"
- 电话: "${phone}"
- 标签: "${tag}" (用户认为这是你的"${tag}")

## 审计依据 1: 你当前的行程 (绝对事实)
- 你现在正在: "${currentScheduleLocation}" 做 "${currentActivity}"。
- **判断逻辑**: 如果用户填写的标签是“${tag}”，那么"${address}"这个地址是否与你当前的地点"${currentScheduleLocation}"相符？
    - *允许模糊匹配*: 如果你在“帝都大厦”，用户填“帝都大厦3层”，算对。
    - *拒绝明显冲突*: 如果你在“家”，用户填“公司地址”，算错。

## 审计依据 2: 最近50条聊天记录
\`\`\`
${chatLog}
\`\`\`
- **判断逻辑**: 检查聊天记录，你是否告诉过用户你的地址或电话？用户填写的与你说的是否一致？

## 【【【最终判决逻辑】】】
请综合以上两点。
1. 如果聊天记录里**明确提到了**地址/电话，且用户填对了 -> **通过**。
2. 如果聊天记录没提，但用户填写的地址与你**当前行程所在地**高度一致（说明用户知道你在哪） -> **通过**。
3. 如果聊天记录没提，且与你当前所在地完全不沾边（瞎填） -> **拒绝**。

## 输出要求 (JSON)
{
  "pass": true/false,
  "reason": "如果不通过，请用第三人称的口吻简短说明原因（例如：'TA现在的定位明明在xx，你填的这是哪？' 或 '他好像没告诉过你这个电话吧？'）。如果通过，留空。"
}
`;
            const response = await fetch(targetUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${targetKey}` },
                body: JSON.stringify({ model: targetModel, messages: [{ role: 'user', content: auditPrompt }], temperature: 0.1 })
            });
            const data = await response.json();
            const jsonMatch = data.choices[0].message.content.match(/\{[\s\S]*\}/);
            if (!jsonMatch) throw new Error("校验失败");

            const result = JSON.parse(jsonMatch[0]);

            if (result.pass === true) {
    // --- 事件绑定 ---
                if (!contact.foodProfile.savedAddresses) contact.foodProfile.savedAddresses = [];
                const newAddr = { name, phone, address, tag, fullAddress: `${name} ${phone} ${address}` };

                if (currentEditingAddressIndex !== null) {
                    contact.foodProfile.savedAddresses[currentEditingAddressIndex] = newAddr;
                    showToast('地址修改成功！', 'success');
                    currentEditingAddressIndex = null;
                } else {
                    contact.foodProfile.savedAddresses.push(newAddr);
                    showToast('地址保存成功！', 'success');
                }
                contact.foodProfile.address = newAddr.fullAddress;
                saveAppData();
                loadAddressList(contactId);
                updateFoodAddressBar(contact);
                resetAddressInputs();
            } else {
    // --- 监控系统逻辑 ---
                showCustomAlert('保存失败', result.reason || "地址信息不符。");
            }

        } catch (e) {
            console.error(e);
            showToast("校验服务出错，请检查网络", "error");
        } finally {
            saveBtn.disabled = false;
            saveBtn.textContent = "保存并使用";
        }
    }


