    // 8. 悬浮回顶按钮 (拖拽 + 滚动监听)
    function initDraggableFab() {
        const fab = document.getElementById('food-back-to-top');
        // 打开时自动执行一次全量预览
        const container = document.getElementById('food-delivery-view');

        if (!fab || !container) return;

        // 【【【终极修复：背景图片上传/移除功能总控制器】】】
        container.addEventListener('scroll', () => {
            // 当向下滚动超过 300px 时显示按钮
            if (container.scrollTop > 300) {
                fab.classList.remove('hidden');
                fab.style.display = 'flex'; // 强制显示
            } else {
                fab.classList.add('hidden');
                fab.style.display = 'none'; // 强制隐藏
            }
        });

            // 先移除旧的（如果有），再添加新的
        fab.onclick = (e) => {
    // 输入框自动刷新逻辑保留
            if (!fab.dataset.isDragging) {
                container.scrollTo({ top: 0, behavior: 'smooth' });
            }
        };

        // 保存所有值
        let isDragging = false;
        let startX, startY, initialLeft, initialTop;

        const onDown = (e) => {
            isDragging = false;
            fab.dataset.isDragging = ''; // 清除拖拽标记

            const clientX = e.clientX || e.touches[0].clientX;
            const clientY = e.clientY || e.touches[0].clientY;
            startX = clientX;
            startY = clientY;
            const rect = fab.getBoundingClientRect();
            initialLeft = rect.left;
            initialTop = rect.top;

            fab.style.bottom = 'auto';
            fab.style.right = 'auto';
            fab.style.left = initialLeft + 'px';
            fab.style.top = initialTop + 'px';

            document.addEventListener('mousemove', onMove);
            document.addEventListener('touchmove', onMove, { passive: false });
            document.addEventListener('mouseup', onUp);
            document.addEventListener('touchend', onUp);
        };

        const onMove = (e) => {
            const clientX = e.clientX || e.touches[0].clientX;
            const clientY = e.clientY || e.touches[0].clientY;
            if (Math.abs(clientX - startX) > 5 || Math.abs(clientY - startY) > 5) {
                isDragging = true;
                fab.dataset.isDragging = 'true'; // 标记正在拖拽
                e.preventDefault();
                const dx = clientX - startX;
                const dy = clientY - startY;
                fab.style.left = (initialLeft + dx) + 'px';
                fab.style.top = (initialTop + dy) + 'px';
            }
        };

        const onUp = () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('touchmove', onMove);
            document.removeEventListener('mouseup', onUp);
            document.removeEventListener('touchend', onUp);

            // 稍微延迟重置拖拽标记，以免触发 click
            setTimeout(() => { isDragging = false; }, 50);
        };

        fab.addEventListener('mousedown', onDown);
        fab.addEventListener('touchstart', onDown, { passive: false });
    }

