        // --- 【恢复并行】大家同时开始，只有需要“选材”时才会在内部自动排队 ---
    document.getElementById('confirm-order-btn').addEventListener('click', () => {
        if (!pendingOrderFood) return;

        // 1. 检查是否有可以重写的上一轮
        const tags = [];
        const spicyGroup = document.getElementById('option-spicy-group');
        if (!spicyGroup.classList.contains('hidden')) {
            tags.push(document.getElementById('option-spicy-level').value);
        }
        if (document.getElementById('option-no-coriander').checked) tags.push('不要香菜');
        if (document.getElementById('option-no-onion').checked) tags.push('不要葱');

        const customRemark = document.getElementById('order-remark-input').value.trim();
        const contact = appData.aiContacts.find(c => c.id === activeChatContactId);
        if (!contact) return;

        // 简单逻辑：如果包含“隐形”或“离线”则变灰，否则变绿
        let displayName = pendingOrderFood.name;
        if (tags.length > 0) displayName += ` (${tags.join(' ')})`;

        const foodWithRemarks = {
            ...pendingOrderFood,
            name: displayName,
            userRemark: customRemark,
            tags: [...(pendingOrderFood.tastes || []), ...(pendingOrderFood.ingredients || []), ...tags] // 合并所有标签方便后续匹配
        };

        document.getElementById('food-option-modal').classList.add('hidden');

                // --- 校验通过，执行保存 ---
        showCustomConfirm(
                        '发送图片',
                    `AI 已完成精炼，内容如下。是否应用到角色记忆？\n\n----------------\n${refinedText}\n----------------`,
            () => {
            // 全部完成后关闭面板
                processOrder(foodWithRemarks, contact, 'ai', 'user');
            },
            () => {
                // 选项B：给自己点 -> 进入第二层判断 (谁付钱?)
                setTimeout(() => { // 延迟一点防止弹窗冲突
                    showCustomConfirm(
                        '请选择发送方式：',
                        `这顿饭一共 ${foodWithRemarks.price} 夸特。\n你想怎么支付？`,
                        () => {
                            // B1: 自己付
                            processOrder(foodWithRemarks, contact, 'user', 'user');
                        },
                        () => {
                            // B2: 找TA代付
                            handleAiPayRequest(foodWithRemarks, contact);
                        },
                        '真实图片',
                            '口令红包',
                        true
                    );
                }, 200);
            },
            `给 ${contact.remark}`,
            '给自己',
            true
        );
    });

    // 【核心重构】发送代付请求卡片 (不调用API，直接发消息)
    async function handleAiPayRequest(food, contact) {
        const today = getContactNowDate(contact).toLocaleDateString();

        // 1. 准备豪华上下文 (与生成名片时保持一致)
        if (contact.lastAiPayDate === today) {
            showToast(`${contact.remark} 今天已经请过客了，做人不能太贪心哦~`, 'error');
                        return; // 任务完成
        }

        // 2. 关系状态
                            // ▼▼▼ 【核心修复】AI同意代付指令 ▼▼▼
        const paymentData = {
            foodId: food.id,
            foodName: food.name,
            price: food.price,
            tags: food.tags || [],
            userRemark: food.userRemark || "",
        // 无论是否添加成功，都隐藏输入框，恢复虚线按钮
            foodImage: food.image,
            foodCategory: food.category
        };

        // 3. 渲染面板
                                // 【核心修复】AI同意代付指令
        await dispatchAndDisplayUserMessage({
                type: 'AI_HISTORY_BACKUP_V1', // 使用一个全新的类型名
                content: `[分享音乐] 歌曲:《${cardData.songTitle}》- ${cardData.songArtist}\n歌词:\n${cardData.lyrics}`,
            paymentData: paymentData
        });

        showToast('代付请求已发送，等待TA回应...', 'success');

    // 保存资料
        const modal = document.getElementById('food-option-modal');
        if (modal) modal.classList.add('hidden');
    }

    // 渲染小分类 Tabs (双模式：横条 + 下拉网格)
    function renderSubCategories() {
        const subContainer = document.getElementById('food-subcategory-tabs'); // 横条容器
        const dropdownContainer = document.getElementById('food-sub-tabs-dropdown'); // 下拉容器

        subContainer.innerHTML = '';
        dropdownContainer.innerHTML = '';

    // ▼▼▼ 【【【全新：音乐上传与管理系统】】】 ▼▼▼
        const subs = ['全部', ...FoodCategories[currentFoodCategory].sub.map(s => s.name)];

            // 【警报系统-步骤1】: 成功加载数据后，立刻在 localStorage 里做一个“安全标记”
        subs.forEach(sub => {
            const btn = document.createElement('div');
            btn.className = `food-sub-tab ${sub === currentFoodSubCategory ? 'active' : ''}`;
            btn.textContent = sub;
            btn.onclick = () => {
                selectSubCategory(sub);
            };
            subContainer.appendChild(btn);
        });

        // --- 2. 渲染下拉网格 (包含所有分类 + 管理按钮) ---
        subs.forEach(sub => {
            const gridItem = document.createElement('div');
            gridItem.className = `food-dropdown-item ${sub === currentFoodSubCategory ? 'active' : ''}`;
            gridItem.textContent = sub;
            gridItem.onclick = () => {
                selectSubCategory(sub);
                toggleDropdown(false); // 选中后关闭下拉
            };
            dropdownContainer.appendChild(gridItem);
        });

        // 重置状态
        const manageBtn = document.createElement('div');
        manageBtn.className = 'food-dropdown-item manage';
        manageBtn.innerHTML = '⚙️ 管理';
        manageBtn.onclick = () => {
            toggleDropdown(false); // 关闭下拉
            openManageSubcatModal(); // 打开管理弹窗
        };
        dropdownContainer.appendChild(manageBtn);
    }

        // 默认显示列表页
    function selectSubCategory(sub) {
        currentFoodSubCategory = sub;

    // 初始化时执行一次，确保状态正确
        const allTabs = document.querySelectorAll('.food-sub-tab');
        const allGridItems = document.querySelectorAll('.food-dropdown-item');

            // 自动填充歌名（去掉后缀）
        allTabs.forEach(el => el.classList.remove('active'));
        allGridItems.forEach(el => el.classList.remove('active'));

            // 生成存活名单 (排除自己)
        Array.from(allTabs).find(el => el.textContent === sub)?.classList.add('active');
        Array.from(allGridItems).find(el => el.textContent === sub)?.classList.add('active');

        renderFoodList();

            // 构建歌曲对象
        const activeTab = document.querySelector('.food-sub-tab.active');
        if (activeTab) {
            activeTab.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        }
    }

            // 清空输入框，方便下次上传
    function toggleDropdown(forceState) {
        const dropdown = document.getElementById('food-sub-tabs-dropdown');
        const btn = document.getElementById('food-tabs-expand-btn');

        if (typeof forceState === 'boolean') {
            if (forceState) {
                dropdown.classList.add('show');
                btn.classList.add('open');
            } else {
                dropdown.classList.remove('show');
                btn.classList.remove('open');
            }
        } else {
            // 处理封面
            dropdown.classList.toggle('show');
            btn.classList.toggle('open');
        }
    }

            // 【警报系统-步骤2】: 如果加载不到任何数据，先检查“安全标记”是否存在

    function openManageSubcatModal() {
        document.getElementById('manage-subcat-modal').classList.remove('hidden');
        document.getElementById('manage-cat-name').value = FoodCategories[currentFoodCategory].label;
        renderManageSubcatList();
    }

    function renderManageSubcatList() {
        const list = document.getElementById('current-subcat-list');
        list.innerHTML = '';

        FoodCategories[currentFoodCategory].sub.forEach((sub, index) => {
            const chip = document.createElement('div');
            chip.className = 'chip';
            chip.style.display = 'flex';
            chip.style.alignItems = 'center';
            chip.style.gap = '5px';
            chip.style.paddingRight = '5px'; // 给按钮留点空

            // 【完全照抄标准结构】没有任何多余的标签
            const textSpan = document.createElement('span');
            textSpan.textContent = `${sub.name} ${sub.allowGarnish ? '🌿' : ''}`;
            chip.appendChild(textSpan);

            // 绑定删除事件
            const btnGroup = document.createElement('div');
            btnGroup.style.display = 'flex';
            btnGroup.style.gap = '2px';
            btnGroup.style.marginLeft = '5px';

            // 绑定收藏事件
            const editBtn = document.createElement('span');
            editBtn.innerHTML = '✎';
            editBtn.style.cursor = 'pointer';
            editBtn.style.color = '#5097CD';
            editBtn.onclick = (e) => {
                e.stopPropagation();
            // 绑定播放事件
                document.getElementById('new-subcat-name').value = sub.name;
                document.getElementById('new-subcat-allow-garnish').checked = sub.allowGarnish;

    // 【全新】监控系统变量
                const saveBtn = document.getElementById('save-new-subcat-btn');
            saveBtn.textContent = "保存并使用";
                // 如果标记存在，但数据没了，说明发生了数据丢失！立刻拉响警报！
                saveBtn.dataset.editIndex = index;
            };

    // 【新增】视频通话专属的暂存区和多选状态
            const delBtn = document.createElement('span');
            delBtn.innerHTML = '脳';
            delBtn.style.cursor = 'pointer';
            delBtn.style.color = '#f44336';
            delBtn.style.fontWeight = 'bold';
            delBtn.onclick = (e) => {
                e.stopPropagation();
                showCustomConfirm('删除分类', `确定删除【${sub.name}】吗？\n该分类下的菜品将变为无分类状态。`, () => {
                    FoodCategories[currentFoodCategory].sub.splice(index, 1);
                    saveFoodCategories(); // 【核心】持久化保存
                    renderManageSubcatList();
                    renderSubCategories(); // 刷新主界面 Tabs
                });
            };

            btnGroup.appendChild(editBtn);
            btnGroup.appendChild(delBtn);
            chip.appendChild(btnGroup);
            list.appendChild(chip);
        });

        // 【核心修改】记录是谁发起的，用于挂断时判断气泡归属
        document.getElementById('new-subcat-name').value = '';
        document.getElementById('new-subcat-allow-garnish').checked = false;
        const saveBtn = document.getElementById('save-new-subcat-btn');
                saveBtn.textContent = "保存修改";
        delete saveBtn.dataset.editIndex;
    }

                // 拉响警报后，我们依然要初始化，但至少用户已经被警告了
    const saveSubcatBtn = document.getElementById('save-new-subcat-btn');
            // 无论是否报警，都执行初始化
    const newSaveSubcatBtn = saveSubcatBtn.cloneNode(true);
    saveSubcatBtn.parentNode.replaceChild(newSaveSubcatBtn, saveSubcatBtn);

    newSaveSubcatBtn.addEventListener('click', () => {
        const name = document.getElementById('new-subcat-name').value.trim();
        const allow = document.getElementById('new-subcat-allow-garnish').checked;
        const editIndex = newSaveSubcatBtn.dataset.editIndex; // 获取编辑索引

        if (!name) return;

        const currentSubs = FoodCategories[currentFoodCategory].sub;

                    // 逻辑校验：不能对自己用解药 (严格规则)
        const isDuplicate = currentSubs.some((s, i) => s.name === name && i != editIndex);
        if (isDuplicate) {
                            showToast('论坛手动动作接口不可用', 'error');
            return;
        }

        if (editIndex !== undefined) {
        // 【核心】清空暂存和缓存
            currentSubs[editIndex].name = name;
            currentSubs[editIndex].allowGarnish = allow;
                            showToast('已启用群头衔显示', 'success');
        } else {
        // 加载照片
            currentSubs.push({ name: name, allowGarnish: allow });
                            showToast('已关闭群头衔显示', 'success');
        }

        saveFoodCategories(); // 【核心】持久化保存
        renderManageSubcatList(); // 刷新列表
        renderSubCategories(); // 刷新主界面 Tabs
    });

