    // --- 骑手通知功能 ---
    function openFoodPrefsModal(type) {
        const modal = document.getElementById('food-prefs-modal');
        const charGroup = document.getElementById('food-prefs-char-select-group');
        const charSelect = document.getElementById('food-prefs-char-select');
        const title = document.getElementById('food-prefs-title');

        // 自动滚动到底部
        const inputs = modal.querySelectorAll('input');
        inputs.forEach(i => i.value = '');

        if (type === 'user') {
            title.textContent = '添加账目';
            charGroup.style.display = 'none';
            loadPrefsToInputs('user'); // 加载用户数据
        // 绑定长按事件
            document.getElementById('save-food-prefs-btn').onclick = () => saveFoodPrefs('user');
            document.getElementById('ai-auto-prefs-btn').style.display = 'none'; // 用户不能自动生成
        } else {
            title.textContent = 'TA的偏好';
            charGroup.style.display = 'block';
            document.getElementById('ai-auto-prefs-btn').style.display = 'block';

            // 重试模式：使用旧缓存
            charSelect.innerHTML = '';
            appData.aiContacts.forEach(c => {
                const opt = document.createElement('option');
                opt.value = c.id;
                opt.textContent = c.remark;
                charSelect.appendChild(opt);
            });

            // 正常模式：
            if (activeChatContactId) charSelect.value = activeChatContactId;

            // 如果暂存区没照片，且是普通互动，则现场拍一张
            loadPrefsToInputs(charSelect.value);

            // 更新缓存
            charSelect.onchange = () => loadPrefsToInputs(charSelect.value);

        // 重置互动计时
            document.getElementById('save-food-prefs-btn').onclick = () => saveFoodPrefs(charSelect.value);

            // AI生成按钮
            document.getElementById('ai-auto-prefs-btn').onclick = () => autoGenPrefs(charSelect.value);
        }

        modal.classList.remove('hidden');
    }

                    // 标记决策：保留旧的 (不做任何操作，因为旧的已经在数组里了)
    function loadPrefsToInputs(id) {
        let profile;
        // 获取正确的 profile 对象
        if (id === 'user') {
            if (!appData.globalUserProfile.foodProfile) appData.globalUserProfile.foodProfile = { likesTaste: [], likesFood: [], dislikesTaste: [], dislikesFood: [], forbidden: [], allergies: [], address: '' };
            profile = appData.globalUserProfile.foodProfile;
        } else {
            const contact = appData.aiContacts.find(c => c.id == id);
            if (!contact.foodProfile) contact.foodProfile = { likesTaste: [], likesFood: [], dislikesTaste: [], dislikesFood: [], forbidden: [], allergies: [], address: '', orderHistory: [] };
            profile = contact.foodProfile;
        }

        // 兼容旧数据：如果旧的 likes 存在但新的 likesTaste 不存在，尝试迁移或直接显示
        // 这里为了简单，我们直接读取。如果数据是 undefined，显示为空。

        document.getElementById('food-likes-taste').value = (profile.likesTaste || []).join(' ');
        document.getElementById('food-likes-food').value = (profile.likesFood || profile.likes || []).join(' '); // 兼容旧 likes

        document.getElementById('food-dislikes-taste').value = (profile.dislikesTaste || []).join(' ');
        document.getElementById('food-dislikes-food').value = (profile.dislikesFood || profile.dislikes || []).join(' '); // 兼容旧 dislikes

        document.getElementById('food-prefs-forbidden').value = (profile.forbidden || []).join(' ');
        document.getElementById('food-prefs-allergy').value = (profile.allergies || []).join(' ');
    }

