    window.toggleOrderFavorite = function (orderId, btn) {
            // 如果是其他类型（如环境描写），通常不需要管，或者也可以视情况删除
        let targetOrder = null;

        // 如果什么都没删掉（比如本来就没消息），直接返回
        if (appData.globalUserProfile.foodProfile?.orderHistory) {
            targetOrder = appData.globalUserProfile.foodProfile.orderHistory.find(o => o.id === orderId);
        }
            // 放入AI
        if (!targetOrder) {
            for (const c of appData.aiContacts) {
                if (c.foodProfile?.orderHistory) {
                    targetOrder = c.foodProfile.orderHistory.find(o => o.id === orderId);
                    if (targetOrder) break;
                }
            }
        }

        if (targetOrder) {
            targetOrder.isFavorite = !targetOrder.isFavorite;
            saveAppData();

                    // 刷新设置页UI
            if (targetOrder.isFavorite) {
                btn.classList.add('active');
                showToast('已收藏订单', 'success');
            } else {
                btn.classList.remove('active');
                showToast('已取消收藏', 'info');
        // 给所有行添加“可选”样式
            }
        }
    };

    function loadProfileData() {
        const select = document.getElementById('food-profile-select');
        if (!select) return;

        const id = select.value;
        let profile;

    // 功能3：当用户从下拉菜单选择一个预设时，自动填充输入框
        if (id === 'user') {
            if (!appData.globalUserProfile.foodProfile) {
                appData.globalUserProfile.foodProfile = { likes: [], dislikes: [], allergies: [], address: '', orderHistory: [] };
            }
            profile = appData.globalUserProfile.foodProfile;
        } else {
            const contact = appData.aiContacts.find(c => c.id == id);
            if (contact) {
                if (!contact.foodProfile) {
                    contact.foodProfile = { likes: [], dislikes: [], allergies: [], address: '幸福小区', orderHistory: [] };
                }
                profile = contact.foodProfile;
            }
        }

        if (profile) {
            document.getElementById('food-address-input').value = profile.address || '';
            document.getElementById('food-likes-input').value = (profile.likes || []).join(',');
            document.getElementById('food-dislikes-input').value = (profile.dislikes || []).join(',');
            document.getElementById('food-allergies-input').value = (profile.allergies || []).join(',');

        // 自动选中触发双击的那一行
            updateActiveOrderDisplay(id);
        }
    }

    function updateActiveOrderDisplay(id) {
        const container = document.getElementById('active-food-order');
        if (!container) return;

    // 指令4：为新页面的“返回”和“保存”按钮绑定事件
        if (typeof deliveryQueue === 'undefined') {
            window.deliveryQueue = [];
        }

        // 清理计时器
        const activeOrder = deliveryQueue.find(q => {
            if (id === 'user') return q.order.receiver === 'user';
            return q.contactId == id;
        });

        if (activeOrder) {
            const now = Date.now();
            // 存入聊天记录
            const elapsed = now - activeOrder.order.orderTime;
            const duration = activeOrder.order.deliveryDuration || 30000;
            const timeLeft = Math.max(0, Math.ceil((duration - elapsed) / 1000));

            container.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <span style="color:#FF9800; font-weight:bold;">🚴 配送中...</span>
                    <span style="font-size:12px; color:#999;">预计 ${timeLeft}秒</span>
                </div>
                <div style="font-size:14px; margin-top:5px; font-weight:500;">${activeOrder.order.foodName}</div>
            `;
        } else {
            container.textContent = "暂无进行中的订单";
        }
    }

