    function renderOrderHistory() {
        const container = document.getElementById('food-history-list');
        container.innerHTML = '';
        let allOrders = [];
        if (appData.globalUserProfile.foodProfile && appData.globalUserProfile.foodProfile.orderHistory) {
            allOrders.push(...appData.globalUserProfile.foodProfile.orderHistory.map(o => ({ ...o, ownerName: '我' })));
        }
        appData.aiContacts.forEach(c => {
            // 【核心修复】先检查 c.foodProfile 是否存在，再检查 orderHistory
            if (c.foodProfile && c.foodProfile.orderHistory) {
                allOrders.push(...c.foodProfile.orderHistory.map(o => ({ ...o, ownerName: c.remark })));
            }
        });
        allOrders.sort((a, b) => b.orderTime - a.orderTime);

        if (allOrders.length === 0) { container.innerHTML = '<p class="placeholder-text">暂无历史订单</p>'; return; }

        allOrders.forEach(order => {
            const date = new Date(order.orderTime).toLocaleString();
            const card = document.createElement('div');
            card.className = 'order-history-card';
            let extra = '';
            if (order.aiThought) extra += `<div class="ai-thought-box">AI心声: ${order.aiThought}</div>`;
            if (order.rewardQuart) extra += `<div style="color:#FF9800;font-size:12px;">💰 +${order.rewardQuart} 夸特</div>`;
            if (order.rating) extra += `<div style="color:#555;font-size:12px;">⭐ 评分 ${order.rating} 分</div>`;
            if (order.reviewText) extra += `<div style="color:#555;font-size:12px;">📝 评价: ${order.reviewText}</div>`;
            if (order.compensation) extra += `<div style="color:#FF9800;font-size:12px;">💰 赔偿 ${order.compensation} 夸特</div>`;
            if (order.realDescription) extra += `<div style="background:#f5f5f5;padding:5px;font-size:12px;">${order.realDescription}</div>`;

            card.innerHTML = `
                <div class="order-history-header"><span>${date}</span><span>给 ${order.ownerName}</span></div>
                <div class="order-history-content">
                    <img src="https://image.pollinations.ai/prompt/${encodeURIComponent(order.foodName)}" class="order-history-img">
                    <div class="order-history-details"><h4>${order.foodName}</h4><p>品质: ${order.quality}分</p></div>
                </div>
                <div class="order-history-footer">${extra}</div>
            `;
            container.appendChild(card);
        });
    }

