    const dishImgArea = document.getElementById('new-dish-img-area');
    const dishImgInput = document.getElementById('new-dish-img-input');
    const dishImgPreview = document.getElementById('new-dish-img-preview');
    if (dishImgArea && dishImgInput && dishImgPreview) {
        dishImgArea.onclick = () => dishImgInput.click();
        dishImgInput.onchange = (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = () => {
                dishImgPreview.src = reader.result;
                dishImgPreview.dataset.uploaded = 'true';
            };
            reader.readAsDataURL(file);
        };
    }

    function renderChipSelector(id, items, selectedItems = []) {
        const c = document.getElementById(id); c.innerHTML = '';
        const selected = new Set((Array.isArray(selectedItems) ? selectedItems : []).map(item => String(item || '').trim()));
        items.forEach(i => {
            const d = document.createElement('div'); d.className = 'chip'; d.textContent = i;
            if (selected.has(String(i || '').trim())) d.classList.add('selected');
            d.onclick = () => d.classList.toggle('selected');
            c.appendChild(d);
        });
    }

    async function handleGenerateNewDishFromPrompt() {
        const promptInput = document.getElementById('new-dish-ai-prompt');
        const status = document.getElementById('new-dish-ai-status');
        const btn = document.getElementById('generate-new-dish-from-prompt-btn');
        const promptText = String(promptInput?.value || '').trim();
        if (!promptText) {
            showToast('先写一句想生成什么菜品', 'info');
            return;
        }
        try {
            if (btn) {
                btn.disabled = true;
                btn.textContent = '生成中...';
            }
            if (status) status.textContent = '正在根据提示词生成菜名、描述、口味、价格和图片...';
            const catSelect = document.getElementById('new-dish-cat');
            const subSelect = document.getElementById('new-dish-subcat');
            const draft = await generateFoodDishFromPrompt({
                promptText,
                category: catSelect?.value || currentFoodCategory,
                preferredSubCategory: subSelect?.value || currentFoodSubCategory,
                contact: appData.aiContacts.find(c => String(c.id) === String(activeChatContactId)) || null
            });

            catSelect.value = draft.category;
            catSelect.dispatchEvent(new Event('change'));
            document.getElementById('new-dish-subcat').value = draft.subCategory;
            document.getElementById('new-dish-name').value = draft.name;
            document.getElementById('new-dish-price').value = draft.price;
            document.getElementById('new-dish-desc').value = draft.desc;
            ensureGeneratedFoodTags(draft);
            renderChipSelector('new-dish-tastes', GlobalFoodTags.tastes, draft.tastes);
            renderChipSelector('new-dish-ingredients', GlobalFoodTags.ingredients, draft.ingredients);
            const imgPreview = document.getElementById('new-dish-img-preview');
            if (imgPreview) {
                imgPreview.src = draft.image;
                imgPreview.dataset.isRegenerated = 'true';
                imgPreview.removeAttribute('data-uploaded');
            }
            if (status) status.textContent = '已生成草稿，确认无误后点“保存上架”。';
            showToast('新品草稿已生成', 'success');
        } catch (error) {
            console.error('[外卖] 提示词生成菜品失败:', error);
            if (status) status.textContent = `生成失败：${error.message || error}`;
            showToast(`生成失败：${error.message || error}`, 'error');
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.textContent = 'AI生成菜品';
            }
        }
    }

