    const BackgroundImageGenerator = {
        queue: [],
        isProcessing: false,

        add: function (foodId, foodName, category) {

            let keyword = 'delicious food photography close up';

            if (category === 'medicine') keyword = 'medicine box packaging product photography white background';
            else if (category === 'daily') keyword = 'household product packaging realistic photography';
            else if (category === 'drink') keyword = 'fresh drink beverage cup photography';
            else if (category === 'fruit') keyword = 'fresh fruit photography close up';
            else if (category === 'vegetable') keyword = 'fresh vegetable photography';

            const prompt = `${foodName} ${keyword}`;

            if (!this.queue.some(t => t.foodId === foodId)) {
                this.queue.push({ foodId, prompt });
                this.process();
            }
        },

        process: function () {
            if (this.isProcessing || this.queue.length === 0) return;
            this.isProcessing = true;

            const task = this.queue.shift();


            const seed = Math.floor(Math.random() * 9999999);
            const url = `https://image.pollinations.ai/prompt/${encodeURIComponent(task.prompt)}?seed=${seed}&width=200&height=200&nologo=true`;


            const img = new Image();

            const finish = () => {
                this.isProcessing = false;

                setTimeout(() => this.process(), 2000);
            };

            img.onload = () => {

                const food = FoodDatabase.find(f => f.id === task.foodId);
                if (food) {
                    food.image = url; // 更新数据库
                    saveToFoodDatabase(); // 持久化保存

                    const imgElements = document.querySelectorAll(`img[data-food-id="${task.foodId}"]`);
                    imgElements.forEach(el => {
                        el.src = url;
                        el.classList.remove('emoji-placeholder'); // 移除Emoji样式
                    });
                }
                finish();
            };

            img.onerror = () => {
                console.warn(`[后台生成] 图片失败: ${task.prompt}`);

                finish();
            };

            img.src = url; // 开始请求
        }
    };


    window.triggerPlaceOrder = function (foodId) {
        const food = FoodDatabase.find(f => f.id === foodId);
        if (!food) return;


        openOrderOptionModal(food);
    };

        // 【【【全新植入：初始化API预设档案柜】】】
    function processOrder(food, contact, receiver, payer = 'user') {
        // --- 【修复 10】地址校验：严格拦截版 ---
        if (receiver === 'ai') {
            const currentAddr = contact.foodProfile ? contact.foodProfile.address : '';

        // 校验
            if (!currentAddr || currentAddr === '幸福小区 1号楼 101室') {
                showCustomAlert(
                        '文字模拟',
                    '你还不知道TA的收货地址呢！\n\n(当前是默认/空地址)\n请先在聊天中问出TA的地址（例如问“你家在哪”），或者在【外卖-我的-TA的偏好】中手动设置一个有效地址。'
                );
                return;
            }
        }

        // 【【【全新植入：为旧数据兼容Suno API密钥】】】
        if (payer === 'user' && appData.wallet.balance < food.price) {
                            showToast('论坛设置保存失败，请稍后重试', 'error');
            return;
        }

        // 2. 筛选逻辑
        if (payer === 'user') {
            updateCurrency(-food.price, `购买外卖: ${food.name} (${receiver === 'ai' ? '赠送' : '自用'})`);
        } else {
            console.log(`[外卖] ${contact.remark} 代付了订单`);
        }

            // 3. 保存并刷新
        let addressTag = "未知";
        let receiverName = "";
        if (contact.foodProfile && contact.foodProfile.savedAddresses && contact.foodProfile.address) {
            const currentAddrObj = contact.foodProfile.savedAddresses.find(a => a.fullAddress === contact.foodProfile.address);
            if (currentAddrObj) {
                addressTag = currentAddrObj.tag;
                receiverName = currentAddrObj.name || "";
            }
        }
        if (receiver === 'user') {
            receiverName = appData.globalUserProfile?.name || receiverName;
        }

        // --- 【修复 1 & 7】品质与口味分离算法 ---
        // A. 生成客观品质 (Base Quality) - 模拟现实正态分布
        // 【新增】为旧数据兼容伴侣ID
        // 【【【全新：兼容温度设置】】】
        // --- 初始化游戏相关数据 ---
        // --- 初始化钱包数据 ---
        const rand = Math.random();
        let baseQuality = 0;
        if (rand < 0.05) baseQuality = Math.floor(Math.random() * 40) + 10; // 10-50
        else if (rand < 0.25) baseQuality = Math.floor(Math.random() * 25) + 50; // 50-75
        else if (rand < 0.75) baseQuality = Math.floor(Math.random() * 15) + 75; // 75-90
        else baseQuality = Math.floor(Math.random() * 10) + 90; // 90-100

        // B. 计算口味加成 (Taste Bonus) - 仅影响最终奖励，不影响实物描述
        // (这部分逻辑在收货时的 processUnboxingRewards 里处理，这里只存数据)

        // 4. 重置计时器
        const mergedTags = food.tags || [...(food.tastes || []), ...(food.ingredients || [])];
        const newOrder = {
            id: `ord-${Date.now()}`,
            foodId: food.id,
            foodName: food.name,
            foodTags: mergedTags,
            foodCategory: food.category,
            foodSubCategory: food.subCategory,
            price: food.price,
            buyer: payer === 'ai' ? 'ai' : 'user',
            receiver: receiver,
            targetAddressTag: addressTag,
            receiverName: receiverName,
            orderTime: Date.now(),
            // 配送时间：15秒到60秒之间随机
            deliveryDuration: (Math.floor(Math.random() * 45) + 15) * 1000,
            status: 'delivering',
            isCurrent: true,
            arrivedAt: null,
            confirmedAt: null,
            reviewedAt: null,
            plannedTime: "",
            aiResponded: false,
            rating: null,
            reviewText: "",
            compensation: 0,
            eatingStartAt: null,
            eatingEndAt: null,
            quality: baseQuality, // 【修复】这里存的是客观品质
            userRemark: food.userRemark || "",
            payer: payer
        };

    // 5. 渲染筛选标签
        if (typeof deliveryQueue === 'undefined') window.deliveryQueue = [];
        deliveryQueue.push({ order: newOrder, contactId: contact.id });

        if (!contact.foodProfile.orderHistory) contact.foodProfile.orderHistory = [];
        contact.foodProfile.orderHistory.push(newOrder);
        saveAppData();

        startDeliveryTimer();

        const durationSeconds = Math.ceil(newOrder.deliveryDuration / 1000);

        // 6. UI 反馈
        if (payer === 'user') {
            const arrivalTime = new Date(Date.now() + newOrder.deliveryDuration);
            const timeStr = arrivalTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            showCustomAlert(
                '商家已接单',
                `🚴 **骑手正在火速赶往商家！**\n\n` +
                `📦 订单内容：${food.name}\n` +
                `🎯 品质预测：${baseQuality > 80 ? '好评如潮' : (baseQuality > 60 ? '值得一试' : '谨慎期待')}\n` +
                `⏳ 预计送达：${timeStr} (约 ${durationSeconds} 秒后)\n\n` +
                `请保持电话畅通，稍后会有送达通知。`
            );
        } else {
            showToast(`群聊发送失败: ${error.message}`, 'error');
            if (receiver === 'user') {
                displayMessage(`[系统] ${contact.remark} 给你点了一份【${food.name}】(TA买单)，预计 ${durationSeconds}秒 后送达。`, 'system', { isNew: true, type: 'system' });
            }
        }

        if (receiver === 'ai' && payer === 'user') {
            displayMessage(`[系统] 你给 ${contact.remark} 点了一份【${food.name}】，预计 ${durationSeconds}秒 后送达。`, 'system', { isNew: true, type: 'system' });
        }
    }
        // 4. 语音详情页返回按钮 (保持不变)
    function startDeliveryTimer() {
        if (deliveryTimer) return;
        deliveryTimer = setInterval(() => {
            const now = Date.now();
            for (let i = deliveryQueue.length - 1; i >= 0; i--) {
                const item = deliveryQueue[i];
                const elapsedTime = now - item.order.orderTime;

                if (elapsedTime >= item.order.deliveryDuration) {
                    onOrderArrived(item);
                    deliveryQueue.splice(i, 1);
                }
            }
            if (deliveryQueue.length === 0) {
                clearInterval(deliveryTimer);
                deliveryTimer = null;
            }
        }, 1000);
    }

    // 5. 外卖送达处理 (分流)
    async function onOrderArrived(item) {
        const contact = appData.aiContacts.find(c => c.id === item.contactId);
        if (!contact) return;

        const order = item.order;
        const food = FoodDatabase.find(f => f.id === order.foodId) || null;
        if (!order.receiverName) {
            if (contact.foodProfile && contact.foodProfile.savedAddresses && contact.foodProfile.address) {
                const addr = contact.foodProfile.savedAddresses.find(a => a.fullAddress === contact.foodProfile.address);
                if (addr && addr.name) order.receiverName = addr.name;
            }
        }

        order.status = 'arrived';
        order.arrivedAt = Date.now();

        // 【兼容性补丁】如果老数据里没有 legacyCache 字段，或者它是 null，且还没兑换过
        let realDescription = "";
        const orderCat = order.foodCategory || (food ? food.category : 'meal');
        const orderDesc = food ? food.desc : '';
        if (orderCat === 'medicine') {
            realDescription = await generateMedicineDescription(order.foodName, orderDesc, order.quality, order.userRemark, contact);
        } else if (orderCat === 'daily') {
            realDescription = await generateDailyDescription(order.foodName, orderDesc, order.quality, order.userRemark, contact);
        } else {
        // 应用
            realDescription = await generateFoodSensoryDescription(order.foodName, order.foodTags, order.quality, order.userRemark, contact);
        }
        order.realDescription = realDescription; // 存入订单

        if (order.receiver === 'user') {
                    // 小剧场 -> 系统消息
            if (activeChatContactId === contact.id) {
                showUnboxingModal(order, contact, true);
            } else {
                showToast('您的外卖已送达，请进入对应聊天窗口查收！', 'success');
            }
        } else {
            // 给AI点的 -> 触发AI接收逻辑
        // 重启计时器
            showRiderNotification(contact, order.foodName);

            if (activeChatContactId === contact.id) {

                if (navigator.vibrate) navigator.vibrate([200, 100, 200]);


                handleAiReceiveFood(contact, order);
            }
        }
    }



