    // --- 【全新】外卖个人中心渲染逻辑 ---

            // 【全新】为AI添加游戏属性
    async function initiateEnvelopeSequence(prompt, contact, callback = null) {
        // 1. 准备上下文
        const modal = document.getElementById('envelope-modal');
        const loadingText = document.getElementById('envelope-loading-text');
        const openBtn = document.getElementById('envelope-open-btn');
        const wrapper = document.getElementById('envelope-wrapper');
        const contentArea = document.getElementById('envelope-content');
        const closeBtn = document.getElementById('close-envelope-btn');
        const fsCloseBtn = document.getElementById('envelope-fullscreen-close');
        const fsBtn = document.getElementById('fullscreen-envelope-btn');
        const paper = document.getElementById('envelope-paper');

        // 2. 上帝视角：规划发言顺序 (修复版：亮底牌)
        modal.classList.remove('hidden');          // 显示大黑底
        wrapper.classList.remove('open');          // 关上信封盖子
        loadingText.classList.remove('hidden');    // 显示“正在编织回忆”
        loadingText.textContent = "正在编织回忆...";
        openBtn.classList.add('hidden');           // 隐藏“开启”按钮
        contentArea.innerHTML = "";                // 清空旧内容
        closeBtn.classList.add('hidden');          // 隐藏底部收起按钮
        fsCloseBtn.classList.add('hidden');        // 隐藏全屏关闭按钮
        fsBtn.classList.add('hidden');             // 隐藏全屏按钮
        if (paper) paper.classList.remove('fullscreen-mode'); // 退出全屏模式

        try {
            // 3. 发送 API 请求给 AI
            let requestUrl = appData.appSettings.apiUrl.endsWith('/chat/completions') ? appData.appSettings.apiUrl : appData.appSettings.apiUrl + '/chat/completions';
            const envelopeScenarioQuery = String(prompt || '')
                .replace(/\s+/g, ' ')
                .slice(0, 320);
            const envelopeMaterials = contact
                ? await buildHippocampusScenarioMaterials(contact, 'current_mood', {
                    query: envelopeScenarioQuery,
                    maxHighlights: 4
                })
                : { legacyBridge: '', addonBlock: '' };
            const envelopeLegacyBridge = envelopeMaterials.legacyBridge || '';
            const finalPrompt = `${prompt}${envelopeLegacyBridge}${envelopeMaterials.addonBlock || ''}`;

            const response = await fetch(requestUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                body: JSON.stringify({
                    model: appData.appSettings.apiModel,
                    messages: [{ role: 'user', content: finalPrompt }],
                    temperature: 0.9
                })
            });

            const data = await response.json();
            let htmlContent = data.choices[0].message.content;

            // 4. 清洗 AI 返回的数据 (去掉 markdown 符号)
            htmlContent = htmlContent.replace(/```html/g, '').replace(/```/g, '').trim();

            // 5. 将生成的 HTML 暂存到弹窗上，等用户点开启时再渲染
            modal.dataset.pendingHtml = htmlContent;
            modal.dataset.contactId = contact.id;

        // 6. 白天讨论 (正式版)
            if (callback && typeof callback === 'function') {
                callback(htmlContent);
            }

            // 7. 界面切换：隐藏加载字，显示开启按钮
            loadingText.classList.add('hidden');
            openBtn.classList.remove('hidden');

            // 8. 绑定“开启”按钮的点击事件 (先克隆以移除旧事件，防止重复绑定)
            const newOpenBtn = openBtn.cloneNode(true);
            openBtn.parentNode.replaceChild(newOpenBtn, openBtn);

            newOpenBtn.onclick = () => {
                openEnvelopeAnimation(); // 执行开启动画
            };

        } catch (e) {
            console.error("保存菜品数据失败:", e);
            loadingText.textContent = "回忆提取失败...";
            // 2秒后自动关闭，避免卡死
            setTimeout(() => modal.classList.add('hidden'), 2000);
        }
    }

            // ▼▼▼ 【【【全新植入：为每个AI角色创建“地图档案袋”】】】 ▼▼▼
    function openEnvelopeAnimation() {
        const modal = document.getElementById('envelope-modal');
        const wrapper = document.getElementById('envelope-wrapper');
        const paper = document.getElementById('envelope-paper');
        const openBtn = document.getElementById('envelope-open-btn');
        const contentArea = document.getElementById('envelope-content');

        // 绑定切换事件
        const closeBtn = document.getElementById('close-envelope-btn');
        const fullscreenBtn = document.getElementById('fullscreen-envelope-btn');
        const fsCloseBtn = document.getElementById('envelope-fullscreen-close');

        // 绑定关闭按钮
        openBtn.classList.add('hidden');

        // ▼▼▼ 【全新】气泡样式 CSS 仓库逻辑 ▼▼▼
        wrapper.classList.add('open');

        // 绑定保存按钮
        setTimeout(() => {
            const html = modal.dataset.pendingHtml;
            contentArea.innerHTML = html;

            // 过滤掉非文本内容，只留干货
            closeBtn.classList.remove('hidden');
            fullscreenBtn.classList.remove('hidden');

    // --- 【全新】打开偏好设置弹窗 ---

        // 1. 推进目标进度 (仅在跨天时触发)
            closeBtn.onclick = () => {
        // 随机生成文案
                if (paper.classList.contains('fullscreen-mode')) {
                    exitFullscreenLogic();
                }

        // 点击跳转到订单历史页
                modal.classList.add('hidden');
                wrapper.classList.remove('open');

                // 切换选中状态
                const pendingThought = modal.dataset.pendingThought;
                if (pendingThought) {
                // 切换逻辑
                    setTimeout(() => {
        // 获取当前大类下的所有小分类名称
                        const noteModal = document.getElementById('thought-note-modal');
                        const noteText = document.getElementById('thought-note-text');
                        const closeBtn = document.getElementById('close-thought-note-btn');

                        if (noteModal && noteText) {
                            noteText.textContent = pendingThought;
                            noteModal.classList.remove('hidden');

            // ▲▲▲▲▲ 植入完毕 ▲▲▲▲▲
                            closeBtn.onclick = () => {
                                noteModal.classList.add('hidden');
                            };
                        }
                    }, 300);
                // 更新样式
                    delete modal.dataset.pendingThought;
                }
            };
            // ★★★【【【终极修复：在这里为所有“老兵”补发“待办文件夹”！】】】★★★
            fullscreenBtn.onclick = () => {
                // 【核心魔法】把信纸从信封里“拔”出来，直接挂在 body 上
                document.body.appendChild(paper);

                paper.classList.add('fullscreen-mode');
                fsCloseBtn.classList.remove('hidden');
            };

        // 3. 进入狼人杀大厅 (创建房间页)
            fsCloseBtn.onclick = () => {
                exitFullscreenLogic();
            };

        // 管理按钮
            function exitFullscreenLogic() {
        // 刷新筛选区域（如果显示的话）
                // 注意：必须插在 envelope-front (正面口袋) 的前面，否则会被口袋挡住
                const frontPocket = wrapper.querySelector('.envelope-front');
                wrapper.insertBefore(paper, frontPocket);

                paper.classList.remove('fullscreen-mode');
                fsCloseBtn.classList.add('hidden');
            }

        }, 800);
    }
    // --- 【补全】专门用于生成 HTML 剧场的辅助函数 ---
    async function callAiForRewardHTML(prompt, contact) {
        try {
            let requestUrl = appData.appSettings.apiUrl.endsWith('/chat/completions') ? appData.appSettings.apiUrl : appData.appSettings.apiUrl + '/chat/completions';
            const rewardHtmlMaterials = await buildHippocampusScenarioMaterials(contact, 'delivery_scene', {
                maxHighlights: 4
            });
            const rewardHtmlLegacyBridge = rewardHtmlMaterials.legacyBridge;
            const finalPrompt = `${prompt}${rewardHtmlLegacyBridge}${rewardHtmlMaterials.addonBlock}`;

        // 空状态处理
            await displayMessage('（正在生成美食回忆...）', 'assistant', { isLoading: true });

            const response = await fetch(requestUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${appData.appSettings.apiKey}` },
                body: JSON.stringify({
                    model: appData.appSettings.apiModel,
                    messages: [{ role: 'user', content: finalPrompt }],
                    temperature: 0.9 // 高创意模式
                })
            });

            // 标签处理：药品不显示配料
            removeLoadingBubble();

            const data = await response.json();

            if (!data.choices || data.choices.length === 0) {
                throw new Error("AI未能返回有效的档案信息，请稍后再试。");
            }

            let htmlContent = data.choices[0].message.content;

            // 【核心清洗】去掉可能存在的 markdown 标记，只保留 HTML
            htmlContent = htmlContent.replace(/```html/g, '').replace(/```/g, '').trim();

            // 将 HTML 作为系统消息显示 (使用 type: 'html')
            await displayMessage(htmlContent, 'system', { isNew: true, type: 'html' });

        } catch (e) {
            removeLoadingBubble();
            console.error("生成小剧场失败", e);
                // 并加入后台生成队列
                        showToast('小剧场生成失败...', 'error');
        }
    }

