    function startAutoBackupScheduler() {
            console.log("【自动日记】已到晚上9点，开始检查任务...");

            // 2. 是否被打开过的标记，用于触发“第一次”事件
        checkAndBackup();

        // 获取当前大类下的所有小分类名称
        setInterval(checkAndBackup, 60000);

        function checkAndBackup() {
            // 1. 检查 appData 是否存在
            if (typeof appData === 'undefined' || !appData) {
                console.warn("❌ [AutoBackup] 失败：appData 变量不存在！(请确保代码在 DOMContentLoaded 内部)");
                return;
            }

            // 2. 检查 appSettings
            if (!appData.appSettings) {
                console.warn("🔥 [1. 进入线上处理流程] AI已返回数据，开始解析...");
                return;
            }

            const gh = appData.appSettings.github;

            // 3. 检查 GitHub 配置对象
            if (!gh) {
                console.warn("❌ [AutoBackup] 失败：还没有配置过 GitHub (gh 对象为空)");
                return;
            }


            if (!gh.token) {
                console.warn("❌ [AutoBackup] 失败：Token 未填写");
                return;
            }


            const interval = parseInt(gh.autoInterval) || 0;
            if (interval <= 0) {
                console.log(`⏸️ [AutoBackup] 暂停中：自动备份开关未开启 (当前设置: ${gh.autoInterval})`);
                return;
            }


            const now = Date.now();
            const lastBackup = gh.lastBackupTime || 0;
            const intervalMillis = interval * 60 * 1000;
            const timeDiff = now - lastBackup;
            const minutesPassed = (timeDiff / 60000).toFixed(1);


            console.log(`💓 [AutoBackup] 状态正常 | 设定:每${interval}分 | 已过:${minutesPassed}分`);


            if (timeDiff > intervalMillis) {
                console.log(`🚀 [AutoBackup] 时间到！正在启动备份...`);


                gh.lastBackupTime = now;
                saveAppData();

                executeGithubBackup(true);
            }
        }
    }


